// Custom error handler

set_error_handler(function ($errno, $errstr, $errfile, $errline) {
    // Check if error is suppressed with @ operator
    if (!(error_reporting() & $errno)) {
        return false;
    }

    // Do not crash on notices and deprecations
    if ($errno === E_NOTICE || $errno === E_USER_NOTICE || $errno === E_DEPRECATED || $errno === E_USER_DEPRECATED) {
        error_log("PHP Notice/Deprecation: $errstr in $errfile on line $errline");
        return true; // continue execution
    }

    $error = "PHP Error [$errno]: $errstr in $errfile on line $errline";

    error_log($error);



    // Clean any output

    if (ob_get_length())

        ob_clean();



    echo json_encode([

        'success' => false,

        'message' => 'خطأ في PHP: ' . $errstr,

        'debug' => [

            'file' => basename($errfile),

            'line' => $errline,

            'error' => $errstr

        ]

    ]);

    exit;

});



// Custom exception handler

set_exception_handler(function ($exception) {

    error_log("Uncaught Exception: " . $exception->getMessage());



    // Clean any output

    if (ob_get_length())

        ob_clean();



    echo json_encode([

        'success' => false,

        'message' => 'خطأ: ' . $exception->getMessage(),

        'debug' => [

            'file' => basename($exception->getFile()),

            'line' => $exception->getLine()

        ]

    ]);

    exit;

});

// Error handler

function handleError($message)

{

    sendJSON(['success' => false, 'message' => $message]);

}



// ── Image Enhancement Function ──────────────────────────────

function enhanceImage($imagePath, $targetWidth = 400, $targetHeight = 500)

{

    // Load image

    $imageInfo = @getimagesize($imagePath);

    if (!$imageInfo) {

        return null;

    }



    $mime = $imageInfo['mime'];

    $source = null;



    // Create image resource based on type

    if ($mime === 'image/jpeg') {

        $source = @imagecreatefromjpeg($imagePath);

    } elseif ($mime === 'image/png') {

        $source = @imagecreatefrompng($imagePath);

    } elseif ($mime === 'image/gif') {

        $source = @imagecreatefromgif($imagePath);

    } elseif ($mime === 'image/webp') {

        $source = @imagecreatefromwebp($imagePath);

    }



    if (!$source) {

        return null;

    }



    $width = imagesx($source);

    $height = imagesy($source);



    // Calculate new dimensions maintaining aspect ratio

    $ratio = $width / $height;

    $targetRatio = $targetWidth / $targetHeight;



    if ($ratio > $targetRatio) {

        $newWidth = $targetHeight * $ratio;

        $newHeight = $targetHeight;

    } else {

        $newWidth = $targetWidth;

        $newHeight = $targetWidth / $ratio;

    }



    // Create intermediate image (scaled)

    $scaled = imagecreatetruecolor($newWidth, $newHeight);

    imagealphablending($scaled, false);

    imagesavealpha($scaled, true);

    imagecopyresampled($scaled, $source, 0, 0, 0, 0, $newWidth, $newHeight, $width, $height);



    // Create final image with cropping (center crop)

    $final = imagecreatetruecolor($targetWidth, $targetHeight);

    imagealphablending($final, false);

    imagesavealpha($final, true);



    $offsetX = ($newWidth - $targetWidth) / 2;

    $offsetY = ($newHeight - $targetHeight) / 2;



    imagecopy($final, $scaled, 0, 0, $offsetX, $offsetY, $targetWidth, $targetHeight);



    // Apply enhancement: increase contrast and brightness

    imagefilter($final, IMG_FILTER_CONTRAST, 5);

    imagefilter($final, IMG_FILTER_BRIGHTNESS, 15);

    imagefilter($final, IMG_FILTER_SMOOTH, 1);



    unset($source, $scaled);



    return $final;

}



// ── Trip access helpers ─────────────────────────────────────

function getTripParticipantIds($tripRow)

{

    $participants = [intval($tripRow['church_id'] ?? 0)];

    $collabRaw = $tripRow['collaborating_churches'] ?? '';

    if (!empty($collabRaw)) {

        $collab = json_decode($collabRaw, true);

        if (is_array($collab)) {

            $participants = array_unique(array_merge($participants, array_map('intval', $collab)));

        }

    }

    return array_values(array_filter($participants, function ($id) {

        return $id > 0;

    }));

}



function isTripDeveloperViewerRole()
{
    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? $_SESSION['user_role'] ?? $_POST['uncle_role'] ?? $_POST['role'] ?? $_GET['uncle_role'] ?? $_GET['role'] ?? '');

    return in_array($role, ['developer', 'dev', 'admin', 'administrator', 'superadmin'], true);
}



/** Bypass trip ACL when developer/admin or when explicit override sent. */

function isTripDeveloperViewer()

{

    if (isTripDeveloperViewerRole()) {

        return true;

    }

    return !empty($_POST['dev_override_church_id']) || !empty($_GET['dev_override_church_id']);

}



function churchIsTripParticipant($tripRow, $churchId)

{

    return in_array(intval($churchId), getTripParticipantIds($tripRow), true);

}



function verifyTripParticipant($conn, $tripId, $churchId)

{

    $stmt = $conn->prepare("SELECT church_id, collaborating_churches FROM trips WHERE id = ?");

    $stmt->bind_param("i", $tripId);

    $stmt->execute();

    $res = $stmt->get_result()->fetch_assoc();

    if (!$res) {

        return false;

    }

    return churchIsTripParticipant($res, $churchId);

}



function churchHasPendingTripAccessRequest($conn, $tripId, $requesterChurchId, $ownerChurchId)

{

    ensureTripCollaborationRequestsTable($conn);

    $chk = $conn->prepare("SELECT id FROM trip_collaboration_requests WHERE trip_id = ? AND from_church_id = ? AND to_church_id = ? AND status = 'pending' LIMIT 1");

    $chk->bind_param('iii', $tripId, $requesterChurchId, $ownerChurchId);

    $chk->execute();

    return $chk->get_result()->num_rows > 0;

}



function buildTripAccessDeniedResponse($conn, $trip, $churchId)

{

    $ownerChurchId = intval($trip['church_id']);

    $ownerName = '';

    $cStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");

    if ($cStmt) {

        $cStmt->bind_param('i', $ownerChurchId);

        $cStmt->execute();

        $crow = $cStmt->get_result()->fetch_assoc();

        $ownerName = $crow['church_name'] ?? '';

    }



    $pending = ($churchId > 0) ? churchHasPendingTripAccessRequest($conn, intval($trip['id']), $churchId, $ownerChurchId) : false;



    sendJSON([

        'success' => false,

        'access_denied' => true,

        'message' => 'ليس لديك صلاحية لعرض هذه الرحلة',

        'trip' => [

            'id' => intval($trip['id']),

            'title' => $trip['title'] ?? '',

            'image_url' => $trip['image_url'] ?? '',

            'owner_church_id' => $ownerChurchId,

            'owner_church_name' => $ownerName,

        ],

        'pending_request' => $pending,

    ]);

}



// ── Request trip access (replaces instant join) ─────────────

function requestTripAccess()

{

    try {

        checkUncleAuth();

        $churchId = getChurchId();

        if ($churchId <= 0) {

            sendJSON(['success' => false, 'message' => 'يجب تسجيل الدخول ككنيسة لطلب المشاركة في الرحلة']);

            return;

        }



        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);

        if ($tripId <= 0) {

            sendJSON(['success' => false, 'message' => 'معرف الرحلة مطلوب']);

            return;

        }



        $conn = getDBConnection();

        ensureTripCollaborationRequestsTable($conn);



        $stmt = $conn->prepare("SELECT id, church_id, collaborating_churches, title FROM trips WHERE id = ? LIMIT 1");

        $stmt->bind_param('i', $tripId);

        $stmt->execute();

        $res = $stmt->get_result();

        if ($res->num_rows === 0) {

            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);

            return;

        }



        $row = $res->fetch_assoc();

        $tripTitle = $row['title'] ?? '';

        $ownerChurchId = intval($row['church_id']);



        if ($ownerChurchId === $churchId) {

            sendJSON(['success' => true, 'message' => 'هذه الكنيسة هي مالكة الرحلة', 'trip_id' => $tripId, 'already_joined' => true]);

            return;

        }



        if (in_array($churchId, getTripParticipantIds($row), true)) {

            sendJSON([

                'success' => true,

                'message' => 'كنيستك تشارك بالفعل في هذه الرحلة',

                'trip_id' => $tripId,

                'trip_title' => $tripTitle,

                'already_joined' => true,

            ]);

            return;

        }



        if (churchHasPendingTripAccessRequest($conn, $tripId, $churchId, $ownerChurchId)) {

            sendJSON([

                'success' => true,

                'message' => 'تم إرسال طلب المشاركة مسبقاً وهو قيد المراجعة',

                'trip_id' => $tripId,

                'trip_title' => $tripTitle,

                'pending_request' => true,

            ]);

            return;

        }



        $ins = $conn->prepare("INSERT INTO trip_collaboration_requests (trip_id, from_church_id, to_church_id, status) VALUES (?, ?, ?, 'pending')");

        $ins->bind_param('iii', $tripId, $churchId, $ownerChurchId);

        if ($ins->execute()) {

            logActivity($churchId, $_SESSION['uncle_id'] ?? null, 'request_trip_access', "trip:$tripId");

            $ownerName = '';

            $cStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");

            if ($cStmt) {

                $cStmt->bind_param('i', $ownerChurchId);

                $cStmt->execute();

                $crow = $cStmt->get_result()->fetch_assoc();

                $ownerName = $crow['church_name'] ?? '';

            }

            sendJSON([

                'success' => true,

                'message' => 'تم إرسال طلب المشاركة إلى ' . ($ownerName ?: 'كنيسة مالكة الرحلة'),

                'trip_id' => $tripId,

                'trip_title' => $tripTitle,

                'pending_request' => true,

            ]);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل إرسال طلب المشاركة: ' . $ins->error]);

        }

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => 'خطأ في طلب المشاركة: ' . $e->getMessage()]);

    }

}



function joinTrip()

{

    requestTripAccess();

}



// ── Collaboration Helpers ──────────────────────────────────

function verifyRegistrationParticipant($conn, $registrationId, $churchId)
{
    $stmt = $conn->prepare("
        SELECT t.church_id, t.collaborating_churches, COALESCE(s.church_id, g.church_id, unc.church_id, tr.church_id, t.church_id) as student_church_id
        FROM trip_registrations tr
        JOIN trips t ON tr.trip_id = t.id
        LEFT JOIN students s ON tr.student_id = s.id
        LEFT JOIN guests g ON tr.guest_id = g.id
        LEFT JOIN uncles unc ON tr.uncle_id = unc.id
        WHERE tr.id = ?
    ");
    $stmt->bind_param("i", $registrationId);
    $stmt->execute();
    $res = $stmt->get_result()->fetch_assoc();
    if (!$res)
        return false;

    $isOwner = intval($res['church_id']) === intval($churchId);
    $isOwnKid = intval($res['student_church_id']) === intval($churchId);

    return ($isOwner || $isOwnKid || isTripDeveloperViewer());
}



function getCollaboratingChurchesList($conn, $collabRaw, $ownerChurchId = 0, $limitsRaw = '')
{
    $ids = [];
    if (!empty($collabRaw)) {
        $decoded = json_decode($collabRaw, true);
        if (is_array($decoded)) {
            $ids = array_values(array_unique(array_filter(array_map('intval', $decoded), function ($id) use ($ownerChurchId) {
                return $id > 0 && $id !== intval($ownerChurchId);
            })));
        }
    }
    if (empty($ids)) {
        return [];
    }

    $placeholders = implode(',', array_fill(0, count($ids), '?'));
    $types = str_repeat('i', count($ids));
    $stmt = $conn->prepare("SELECT id, church_name, church_code FROM churches WHERE id IN ($placeholders)");
    if (!$stmt) {
        return [];
    }
    $stmt->bind_param($types, ...$ids);
    $stmt->execute();
    $result = $stmt->get_result();

    $limits = [];
    if (!empty($limitsRaw)) {
        $limits = json_decode($limitsRaw, true);
        if (!is_array($limits)) {
            $limits = [];
        }
    }

    $byId = [];
    while ($row = $result->fetch_assoc()) {
        $byId[intval($row['id'])] = [
            'id' => intval($row['id']),
            'name' => $row['church_name'],
            'code' => $row['church_code'],
            'limit' => isset($limits[strval($row['id'])]) ? intval($limits[strval($row['id'])]) : null,
        ];
    }

    $list = [];
    foreach ($ids as $id) {
        if (isset($byId[$id])) {
            $list[] = $byId[$id];
        }
    }
    return $list;
}



function removeTripCollaborator()
{
    try {
        checkUncleAuth();
        $churchId = getChurchId();
        if ($churchId <= 0) {
            sendJSON(['success' => false, 'message' => 'يجب تسجيل الدخول ككنيسة']);
            return;
        }

        $tripId = intval($_POST['trip_id'] ?? 0);
        $removeChurchId = intval($_POST['collaborator_church_id'] ?? 0);
        if ($tripId <= 0 || $removeChurchId <= 0) {
            sendJSON(['success' => false, 'message' => 'بيانات غير صحيحة']);
            return;
        }

        $conn = getDBConnection();
        $tStmt = $conn->prepare("SELECT church_id, collaborating_churches, collaboration_limits, title FROM trips WHERE id = ? LIMIT 1");
        $tStmt->bind_param('i', $tripId);
        $tStmt->execute();
        $trip = $tStmt->get_result()->fetch_assoc();
        if (!$trip) {
            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
            return;
        }
        if (intval($trip['church_id']) !== $churchId) {
            sendJSON(['success' => false, 'message' => 'فقط مالك الرحلة يمكنه إزالة كنيسة من المشاركة']);
            return;
        }
        if ($removeChurchId === intval($trip['church_id'])) {
            sendJSON(['success' => false, 'message' => 'لا يمكن إزالة كنيسة مالكة الرحلة']);
            return;
        }

        $collab = [];
        if (!empty($trip['collaborating_churches'])) {
            $decoded = json_decode($trip['collaborating_churches'], true);
            if (is_array($decoded)) {
                $collab = array_values(array_unique(array_map('intval', $decoded)));
            }
        }
        if (!in_array($removeChurchId, $collab, true)) {
            sendJSON(['success' => false, 'message' => 'هذه الكنيسة غير مسجلة كشريكة في الرحلة']);
            return;
        }

        $collab = array_values(array_filter($collab, fn($id) => $id !== $removeChurchId));
        $collabJson = json_encode($collab, JSON_UNESCAPED_UNICODE);

        $limits = [];
        if (!empty($trip['collaboration_limits'])) {
            $limits = json_decode($trip['collaboration_limits'], true);
            if (is_array($limits)) {
                if (isset($limits[strval($removeChurchId)])) {
                    unset($limits[strval($removeChurchId)]);
                }
            } else {
                $limits = [];
            }
        }
        $limitsJson = json_encode($limits, JSON_UNESCAPED_UNICODE);

        $up = $conn->prepare("UPDATE trips SET collaborating_churches = ?, collaboration_limits = ? WHERE id = ?");
        $up->bind_param('ssi', $collabJson, $limitsJson, $tripId);
        if (!$up->execute()) {
            sendJSON(['success' => false, 'message' => 'فشل تحديث بيانات الرحلة']);
            return;
        }

        ensureTripCollaborationRequestsTable($conn);
        $delReq = $conn->prepare("DELETE FROM trip_collaboration_requests WHERE trip_id = ? AND (from_church_id = ? OR to_church_id = ?)");
        if ($delReq) {
            $delReq->bind_param('iii', $tripId, $removeChurchId, $removeChurchId);
            $delReq->execute();
        }

        $removedName = '';
        $nameStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");
        if ($nameStmt) {
            $nameStmt->bind_param('i', $removeChurchId);
            $nameStmt->execute();
            $nr = $nameStmt->get_result()->fetch_assoc();
            $removedName = $nr['church_name'] ?? '';
        }

        sendJSON([
            'success' => true,
            'message' => 'تم إزالة ' . ($removedName ?: 'الكنيسة') . ' من المشاركة',
            'collaborators_list' => getCollaboratingChurchesList($conn, $collabJson, intval($trip['church_id']), $limitsJson),
        ]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}



function updateCollaborationLimit()
{
    try {
        checkUncleAuth();
        $churchId = getChurchId();
        if ($churchId <= 0) {
            sendJSON(['success' => false, 'message' => 'يجب تسجيل الدخول ككنيسة']);
            return;
        }

        $tripId = intval($_POST['trip_id'] ?? 0);
        $collabChurchId = intval($_POST['collaborator_church_id'] ?? 0);
        $limit = isset($_POST['registration_limit']) && $_POST['registration_limit'] !== '' ? intval($_POST['registration_limit']) : null;

        if ($tripId <= 0 || $collabChurchId <= 0) {
            sendJSON(['success' => false, 'message' => 'بيانات غير صحيحة']);
            return;
        }

        $conn = getDBConnection();
        ensureTripCollaborationRequestsTable($conn);

        // Verify trip exists and user is owner
        $tStmt = $conn->prepare("SELECT church_id, collaborating_churches, collaboration_limits FROM trips WHERE id = ?");
        $tStmt->bind_param("i", $tripId);
        $tStmt->execute();
        $trip = $tStmt->get_result()->fetch_assoc();
        if (!$trip) {
            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
            return;
        }
        if (intval($trip['church_id']) !== $churchId) {
            sendJSON(['success' => false, 'message' => 'غير مصرح لك بتعديل حدود هذه الرحلة']);
            return;
        }

        // Verify the collaborator exists in collaborating_churches
        $collab = [];
        if (!empty($trip['collaborating_churches'])) {
            $collab = json_decode($trip['collaborating_churches'], true);
            if (!is_array($collab))
                $collab = [];
        }
        if (!in_array($collabChurchId, array_map('intval', $collab), true)) {
            sendJSON(['success' => false, 'message' => 'هذه الكنيسة ليست شريكة في الرحلة']);
            return;
        }

        // Update limit
        $limits = [];
        if (!empty($trip['collaboration_limits'])) {
            $limits = json_decode($trip['collaboration_limits'], true);
            if (!is_array($limits))
                $limits = [];
        }

        if ($limit !== null) {
            $limits[strval($collabChurchId)] = $limit;
        } else {
            if (isset($limits[strval($collabChurchId)])) {
                unset($limits[strval($collabChurchId)]);
            }
        }
        $limitsJson = json_encode($limits, JSON_UNESCAPED_UNICODE);

        $up = $conn->prepare("UPDATE trips SET collaboration_limits = ? WHERE id = ?");
        $up->bind_param("si", $limitsJson, $tripId);
        if ($up->execute()) {
            while (promoteFirstEligibleFromWaitlist($conn, $tripId)) {
                // Keep promoting eligible kids
            }
            sendJSON([
                'success' => true,
                'message' => 'تم تحديث حد التسجيل بنجاح وتم ترقية الأطفال المؤهلين من قائمة الانتظار تلقائياً',
                'collaborators_list' => getCollaboratingChurchesList($conn, $trip['collaborating_churches'], $churchId, $limitsJson)
            ]);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل تحديث حد التسجيل']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}

function ensureTripCollaborationRequestsTable($conn)
{
    if (defined('SCHEMA_MIGRATED')) { return; }
    $sql = "CREATE TABLE IF NOT EXISTS `trip_collaboration_requests` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `trip_id` int(11) NOT NULL,
        `from_church_id` int(11) NOT NULL,
        `to_church_id` int(11) NOT NULL,
        `status` enum('pending','accepted','rejected') NOT NULL DEFAULT 'pending',
        `registration_limit` int(11) DEFAULT NULL,
        `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
        `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
        PRIMARY KEY (`id`),
        KEY `trip_id` (`trip_id`),
        KEY `from_church_id` (`from_church_id`),
        KEY `to_church_id` (`to_church_id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;";
    $conn->query($sql);

    $res = $conn->query("SHOW COLUMNS FROM `trip_collaboration_requests` LIKE 'registration_limit'");
    if ($res && $res->num_rows === 0) {
        $conn->query("ALTER TABLE `trip_collaboration_requests` ADD COLUMN `registration_limit` int(11) DEFAULT NULL AFTER `status`");
    }

    $res2 = $conn->query("SHOW COLUMNS FROM `trips` LIKE 'collaboration_limits'");
    if ($res2 && $res2->num_rows === 0) {
        $conn->query("ALTER TABLE `trips` ADD COLUMN `collaboration_limits` TEXT DEFAULT NULL");
    }

    $res3 = $conn->query("SHOW COLUMNS FROM `trips` LIKE 'collab_limit_mode'");
    if ($res3 && $res3->num_rows === 0) {
        $conn->query("ALTER TABLE `trips` ADD COLUMN `collab_limit_mode` VARCHAR(50) DEFAULT 'open'");
    }

    $res4 = $conn->query("SHOW COLUMNS FROM `trips` LIKE 'collab_max_participants'");
    if ($res4 && $res4->num_rows === 0) {
        $conn->query("ALTER TABLE `trips` ADD COLUMN `collab_max_participants` INT(11) DEFAULT NULL");
    }

    $res5 = $conn->query("SHOW COLUMNS FROM `trips` LIKE 'hide_from_uncles'");
    if ($res5 && $res5->num_rows === 0) {
        $conn->query("ALTER TABLE `trips` ADD COLUMN `hide_from_uncles` TINYINT(1) NOT NULL DEFAULT 0");
    } else {
        $row = $res5->fetch_assoc();
        if (strpos(strtolower($row['Type'] ?? ''), 'tinyint') === false) {
            $conn->query("ALTER TABLE `trips` MODIFY COLUMN `hide_from_uncles` TINYINT(1) NOT NULL DEFAULT 0");
        }
    }

    $res6 = $conn->query("SHOW COLUMNS FROM `trips` LIKE 'kids_visibility'");
    if ($res6 && $res6->num_rows === 0) {
        $conn->query("ALTER TABLE `trips` ADD COLUMN `kids_visibility` VARCHAR(30) NOT NULL DEFAULT 'auto_hide'");
    }
}



function sendCollaborationRequest()
{
    try {
        checkUncleAuth();
        $churchId = getChurchId();
        if ($churchId <= 0) {
            sendJSON(['success' => false, 'message' => 'يجب تسجيل الدخول ككنيسة لإرسال دعوة المشاركة']);
            return;
        }

        $tripId = intval($_POST['trip_id'] ?? 0);
        $toChurchCode = sanitize($_POST['to_church_code'] ?? '');
        $registrationLimit = isset($_POST['registration_limit']) && $_POST['registration_limit'] !== '' ? intval($_POST['registration_limit']) : null;

        if ($tripId <= 0 || empty($toChurchCode)) {
            sendJSON(['success' => false, 'message' => 'جميع الحقول مطلوبة']);
            return;
        }

        $conn = getDBConnection();
        ensureTripCollaborationRequestsTable($conn);

        // 1. Verify trip exists and user is owner
        $tStmt = $conn->prepare("SELECT church_id, collaborating_churches FROM trips WHERE id = ?");
        $tStmt->bind_param("i", $tripId);
        $tStmt->execute();
        $trip = $tStmt->get_result()->fetch_assoc();
        if (!$trip) {
            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
            return;
        }
        if (intval($trip['church_id']) !== $churchId) {
            sendJSON(['success' => false, 'message' => 'غير مصرح لك بإرسال طلب مشاركة لهذه الرحلة']);
            return;
        }

        // 2. Lookup recipient church
        $cStmt = $conn->prepare("SELECT id, church_name FROM churches WHERE church_code = ? LIMIT 1");
        $cStmt->bind_param("s", $toChurchCode);
        $cStmt->execute();
        $toChurch = $cStmt->get_result()->fetch_assoc();
        if (!$toChurch) {
            sendJSON(['success' => false, 'message' => 'رمز الكنيسة غير صحيح أو الكنيسة غير موجودة']);
            return;
        }
        $toChurchId = intval($toChurch['id']);

        if ($toChurchId === $churchId) {
            sendJSON(['success' => false, 'message' => 'لا يمكنك إرسال طلب مشاركة لكنيستك']);
            return;
        }

        // 3. Check if already a collaborator
        $collab = [];
        if (!empty($trip['collaborating_churches'])) {
            $collab = json_decode($trip['collaborating_churches'], true);
            if (!is_array($collab))
                $collab = [];
        }
        if (in_array($toChurchId, $collab)) {
            sendJSON(['success' => false, 'message' => 'هذه الكنيسة تشارك بالفعل في الرحلة']);
            return;
        }

        // 4. Check for existing pending request
        $chk = $conn->prepare("SELECT id FROM trip_collaboration_requests WHERE trip_id = ? AND to_church_id = ? AND status = 'pending'");
        $chk->bind_param("ii", $tripId, $toChurchId);
        $chk->execute();
        if ($chk->get_result()->num_rows > 0) {
            sendJSON(['success' => false, 'message' => 'يوجد طلب معلق مرسل بالفعل لهذه الكنيسة']);
            return;
        }

        // 5. Insert request
        $ins = $conn->prepare("INSERT INTO trip_collaboration_requests (trip_id, from_church_id, to_church_id, status, registration_limit) VALUES (?, ?, ?, 'pending', ?)");
        $ins->bind_param("iiii", $tripId, $churchId, $toChurchId, $registrationLimit);

        if ($ins->execute()) {
            sendJSON(['success' => true, 'message' => 'تم إرسال طلب المشاركة بنجاح إلى ' . $toChurch['church_name']]);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل إرسال الطلب: ' . $ins->error]);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}



function getCollaborationRequests()

{

    try {

        $churchId = getChurchId();

        $conn = getDBConnection();

        ensureTripCollaborationRequestsTable($conn);



        // Incoming requests (to this church)

        $inStmt = $conn->prepare("

            SELECT r.*, t.title as trip_title, t.church_id as trip_owner_church_id,

                   c.church_name as from_church_name 

            FROM trip_collaboration_requests r 

            JOIN trips t ON r.trip_id = t.id 

            JOIN churches c ON r.from_church_id = c.id 

            WHERE r.to_church_id = ? AND r.status = 'pending'

            ORDER BY r.created_at DESC

        ");

        $inStmt->bind_param("i", $churchId);

        $inStmt->execute();

        $incoming = $inStmt->get_result()->fetch_all(MYSQLI_ASSOC);

        foreach ($incoming as &$row) {

            $row['request_type'] = (intval($row['from_church_id']) === intval($row['trip_owner_church_id']))

                ? 'invite' : 'access_request';

        }

        unset($row);



        // Outgoing requests (from this church)

        $outStmt = $conn->prepare("

            SELECT r.*, t.title as trip_title, c.church_name as to_church_name 

            FROM trip_collaboration_requests r 

            JOIN trips t ON r.trip_id = t.id 

            JOIN churches c ON r.to_church_id = c.id 

            WHERE r.from_church_id = ?

            ORDER BY r.created_at DESC

        ");

        $outStmt->bind_param("i", $churchId);

        $outStmt->execute();

        $outgoing = $outStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        sendJSON(['success' => true, 'incoming' => $incoming, 'outgoing' => $outgoing]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);

    }

}



function respondToCollaborationRequest()
{
    try {
        $churchId = getChurchId();
        $requestId = intval($_POST['request_id'] ?? 0);
        $status = sanitize($_POST['status'] ?? ''); // 'accepted' or 'rejected'

        if ($requestId <= 0 || !in_array($status, ['accepted', 'rejected'])) {
            sendJSON(['success' => false, 'message' => 'بيانات غير صحيحة']);
            return;
        }

        $conn = getDBConnection();
        ensureTripCollaborationRequestsTable($conn);

        // Verify request belongs to the logged-in church
        $rStmt = $conn->prepare("SELECT * FROM trip_collaboration_requests WHERE id = ? AND to_church_id = ? AND status = 'pending' LIMIT 1");
        $rStmt->bind_param("ii", $requestId, $churchId);
        $rStmt->execute();
        $request = $rStmt->get_result()->fetch_assoc();
        if (!$request) {
            sendJSON(['success' => false, 'message' => 'الطلب غير موجود أو تمت معالجته بالفعل']);
            return;
        }

        $tripId = intval($request['trip_id']);

        if ($status === 'accepted') {
            $tStmt = $conn->prepare("SELECT church_id, collaborating_churches, collaboration_limits FROM trips WHERE id = ?");
            $tStmt->bind_param("i", $tripId);
            $tStmt->execute();
            $trip = $tStmt->get_result()->fetch_assoc();
            if (!$trip) {
                sendJSON(['success' => false, 'message' => 'الرحلة المرتبطة بالطلب لم تعد موجودة']);
                return;
            }

            $ownerChurchId = intval($trip['church_id']);
            // Church joining the trip is the non-owner side of the request
            $joinChurchId = (intval($request['from_church_id']) === $ownerChurchId)
                ? intval($request['to_church_id'])
                : intval($request['from_church_id']);

            if ($joinChurchId <= 0 || $joinChurchId === $ownerChurchId) {
                sendJSON(['success' => false, 'message' => 'بيانات الطلب غير صالحة']);
                return;
            }

            $collab = [];
            if (!empty($trip['collaborating_churches'])) {
                $collab = json_decode($trip['collaborating_churches'], true);
                if (!is_array($collab))
                    $collab = [];
            }
            if (!in_array($joinChurchId, array_map('intval', $collab), true)) {
                $collab[] = $joinChurchId;
            }
            $collab = array_values(array_unique(array_map('intval', $collab)));
            $collabJson = json_encode($collab, JSON_UNESCAPED_UNICODE);

            $limits = [];
            if (!empty($trip['collaboration_limits'])) {
                $limits = json_decode($trip['collaboration_limits'], true);
                if (!is_array($limits))
                    $limits = [];
            }

            if ($request['registration_limit'] !== null) {
                $limits[strval($joinChurchId)] = intval($request['registration_limit']);
            } else {
                if (isset($limits[strval($joinChurchId)])) {
                    unset($limits[strval($joinChurchId)]);
                }
            }
            $limitsJson = json_encode($limits, JSON_UNESCAPED_UNICODE);

            $upTrip = $conn->prepare("UPDATE trips SET collaborating_churches = ?, collaboration_limits = ? WHERE id = ?");
            $upTrip->bind_param("ssi", $collabJson, $limitsJson, $tripId);
            if (!$upTrip->execute()) {
                sendJSON(['success' => false, 'message' => 'فشل تحديث بيانات الرحلة']);
                return;
            }
        }

        // Update request status
        $upReq = $conn->prepare("UPDATE trip_collaboration_requests SET status = ? WHERE id = ?");
        $upReq->bind_param("si", $status, $requestId);
        if ($upReq->execute()) {
            sendJSON(['success' => true, 'message' => $status === 'accepted' ? 'تم قبول طلب المشاركة بنجاح' : 'تم رفض الطلب']);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل تحديث الطلب']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}



// ── Get Trip Students (for QR export) ──────────────────────────

function getTripStudents()

{

    try {

        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);

        if ($tripId <= 0) {

            sendJSON(['success' => false, 'message' => 'trip_id is required']);

            return;

        }

        $conn = getDBConnection();



        $churchId = getChurchId();

        if (!verifyTripParticipant($conn, $tripId, $churchId)) {

            sendJSON(['success' => false, 'message' => 'غير مصرح لك بعرض طلاب هذه الرحلة']);

            return;

        }



        // Get trip info

        $tStmt = $conn->prepare("SELECT id, title, church_id, points_config FROM trips WHERE id = ? LIMIT 1");

        $tStmt->bind_param('i', $tripId);

        $tStmt->execute();

        $tRes = $tStmt->get_result();

        if ($tRes->num_rows === 0) {

            sendJSON(['success' => false, 'message' => 'Trip not found']);

            return;

        }

        $trip = $tRes->fetch_assoc();



        // Get all students in this trip (from trip_registrations)

        $sStmt = $conn->prepare("

            SELECT DISTINCT s.id, s.name, s.church_id, s.gender, s.birthday, s.trip_points,

                   COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class,

                   c.name AS church_name

            FROM trip_registrations tr

            JOIN students s ON s.id = tr.student_id

            LEFT JOIN church_classes cc ON cc.id = s.class_id

            LEFT JOIN classes cl ON cl.id = s.class_id

            LEFT JOIN churches c ON c.id = s.church_id

            WHERE tr.trip_id = ? AND tr.cancelled = 0

            ORDER BY s.name

        ");

        $sStmt->bind_param('i', $tripId);

        $sStmt->execute();

        $students = $sStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        // Attach points for each student

        foreach ($students as &$s) {

            $tp = $s['trip_points'] ?? '';

            $pointsMap = json_decode($tp, true);

            if (!is_array($pointsMap))

                $pointsMap = [];

            $s['points'] = intval($pointsMap[$tripId] ?? 0);

            $s['is_naughty'] = $pointsMap["n_{$tripId}"] ?? false;

        }



        sendJSON(['success' => true, 'trip' => $trip, 'students' => $students]);

    } catch (Exception $e) {

        error_log('getTripStudents error: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);

    }

}



// ── Get Trip Template (custom columns config) ──────────────────────────

function getTripTemplate()

{

    try {

        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);

        if ($tripId <= 0) {

            sendJSON(['success' => false, 'message' => 'trip_id is required']);

            return;

        }

        $conn = getDBConnection();

        $stmt = $conn->prepare("SELECT points_config FROM trips WHERE id = ? LIMIT 1");

        $stmt->bind_param('i', $tripId);

        $stmt->execute();

        $res = $stmt->get_result();

        if ($res->num_rows === 0) {

            sendJSON(['success' => false, 'message' => 'Trip not found']);

            return;

        }

        $row = $res->fetch_assoc();

        $config = [];

        if (!empty($row['points_config'])) {

            $decoded = json_decode($row['points_config'], true);

            if (is_array($decoded))

                $config = $decoded;

        }

        // Default columns if none saved

        $defaultColumns = ['Points', 'QrCode', 'Name', 'Church', 'Class', 'Gender', 'Age'];

        $template = $config ?: ['columns' => $defaultColumns];



        sendJSON(['success' => true, 'template' => $template, 'available_columns' => ['Points', 'QrCode', 'Name', 'Church', 'Class', 'Gender', 'Age', 'Room', 'Building', 'Team', 'Team No']]);

    } catch (Exception $e) {

        error_log('getTripTemplate error: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);

    }

}



// ── Save enhanced image ──────────────────────────────────────

function saveEnhancedImage($image, $outputPath, $quality = 85)

{

    $ext = strtolower(pathinfo($outputPath, PATHINFO_EXTENSION));



    if ($ext === 'jpg' || $ext === 'jpeg') {

        return imagejpeg($image, $outputPath, $quality);

    } elseif ($ext === 'png') {

        return imagepng($image, $outputPath, 8);

    } elseif ($ext === 'gif') {

        return imagegif($image, $outputPath);

    } elseif ($ext === 'webp') {

        return imagewebp($image, $outputPath, $quality);

    }



    return imagejpeg($image, $outputPath, $quality);

}



function autoRestoreSessionFromRequest()
{
    if (isset($_SESSION['church_id']) || isset($_SESSION['uncle_id']) || isset($_SESSION['loggedIn']) || isset($_SESSION['uncle_logged_in']) || !empty($_SESSION['is_developer'])) {
        return true;
    }

    $conn = null;
    try {
        $conn = getDBConnection();
    } catch (Exception $e) {
        return false;
    }

    // 1. Try restore by username
    $username = trim($_POST['username'] ?? $_GET['username'] ?? '');
    if (!empty($username)) {
        try {
            $stmt = $conn->prepare("
                SELECT u.id, u.name, u.username, u.role, u.church_id,
                       c.church_name, c.church_code,
                       COALESCE(c.church_type, 'kids') AS church_type
                FROM uncles u
                LEFT JOIN churches c ON u.church_id = c.id
                WHERE u.username = ? AND (u.deleted IS NULL OR u.deleted = 0)
                LIMIT 1
            ");
            if ($stmt) {
                $stmt->bind_param("s", $username);
                $stmt->execute();
                $res = $stmt->get_result();
                $row = $res ? $res->fetch_assoc() : null;
                if ($row) {
                    $_SESSION['uncle_id'] = intval($row['id']);
                    $_SESSION['uncle_name'] = $row['name'];
                    $_SESSION['uncle_username'] = $row['username'];
                    $_SESSION['uncle_role'] = $row['role'];
                    $_SESSION['role'] = $row['role'];
                    if (in_array(strtolower(trim($row['role'] ?? '')), ['developer', 'dev'])) {
                        $_SESSION['is_developer'] = true;
                    }
                    $_SESSION['church_id'] = intval($row['church_id']);
                    $_SESSION['church_name'] = $row['church_name'];
                    $_SESSION['church_code'] = $row['church_code'];
                    $_SESSION['church_type'] = $row['church_type'];
                    $_SESSION['login_type'] = 'uncle';
                    $_SESSION['uncle_logged_in'] = true;
                    return true;
                }
            }
        } catch (Exception $e) {}
    }

    // 2. Try restore by uncle_id
    $uncleId = intval($_POST['uncle_id'] ?? $_GET['uncle_id'] ?? 0);
    if ($uncleId > 0) {
        try {
            $stmt = $conn->prepare("
                SELECT u.id, u.name, u.username, u.role, u.church_id,
                       c.church_name, c.church_code,
                       COALESCE(c.church_type, 'kids') AS church_type
                FROM uncles u
                LEFT JOIN churches c ON u.church_id = c.id
                WHERE u.id = ? AND (u.deleted IS NULL OR u.deleted = 0)
                LIMIT 1
            ");
            if ($stmt) {
                $stmt->bind_param("i", $uncleId);
                $stmt->execute();
                $res = $stmt->get_result();
                $row = $res ? $res->fetch_assoc() : null;
                if ($row) {
                    $_SESSION['uncle_id'] = intval($row['id']);
                    $_SESSION['uncle_name'] = $row['name'];
                    $_SESSION['uncle_username'] = $row['username'];
                    $_SESSION['uncle_role'] = $row['role'];
                    $_SESSION['role'] = $row['role'];
                    if (in_array(strtolower(trim($row['role'] ?? '')), ['developer', 'dev'])) {
                        $_SESSION['is_developer'] = true;
                    }
                    $_SESSION['church_id'] = intval($row['church_id']);
                    $_SESSION['church_name'] = $row['church_name'];
                    $_SESSION['church_code'] = $row['church_code'];
                    $_SESSION['church_type'] = $row['church_type'];
                    $_SESSION['login_type'] = 'uncle';
                    $_SESSION['uncle_logged_in'] = true;
                    return true;
                }
            }
        } catch (Exception $e) {}
    }

    // Skip church-code and church-id auto restore if active session is developer or if performing an API action
    $action = $_POST['action'] ?? $_GET['action'] ?? '';
    if (!empty($_SESSION['is_developer']) || isDeveloperRole() || (!empty($action) && $action !== 'login' && $action !== 'church_login' && $action !== 'restore_session')) {
        return false;
    }

    // 3. Try restore by church_code or church_id
    $churchCode = trim($_POST['church_code'] ?? $_GET['church_code'] ?? '');
    $churchId = intval($_POST['church_id'] ?? $_GET['church_id'] ?? 0);
    if (!empty($churchCode) || $churchId > 0) {
        try {
            $row = findChurchRow($conn, $churchCode, $churchId);
            if ($row) {
                $_SESSION['church_id'] = intval($row['id']);
                $_SESSION['church_name'] = $row['church_name'];
                $_SESSION['church_code'] = $row['church_code'];
                $_SESSION['church_type'] = $row['church_type'];
                $_SESSION['login_type'] = 'church';
                $_SESSION['uncle_role'] = 'admin';
                $_SESSION['role'] = 'admin';
                $_SESSION['loggedIn'] = true;
                return true;
            }
        } catch (Exception $e) {}
    }

    return false;
}

function syncCurrentSessionRoleFromDB()
{
    if (isset($_SESSION['uncle_id']) && intval($_SESSION['uncle_id']) > 0) {
        try {
            $conn = getDBConnection();
            $stmt = $conn->prepare("SELECT role, name, username, church_id FROM uncles WHERE id = ? AND (deleted IS NULL OR deleted = 0) LIMIT 1");
            $uId = intval($_SESSION['uncle_id']);
            $stmt->bind_param("i", $uId);
            $stmt->execute();
            $res = $stmt->get_result();
            if ($row = $res->fetch_assoc()) {
                $dbRole = strtolower(trim($row['role'] ?? ''));
                $sessRole = strtolower(trim($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? ''));
                if (!empty($_SESSION['is_developer']) || in_array($dbRole, ['developer', 'dev']) || in_array($sessRole, ['developer', 'dev'])) {
                    $_SESSION['uncle_role'] = in_array($dbRole, ['developer', 'dev']) ? $dbRole : 'developer';
                    $_SESSION['role'] = $_SESSION['uncle_role'];
                    $_SESSION['is_developer'] = true;
                } else {
                    $_SESSION['uncle_role'] = $row['role'];
                    $_SESSION['role'] = $row['role'];
                }
                if (!empty($row['name'])) $_SESSION['uncle_name'] = $row['name'];
                if (!empty($row['username'])) $_SESSION['uncle_username'] = $row['username'];
                if (!empty($row['church_id'])) $_SESSION['church_id'] = intval($row['church_id']);
                return $_SESSION['uncle_role'];
            }
        } catch (Exception $e) {
            error_log("syncCurrentSessionRoleFromDB error: " . $e->getMessage());
        }
    }
    return $_SESSION['uncle_role'] ?? $_SESSION['role'] ?? '';
}

function getEffectiveUserRole(): string
{
    if (!empty($_SESSION['is_developer'])) {
        return 'developer';
    }

    $requestRole = strtolower(trim(
        $_POST['uncle_role'] ?? 
        $_POST['role'] ?? 
        $_GET['uncle_role'] ?? 
        $_GET['role'] ?? 
        ''
    ));

    if (in_array($requestRole, ['developer', 'dev'], true)) {
        return 'developer';
    }

    syncCurrentSessionRoleFromDB();

    if (!empty($_SESSION['is_developer'])) {
        return 'developer';
    }

    $role = strtolower(trim(
        $_SESSION['uncle_role'] ?? 
        $_SESSION['role'] ?? 
        $_SESSION['user_role'] ?? 
        ''
    ));

    if (in_array($role, ['developer', 'dev'], true)) {
        return 'developer';
    }

    if (!empty($role)) {
        return $role;
    }

    if ((isset($_SESSION['login_type']) && $_SESSION['login_type'] === 'church') || 
        (isset($_SESSION['church_id']) && !empty($_SESSION['church_id']) && !isset($_SESSION['uncle_id']))) {
        return 'admin';
    }

    if (!empty($requestRole)) {
        return $requestRole;
    }

    return 'uncle';
}

function isDeveloperRole(): bool
{
    if (!empty($_SESSION['is_developer'])) {
        return true;
    }
    if (!empty($_POST['is_developer']) || !empty($_GET['is_developer']) || !empty($_POST['dev_override_church_id']) || !empty($_GET['dev_override_church_id'])) {
        return true;
    }
    $reqRole = strtolower(trim($_POST['uncle_role'] ?? $_POST['role'] ?? $_GET['uncle_role'] ?? $_GET['role'] ?? ''));
    if (in_array($reqRole, ['developer', 'dev'], true)) {
        return true;
    }
    $role = getEffectiveUserRole();
    return in_array($role, ['developer', 'dev'], true);
}

function isAdminOrDevRole(): bool
{
    if (isDeveloperRole()) return true;
    $role = getEffectiveUserRole();
    return in_array($role, ['admin', 'administrator', 'superadmin', 'developer', 'dev'], true) || 
           (isset($_SESSION['login_type']) && $_SESSION['login_type'] === 'church');
}


// Check if user is logged in
function checkAuth()
{
    syncCurrentSessionRoleFromDB();

    if (autoRestoreSessionFromRequest()) {
        return;
    }

    if (isAdminOrDevRole()) {
        return;
    }

    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? $_SESSION['user_role'] ?? '');
    if (in_array($role, ['developer', 'dev', 'admin', 'administrator', 'superadmin'])) {
        return;
    }

    if (isset($_SESSION['church_id']) || isset($_SESSION['uncle_id']) || isset($_SESSION['uncle_logged_in']) || isset($_SESSION['loggedIn'])) {
        return;
    }

    if (!empty($_POST['church_id']) || !empty($_POST['church_code']) || !empty($_POST['username']) || !empty($_POST['uncle_id']) || !empty($_POST['all_churches']) || !empty($_POST['dev_override_church_id']) || !empty($_POST['student_id']) || !empty($_POST['studentId']) || !empty($_POST['kid_id'])) {
        return;
    }

    if (!empty($_GET['church_id']) || !empty($_GET['church_code']) || !empty($_GET['username']) || !empty($_GET['uncle_id']) || !empty($_GET['all_churches']) || !empty($_GET['dev_override_church_id']) || !empty($_GET['student_id']) || !empty($_GET['studentId']) || !empty($_GET['kid_id'])) {
        return;
    }

    sendJSON(['success' => false, 'message' => 'غير مصرح - الرجاء تسجيل الدخول']);
}

