        return;
    }

    if (!empty($_GET['church_id']) || !empty($_GET['church_code']) || !empty($_GET['username']) || !empty($_GET['uncle_id']) || !empty($_GET['all_churches']) || !empty($_GET['dev_override_church_id']) || !empty($_GET['student_id']) || !empty($_GET['kid_id'])) {
