// ===== BULK SAVE IMPORTED UNCLES =====

function bulkSaveImportedUncles()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $conn = getDBConnection();

        $conn->begin_transaction();



        $unclesJson = $_POST['uncles'] ?? '';

        $uncles = json_decode($unclesJson, true);



        if (!is_array($uncles)) {

            sendJSON(['success' => false, 'message' => 'بيانات الخُدام غير صالحة']);

            return;

        }



        $addedCount = 0;

        $errors = [];



        foreach ($uncles as $u) {

            $name = sanitize($u['name'] ?? '');

            $username = sanitize($u['username'] ?? '');

            $password = $u['password'] ?? '';

            $gender = sanitize($u['gender'] ?? 'male');

            $phone = sanitize($u['phone'] ?? '');

            $role = sanitize($u['role'] ?? 'uncle');

            $classesRaw = $u['classes'] ?? '';



            if (empty($name) || empty($username) || empty($password)) {

                $errors[] = "الاسم واسم المستخدم وكلمة المرور مطلوبة للخادم: " . ($name ?: $username ?: 'مجهول');

                continue;

            }



            // Check if username already exists in database

            $userCheck = $conn->prepare("SELECT id FROM uncles WHERE username = ?");

            $userCheck->bind_param("s", $username);

            $userCheck->execute();

            if ($userCheck->get_result()->num_rows > 0) {

                $errors[] = "اسم المستخدم '$username' مستخدم بالفعل";

                continue;

            }



            $passwordHash = hash('sha256', $password);



            // Normalize role

            if ($role !== 'admin' && $role !== 'uncle' && $role !== 'developer') {

                $role = 'uncle';

            }



            // Normalize gender

            if ($gender !== 'male' && $gender !== 'female') {

                $gender = 'male';

            }



            // Insert uncle

            $stmt = $conn->prepare("

                INSERT INTO uncles (church_id, name, username, password_hash, role, gender, phone)

                VALUES (?, ?, ?, ?, ?, ?, ?)

            ");

            $stmt->bind_param("issssss", $churchId, $name, $username, $passwordHash, $role, $gender, $phone);



            if ($stmt->execute()) {

                $newUncleId = $conn->insert_id;

                $addedCount++;



                // Process classes

                $assignedClasses = [];

                if (is_array($classesRaw)) {

                    $assignedClasses = $classesRaw;

                } elseif (!empty($classesRaw)) {

                    // Split comma-separated classes

                    $assignedClasses = array_map('trim', explode(',', $classesRaw));

                }



                $assignedClasses = array_filter(array_map('sanitize', $assignedClasses));



                if (!empty($assignedClasses)) {

                    saveUncleClasses($newUncleId, $churchId, $assignedClasses);

                }



                // Audit log for each uncle added

                writeAuditLog('uncle_add', 'uncle', $newUncleId, $name, null, [

                    'name' => $name,

                    'username' => $username,

                    'role' => $role,

                    'church_id' => $churchId,

                    'classes' => $assignedClasses,

                    'gender' => $gender,

                    'phone' => $phone,

                    'imported' => true

                ], 'إضافة خادم جديد عبر الاستيراد الجماعي');

            } else {

                $errors[] = "فشل إضافة الخادم '$name': " . $conn->error;

            }

        }



        if (!empty($errors) && $addedCount === 0) {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل الاستيراد بالكامل', 'errors' => $errors]);

        } else {

            $conn->commit();

            $msg = "تم استيراد $addedCount من الخدام بنجاح.";

            if (!empty($errors)) {

                $msg .= " ولكن حدثت بعض الأخطاء: " . count($errors);

            }

            sendJSON(['success' => true, 'message' => $msg, 'errors' => $errors]);

        }



    } catch (Exception $e) {

        if (isset($conn)) {

            $conn->rollback();

        }

        error_log("bulkSaveImportedUncles error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في السيرفر أثناء حفظ الخُدام: ' . $e->getMessage()]);

    }

}





// ===== GENERATE EXCEL TEMPLATE =====

function generateExcelTemplate()
{
    try {
        if (file_exists('vendor/autoload.php')) {
            require_once 'vendor/autoload.php'; // If using PhpSpreadsheet
        }

        $spreadsheetClass = 'PhpOffice\\PhpSpreadsheet\\Spreadsheet';
        $writerClass = 'PhpOffice\\PhpSpreadsheet\\Writer\\Xlsx';
        $fillClass = 'PhpOffice\\PhpSpreadsheet\\Style\\Fill';

        if (!class_exists($spreadsheetClass) || !class_exists($writerClass)) {
            generateKidsTemplate();
            return;
        }

        $spreadsheet = new $spreadsheetClass();

        // Define all classes
        $classes = ['حضانة', 'أولى', 'تانية', 'تالتة', 'رابعة', 'خامسة', 'سادسة'];

        foreach ($classes as $index => $class) {
            if ($index > 0) {
                $spreadsheet->createSheet();
            }

            $sheet = $spreadsheet->setActiveSheetIndex($index);
            $sheet->setTitle($class);

            // Set headers
            $sheet->setCellValue('A1', 'الاسم');
            $sheet->setCellValue('B1', 'العنوان');
            $sheet->setCellValue('C1', 'الهاتف');
            $sheet->setCellValue('D1', 'تاريخ الميلاد (DD/MM/YYYY)');

            // Style headers
            $sheet->getStyle('A1:D1')->getFont()->setBold(true);

            $fillSolid = defined("$fillClass::FILL_SOLID") ? constant("$fillClass::FILL_SOLID") : 'solid';
            $sheet->getStyle('A1:D1')->getFill()
                ->setFillType($fillSolid)
                ->getStartColor()->setARGB('FF4F46E5');

            $sheet->getStyle('A1:D1')->getFont()->getColor()->setARGB('FFFFFFFF');

            // Set column widths
            $sheet->getColumnDimension('A')->setWidth(30);
            $sheet->getColumnDimension('B')->setWidth(40);
            $sheet->getColumnDimension('C')->setWidth(20);
            $sheet->getColumnDimension('D')->setWidth(25);

            // Add instructions
            $sheet->setCellValue('F1', 'تعليمات:');
            $sheet->setCellValue('F2', '1. املأ البيانات في الأعمدة A-D فقط');
            $sheet->setCellValue('F3', '2. تاريخ الميلاد: استخدم صيغة DD/MM/YYYY');
            $sheet->setCellValue('F4', '3. رقم الهاتف: ابدأ بـ 01XXXXXXXXX');
            $sheet->setCellValue('F5', '4. لا تغير تنسيق الأعمدة');
        }

        // Set first sheet as active
        $spreadsheet->setActiveSheetIndex(0);

        // Create Excel file
        $writer = new $writerClass($spreadsheet);

        header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        header('Content-Disposition: attachment;filename="kids_template_' . date('Y-m-d') . '.xlsx"');
        header('Cache-Control: max-age=0');

        $writer->save('php://output');
        exit;

    } catch (Throwable $e) {
        // Fallback to CSV if Excel not available
        generateKidsTemplate();
    }
}



// ===== EXPORT ALL EXISTING KIDS AS CSV (pre-filled for editing) =====

function exportKidsData()

{

    try {

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'معرف الكنيسة مطلوب']);

            return;

        }



        $conn = getDBConnection();



        // ── Load custom field definitions ─────────────────────────

        ensureChurchSettingsTable($conn);

        $cfStmt = $conn->prepare("SELECT custom_field FROM church_settings WHERE church_id = ? LIMIT 1");

        $cfStmt->bind_param("i", $churchId);

        $cfStmt->execute();

        $cfRow = $cfStmt->get_result()->fetch_assoc();

        $customFieldDefs = [];

        if ($cfRow && !empty($cfRow['custom_field'])) {

            $cfData = json_decode($cfRow['custom_field'], true);

            if (is_array($cfData)) {

                if (isset($cfData[0]) && is_array($cfData[0]))

                    $customFieldDefs = $cfData;

                elseif (!empty($cfData['name']))

                    $customFieldDefs = [$cfData];

            }

        }



        // ── Load all students for this church ─────────────────────

        $stmt = $conn->prepare("

            SELECT s.id, s.name, s.address, s.phone, s.emergency_phone, s.medical_notes, s.birthday, s.gender, s.custom_info,

                   COALESCE(cc.arabic_name, gc.arabic_name, s.class) AS class_name

            FROM students s

            LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id AND cc.is_active = 1

            LEFT JOIN classes gc        ON gc.id = s.class_id

            WHERE s.church_id = ?

              AND COALESCE(s.enrollment_status, 'active') = 'active'

            ORDER BY class_name, s.name

        ");

        $stmt->bind_param("i", $churchId);

        $stmt->execute();

        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);



        // ── Fetch Sibling Names ───────────────────────────────────

        $siblingsMap = [];

        $sibStmt = $conn->prepare("

            SELECT ssgm.student_id, s_sib.name AS sibling_name

            FROM student_sibling_group_members ssgm

            INNER JOIN student_sibling_group_members ssgm2 

                ON ssgm.group_id = ssgm2.group_id AND ssgm.student_id != ssgm2.student_id

            INNER JOIN students s_sib 

                ON ssgm2.student_id = s_sib.id

            WHERE ssgm.church_id = ?

        ");

        if ($sibStmt) {

            $sibStmt->bind_param("i", $churchId);

            $sibStmt->execute();

            $sibRes = $sibStmt->get_result();

            while ($sibRow = $sibRes->fetch_assoc()) {

                $sid = (int) $sibRow['student_id'];

                $siblingsMap[$sid][] = $sibRow['sibling_name'];

            }

        }



        // ── Build CSV ─────────────────────────────────────────────

        // Columns: student_id, class, name, address, phone, emergency_phone, medical_notes, birthday, gender, siblings [, custom_fields...]

        // Quote custom field names to handle commas/special characters safely

        $customHeadersQuoted = array_map(function ($f) {

            $n = $f['name'] ?? '';

            return '"' . str_replace('"', '""', $n) . '"';

        }, $customFieldDefs);

        $headerLine = 'student_id,class,name,address,phone,emergency_phone,medical_notes,birthday,gender,siblings';

        if ($customHeadersQuoted)

            $headerLine .= ',' . implode(',', $customHeadersQuoted);

        $headerLine .= "\n";



        $csvContent = $headerLine;

        foreach ($rows as $r) {

            $id = (int) $r['id'];

            $class = $r['class_name'] ?? '';

            $name = $r['name'] ?? '';

            $address = $r['address'] ?? '';

            $phone = $r['phone'] ?? '';

            $emergencyPhone = $r['emergency_phone'] ?? '';

            $medicalNotes = $r['medical_notes'] ?? '';

            $birthday = $r['birthday'] ? date('d/m/Y', strtotime($r['birthday'])) : '';

            $gender = $r['gender'] ?? '';

            $genderLabel = '';

            if ($gender === 'female') {

                $genderLabel = 'أنثى';

            } elseif ($gender === 'male') {

                $genderLabel = 'ذكر';

            }

            $studentSiblings = isset($siblingsMap[$id]) ? implode(', ', $siblingsMap[$id]) : '';



            // Escape cell: wrap in quotes, escape internal quotes

            $esc = function ($v) {

                return '"' . str_replace('"', '""', $v) . '"';

            };



            $line = $id . ',' . $esc($class) . ',' . $esc($name) . ',' .

                $esc($address) . ',' . $esc($phone) . ',' . $esc($emergencyPhone) . ',' .

                $esc($medicalNotes) . ',' . $esc($birthday) . ',' . $esc($genderLabel) . ',' . $esc($studentSiblings);



            // Custom fields

            if ($customFieldDefs) {

                $info = !empty($r['custom_info']) ? json_decode($r['custom_info'], true) : [];

                if (!is_array($info))

                    $info = [];

                foreach ($customFieldDefs as $cfIdx => $cfDef) {

                    $key = $cfDef['key'] ?? ('field_' . $cfIdx);

                    // Support both new key format and legacy {'value':...}

                    $val = $info[$key] ?? ($info['field_' . $cfIdx] ?? ($cfIdx === 0 ? ($info['value'] ?? '') : ''));

                    $line .= ',' . $esc((string) $val);

                }

            }



            $csvContent .= $line . "\n";

        }



        header('Content-Type: text/csv; charset=utf-8');

        header('Content-Disposition: attachment; filename="kids_data_' . date('Y-m-d') . '.csv"');

        header('Cache-Control: no-cache, no-store, must-revalidate');

        echo chr(0xEF) . chr(0xBB) . chr(0xBF); // UTF-8 BOM for Excel

        echo $csvContent;

        exit;



    } catch (Exception $e) {

        error_log("exportKidsData error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تصدير البيانات: ' . $e->getMessage()]);

    }

}



function bulkAddKids()

{

    try {

        $churchId = getChurchId();

        $csvData = $_FILES['csvFile']['tmp_name'] ?? '';



        if (empty($csvData) || !file_exists($csvData)) {

            sendJSON(['success' => false, 'message' => 'الرجاء تحميل ملف CSV']);

            return;

        }



        $conn = getDBConnection();

        $conn->begin_transaction();



        // ── Read custom field definitions for this church ─────────

        $customFieldDefs = [];

        ensureChurchSettingsTable($conn);

        $cfStmt2 = $conn->prepare("SELECT custom_field FROM church_settings WHERE church_id = ? LIMIT 1");

        $cfStmt2->bind_param("i", $churchId);

        $cfStmt2->execute();

        $cfRow2 = $cfStmt2->get_result()->fetch_assoc();

        if ($cfRow2 && !empty($cfRow2['custom_field'])) {

            $cfData2 = json_decode($cfRow2['custom_field'], true);

            if (is_array($cfData2)) {

                if (isset($cfData2[0]) && is_array($cfData2[0]))

                    $customFieldDefs = $cfData2;

                elseif (!empty($cfData2['name']))

                    $customFieldDefs = [$cfData2];

            }

        }



        // ── Build class lookup map ────────────────────────────────

        $churchClasses = getClassesForChurch($churchId);

        $classMap = [];

        foreach ($churchClasses as $cls) {

            $key1 = mb_strtolower(trim($cls['arabic_name']));

            $key2 = mb_strtolower(trim($cls['code'] ?? ''));

            $classMap[$key1] = ['id' => $cls['id'], 'arabic_name' => $cls['arabic_name']];

            if (!empty($key2))

                $classMap[$key2] = ['id' => $cls['id'], 'arabic_name' => $cls['arabic_name']];

        }



        $addedCount = 0;

        $updatedCount = 0;

        $errorCount = 0;

        $skippedEmpty = 0;

        $errors = [];



        // ── Read CSV ──────────────────────────────────────────────

        $file = fopen($csvData, 'r');

        $bom = fread($file, 3);

        if ($bom !== chr(0xEF) . chr(0xBB) . chr(0xBF))

            rewind($file);



        // Read and detect header

        $headerRow = fgetcsv($file);

        $headerRow = array_map(function ($h) {

            return mb_strtolower(trim(str_replace('"', '', $h)));

        }, $headerRow);



        // Detect mode: does the CSV have a student_id column?

        $colStudentId = array_search('student_id', $headerRow);

        $isUpdateMode = $colStudentId !== false;



        // Detect column positions (flexible — works for both template and export formats)

        $colClass = array_search('class', $headerRow) !== false ? array_search('class', $headerRow) : ($isUpdateMode ? 1 : 0);

        $colName = array_search('name', $headerRow) !== false ? array_search('name', $headerRow) : ($isUpdateMode ? 2 : 1);

        $colAddress = array_search('address', $headerRow) !== false ? array_search('address', $headerRow) : ($isUpdateMode ? 3 : 2);

        $colPhone = array_search('phone', $headerRow) !== false ? array_search('phone', $headerRow) : ($isUpdateMode ? 4 : 3);

        $colBirthday = array_search('birthday', $headerRow) !== false ? array_search('birthday', $headerRow) : ($isUpdateMode ? 5 : 4);



        // Custom field columns: match by field key (e.g. "field_0") or by display name as fallback

        // The CSV header uses the field's display name (quoted), so we search for it.

        // We also check the key directly in case the header was generated with keys.

        $customColMap = []; // cfIdx => headerColIdx

        foreach ($customFieldDefs as $cfIdx => $cfDef) {

            $cfKey = $cfDef['key'] ?? ('field_' . $cfIdx);

            $cfNameLower = mb_strtolower(trim($cfDef['name'] ?? ''));



            // Try matching by display name first (normal flow)

            $found = false;

            foreach ($headerRow as $hIdx => $hVal) {

                $hLower = mb_strtolower(trim($hVal));

                if ($hLower === $cfNameLower || $hLower === $cfKey) {

                    $customColMap[$cfIdx] = $hIdx;

                    $found = true;

                    break;

                }

            }

            if (!$found) {

                // Positional fallback: custom fields start at col 5 (add mode) or 6 (update mode)

                $basePos = $isUpdateMode ? 6 : 5;

                $customColMap[$cfIdx] = $basePos + $cfIdx;

            }

        }



        error_log("bulkAddKids: isUpdateMode=" . ($isUpdateMode ? 'true' : 'false') . " | headerRow=" . implode('|', $headerRow));

        error_log("bulkAddKids: customFieldDefs count=" . count($customFieldDefs) . " | customColMap=" . json_encode($customColMap));



        $lineNumber = 1;



        while (($row = fgetcsv($file)) !== false) {

            $lineNumber++;

            // Pad to max needed index

            $maxIdx = max(array_merge(

                [$colClass, $colName, $colAddress, $colPhone, $colBirthday],

                $isUpdateMode ? [$colStudentId] : [],

                array_values($customColMap)

            ));

            while (count($row) <= $maxIdx)

                $row[] = '';



            $studentId = $isUpdateMode ? intval($row[$colStudentId] ?? 0) : 0;

            $classRaw = trim($row[$colClass] ?? '');

            $name = trim($row[$colName] ?? '');

            $address = trim($row[$colAddress] ?? '');

            $phone = trim($row[$colPhone] ?? '');

            $birthday = trim($row[$colBirthday] ?? '');



            // Custom field values

            $customRaws = [];

            foreach ($customFieldDefs as $cfIdx => $cfDef) {

                $customRaws[$cfIdx] = trim($row[$customColMap[$cfIdx]] ?? '');

            }



            if (empty($name)) {

                $skippedEmpty++;

                continue;

            }



            // ── Resolve class ─────────────────────────────────────

            $classId = 0;

            $className = $classRaw;

            if (!empty($classRaw)) {

                $lookupKey = mb_strtolower(trim($classRaw));

                if (isset($classMap[$lookupKey])) {

                    $classId = $classMap[$lookupKey]['id'];

                    $className = $classMap[$lookupKey]['arabic_name'];

                } else {

                    $errors[] = "السطر $lineNumber ($name): الفصل '$classRaw' غير معروف — تم التجاهل";

                    $errorCount++;

                    continue;

                }

            } elseif ($studentId > 0) {

                // In update mode, class is optional — keep existing if blank

                $existingStmt = $conn->prepare("SELECT class_id, class FROM students WHERE id = ? AND church_id = ?");

                $existingStmt->bind_param("ii", $studentId, $churchId);

                $existingStmt->execute();

                $existing = $existingStmt->get_result()->fetch_assoc();

                if ($existing) {

                    $classId = (int) $existing['class_id'];

                    $className = $existing['class'];

                }

            }



            if (!$classId && !$studentId) {

                $errors[] = "السطر $lineNumber ($name): الفصل مطلوب — تم التجاهل";

                $errorCount++;

                continue;

            }



            // ── Birthday ──────────────────────────────────────────

            $formattedBirthday = null;

            if (!empty($birthday)) {

                $formattedBirthday = formatDateToDB($birthday);

                if (!$formattedBirthday) {

                    $errors[] = "السطر $lineNumber ($name): تاريخ الميلاد '$birthday' غير صالح — تم الإضافة بدون تاريخ";

                }

            }



            // ── Phone cleaning ────────────────────────────────────

            $cleanPhone = trim($phone);

            if (preg_match('/^[\d.]+[eE][+\-]?\d+$/', $cleanPhone))

                $cleanPhone = number_format((float) $cleanPhone, 0, '.', '');

            $cleanPhone = preg_replace('/[^\d]/', '', $cleanPhone);

            if (!empty($cleanPhone)) {

                $len = strlen($cleanPhone);

                if ($len === 10 && $cleanPhone[0] === '1')

                    $cleanPhone = '0' . $cleanPhone;

                elseif ($len === 11 && substr($cleanPhone, 0, 2) !== '01')

                    $cleanPhone = '0' . substr($cleanPhone, 0, 10);

                elseif ($len < 10)

                    $cleanPhone = '';

                elseif ($len > 11)

                    $cleanPhone = substr($cleanPhone, -11);

            }

            if (!empty($cleanPhone) && !preg_match('/^01[0-9]{9}$/', $cleanPhone))

                $cleanPhone = '';



            // ── Build custom_info JSON ────────────────────────────

            $customInfoJson = null;

            if (!empty($customFieldDefs)) {

                $infoObj = [];

                foreach ($customFieldDefs as $cfIdx => $cfDef) {

                    $val = $customRaws[$cfIdx] ?? '';

                    if ($val !== '') {

                        $key = $cfDef['key'] ?? ('field_' . $cfIdx);

                        $infoObj[$key] = $val;

                    }

                }

                if (!empty($infoObj))

                    $customInfoJson = json_encode($infoObj, JSON_UNESCAPED_UNICODE);

            }



            // ══════════════════════════════════════════════════════

            // UPDATE MODE — student_id present in CSV

            // ══════════════════════════════════════════════════════

            if ($isUpdateMode && $studentId > 0) {

                // Verify the student belongs to this church

                $verifyStmt = $conn->prepare("SELECT id FROM students WHERE id = ? AND church_id = ?");

                $verifyStmt->bind_param("ii", $studentId, $churchId);

                $verifyStmt->execute();

                if (!$verifyStmt->get_result()->fetch_assoc()) {

                    $errors[] = "السطر $lineNumber ($name): ID $studentId غير موجود أو لا يخص هذه الكنيسة — تم التجاهل";

                    $errorCount++;

                    continue;

                }



                // Build UPDATE — only update fields that are non-empty in CSV

                // (so leaving a cell blank doesn't erase existing data)

                $setParts = ["name = ?", "updated_at = NOW()"];

                $setTypes = "s";

                $setValues = [$name];



                if ($classId > 0) {

                    $setParts[] = "class_id = ?";

                    $setParts[] = "class = ?";

                    $setTypes .= "is";

                    $setValues[] = $classId;

                    $setValues[] = $className;

                }

                if ($address !== '') {

                    $setParts[] = "address = ?";

                    $setTypes .= "s";

                    $setValues[] = $address;

                }

                if ($cleanPhone !== '') {

                    $setParts[] = "phone = ?";

                    $setTypes .= "s";

                    $setValues[] = $cleanPhone;

                }

                if ($formattedBirthday !== null) {

                    $setParts[] = "birthday = ?";

                    $setTypes .= "s";

                    $setValues[] = $formattedBirthday;

                }

                if ($customInfoJson !== null) {

                    $setParts[] = "custom_info = ?";

                    $setTypes .= "s";

                    $setValues[] = $customInfoJson;

                }



                $setTypes .= "ii"; // WHERE id = ? AND church_id = ?

                $setValues[] = $studentId;

                $setValues[] = $churchId;



                $updateSql = "UPDATE students SET " . implode(', ', $setParts) . " WHERE id = ? AND church_id = ?";

                $updateStmt = $conn->prepare($updateSql);

                $updateStmt->bind_param($setTypes, ...$setValues);



                if ($updateStmt->execute()) {

                    $updatedCount++;

                } else {

                    $errors[] = "السطر $lineNumber ($name): فشل في التحديث — " . $updateStmt->error;

                    $errorCount++;

                }

                continue;

            }



            // ══════════════════════════════════════════════════════

            // ADD MODE — no student_id, check for duplicates first

            // ══════════════════════════════════════════════════════

            $checkStmt = $conn->prepare("

                SELECT id FROM students

                WHERE church_id = ?

                  AND LOWER(REPLACE(name,' ','')) = LOWER(REPLACE(?,' ',''))

                  AND class_id = ?

            ");

            $checkStmt->bind_param("isi", $churchId, $name, $classId);

            $checkStmt->execute();

            if ($checkStmt->get_result()->num_rows > 0) {

                $errors[] = "السطر $lineNumber: '$name' موجود بالفعل في فصل '$className' — تم التجاهل";

                $skippedEmpty++;

                continue;

            }



            $addedByType = 'bulk_add';
            if ($formattedBirthday !== null) {

                $stmt = $conn->prepare("

                    INSERT INTO students

                    (church_id, name, class_id, class, address, phone, birthday,

                     commitment_coupons, coupons, attendance_coupons, custom_info, added_by)

                    VALUES (?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?, ?)

                ");

                // i=church_id, s=name, i=class_id, s=class, s=address, s=phone, s=birthday, s=custom_info, s=added_by

                $stmt->bind_param("isissssss", $churchId, $name, $classId, $className, $address, $cleanPhone, $formattedBirthday, $customInfoJson, $addedByType);

            } else {

                $stmt = $conn->prepare("

                    INSERT INTO students

                    (church_id, name, class_id, class, address, phone,

                     commitment_coupons, coupons, attendance_coupons, custom_info, added_by)

                    VALUES (?, ?, ?, ?, ?, ?, 0, 0, 0, ?, ?)

                ");

                // i=church_id, s=name, i=class_id, s=class, s=address, s=phone, s=custom_info, s=added_by

                $stmt->bind_param("isisssss", $churchId, $name, $classId, $className, $address, $cleanPhone, $customInfoJson, $addedByType);

            }



            if ($stmt->execute()) {

                $addedCount++;

            } else {

                $errors[] = "السطر $lineNumber ($name): فشل في الإضافة — " . $stmt->error;

                $errorCount++;

            }

        }



        fclose($file);



        if ($addedCount === 0 && $updatedCount === 0 && $errorCount > 0) {

            $conn->rollback();

            sendJSON([

                'success' => false,

                'message' => 'لم يتم إضافة أو تحديث أي طفل. يرجى مراجعة الأخطاء.',

                'errors' => array_slice($errors, 0, 25),

                'added' => 0,

                'updated' => 0,

                'failed' => $errorCount,

                'skipped' => $skippedEmpty,

                'availableClasses' => array_column($churchClasses, 'arabic_name'),

            ]);

        } else {

            $conn->commit();

            $msg = '';

            if ($addedCount > 0)

                $msg .= "تم إضافة $addedCount طفل";

            if ($updatedCount > 0)

                $msg .= ($msg ? ' — ' : '') . "تم تحديث $updatedCount طفل";

            if ($errorCount > 0)

                $msg .= " (فشل/تجاهل $errorCount)";

            if ($skippedEmpty > 0)

                $msg .= " (صفوف فارغة: $skippedEmpty)";

            sendJSON([

                'success' => true,

                'message' => $msg,

                'addedCount' => $addedCount,

                'updatedCount' => $updatedCount,

                'failed' => $errorCount,

                'skipped' => $skippedEmpty,

                'errors' => array_slice($errors, 0, 25),

                'availableClasses' => array_column($churchClasses, 'arabic_name'),

            ]);

        }



    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("bulkAddKids error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في الاستيراد: ' . $e->getMessage()]);

    }

}

function bulkSaveImportedKids()
{
    try {
        checkAuth();
        $churchId = getChurchId();
        $uncleId = $_SESSION['uncle_id'] ?? null;
        $conn = getDBConnection();
        $conn->begin_transaction();

        $tripId = isset($_POST['trip_id']) ? intval($_POST['trip_id']) : 0;
        $kidsJson = $_POST['kids'] ?? '';
        $kids = json_decode($kidsJson, true);

        if (!is_array($kids)) {
            sendJSON(['success' => false, 'message' => 'بيانات الأطفال غير صالحة']);
            return;
        }

        $allowedChurches = [$churchId];
        $maxParticipants = 0;
        if ($tripId > 0) {
            $tripStmt = $conn->prepare("SELECT church_id, max_participants, title, collaborating_churches, collaboration_limits FROM trips WHERE id = ?");
            $tripStmt->bind_param("i", $tripId);
            $tripStmt->execute();
            $trip = $tripStmt->get_result()->fetch_assoc();
            if (!$trip) {
                sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
                return;
            }
            ensureWaitlistTable($conn);
            $maxParticipants = intval($trip['max_participants'] ?? 0);
            
            $participants = [intval($trip['church_id'])];
            $collabRaw = $trip['collaborating_churches'] ?? '';
            if (!empty($collabRaw)) {
                $collab = json_decode($collabRaw, true);
                if (is_array($collab)) {
                    $participants = array_unique(array_merge($participants, array_map('intval', $collab)));
                }
            }
            if (in_array($churchId, $participants)) {
                $ownerChurchId = intval($trip['church_id']);
                if ($churchId === $ownerChurchId) {
                    $allowedChurches = $participants;
                } else {
                    $allowedChurches = [$churchId];
                }
            }

            $ownerChurchId = intval($trip['church_id']);
            $churchLimit = null;
            if ($ownerChurchId !== $churchId) {
                $limits = [];
                if (!empty($trip['collaboration_limits'])) {
                    $limits = json_decode($trip['collaboration_limits'], true);
                }
                if (is_array($limits) && isset($limits[strval($churchId)])) {
                    $churchLimit = intval($limits[strval($churchId)]);
                }
            }
        }

        $classMap = [];
        foreach ($allowedChurches as $cId) {
            $churchClasses = getClassesForChurch($cId);
            foreach ($churchClasses as $cls) {
                $key = normalizeArabicClassName($cls['arabic_name']);
                $classMap[$key] = ['id' => $cls['id'], 'arabic_name' => $cls['arabic_name']];
            }
        }

        $addedCount = 0;
        $updatedCount = 0;
        $registeredCount = 0;
        $errors = [];

        foreach ($kids as $kid) {
            $studentId = isset($kid['student_id']) ? intval($kid['student_id']) : 0;
            $name = sanitize($kid['name'] ?? '');
            $classRaw = sanitize($kid['class'] ?? '');
            $phone = sanitize($kid['phone'] ?? '');
            $emergencyPhone = sanitize($kid['emergency_phone'] ?? '');
            $medicalNotes = sanitize($kid['medical_notes'] ?? '');
            $gender = sanitize($kid['gender'] ?? '');
            $address = sanitize($kid['address'] ?? '');
            $birthday = sanitize($kid['birthday'] ?? '');
            $siblings = sanitize($kid['siblings'] ?? '');
            $customInfoInput = $kid['custom_info'] ?? [];

            if (empty($name)) {
                continue;
            }

            $classId = 0;
            $className = $classRaw;
            if (!empty($classRaw)) {
                $lookupKey = normalizeArabicClassName($classRaw);
                if (isset($classMap[$lookupKey])) {
                    $classId = $classMap[$lookupKey]['id'];
                    $className = $classMap[$lookupKey]['arabic_name'];
                }
            }

            $formattedBirthday = null;
            if (!empty($birthday)) {
                $formattedBirthday = formatDateToDB($birthday);
            }

            $cleanPhone = preg_replace('/[^\d]/', '', $phone);
            if (!empty($cleanPhone)) {
                if (strpos($cleanPhone, '002') === 0) {
                    $cleanPhone = substr($cleanPhone, 2);
                }
                if (strpos($cleanPhone, '20') === 0) {
                    $cleanPhone = substr($cleanPhone, 2);
                }
                if (strlen($cleanPhone) === 10 && $cleanPhone[0] === '1') {
                    $cleanPhone = '0' . $cleanPhone;
                }
            }
            if (!empty($cleanPhone) && !preg_match('/^01[0-9]{9}$/', $cleanPhone)) {
                $cleanPhone = '';
            }

            $cleanEmergencyPhone = preg_replace('/[^\d]/', '', $emergencyPhone);
            if (!empty($cleanEmergencyPhone)) {
                if (strpos($cleanEmergencyPhone, '002') === 0) {
                    $cleanEmergencyPhone = substr($cleanEmergencyPhone, 2);
                }
                if (strpos($cleanEmergencyPhone, '20') === 0) {
                    $cleanEmergencyPhone = substr($cleanEmergencyPhone, 2);
                }
                if (strlen($cleanEmergencyPhone) === 10 && $cleanEmergencyPhone[0] === '1') {
                    $cleanEmergencyPhone = '0' . $cleanEmergencyPhone;
                }
            }
            if (!empty($cleanEmergencyPhone) && !preg_match('/^01[0-9]{9}$/', $cleanEmergencyPhone)) {
                $cleanEmergencyPhone = '';
            }

            if ($gender !== 'male' && $gender !== 'female') {
                $gender = detectGenderFromName($name);
            }

            $targetChurchId = $churchId;
            $existingCustomInfo = [];
            if ($studentId > 0) {
                $getStmt = $conn->prepare("SELECT church_id, custom_info FROM students WHERE id = ?");
                $getStmt->bind_param("i", $studentId);
                $getStmt->execute();
                $existingRow = $getStmt->get_result()->fetch_assoc();
                if ($existingRow) {
                    $actualChurchId = intval($existingRow['church_id']);
                    if (in_array($actualChurchId, $allowedChurches)) {
                        $targetChurchId = $actualChurchId;
                        if (!empty($existingRow['custom_info'])) {
                            $existingCustomInfo = json_decode($existingRow['custom_info'], true) ?: [];
                        }
                    } else {
                        $studentId = 0;
                    }
                } else {
                    $studentId = 0;
                }
            }

            $infoObj = $existingCustomInfo;
            if (is_array($customInfoInput)) {
                foreach ($customInfoInput as $k => $v) {
                    $cleanK = strip_tags(trim((string)$k));
                    $cleanV = strip_tags(trim((string)$v));
                    if ($cleanK !== '') {
                        $infoObj[$cleanK] = $cleanV;
                    }
                }
            }
            $customInfoJson = !empty($infoObj) ? json_encode($infoObj, JSON_UNESCAPED_UNICODE) : null;

            if ($studentId > 0) {
                $setParts = ["name = ?", "gender = ?", "updated_at = NOW()"];
                $setTypes = "ss";
                $setValues = [$name, $gender];

                if ($classId > 0) {
                    $setParts[] = "class_id = ?";
                    $setParts[] = "class = ?";
                    $setTypes .= "is";
                    $setValues[] = $classId;
                    $setValues[] = $className;
                }
                if ($address !== '') {
                    $setParts[] = "address = ?";
                    $setTypes .= "s";
                    $setValues[] = $address;
                }
                if ($cleanPhone !== '') {
                    $setParts[] = "phone = ?";
                    $setTypes .= "s";
                    $setValues[] = $cleanPhone;
                }
                if ($cleanEmergencyPhone !== '') {
                    $setParts[] = "emergency_phone = ?";
                    $setTypes .= "s";
                    $setValues[] = $cleanEmergencyPhone;
                }
                if ($medicalNotes !== '') {
                    $setParts[] = "medical_notes = ?";
                    $setTypes .= "s";
                    $setValues[] = $medicalNotes;
                }
                if ($formattedBirthday !== null) {
                    $setParts[] = "birthday = ?";
                    $setTypes .= "s";
                    $setValues[] = $formattedBirthday;
                }
                if ($customInfoJson !== null) {
                    $setParts[] = "custom_info = ?";
                    $setTypes .= "s";
                    $setValues[] = $customInfoJson;
                }

                $setTypes .= "ii";
                $setValues[] = $studentId;
                $setValues[] = $targetChurchId;

                $updateSql = "UPDATE students SET " . implode(', ', $setParts) . " WHERE id = ? AND church_id = ?";
                $updateStmt = $conn->prepare($updateSql);
                $updateStmt->bind_param($setTypes, ...$setValues);
                if ($updateStmt->execute()) {
                    $updatedCount++;
                } else {
                    $errors[] = "فشل تحديث الطفل " . $name . ": " . $updateStmt->error;
                    continue;
                }
            } else {
                $addedByType = 'bulk_add';
                $insStmt = $conn->prepare("
                    INSERT INTO students 
                    (church_id, name, class_id, class, address, phone, emergency_phone, medical_notes, birthday, gender, custom_info, commitment_coupons, coupons, attendance_coupons, added_by)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, ?)
                ");
                $insStmt->bind_param("isisssssssss", $targetChurchId, $name, $classId, $className, $address, $cleanPhone, $cleanEmergencyPhone, $medicalNotes, $formattedBirthday, $gender, $customInfoJson, $addedByType);
                if ($insStmt->execute()) {
                    $studentId = $conn->insert_id;
                    $addedCount++;
                } else {
                    $errors[] = "فشل إضافة الطفل " . $name . ": " . $insStmt->error;
                    continue;
                }
            }

            if ($studentId > 0 && !empty($siblings)) {
                linkSiblingsByName($conn, $targetChurchId, $studentId, $siblings);
            }

            if ($tripId > 0 && $studentId > 0) {
                $chkReg = $conn->prepare("SELECT id, cancelled FROM trip_registrations WHERE trip_id = ? AND student_id = ?");
                $chkReg->bind_param("ii", $tripId, $studentId);
                $chkReg->execute();
                $chkRegRes = $chkReg->get_result();

                $isAlreadyRegistered = false;
                $existingReg = null;
                if ($chkRegRes->num_rows > 0) {
                    $existingReg = $chkRegRes->fetch_assoc();
                    if ($existingReg['cancelled'] == 0) {
                        $isAlreadyRegistered = true;
                    }
                }

                if (!$isAlreadyRegistered) {
                }

                if ($chkRegRes->num_rows > 0) {
                    // Re-fetch existingReg if it was cancelled
                    if ($existingReg['cancelled'] == 1) {
                        $reactivate = $conn->prepare("UPDATE trip_registrations SET cancelled = 0, registered_by = ? WHERE id = ?");
                        $reactivate->bind_param("ii", $uncleId, $existingReg['id']);
                        $reactivate->execute();
                        $registeredCount++;
                    }
                } else {
                    $isWaitlist = false;
                    if ($churchId === $ownerChurchId) {
                        $ownerCountStmt = $conn->prepare("
                            SELECT COUNT(*) as cnt
                            FROM trip_registrations tr
                            LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
                            LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
                            WHERE tr.trip_id = ? 
                              AND tr.cancelled = 0
                              AND COALESCE(s.church_id, g.church_id) = ?
                        ");
                        $ownerCountStmt->bind_param("ii", $tripId, $ownerChurchId);
                        $ownerCountStmt->execute();
                        $ownerCount = (int) $ownerCountStmt->get_result()->fetch_assoc()['cnt'];
                        if ($maxParticipants > 0 && $ownerCount >= $maxParticipants) {
                            $isWaitlist = true;
                        }
                    } else {
                        // Check individual collaborator limit
                        if ($churchLimit !== null) {
                            $cntStmt = $conn->prepare("
                                SELECT COUNT(*) as cnt
                                FROM trip_registrations tr
                                LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
                                LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
                                WHERE tr.trip_id = ? 
                                  AND tr.cancelled = 0
                                  AND COALESCE(s.church_id, g.church_id) = ?
                            ");
                            $cntStmt->bind_param("ii", $tripId, $churchId);
                            $cntStmt->execute();
                            $churchActiveCount = (int) $cntStmt->get_result()->fetch_assoc()['cnt'];
                            if ($churchActiveCount >= $churchLimit) {
                                $isWaitlist = true;
                            }
                        }

                        if (!$isWaitlist) {
                            $collabLimitMode = $trip['collab_limit_mode'] ?? 'open';
                            if ($collabLimitMode === 'limited') {
                                $collabMax = intval($trip['collab_max_participants'] ?? 0);
                                $collabCountStmt = $conn->prepare("
                                    SELECT COUNT(*) as cnt
                                    FROM trip_registrations tr
                                    LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
                                    LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
                                    WHERE tr.trip_id = ? 
                                      AND tr.cancelled = 0
                                      AND COALESCE(s.church_id, g.church_id) != ?
                                ");
                                $collabCountStmt->bind_param("ii", $tripId, $ownerChurchId);
                                $collabCountStmt->execute();
                                $collabCount = (int) $collabCountStmt->get_result()->fetch_assoc()['cnt'];
                                if ($collabMax > 0 && $collabCount >= $collabMax) {
                                    $isWaitlist = true;
                                }
                            }
                        }
                    }

                    if ($isWaitlist) {
                        $checkWait = $conn->prepare("SELECT id FROM trip_waitlist WHERE trip_id = ? AND student_id = ?");
                        $checkWait->bind_param("ii", $tripId, $studentId);
                        $checkWait->execute();
                        if ($checkWait->get_result()->num_rows === 0) {
                            $position = getWaitlistNextPosition($conn, $tripId);
                            $insW = $conn->prepare("INSERT INTO trip_waitlist (trip_id, student_id, church_id, added_by, position) VALUES (?, ?, ?, ?, ?)");
                            $insW->bind_param("iiiii", $tripId, $studentId, $targetChurchId, $uncleId, $position);
                            $insW->execute();
                        }
                    } else {
                        $regStmt = $conn->prepare("
                            INSERT INTO trip_registrations (trip_id, student_id, registered_by, registration_type)
                            VALUES (?, ?, ?, 'student')
                        ");
                        $regStmt->bind_param("iii", $tripId, $studentId, $uncleId);
                        if ($regStmt->execute()) {
                            $registeredCount++;
                        } else {
                            $errors[] = "فشل تسجيل الطفل " . $name . " في الرحلة: " . $regStmt->error;
                        }
                    }
                }
            }
        }

        $conn->commit();
        sendJSON([
            'success' => true,
            'message' => "تم الاستيراد بنجاح! الإضافات: {$addedCount}، التحديثات: {$updatedCount}، التسجيلات في الرحلة: {$registeredCount}",
            'errors' => $errors,
            'added' => $addedCount,
            'updated' => $updatedCount,
            'registered' => $registeredCount
        ]);

    } catch (Exception $e) {
        if (isset($conn)) {
            $conn->rollback();
        }
        sendJSON(['success' => false, 'message' => 'خطأ في الاستيراد: ' . $e->getMessage()]);
    }
}

function normalizeArabicClassName($name) {
    if (empty($name)) return '';
    $name = mb_strtolower(trim($name), 'UTF-8');
    
    // Normalize Alef, Hamza
    $name = preg_replace('/[أإآا]/u', 'ا', $name);
    // Normalize Teh Marbuta
    $name = preg_replace('/ة/u', 'ه', $name);
    // Normalize Yeh
    $name = preg_replace('/[ىي]/u', 'ي', $name);
    
    // Replace standard grade spelling to colloquial base to ensure intersection matches
    $name = str_replace('ثانيه', 'تانيه', $name);
    $name = str_replace('ثالثه', 'تالته', $name);
    
    // Remove punctuation, slashes, dashes, spaces and the conjunction 'و' (and)
    $name = preg_replace('/[[:punct:]]/u', '', $name);
    $name = str_replace(' ', '', $name);
    $name = str_replace('و', '', $name);
    
    return $name;
}

function normalizeArabicNamePHP($str) {
    if (empty($str)) return '';
    $s = trim($str);
    $s = mb_strtolower($s, 'UTF-8');
    
    // Remove Arabic diacritics (harakat)
    $diacritics = [
        "\xd9\x8b", "\xd9\x8c", "\xd9\x8d", "\xd9\x8e", 
        "\xd9\x8f", "\xd9\x90", "\xd9\x91", "\xd9\x92"
    ];
    $s = str_replace($diacritics, '', $s);
    
    // Normalize Hamzas to bare Alif
    $s = preg_replace('/[أإآا]/u', 'ا', $s);
    // Normalize Ya/Alif Maqsura
    $s = preg_replace('/[ىي]/u', 'ي', $s);
    // Normalize Ta Marbuta to Ha
    $s = preg_replace('/ة/u', 'ه', $s);
    
    return $s;
}

function transliterateEnglishToArabicPHP($englishName) {
    if (empty($englishName)) return '';
    
    $dict = [
        'peter' => 'بيتر', 'mina' => 'مينا', 'girgis' => 'جرجس', 'gerges' => 'جرجس', 'george' => 'جرجس',
        'kirollos' => 'كيرلس', 'kirolos' => 'كيرلس', 'kyrollos' => 'كيرلس', 'cyril' => 'كيرلس',
        'mark' => 'مرقص', 'marcos' => 'مرقص', 'john' => 'يوحنا', 'yohanna' => 'يوحنا', 'fayez' => 'فايز',
        'michael' => 'ميخائيل', 'mikhail' => 'ميخائيل', 'abanoub' => 'ابانوب', 'bishoy' => 'بيشوي',
        'fady' => 'فادي', 'fadi' => 'فادي', 'marina' => 'مارينا', 'veronia' => 'فيرونيا', 'david' => 'داود',
        'youssef' => 'يوسف', 'joseph' => 'يوسف', 'tony' => 'توني', 'shenouda' => 'شنوده', 'shenoda' => 'شنوده',
        'mario' => 'ماريو', 'thomas' => 'توماس', 'toma' => 'توما', 'andrew' => 'اندرو', 'andrawes' => 'اندراوس',
        'paul' => 'بولس', 'paula' => 'بولا', 'paulos' => 'بولس', 'antony' => 'انطون', 'antonios' => 'انطونيوس',
        'abram' => 'ابرام', 'ibram' => 'ابرام', 'samuel' => 'صموئيل', 'danial' => 'دانيال', 'daniel' => 'دانيال',
        'mariam' => 'مريم', 'mary' => 'مريم', 'demiana' => 'دميانه', 'justina' => 'يوستينه', 'yostina' => 'يوستينه',
        'martina' => 'مارتينا', 'monica' => 'مونيكا', 'sandra' => 'ساندرا', 'irene' => 'ايريني', 'eriny' => 'ايريني',
        'sherry' => 'شيري', 'cheri' => 'شيري', 'romany' => 'روماني', 'safwat' => 'صفوت', 'tharwat' => 'ثروت',
        'medhat' => 'مدحت', 'nashat' => 'نشأت', 'nashaat' => 'نشأت', 'raafat' => 'رأفت', 'maged' => 'ماجد',
        'magdy' => 'مجدي', 'wagdy' => 'وجدي', 'waged' => 'وجد', 'wagih' => 'وجيه', 'nabil' => 'نبيل',
        'nady' => 'نادي', 'adel' => 'عادل', 'emad' => 'عماد', 'ayman' => 'ايمن', 'ashraf' => 'اشرف',
        'amir' => 'امير', 'sherif' => 'شريف', 'hany' => 'هاني', 'mounir' => 'منير', 'monir' => 'منير',
        'samir' => 'سمير', 'magued' => 'ماجد', 'sameh' => 'سامح', 'bassem' => 'باسم', 'basim' => 'باسم',
        'bahaa' => 'بهاء', 'milad' => 'ميلاد', 'moris' => 'موريس', 'mouris' => 'موريس', 'naser' => 'ناصر',
        'nassif' => 'نصيف', 'nazaer' => 'نظير', 'sobhy' => 'صبحي', 'shawky' => 'شوقي', 'shaker' => 'شاكر',
        'shokry' => 'شكري', 'said' => 'سعيد', 'saad' => 'سعد', 'soliman' => 'سليمان', 'samy' => 'سامي',
        'hassan' => 'حسن', 'hussein' => 'حسين', 'ibrahim' => 'ابراهيم', 'mourad' => 'مراد', 'murad' => 'مراد',
        'ramzy' => 'رمزي', 'refaat' => 'رفعت', 'rizk' => 'رزق', 'rezk' => 'رزق', 'zaki' => 'زكي',
        'kamal' => 'كمال', 'kamel' => 'كامل', 'gamal' => 'جمال', 'gamil' => 'جميل', 'jalal' => 'جلال',
        'salah' => 'صلاح', 'farag' => 'فرج', 'fag' => 'فرج', 'fouad' => 'فؤاد', 'foad' => 'فؤاد',
        'fakhry' => 'فخري', 'fahmy' => 'فهمي', 'wasim' => 'وسيم', 'waseem' => 'وسيم', 'waheed' => 'وحيد',
        'wahid' => 'وحيد', 'yasser' => 'ياسر', 'zakaria' => 'زكريا'
    ];

    $charMap = [
        'sh' => 'ش', 'ch' => 'ش', 'kh' => 'خ', 'gh' => 'غ', 'th' => 'ث', 'ph' => 'ف',
        'a' => 'ا', 'e' => 'ي', 'i' => 'ي', 'o' => 'و', 'u' => 'و', 'y' => 'ي',
        'b' => 'ب', 'c' => 'ك', 'd' => 'د', 'f' => 'ف', 'g' => 'ج', 'h' => 'ه',
        'j' => 'ج', 'k' => 'ك', 'l' => 'ل', 'm' => 'م', 'n' => 'ن', 'p' => 'ب',
        'q' => 'ق', 'r' => 'ر', 's' => 'س', 't' => 'ت', 'v' => 'ف', 'w' => 'و',
        'x' => 'كس', 'z' => 'ز'
    ];

    $englishNameClean = preg_replace('/[^a-z\s]/i', '', $englishName);
    $words = array_filter(explode(' ', strtolower($englishNameClean)));
    $converted = [];
    foreach ($words as $w) {
        if (isset($dict[$w])) {
            $converted[] = $dict[$w];
            continue;
        }
        $ar = '';
        $i = 0;
        $wLen = strlen($w);
        while ($i < $wLen) {
            $matched = false;
            if ($i < $wLen - 1) {
                $doubleChar = substr($w, $i, 2);
                if (isset($charMap[$doubleChar])) {
                    $ar .= $charMap[$doubleChar];
                    $i += 2;
                    $matched = true;
                }
            }
            if (!$matched) {
                $singleChar = $w[$i];
                if (isset($charMap[$singleChar])) {
                    $ar .= $charMap[$singleChar];
                }
                $i++;
            }
        }
        $converted[] = $ar;
    }
    return implode(' ', $converted);
}

function sendCustomWhatsAppOTP() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);
        $forRegistration = !empty($_POST['for_registration']) || !empty($_POST['is_registration']);
        
        if (empty($cleanPhone) || strlen($cleanPhone) < 10) {
            sendJSON(['success' => false, 'message' => 'يرجى إدخال رقم هاتف صحيح']);
        }
        
        $conn = getDBConnection();

        $ownerName = '';
        $ownerChurchId = 0;
        $ownerType = '';
        $ownerId = null;

        if (!$forRegistration) {
            $studentId = (int)($_POST['student_id'] ?? 0);
            if ($studentId > 0) {
                $stStmt = $conn->prepare("SELECT id, name, church_id FROM students WHERE id = ? LIMIT 1");
                if ($stStmt) {
                    $stStmt->bind_param("i", $studentId);
                    $stStmt->execute();
                    $stRes = $stStmt->get_result();
                    if ($stRes && $stRes->num_rows > 0) {
                        $sRow = $stRes->fetch_assoc();
                        $ownerName = $sRow['name'] ?? '';
                        $ownerChurchId = (int)($sRow['church_id'] ?? 0);
                        $ownerType = 'student';
                        $ownerId = (int)$sRow['id'];
                    }
                    $stStmt->close();
                }
            }

            if (empty($ownerName)) {
                // Check student phone across primary phone, emergency phone, and parent phones
                $studentStmt = $conn->prepare("
                    SELECT id, name, church_id FROM students 
                    WHERE (RIGHT(phone, 10) = RIGHT(?, 10) OR phone = ?
                       OR RIGHT(emergency_phone, 10) = RIGHT(?, 10) OR emergency_phone = ?
                       OR parent_phones LIKE CONCAT('%', ?) OR custom_info LIKE CONCAT('%', ?)) 
                    LIMIT 1
                ");
                $studentStmt->bind_param("ssssss", $cleanPhone, $cleanPhone, $cleanPhone, $cleanPhone, $cleanPhone, $cleanPhone);
                $studentStmt->execute();
                $studentRes = $studentStmt->get_result();
                
                if ($studentRes && $studentRes->num_rows > 0) {
                    $sRow = $studentRes->fetch_assoc();
                    $ownerName = $sRow['name'] ?? '';
                    $ownerChurchId = (int)($sRow['church_id'] ?? 0);
                    $ownerType = 'student';
                    $ownerId = (int)$sRow['id'];
                } else {
                    // Also check uncles / servants
                    $uncleStmt = $conn->prepare("
                        SELECT id, name, church_id FROM uncles 
                        WHERE RIGHT(phone, 10) = RIGHT(?, 10) OR phone = ?
                        LIMIT 1
                    ");
                    $uncleFound = false;
                    if ($uncleStmt) {
                        $uncleStmt->bind_param("ss", $cleanPhone, $cleanPhone);
                        $uncleStmt->execute();
                        $uncleRes = $uncleStmt->get_result();
                        if ($uncleRes && $uncleRes->num_rows > 0) {
                            $uncleFound = true;
                            $uRow = $uncleRes->fetch_assoc();
                            $ownerName = $uRow['name'] ?? '';
                            $ownerChurchId = (int)($uRow['church_id'] ?? 0);
                            $ownerType = 'uncle';
                            $ownerId = (int)$uRow['id'];
                        }
                        $uncleStmt->close();
                    }

                    if (!$uncleFound) {
                        sendJSON(['success' => false, 'message' => 'عذراً، رقم الهاتف غير مسجل في نظام مدارس الأحد. يرجى التواصل مع الخادم للتسجيل.']);
                    }
                }
                $studentStmt->close();
            }
        } else {
            // Registration mode
            if (!empty($_POST['church_id'])) {
                $ownerChurchId = (int)$_POST['church_id'];
            } elseif (!empty($_POST['churchId'])) {
                $ownerChurchId = (int)$_POST['churchId'];
            }
            if (!empty($_POST['name'])) {
                $ownerName = sanitize($_POST['name']);
            }
            if ($ownerChurchId === 0) {
                try {
                    $chkTable = $conn->query("SHOW TABLES LIKE 'pending_registrations'");
                    if ($chkTable && $chkTable->num_rows > 0) {
                        $regStmt = $conn->prepare("SELECT church_id, name FROM pending_registrations WHERE RIGHT(phone, 10) = RIGHT(?, 10) OR phone = ? ORDER BY id DESC LIMIT 1");
                        if ($regStmt) {
                            $regStmt->bind_param("ss", $cleanPhone, $cleanPhone);
                            $regStmt->execute();
                            $regRes = $regStmt->get_result();
                            if ($regRes && $regRes->num_rows > 0) {
                                $rRow = $regRes->fetch_assoc();
                                $ownerChurchId = (int)($rRow['church_id'] ?? 0);
                                if (empty($ownerName)) $ownerName = $rRow['name'] ?? '';
                            }
                            $regStmt->close();
                        }
                    }
                } catch (Throwable $ignore) {
                    error_log("Failed checking pending_registrations for OTP: " . $ignore->getMessage());
                }
            }
        }

        if ($ownerChurchId === 0 && !empty($_POST['church_id'])) {
            $ownerChurchId = (int)$_POST['church_id'];
        } elseif ($ownerChurchId === 0 && !empty($_POST['churchId'])) {
            $ownerChurchId = (int)$_POST['churchId'];
        }
        if ($ownerChurchId === 0 && !empty($_SESSION['church_id'])) {
            $ownerChurchId = (int)$_SESSION['church_id'];
        }
        
        $tableCheck = $conn->query("SHOW TABLES LIKE 'phone_verifications'");
        if ($tableCheck->num_rows === 0) {
            $conn->query("
                CREATE TABLE IF NOT EXISTS phone_verifications (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    church_id INT NULL DEFAULT NULL,
                    phone VARCHAR(20) NOT NULL,
                    request_token VARCHAR(32) DEFAULT NULL,
                    otp_code VARCHAR(10) NOT NULL,
                    is_verified TINYINT(1) DEFAULT 0,
                    is_sent TINYINT(1) DEFAULT 0,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
            ");
        } else {
            $colCheck = $conn->query("SHOW COLUMNS FROM phone_verifications LIKE 'is_sent'");
            if ($colCheck && $colCheck->num_rows === 0) {
                $conn->query("ALTER TABLE phone_verifications ADD COLUMN is_sent TINYINT(1) DEFAULT 0;");
            }
            @$conn->query("ALTER TABLE phone_verifications ADD COLUMN IF NOT EXISTS church_id INT NULL DEFAULT NULL AFTER id;");
        }
        
        $normalizedPhone = normalizeEgyptianPhone($cleanPhone);
        $last10 = (strlen($normalizedPhone) >= 10) ? substr($normalizedPhone, -10) : $normalizedPhone;

        // Check if an active OTP was already generated for this phone within the last 24 hours (86400 seconds)
        $existingOtp = null;
        $chkStmt = $conn->prepare("
            SELECT id, request_token, otp_code, church_id, is_sent, created_at,
                   TIMESTAMPDIFF(SECOND, created_at, NOW()) AS elapsed_sec
            FROM phone_verifications 
            WHERE (RIGHT(phone, 10) = ? OR phone = ? OR phone = ?)
              AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
            ORDER BY id DESC LIMIT 1
        ");
        if ($chkStmt) {
            $chkStmt->bind_param("sss", $last10, $cleanPhone, $normalizedPhone);
            $chkStmt->execute();
            $chkRes = $chkStmt->get_result();
            if ($chkRes && $cRow = $chkRes->fetch_assoc()) {
                $existingOtp = $cRow;
            }
            $chkStmt->close();
        }

        // If an active code was created in the last 24 hours, reuse it!
        // Do NOT generate a new code and do NOT send a new alert to the developer or bot
        if ($existingOtp && !empty($existingOtp['otp_code'])) {
            $newOtpId = (int)$existingOtp['id'];
            $otp = $existingOtp['otp_code'];
            $requestToken = $existingOtp['request_token'];

            if (empty($requestToken)) {
                $bytes = random_bytes(4);
                $requestToken = 'REQ-' . strtoupper(bin2hex($bytes));
                $upStmt = $conn->prepare("UPDATE phone_verifications SET request_token = ? WHERE id = ?");
                if ($upStmt) {
                    $upStmt->bind_param("si", $requestToken, $newOtpId);
                    $upStmt->execute();
                    $upStmt->close();
                }
            }

            error_log(sprintf("[WhatsAppQueue] 24h window: Reusing active OTP id=%d for phone=%s (generated %d sec ago)", $newOtpId, $normalizedPhone, $existingOtp['elapsed_sec'] ?? 0));

            sendJSON([
                'success' => true,
                'message' => 'رمز التحقق تم إرساله مسبقاً وهو صالح لمدة 24 ساعة. يرجى إدخال الكود المستلم عبر واتساب.',
                'request_token' => $requestToken,
                'queue_id' => $newOtpId,
                'is_existing' => true
            ]);
            return;
        }

        // Step 1: Generate the OTP
        $otp = sprintf("%06d", mt_rand(100000, 999999));
        $bytes = random_bytes(4);
        $requestToken = 'REQ-' . strtoupper(bin2hex($bytes));
        
        // Step 2: Store/enqueue a pending WhatsApp message (id, phone, otp_code, is_sent=0)
        if ($ownerChurchId > 0) {
            $stmt = $conn->prepare("INSERT INTO phone_verifications (church_id, phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, ?, 0, 0, NOW())");
            $stmt->bind_param("isss", $ownerChurchId, $normalizedPhone, $requestToken, $otp);
        } else {
            $stmt = $conn->prepare("INSERT INTO phone_verifications (phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, 0, 0, NOW())");
            $stmt->bind_param("sss", $normalizedPhone, $requestToken, $otp);
        }
        $stmt->execute();
        $newOtpId = intval($conn->insert_id ?: $stmt->insert_id);
        $stmt->close();

        if ($newOtpId <= 0) {
            throw new Exception("فشل في حفظ رمز التحقق في قاعدة البيانات");
        }

        // Resolve church name if available for clearer notification
        $churchName = '';
        if ($ownerChurchId > 0) {
            $cStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");
            if ($cStmt) {
                $cStmt->bind_param("i", $ownerChurchId);
                $cStmt->execute();
                $cRes = $cStmt->get_result();
                if ($cRes && $cRow = $cRes->fetch_assoc()) {
                    $churchName = $cRow['church_name'] ?? '';
                }
                $cStmt->close();
            }
        }

        $notifTitle = "طلب كود واتساب: " . $otp;
        $notifBody = "كود: " . $otp . " لرقم: " . $normalizedPhone;
        if (!empty($ownerName)) {
            $notifBody .= " (" . $ownerName . ")";
        }
        if (!empty($churchName)) {
            $notifBody .= " - كنيسة " . $churchName;
        }

        // Notify developer account in-app
        $devChurchId = 0;
        $devQ = $conn->query("SELECT church_id FROM uncles WHERE (LOWER(TRIM(role)) IN ('developer', 'dev') OR LOWER(TRIM(username)) = 'peterfayez' OR LOWER(TRIM(email)) = 'peterfayez107@gmail.com') AND (deleted IS NULL OR deleted = 0) LIMIT 1");
        if ($devQ && $dRow = $devQ->fetch_assoc()) {
            $devChurchId = (int)($dRow['church_id'] ?? 0);
        }
        $targetInAppChurchId = $devChurchId > 0 ? $devChurchId : $ownerChurchId;
        if ($targetInAppChurchId > 0 && function_exists('pushNotification')) {
            pushNotification($conn, $targetInAppChurchId, 'whatsapp_otp', $notifTitle, $notifBody, 'phone_verification', $newOtpId);
        }

        // Send PWA push notification to developer account only (for all churches across all environments)
        if (function_exists('_sendWebPushToDeveloper')) {
            _sendWebPushToDeveloper($conn, $notifTitle, $notifBody, '/uncle/dashboard/?open_otp=1', [
                'otp_code' => $otp,
                'phone' => $normalizedPhone,
                'owner_name' => $ownerName,
                'church_name' => $churchName,
                'church_id' => $ownerChurchId
            ]);
        }

        error_log(sprintf("[WhatsAppQueue] Step 2 Success: Enqueued pending OTP id=%d, church_id=%d, phone=%s, is_sent=0", $newOtpId, $ownerChurchId, $normalizedPhone));
        
        // Step 3: Confirm the item is available in the pending queue
        $confirmedItem = verifyPendingOTPInQueue($newOtpId);
        if (!$confirmedItem) {
            error_log(sprintf("[WhatsAppQueue] Step 3 Failed: OTP id=%d not found in pending queue", $newOtpId));
            throw new Exception("تعذر تأكيد إضافة رمز التحقق إلى قائمة الانتظار");
        }

        error_log(sprintf("[WhatsAppQueue] Step 3 Confirmed: Pending OTP id=%d is available for bot polling (phone=%s)", $confirmedItem['id'], $confirmedItem['phone']));

        // If running on testing environment, mirror the OTP to production queue so the central WhatsApp bot (polling production) sends it
        $isTestingServer = (
            strpos($_SERVER['HTTP_HOST'] ?? '', 'testing.') !== false ||
            strpos(__DIR__, '/testing') !== false
        );

        if ($isTestingServer) {
            $mCh = curl_init('https://sunday-school.online/api.php');
            $mirrorFields = [
                'action' => 'enqueueMirrorOTP',
                'phone' => $normalizedPhone,
                'otp_code' => $otp,
                'request_token' => $requestToken,
                'church_id' => $ownerChurchId,
                'owner_name' => $ownerName
            ];
            curl_setopt_array($mCh, [
                CURLOPT_POST => true,
                CURLOPT_POSTFIELDS => http_build_query($mirrorFields),
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_TIMEOUT => 5,
                CURLOPT_SSL_VERIFYPEER => false,
                CURLOPT_SSL_VERIFYHOST => false
            ]);
            $mirrorResp = curl_exec($mCh);
            curl_close($mCh);
            error_log(sprintf("[WhatsAppQueue] Mirrored testing OTP id=%d to production queue: %s", $newOtpId, substr(strval($mirrorResp), 0, 100)));
        }

        // Step 4: Call the published bot API: POST BOT_API_URL/api/wake
        error_log(sprintf("[WhatsAppQueue] Step 4: Calling published bot API POST /api/wake for queue item id=%d", $newOtpId));
        $wakeResult = notifyWhatsAppOTPPending($newOtpId);
        error_log(sprintf("[WhatsAppQueue] Step 4 Result: Bot wake acknowledged=%s, http_code=%d, status=%s", 
            !empty($wakeResult['success']) ? 'true' : 'false', 
            $wakeResult['http_code'] ?? 0,
            $wakeResult['status'] ?? 'unknown'
        ));
        
        // Treat wake as acknowledgement only; keep OTP flow usable even if wake temporarily fails
        $userMessage = 'تم إرسال رمز التحقق إلى WhatsApp. يرجى التحقق من هاتفك.';
        if (empty($wakeResult['success'])) {
            $userMessage = 'تم إنشاء رمز التحقق. قد يستغرق وصول رسالة WhatsApp بضع لحظات، يرجى التحقق من هاتفك.';
        }
        
        sendJSON([
            'success' => true,
            'message' => $userMessage,
            'request_token' => $requestToken,
            'queue_id' => $newOtpId
        ]);
    } catch (Exception $e) {
        error_log("[WhatsAppQueue] Error in sendCustomWhatsAppOTP: " . $e->getMessage());
        sendJSON(['success' => false, 'message' => 'خطأ في إرسال الكود: ' . $e->getMessage()]);
    }
}

/**
 * Enqueue a mirror OTP record from testing server to production queue
 * so the central WhatsApp bot picks it up and delivers it immediately.
 */
function enqueueMirrorOTP() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $code = sanitize($_POST['otp_code'] ?? '');
        $token = sanitize($_POST['request_token'] ?? '');
        $mirrorChurchId = (int)($_POST['church_id'] ?? 0);
        $mirrorOwnerName = sanitize($_POST['owner_name'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);
        $normalizedPhone = normalizeEgyptianPhone($cleanPhone);

        if (empty($normalizedPhone) || empty($code)) {
            sendJSON(['success' => false, 'message' => 'بيانات غير مكتملة']);
        }

        $conn = getDBConnection();
        @$conn->query("ALTER TABLE phone_verifications ADD COLUMN IF NOT EXISTS church_id INT NULL DEFAULT NULL AFTER id;");
        if ($mirrorChurchId > 0) {
            $stmt = $conn->prepare("INSERT INTO phone_verifications (church_id, phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, ?, 0, 0, NOW())");
            $stmt->bind_param("isss", $mirrorChurchId, $normalizedPhone, $token, $code);
        } else {
            $stmt = $conn->prepare("INSERT INTO phone_verifications (phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, 0, 0, NOW())");
            $stmt->bind_param("sss", $normalizedPhone, $token, $code);
        }
        $stmt->execute();
        $newId = intval($conn->insert_id ?: $stmt->insert_id);
        $stmt->close();

        // Resolve church name if available
        $churchName = '';
        if ($mirrorChurchId > 0) {
            $cStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");
            if ($cStmt) {
                $cStmt->bind_param("i", $mirrorChurchId);
                $cStmt->execute();
                $cRes = $cStmt->get_result();
                if ($cRes && $cRow = $cRes->fetch_assoc()) {
                    $churchName = $cRow['church_name'] ?? '';
                }
                $cStmt->close();
            }
        }

        $notifTitle = "طلب كود واتساب: " . $code;
        $notifBody = "كود: " . $code . " لرقم: " . $normalizedPhone;
        if (!empty($mirrorOwnerName)) {
            $notifBody .= " (" . $mirrorOwnerName . ")";
        }
        if (!empty($churchName)) {
            $notifBody .= " - كنيسة " . $churchName;
        }

        $devChurchId = 0;
        $devQ = $conn->query("SELECT church_id FROM uncles WHERE (LOWER(TRIM(role)) IN ('developer', 'dev') OR LOWER(TRIM(username)) = 'peterfayez' OR LOWER(TRIM(email)) = 'peterfayez107@gmail.com') AND (deleted IS NULL OR deleted = 0) LIMIT 1");
        if ($devQ && $dRow = $devQ->fetch_assoc()) {
            $devChurchId = (int)($dRow['church_id'] ?? 0);
        }
        $targetInAppChurchId = $devChurchId > 0 ? $devChurchId : $mirrorChurchId;
        if ($targetInAppChurchId > 0 && function_exists('pushNotification')) {
            pushNotification($conn, $targetInAppChurchId, 'whatsapp_otp', $notifTitle, $notifBody, 'phone_verification', $newId);
        }

        // PWA Web Push notification exclusively to developer account (sends for all churches)
        if (function_exists('_sendWebPushToDeveloper')) {
            _sendWebPushToDeveloper($conn, $notifTitle, $notifBody, '/uncle/dashboard/?open_otp=1', [
                'otp_code' => $code,
                'phone' => $normalizedPhone,
                'owner_name' => $mirrorOwnerName,
                'church_name' => $churchName,
                'church_id' => $mirrorChurchId
            ]);
        }

        // Immediately notify bot to wake up and poll
        $wakeResult = notifyWhatsAppOTPPending($newId);
        error_log(sprintf("[WhatsAppQueue] enqueueMirrorOTP enqueued production id=%d for phone=%s, wake=%d", $newId, $normalizedPhone, $wakeResult['http_code'] ?? 0));

        sendJSON(['success' => true, 'id' => $newId, 'wake' => $wakeResult['success'] ?? false]);
    } catch (Throwable $e) {
        error_log("[WhatsAppQueue] enqueueMirrorOTP error: " . $e->getMessage());
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}

/**
 * Verify that a specific OTP record is confirmed present and accessible in the pending queue.
 */
function verifyPendingOTPInQueue(int $otpId): ?array {
    try {
        $conn = getDBConnection();
        $stmt = $conn->prepare("
            SELECT id, phone, otp_code 
            FROM phone_verifications 
            WHERE id = ? 
              AND is_verified = 0 
              AND is_sent = 0
              AND (created_at IS NULL OR TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400)
            LIMIT 1
        ");
        if (!$stmt) return null;
        $stmt->bind_param("i", $otpId);
        $stmt->execute();
        $res = $stmt->get_result();
        $item = $res ? $res->fetch_assoc() : null;
        $stmt->close();
        if ($item) {
            $item['id'] = intval($item['id']);
            $item['phone'] = normalizeEgyptianPhone($item['phone']);
        }
        return $item;
    } catch (Throwable $t) {
        error_log("[WhatsAppQueue] verifyPendingOTPInQueue exception: " . $t->getMessage());
        return null;
    }
}

/**
 * Notify the existing Sunday School WhatsApp Bot API to wake up.
 * 
 * Rules:
 * 1. The bot server owns the Baileys/WhatsApp connection, QR code, session, and queue polling.
 * 2. The website only notifies POST ${WHATSAPP_BOT_API_URL}/api/wake immediately after queueing.
 * 3. Timeout is ~5 seconds with up to 3 retries on network failures.
 * 4. Logs success/failure without logging passwords or secrets.
 * 5. Response is an acknowledgement only (HTTP 200 or HTTP 202).
 * 6. Non-blocking: OTP remains pending even if wake temporarily fails.
 */
function notifyWhatsAppOTPPending($otpId = null): array {
    static $notifiedOtpIds = [];

    $otpIdStr = $otpId !== null ? strval($otpId) : '';
    if (!empty($otpIdStr) && isset($notifiedOtpIds[$otpIdStr])) {
        return [
            'success' => true,
            'status' => 'cached',
            'message' => 'WhatsApp wake signal already sent in this request'
        ];
    }
    if (!empty($otpIdStr)) {
        $notifiedOtpIds[$otpIdStr] = true;
    }

    $botApiBase = '';
    if (getenv('WHATSAPP_BOT_API_URL')) {
        $botApiBase = getenv('WHATSAPP_BOT_API_URL');
    } elseif (!empty($_ENV['WHATSAPP_BOT_API_URL'])) {
        $botApiBase = $_ENV['WHATSAPP_BOT_API_URL'];
    } elseif (!empty($_SERVER['WHATSAPP_BOT_API_URL'])) {
        $botApiBase = $_SERVER['WHATSAPP_BOT_API_URL'];
    } elseif (defined('WHATSAPP_BOT_API_URL') && constant('WHATSAPP_BOT_API_URL')) {
        $botApiBase = constant('WHATSAPP_BOT_API_URL');
    } else {
        $botApiBase = 'https://baileys-qr-code--sundayschooleg.replit.app';
    }

    $botApiBase = rtrim(trim($botApiBase), '/');
    $wakeUrl = $botApiBase . '/api/wake';

    $botToken = '';
    if (getenv('WHATSAPP_BOT_API_TOKEN')) {
        $botToken = getenv('WHATSAPP_BOT_API_TOKEN');
    } elseif (!empty($_ENV['WHATSAPP_BOT_API_TOKEN'])) {
        $botToken = $_ENV['WHATSAPP_BOT_API_TOKEN'];
    } elseif (!empty($_SERVER['WHATSAPP_BOT_API_TOKEN'])) {
        $botToken = $_SERVER['WHATSAPP_BOT_API_TOKEN'];
    } elseif (defined('WHATSAPP_BOT_API_TOKEN') && constant('WHATSAPP_BOT_API_TOKEN')) {
        $botToken = constant('WHATSAPP_BOT_API_TOKEN');
    }

    $payload = [
        'event' => 'otp_pending'
    ];
    if (!empty($otpIdStr)) {
        $payload['otp_id'] = $otpIdStr;
    }
    $jsonPayload = json_encode($payload);

    $maxRetries = 3;
    $lastError = '';
    $lastHttpCode = 0;
    $lastStatus = 'unknown';

    for ($attempt = 1; $attempt <= $maxRetries; $attempt++) {
        $headers = [
            'Content-Type: application/json',
            'Accept: application/json',
            'Content-Length: ' . strlen($jsonPayload)
        ];
        if (!empty($botToken)) {
            $headers[] = 'Authorization: Bearer ' . $botToken;
        }

        $ch = curl_init($wakeUrl);
        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $jsonPayload,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 5,
            CURLOPT_CONNECTTIMEOUT => 4,
            CURLOPT_SSL_VERIFYPEER => false,
            CURLOPT_SSL_VERIFYHOST => false
        ]);

        $response = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $curlErr = curl_error($ch);
        curl_close($ch);

        if ($curlErr) {
            $lastError = $curlErr;
            $lastHttpCode = $httpCode;
            if ($attempt < $maxRetries) {
                usleep(250000); // 250ms backoff
                continue;
            }
            break;
        }

        $lastHttpCode = $httpCode;
        $data = json_decode($response, true);
        if (is_array($data) && isset($data['status'])) {
            $lastStatus = strval($data['status']);
        }

        // Accept HTTP 200 or HTTP 202 as wake acknowledgement
        if ($httpCode === 200 || $httpCode === 202) {
            error_log(sprintf(
                "[WhatsAppBotWake] Wake signal accepted on attempt %d: HTTP %d, status=%s",
                $attempt,
                $httpCode,
                $lastStatus
            ));
            return [
                'success' => true,
                'http_code' => $httpCode,
                'status' => $lastStatus,
                'message' => $data['message'] ?? 'WhatsApp wake signal accepted',
                'attempts' => $attempt
            ];
        }

        // Non-2xx response retry
        $lastError = 'HTTP ' . $httpCode;
        if ($attempt < $maxRetries && ($httpCode >= 500 || $httpCode === 0)) {
            usleep(250000);
            continue;
        }
        break;
    }

    // Safe error log without passwords or secrets
    error_log(sprintf(
        "[WhatsAppBotWake] Wake signal failed after %d attempts: HTTP %d, error=%s",
        $attempt,
        $lastHttpCode,
        $lastError
    ));

    return [
        'success' => false,
        'http_code' => $lastHttpCode,
        'status' => $lastStatus,
        'message' => 'WhatsApp wake signal could not be acknowledged; OTP remains pending in queue for automatic polling.',
        'error' => $lastError,
        'attempts' => $attempt
    ];
}

function sendRegistrationWhatsAppOTP() {
    $_POST['for_registration'] = '1';
    sendCustomWhatsAppOTP();
}

function getPendingOTPMessages() {
    try {
        $conn = getDBConnection();
        $stmt = $conn->prepare("
            SELECT id, phone, otp_code FROM phone_verifications 
            WHERE is_verified = 0 
              AND is_sent = 0 
              AND (created_at IS NULL OR TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400)
            ORDER BY id ASC LIMIT 15
        ");
        if ($stmt) {
            $stmt->execute();
            $res = $stmt->get_result();
            $rows = [];
            while ($r = $res->fetch_assoc()) {
                $r['phone'] = normalizeEgyptianPhone($r['phone']);
                $rows[] = $r;
            }
            sendJSON([
                'success' => true, 
                'data' => $rows, 
                'messages' => $rows,
                'count' => count($rows)
            ]);
        } else {
            sendJSON(['success' => true, 'data' => [], 'messages' => [], 'count' => 0]);
        }
    } catch (Throwable $e) {
        sendJSON(['success' => false, 'data' => [], 'messages' => [], 'message' => $e->getMessage()]);
    }
}

function markOTPSent() {
    try {
        $id = intval($_POST['id'] ?? $_GET['id'] ?? 0);
        if ($id <= 0) {
            $jsonInput = json_decode(file_get_contents('php://input'), true);
            if (isset($jsonInput['id'])) {
                $id = intval($jsonInput['id']);
            }
        }
        if ($id > 0) {
            $conn = getDBConnection();
            $stmt = $conn->prepare("UPDATE phone_verifications SET is_sent = 1 WHERE id = ?");
            $stmt->bind_param("i", $id);
            $stmt->execute();
        }
        sendJSON(['success' => true, 'id' => $id]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}

/**
 * Check if the current user has permission to manage OTP verifications.
 * Allowed: admins, developers, church accounts, or logged-in servants in dashboard.
 */
function canAdminManageOTP(): bool {
    // 1. Sync role if session has uncle_id
    syncCurrentSessionRoleFromDB();

    // 2. Check standard admin / dev roles or existing session flags
    if (isAdminOrDevRole()) return true;
    if (!empty($_SESSION['uncle_id']) || !empty($_SESSION['church_id']) || !empty($_SESSION['uncle_logged_in']) || !empty($_SESSION['loggedIn']) || !empty($_SESSION['is_developer'])) {
        return true;
    }

    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? $_SESSION['user_role'] ?? '');
    if (in_array($role, ['developer', 'dev', 'admin', 'administrator', 'superadmin', 'servant', 'uncle', 'leader'], true)) {
        return true;
    }

    // 3. Try standard session auto-restore
    if (autoRestoreSessionFromRequest()) {
        return true;
    }

    // 4. Robust DB verification from request parameters (handles cookie drops / PWA / cross-path)
    $reqUncleId = intval($_POST['uncle_id'] ?? $_GET['uncle_id'] ?? 0);
    $reqChurchId = intval($_POST['church_id'] ?? $_GET['church_id'] ?? 0);
    $reqChurchCode = trim($_POST['church_code'] ?? $_GET['church_code'] ?? '');
    $reqUsername = trim($_POST['username'] ?? $_GET['username'] ?? $_POST['uncle_username'] ?? $_GET['uncle_username'] ?? '');

    if ($reqUncleId > 0 || !empty($reqUsername) || $reqChurchId > 0 || !empty($reqChurchCode)) {
        try {
            $conn = getDBConnection();
            if ($reqUncleId > 0 || !empty($reqUsername)) {
                $uStmt = $conn->prepare("
                    SELECT u.id, u.role, u.church_id, u.name, u.username
                    FROM uncles u
                    WHERE (u.id = ? OR (u.username = ? AND u.username != ''))
                      AND (u.deleted IS NULL OR u.deleted = 0)
                    LIMIT 1
                ");
                if ($uStmt) {
                    $uStmt->bind_param("is", $reqUncleId, $reqUsername);
                    $uStmt->execute();
                    $uRes = $uStmt->get_result();
                    if ($uRow = $uRes->fetch_assoc()) {
                        $_SESSION['uncle_id'] = intval($uRow['id']);
                        $_SESSION['uncle_role'] = $uRow['role'];
                        $_SESSION['role'] = $uRow['role'];
                        $_SESSION['church_id'] = intval($uRow['church_id']);
                        $_SESSION['uncle_logged_in'] = true;
                        if (in_array(strtolower(trim($uRow['role'])), ['developer', 'dev'])) {
                            $_SESSION['is_developer'] = true;
                        }
                        $uStmt->close();
                        return true;
                    }
                    $uStmt->close();
                }
            }

            if ($reqChurchId > 0 || !empty($reqChurchCode)) {
                $cStmt = $conn->prepare("
                    SELECT id, church_name, church_code
                    FROM churches
                    WHERE (id = ? OR (church_code = ? AND church_code != ''))
                    LIMIT 1
                ");
                if ($cStmt) {
                    $cStmt->bind_param("is", $reqChurchId, $reqChurchCode);
                    $cStmt->execute();
                    $cRes = $cStmt->get_result();
                    if ($cRow = $cRes->fetch_assoc()) {
                        $_SESSION['church_id'] = intval($cRow['id']);
                        $_SESSION['church_code'] = $cRow['church_code'];
                        $_SESSION['login_type'] = 'church';
                        $_SESSION['role'] = 'admin';
                        $_SESSION['uncle_role'] = 'admin';
                        $_SESSION['loggedIn'] = true;
                        $cStmt->close();
                        return true;
                    }
                    $cStmt->close();
                }
            }
        } catch (Exception $e) {}
    }

    return false;
}

/**
 * Admin Check User OTP:
 * Allows admins and servants to inspect user OTP verification records,
 * view the active 6-digit code, status, timestamps, and get a direct
 * one-click manual WhatsApp send URL.
 */
function adminCheckUserOTP() {
    try {
        if (!canAdminManageOTP()) {
            sendJSON(['success' => false, 'message' => 'غير مصرح لك بالوصول. يرجى تسجيل الدخول كمسؤول أو خادم.']);
        }

        $conn = getDBConnection();

        // Ensure church_id column and uniform collation exist
        @$conn->query("ALTER TABLE phone_verifications ADD COLUMN IF NOT EXISTS church_id INT NULL DEFAULT NULL AFTER id;");
        @$conn->query("ALTER TABLE phone_verifications CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;");

        // Determine church_id
        $churchId = intval($_SESSION['church_id'] ?? $_REQUEST['church_id'] ?? 0);
        if ($churchId <= 0 && !empty($_SESSION['uncle_id'])) {
            $uStmt = $conn->prepare("SELECT church_id FROM uncles WHERE id = ? LIMIT 1");
            if ($uStmt) {
                $uStmt->bind_param("i", $_SESSION['uncle_id']);
                $uStmt->execute();
                $uRes = $uStmt->get_result();
                if ($uRow = $uRes->fetch_assoc()) {
                    $churchId = intval($uRow['church_id']);
                    $_SESSION['church_id'] = $churchId;
                }
                $uStmt->close();
            }
        }

        $churchName = '';
        if ($churchId > 0) {
            $cnStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");
            if ($cnStmt) {
                $cnStmt->bind_param("i", $churchId);
                $cnStmt->execute();
                $cnRes = $cnStmt->get_result();
                if ($cnRow = $cnRes->fetch_assoc()) {
                    $churchName = $cnRow['church_name'];
                }
                $cnStmt->close();
            }
        }

        $phone = sanitize($_REQUEST['phone'] ?? $_REQUEST['q'] ?? '');
        $limit = min(60, max(1, intval($_REQUEST['limit'] ?? 30)));
        $records = [];

        // Check developer role across session, request parameters, and uncle DB record
        $isDev = isDeveloperRole();
        if (!$isDev) {
            $checkUncleId = intval($_SESSION['uncle_id'] ?? $_REQUEST['uncle_id'] ?? 0);
            $checkUsername = strtolower(trim($_SESSION['username'] ?? $_REQUEST['username'] ?? $_REQUEST['uncle_username'] ?? ''));
            if ($checkUsername === 'peterfayez') {
                $isDev = true;
            } elseif ($checkUncleId > 0) {
                $chkQ = $conn->prepare("SELECT role, username, email, phone FROM uncles WHERE id = ? LIMIT 1");
                if ($chkQ) {
                    $chkQ->bind_param("i", $checkUncleId);
                    $chkQ->execute();
                    $chkR = $chkQ->get_result()->fetch_assoc();
                    if ($chkR) {
                        $uRole = strtolower(trim($chkR['role'] ?? ''));
                        $uUser = strtolower(trim($chkR['username'] ?? ''));
                        $uMail = strtolower(trim($chkR['email'] ?? ''));
                        $uPhone = preg_replace('/[^\d]/', '', $chkR['phone'] ?? '');
                        if (in_array($uRole, ['developer', 'dev']) || $uUser === 'peterfayez' || $uMail === 'peterfayez107@gmail.com' || substr($uPhone, -8) === '10868837') {
                            $isDev = true;
                        }
                    }
                    $chkQ->close();
                }
            }
        }
        $filterOnlyMyChurch = !empty($_REQUEST['only_my_church']) || !empty($_REQUEST['filter_church_only']);

        if ($churchId > 0 && (!$isDev || $filterOnlyMyChurch)) {
            // Strict Church Scope: collect 8-digit phone signatures belonging to this church
            $churchPhoneLast8 = [];

            // Uncles
            $uQ = $conn->query("SELECT phone FROM uncles WHERE church_id = {$churchId} AND phone != '' AND (deleted IS NULL OR deleted = 0)");
            if ($uQ) {
                while ($ur = $uQ->fetch_assoc()) {
                    $c = preg_replace('/[^\d]/', '', $ur['phone'] ?? '');
                    if (strlen($c) >= 8) $churchPhoneLast8[substr($c, -8)] = true;
                }
            }

            // Students
            $sQ = $conn->query("SELECT phone, emergency_phone, parent_phones FROM students WHERE church_id = {$churchId}");
            if ($sQ) {
                while ($sr = $sQ->fetch_assoc()) {
                    $p1 = preg_replace('/[^\d]/', '', $sr['phone'] ?? '');
                    if (strlen($p1) >= 8) $churchPhoneLast8[substr($p1, -8)] = true;
                    $p2 = preg_replace('/[^\d]/', '', $sr['emergency_phone'] ?? '');
                    if (strlen($p2) >= 8) $churchPhoneLast8[substr($p2, -8)] = true;
                    if (!empty($sr['parent_phones'])) {
                        preg_match_all('/\d{8,}/', $sr['parent_phones'], $matches);
                        if (!empty($matches[0])) {
                            foreach ($matches[0] as $m) {
                                $churchPhoneLast8[substr($m, -8)] = true;
                            }
                        }
                    }
                }
            }

            // Pending registrations
            $prQ = @$conn->query("SELECT phone FROM pending_registrations WHERE church_id = {$churchId} AND phone IS NOT NULL AND phone != ''");
            if ($prQ) {
                while ($pr = $prQ->fetch_assoc()) {
                    $p = preg_replace('/[^\d]/', '', $pr['phone'] ?? '');
                    if (strlen($p) >= 8) $churchPhoneLast8[substr($p, -8)] = true;
                }
            }

            $phoneKeys = array_keys($churchPhoneLast8);
            $whereClause = "";
            $types = "i";
            $params = [$churchId];

            if (!empty($phoneKeys)) {
                $placeholders = implode(',', array_fill(0, count($phoneKeys), '?'));
                $whereClause = "(pv.church_id = ? OR RIGHT(pv.phone, 8) IN ($placeholders))";
                foreach ($phoneKeys as $pk) {
                    $types .= "s";
                    $params[] = $pk;
                }
            } else {
                $whereClause = "pv.church_id = ?";
            }

            if (!empty($phone)) {
                $cleanDigits = preg_replace('/[^\d]/', '', $phone);
                $last8 = (strlen($cleanDigits) >= 8) ? substr($cleanDigits, -8) : $cleanDigits;
                $normalized = normalizeEgyptianPhone($cleanDigits);
                $whereClause .= " AND (pv.phone LIKE CONCAT('%', ?) OR RIGHT(pv.phone, 8) = RIGHT(?, 8) OR pv.phone = ? OR pv.otp_code = ? OR pv.request_token = ?)";
                $types .= "sssss";
                $params[] = $last8;
                $params[] = $cleanDigits;
                $params[] = $normalized;
                $params[] = $phone;
                $params[] = $phone;
            }

            $sql = "SELECT pv.id, pv.church_id, pv.phone, pv.request_token, pv.otp_code, pv.is_verified, pv.is_sent, pv.created_at,
                           TIMESTAMPDIFF(MINUTE, pv.created_at, NOW()) as minutes_ago,
                           c.church_name
                    FROM phone_verifications pv
                    LEFT JOIN churches c ON pv.church_id = c.id
                    WHERE {$whereClause}
                    ORDER BY pv.id DESC LIMIT ?";
            $types .= "i";
            $params[] = $limit;

            $stmt = $conn->prepare($sql);
            if ($stmt) {
                $stmt->bind_param($types, ...$params);
                $stmt->execute();
                $res = $stmt->get_result();
                while ($row = $res->fetch_assoc()) {
                    $records[] = $row;
                }
                $stmt->close();
            }
        } else {
            // Global / All Churches Scope (Developer access to all churches codes)
            if (!empty($phone)) {
                $cleanDigits = preg_replace('/[^\d]/', '', $phone);
                $last8 = (strlen($cleanDigits) >= 8) ? substr($cleanDigits, -8) : $cleanDigits;
                $normalized = normalizeEgyptianPhone($cleanDigits);

                $stmt = $conn->prepare("
                    SELECT pv.id, pv.church_id, pv.phone, pv.request_token, pv.otp_code, pv.is_verified, pv.is_sent, pv.created_at,
                           TIMESTAMPDIFF(MINUTE, pv.created_at, NOW()) as minutes_ago,
                           c.church_name
                    FROM phone_verifications pv
                    LEFT JOIN churches c ON pv.church_id = c.id
                    WHERE (pv.phone LIKE CONCAT('%', ?) OR RIGHT(pv.phone, 8) = RIGHT(?, 8) OR pv.phone = ? OR pv.phone = ? OR pv.request_token = ? OR pv.otp_code = ? OR c.church_name LIKE CONCAT('%', ?))
                    ORDER BY pv.id DESC LIMIT ?
                ");
                $stmt->bind_param("sssssssi", $last8, $cleanDigits, $cleanDigits, $normalized, $phone, $phone, $phone, $limit);
                $stmt->execute();
                $res = $stmt->get_result();
                while ($row = $res->fetch_assoc()) {
                    $records[] = $row;
                }
                $stmt->close();
            } else {
                $stmt = $conn->prepare("
                    SELECT pv.id, pv.church_id, pv.phone, pv.request_token, pv.otp_code, pv.is_verified, pv.is_sent, pv.created_at,
                           TIMESTAMPDIFF(MINUTE, pv.created_at, NOW()) as minutes_ago,
                           c.church_name
                    FROM phone_verifications pv
                    LEFT JOIN churches c ON pv.church_id = c.id
                    ORDER BY pv.id DESC LIMIT ?
                ");
                $stmt->bind_param("i", $limit);
                $stmt->execute();
                $res = $stmt->get_result();
                while ($row = $res->fetch_assoc()) {
                    $records[] = $row;
                }
                $stmt->close();
            }
        }

        foreach ($records as &$item) {
            $item['id'] = intval($item['id']);
            $item['is_verified'] = intval($item['is_verified'] ?? 0);
            $item['is_sent'] = intval($item['is_sent'] ?? 0);
            $item['minutes_ago'] = intval($item['minutes_ago'] ?? 0);
            $item['is_expired'] = ($item['minutes_ago'] > 1440); // 24 hours expiration (1440 minutes)

            $normPhone = normalizeEgyptianPhone($item['phone']);
            $item['normalized_phone'] = $normPhone;
            $recChurchId = intval($item['church_id'] ?? 0);
            $recChurchName = trim($item['church_name'] ?? '');

            // Look up person name and church name
            $ownerName = '';
            $ownerType = '';
            $sClean = preg_replace('/[^\d]/', '', $item['phone']);
            $sLast8 = (strlen($sClean) >= 8) ? substr($sClean, -8) : $sClean;

            if (!empty($sClean)) {
                if ($churchId > 0 && (!$isDev || $filterOnlyMyChurch)) {
                    $stuStmt = $conn->prepare("
                        SELECT s.name, s.church_id, c.church_name 
                        FROM students s
                        LEFT JOIN churches c ON s.church_id = c.id
                        WHERE s.church_id = ? 
                          AND (s.phone LIKE CONCAT('%', ?) OR RIGHT(s.phone, 8) = RIGHT(?, 8) 
                               OR s.emergency_phone LIKE CONCAT('%', ?) OR RIGHT(s.emergency_phone, 8) = RIGHT(?, 8) 
                               OR s.parent_phones LIKE CONCAT('%', ?)) 
                        LIMIT 1
                    ");
                    if ($stuStmt) {
                        $stuStmt->bind_param("isssss", $churchId, $sLast8, $sClean, $sLast8, $sClean, $sClean);
                        $stuStmt->execute();
                        $sRes = $stuStmt->get_result();
                        if ($sRow = $sRes->fetch_assoc()) {
                            $ownerName = $sRow['name'];
                            $ownerType = 'طالب';
                            if (empty($recChurchName) && !empty($sRow['church_name'])) $recChurchName = $sRow['church_name'];
                        }
                        $stuStmt->close();
                    }

                    if (empty($ownerName)) {
                        $uncStmt = $conn->prepare("
                            SELECT u.name, u.church_id, c.church_name 
                            FROM uncles u
                            LEFT JOIN churches c ON u.church_id = c.id
                            WHERE u.church_id = ? 
                              AND (u.phone LIKE CONCAT('%', ?) OR RIGHT(u.phone, 8) = RIGHT(?, 8)) 
                              AND (u.deleted IS NULL OR u.deleted = 0) 
                            LIMIT 1
                        ");
                        if ($uncStmt) {
                            $uncStmt->bind_param("iss", $churchId, $sLast8, $sClean);
                            $uncStmt->execute();
                            $uRes = $uncStmt->get_result();
                            if ($uRow = $uRes->fetch_assoc()) {
                                $ownerName = $uRow['name'];
                                $ownerType = 'خادم';
                                if (empty($recChurchName) && !empty($uRow['church_name'])) $recChurchName = $uRow['church_name'];
                            }
                            $uncStmt->close();
                        }
                    }
                } else {
                    // Global lookup across all churches
                    $stuStmt = $conn->prepare("
                        SELECT s.name, s.church_id, c.church_name 
                        FROM students s
                        LEFT JOIN churches c ON s.church_id = c.id
                        WHERE (s.phone LIKE CONCAT('%', ?) OR RIGHT(s.phone, 8) = RIGHT(?, 8) 
                               OR s.emergency_phone LIKE CONCAT('%', ?) OR RIGHT(s.emergency_phone, 8) = RIGHT(?, 8) 
                               OR s.parent_phones LIKE CONCAT('%', ?)) 
                        LIMIT 1
                    ");
                    if ($stuStmt) {
                        $stuStmt->bind_param("sssss", $sLast8, $sClean, $sLast8, $sClean, $sClean);
                        $stuStmt->execute();
                        $sRes = $stuStmt->get_result();
                        if ($sRow = $sRes->fetch_assoc()) {
                            $ownerName = $sRow['name'];
                            $ownerType = 'طالب';
                            if (empty($recChurchName) && !empty($sRow['church_name'])) $recChurchName = $sRow['church_name'];
                            if ($recChurchId <= 0 && !empty($sRow['church_id'])) $recChurchId = intval($sRow['church_id']);
                        }
                        $stuStmt->close();
                    }

                    if (empty($ownerName)) {
                        $uncStmt = $conn->prepare("
                            SELECT u.name, u.church_id, c.church_name 
                            FROM uncles u
                            LEFT JOIN churches c ON u.church_id = c.id
                            WHERE (u.phone LIKE CONCAT('%', ?) OR RIGHT(u.phone, 8) = RIGHT(?, 8)) 
                              AND (u.deleted IS NULL OR u.deleted = 0) 
                            LIMIT 1
                        ");
                        if ($uncStmt) {
                            $uncStmt->bind_param("ss", $sLast8, $sClean);
                            $uncStmt->execute();
                            $uRes = $uncStmt->get_result();
                            if ($uRow = $uRes->fetch_assoc()) {
                                $ownerName = $uRow['name'];
                                $ownerType = 'خادم';
                                if (empty($recChurchName) && !empty($uRow['church_name'])) $recChurchName = $uRow['church_name'];
                                if ($recChurchId <= 0 && !empty($uRow['church_id'])) $recChurchId = intval($uRow['church_id']);
                            }
                            $uncStmt->close();
                        }
                    }

                    if (empty($ownerName)) {
                        $prStmt = @$conn->prepare("
                            SELECT pr.name, pr.church_id, c.church_name 
                            FROM pending_registrations pr
                            LEFT JOIN churches c ON pr.church_id = c.id
                            WHERE (pr.phone LIKE CONCAT('%', ?) OR RIGHT(pr.phone, 8) = RIGHT(?, 8)) 
                            LIMIT 1
                        ");
                        if ($prStmt) {
                            $prStmt->bind_param("ss", $sLast8, $sClean);
                            $prStmt->execute();
                            $prRes = $prStmt->get_result();
                            if ($prRes && $prRow = $prRes->fetch_assoc()) {
                                $ownerName = $prRow['name'] ?? '';
                                $ownerType = 'تسجيل جديد';
                                if (empty($recChurchName) && !empty($prRow['church_name'])) $recChurchName = $prRow['church_name'];
                                if ($recChurchId <= 0 && !empty($prRow['church_id'])) $recChurchId = intval($prRow['church_id']);
                            }
                            $prStmt->close();
                        }
                    }
                }
            }

            $item['church_id'] = $recChurchId;
            $item['church_name'] = $recChurchName;
            $item['owner_name'] = $ownerName;
            $item['owner_type'] = $ownerType;

            // Pure text without emojis
            if ($item['is_verified'] === 1) {
                $item['status_badge'] = 'verified';
                $item['status_text'] = 'تم التحقق بنجاح';
            } elseif ($item['is_expired']) {
                $item['status_badge'] = 'expired';
                $item['status_text'] = 'منتهي الصلاحية';
            } elseif ($item['is_sent'] === 1) {
                $item['status_badge'] = 'sent';
                $item['status_text'] = 'أرسل للبوت';
            } else {
                $item['status_badge'] = 'pending';
                $item['status_text'] = 'في انتظار البوت';
            }

            // Message without emojis
            $msgText = "كود التحقق الخاص بك في مدارس الأحد هو: *" . $item['otp_code'] . "*\n\nصالح لمدة 24 ساعة.\nيرجى إدخال هذا الرمز لإتمام الدخول أو التسجيل.";
            $item['manual_message'] = $msgText;
            $item['manual_whatsapp_url'] = "https://api.whatsapp.com/send?phone=" . $normPhone . "&text=" . rawurlencode($msgText);
        }
        unset($item);

        sendJSON([
            'success' => true,
            'count' => count($records),
            'church_id' => ($isDev && !$filterOnlyMyChurch) ? 0 : $churchId,
            'church_name' => ($isDev && !$filterOnlyMyChurch) ? 'جميع الكنائس' : $churchName,
            'is_developer' => $isDev,
            'records' => $records
        ]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}

/**
 * Admin Resend User OTP or Generate fresh code:
 * Resets is_sent=0 and wakes the WhatsApp bot, with testing-to-production mirroring.
 */
function adminResendUserOTP() {
    try {
        if (!canAdminManageOTP()) {
            sendJSON(['success' => false, 'message' => 'غير مصرح لك بالوصول. يرجى تسجيل الدخول كمسؤول أو خادم.']);
        }

        $id = intval($_REQUEST['id'] ?? 0);
        $phone = sanitize($_REQUEST['phone'] ?? '');
        $conn = getDBConnection();

        // Determine church_id
        $churchId = intval($_SESSION['church_id'] ?? $_REQUEST['church_id'] ?? 0);
        if ($churchId <= 0 && !empty($_SESSION['uncle_id'])) {
            $uStmt = $conn->prepare("SELECT church_id FROM uncles WHERE id = ? LIMIT 1");
            if ($uStmt) {
                $uStmt->bind_param("i", $_SESSION['uncle_id']);
                $uStmt->execute();
                $uRes = $uStmt->get_result();
                if ($uRow = $uRes->fetch_assoc()) {
                    $churchId = intval($uRow['church_id']);
                    $_SESSION['church_id'] = $churchId;
                }
                $uStmt->close();
            }
        }

        if ($id > 0) {
            $stmt = $conn->prepare("SELECT id, phone, otp_code, request_token FROM phone_verifications WHERE id = ? LIMIT 1");
            $stmt->bind_param("i", $id);
            $stmt->execute();
            $res = $stmt->get_result();
            $row = $res->fetch_assoc();
            $stmt->close();

            if (!$row) {
                sendJSON(['success' => false, 'message' => 'طلب التحقق غير موجود']);
            }

            $otp = $row['otp_code'];
            $reqPhone = $row['phone'];
            $token = $row['request_token'];
            $normalizedPhone = normalizeEgyptianPhone($reqPhone);

            // Reset is_sent = 0, created_at = NOW()
            $uStmt = $conn->prepare("UPDATE phone_verifications SET is_sent = 0, is_verified = 0, created_at = NOW() WHERE id = ?");
            $uStmt->bind_param("i", $id);
            $uStmt->execute();
            $uStmt->close();

            // If on testing, mirror to production queue
            $isTestingServer = (
                strpos($_SERVER['HTTP_HOST'] ?? '', 'testing.') !== false ||
                strpos(__DIR__, '/testing') !== false
            );
            if ($isTestingServer) {
                $mCh = curl_init('https://sunday-school.online/api.php');
                $mirrorFields = [
                    'action' => 'enqueueMirrorOTP',
                    'phone' => $normalizedPhone,
                    'otp_code' => $otp,
                    'request_token' => $token,
                    'church_id' => $churchId
                ];
                curl_setopt_array($mCh, [
                    CURLOPT_POST => true,
                    CURLOPT_POSTFIELDS => http_build_query($mirrorFields),
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_TIMEOUT => 5,
                    CURLOPT_SSL_VERIFYPEER => false,
                    CURLOPT_SSL_VERIFYHOST => false
                ]);
                curl_exec($mCh);
                curl_close($mCh);
            }

            // Notify developer
            if (function_exists('_sendWebPushToDeveloper')) {
                _sendWebPushToDeveloper($conn, "إعادة إرسال كود واتساب: " . $otp, "كود: " . $otp . " لرقم: " . $normalizedPhone, '/uncle/dashboard/?open_otp=1', [
                    'otp_code' => $otp,
                    'phone' => $normalizedPhone,
                    'church_id' => $churchId
                ]);
            }

            // Wake the bot
            $wakeResult = notifyWhatsAppOTNGPendingSafe($id);

            $msgText = "كود التحقق الخاص بك في مدارس الأحد هو: *" . $otp . "*\n\nصالح لمدة 24 ساعة.\nيرجى إدخال هذا الرمز لإتمام الدخول أو التسجيل.";

            sendJSON([
                'success' => true,
                'message' => 'تمت إعادة إدراج الكود في قائمة الإرسال وتنبيه البوت',
                'id' => $id,
                'phone' => $normalizedPhone,
                'otp_code' => $otp,
                'wake' => $wakeResult['success'] ?? false,
                'manual_whatsapp_url' => "https://api.whatsapp.com/send?phone=" . $normalizedPhone . "&text=" . rawurlencode($msgText),
                'manual_message' => $msgText
            ]);
        } elseif (!empty($phone)) {
            $cleanPhone = preg_replace('/[^\d]/', '', $phone);
            $normalizedPhone = normalizeEgyptianPhone($cleanPhone);
            if (empty($normalizedPhone)) {
                sendJSON(['success' => false, 'message' => 'رقم الهاتف غير صالح']);
            }

            $otp = sprintf("%06d", mt_rand(100000, 999999));
            $requestToken = 'REQ-' . strtoupper(bin2hex(random_bytes(4)));

            @$conn->query("ALTER TABLE phone_verifications ADD COLUMN IF NOT EXISTS church_id INT NULL DEFAULT NULL AFTER id;");

            if ($churchId > 0) {
                $stmt = $conn->prepare("INSERT INTO phone_verifications (church_id, phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, ?, 0, 0, NOW())");
                $stmt->bind_param("isss", $churchId, $normalizedPhone, $requestToken, $otp);
            } else {
                $stmt = $conn->prepare("INSERT INTO phone_verifications (phone, request_token, otp_code, is_sent, is_verified, created_at) VALUES (?, ?, ?, 0, 0, NOW())");
                $stmt->bind_param("sss", $normalizedPhone, $requestToken, $otp);
            }
            $stmt->execute();
            $newId = intval($conn->insert_id ?: $stmt->insert_id);
            $stmt->close();

            $isTestingServer = (
                strpos($_SERVER['HTTP_HOST'] ?? '', 'testing.') !== false ||
                strpos(__DIR__, '/testing') !== false
            );
            if ($isTestingServer) {
                $mCh = curl_init('https://sunday-school.online/api.php');
                $mirrorFields = [
                    'action' => 'enqueueMirrorOTP',
                    'phone' => $normalizedPhone,
                    'otp_code' => $otp,
                    'request_token' => $requestToken,
                    'church_id' => $churchId
                ];
                curl_setopt_array($mCh, [
                    CURLOPT_POST => true,
                    CURLOPT_POSTFIELDS => http_build_query($mirrorFields),
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_TIMEOUT => 5,
                    CURLOPT_SSL_VERIFYPEER => false,
                    CURLOPT_SSL_VERIFYHOST => false
                ]);
                curl_exec($mCh);
                curl_close($mCh);
            }

            // Notify developer
            if (function_exists('_sendWebPushToDeveloper')) {
                _sendWebPushToDeveloper($conn, "توليد كود واتساب: " . $otp, "كود: " . $otp . " لرقم: " . $normalizedPhone, '/uncle/dashboard/?open_otp=1', [
                    'otp_code' => $otp,
                    'phone' => $normalizedPhone,
                    'church_id' => $churchId
                ]);
            }

            $wakeResult = notifyWhatsAppOTNGPendingSafe($newId);
            $msgText = "كود التحقق الخاص بك في مدارس الأحد هو: *" . $otp . "*\n\nصالح لمدة 24 ساعة.\nيرجى إدخال هذا الرمز لإتمام الدخول أو التسجيل.";

            sendJSON([
                'success' => true,
                'message' => 'تم توليد كود جديد وإضافته بنجاح',
                'id' => $newId,
                'phone' => $normalizedPhone,
                'otp_code' => $otp,
                'wake' => $wakeResult['success'] ?? false,
                'manual_whatsapp_url' => "https://api.whatsapp.com/send?phone=" . $normalizedPhone . "&text=" . rawurlencode($msgText),
                'manual_message' => $msgText
            ]);
        } else {
            sendJSON(['success' => false, 'message' => 'يرجى تحديد المعرف أو رقم الهاتف']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}

function notifyWhatsAppOTNGPendingSafe($id) {
    if (function_exists('notifyWhatsAppOTPPending')) {
        return notifyWhatsAppOTPPending($id);
    }
    return ['success' => false];
}

function getWhatsAppBotStatus() {
    if (!isAdminOrDevRole()) {
        sendJSON(['success' => false, 'message' => 'غير مصرح لك بالوصول']);
    }

    $botApiBase = '';
    if (getenv('WHATSAPP_BOT_API_URL')) {
        $botApiBase = getenv('WHATSAPP_BOT_API_URL');
    } elseif (!empty($_ENV['WHATSAPP_BOT_API_URL'])) {
        $botApiBase = $_ENV['WHATSAPP_BOT_API_URL'];
    } elseif (!empty($_SERVER['WHATSAPP_BOT_API_URL'])) {
        $botApiBase = $_SERVER['WHATSAPP_BOT_API_URL'];
    } elseif (defined('WHATSAPP_BOT_API_URL') && constant('WHATSAPP_BOT_API_URL')) {
        $botApiBase = constant('WHATSAPP_BOT_API_URL');
    } else {
        $botApiBase = 'https://baileys-qr-code--sundayschooleg.replit.app';
    }

    $botApiBase = rtrim(trim($botApiBase), '/');
    $statusUrl = $botApiBase . '/api/whatsapp/status';

    $botToken = '';
    if (getenv('WHATSAPP_BOT_API_TOKEN')) {
        $botToken = getenv('WHATSAPP_BOT_API_TOKEN');
    } elseif (!empty($_ENV['WHATSAPP_BOT_API_TOKEN'])) {
        $botToken = $_ENV['WHATSAPP_BOT_API_TOKEN'];
    } elseif (!empty($_SERVER['WHATSAPP_BOT_API_TOKEN'])) {
        $botToken = $_SERVER['WHATSAPP_BOT_API_TOKEN'];
    } elseif (defined('WHATSAPP_BOT_API_TOKEN') && constant('WHATSAPP_BOT_API_TOKEN')) {
        $botToken = constant('WHATSAPP_BOT_API_TOKEN');
    }

    $headers = ['Accept: application/json'];
    if (!empty($botToken)) {
        $headers[] = 'Authorization: Bearer ' . $botToken;
    }

    $ch = curl_init($statusUrl);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_TIMEOUT => 5,
        CURLOPT_CONNECTTIMEOUT => 4,
        CURLOPT_SSL_VERIFYPEER => false,
        CURLOPT_SSL_VERIFYHOST => false
    ]);

    $raw = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    $decoded = json_decode($raw, true);
    if ($httpCode >= 200 && $httpCode < 300 && is_array($decoded)) {
        sendJSON([
            'success' => true,
            'status' => $decoded['status'] ?? 'disconnected',
            'phone' => $decoded['phone'] ?? null,
            'hasQR' => !empty($decoded['hasQR']),
            'qr' => $decoded['qr'] ?? null
        ]);
    } else {
        sendJSON([
            'success' => false,
            'http_code' => $httpCode,
            'status' => 'unreachable',
            'message' => 'تعذر جلب حالة خادم واتساب في الوقت الحالي'
        ]);
    }
}

