function checkKidPasswordByPhone() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);

        if (empty($cleanPhone)) {
            sendJSON(['success' => false, 'message' => 'رقم الهاتف مطلوب']);
            return;
        }

        $conn = getDBConnection();
        $candidates = findStudentsByPhoneOrSiblings($conn, $phone, true);

        if (!empty($candidates)) {
            $hasPassword = false;
            $primaryStudentId = null;

            foreach ($candidates as $cand) {
                if ($primaryStudentId === null) {
                    $primaryStudentId = (int)$cand['id'];
                }
                if (!empty($cand['password_hash'])) {
                    $hasPassword = true;
                    $primaryStudentId = (int)$cand['id'];
                    break;
                }
            }

            sendJSON([
                'success' => true,
                'has_password' => $hasPassword,
                'student_id' => $primaryStudentId,
                'total_accounts' => count($candidates),
                'message' => $hasPassword ? 'يوجد كلمة مرور مسجلة لهذا الرقم' : 'لا توجد كلمة مرور مسجلة'
            ]);
        } else {
            sendJSON([
                'success' => false,
                'message' => 'لم يتم العثور على طفل بهذا الرقم'
            ]);
        }
    } catch (Throwable $e) {
        sendJSON(['success' => false, 'message' => 'خطأ في التحقق: ' . $e->getMessage()]);
    }
}



function setupStudentPassword()

{

    try {

        $studentId = intval($_POST['studentId'] ?? 0);

        $phone = sanitize($_POST['phone'] ?? '');

        $password = $_POST['password'] ?? '';

        $applyToAllSiblings = isset($_POST['applyToAllSiblings']) && $_POST['applyToAllSiblings'] === 'true';



        if ($studentId === 0 || empty($phone) || empty($password)) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

        }



        $passwordHash = hash('sha256', $password);

        $cleanPhone = preg_replace('/[^\d]/', '', $phone);



        $conn = getDBConnection();



        if ($applyToAllSiblings) {

            // Apply password to ALL students with this phone number

            $updateStmt = $conn->prepare("

                UPDATE students 

                SET password_hash = ?, updated_at = NOW()

                WHERE (phone LIKE CONCAT('%', ?) OR phone = ?)

            ");

            $updateStmt->bind_param("sss", $passwordHash, $cleanPhone, $cleanPhone);



            if ($updateStmt->execute()) {

                $affectedRows = $updateStmt->affected_rows;

                sendJSON([

                    'success' => true,

                    'message' => "تم حفظ كلمة المرور لـ $affectedRows حساب",

                    'updated_count' => $affectedRows

                ]);

            } else {

                sendJSON(['success' => false, 'message' => 'فشل في حفظ كلمة المرور: ' . $conn->error]);

            }

        } else {

            // Apply password only to selected student

            $updateStmt = $conn->prepare("

                UPDATE students 

                SET password_hash = ?, updated_at = NOW()

                WHERE id = ?

            ");

            $updateStmt->bind_param("si", $passwordHash, $studentId);



            if ($updateStmt->execute()) {

                sendJSON([

                    'success' => true,

                    'message' => 'تم حفظ كلمة المرور بنجاح'

                ]);

            } else {

                sendJSON(['success' => false, 'message' => 'فشل في حفظ كلمة المرور: ' . $conn->error]);

            }

        }



    } catch (Exception $e) {

        error_log("setupStudentPassword error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في إعداد كلمة المرور: ' . $e->getMessage()]);

    }

}



function normalizeEgyptianPhone($phone) {
    $digits = preg_replace('/[^\d]/', '', $phone);
    if (strlen($digits) === 11 && substr($digits, 0, 1) === '0') {
        return '2' . $digits; // Convert 01210868837 -> 201210868837
    }
    if (strlen($digits) === 10 && substr($digits, 0, 1) === '1') {
        return '20' . $digits; // Convert 1210868837 -> 201210868837
    }
    return $digits;
}

function verifyAndGetOTPToken() {
    try {
        $rawToken = $_POST['token'] ?? $_GET['token'] ?? '';
        $token = sanitize($rawToken);
        if (preg_match('/REQ-[A-Z0-9]+/i', $rawToken, $m)) {
            $token = strtoupper($m[0]);
        }
        $senderPhone = sanitize($_POST['phone'] ?? $_GET['phone'] ?? '');
        $cleanSender = preg_replace('/[^\d]/', '', $senderPhone);

        if (empty($token)) {
            sendJSON(['success' => false, 'message' => 'رمز الطلب غير موجود']);
        }

        $conn = getDBConnection();
        $stmt = $conn->prepare("
            SELECT id, otp_code, phone FROM phone_verifications 
            WHERE request_token = ? 
              AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
            ORDER BY id DESC LIMIT 1
        ");
        $stmt->bind_param("s", $token);
        $stmt->execute();
        $res = $stmt->get_result();

        if ($row = $res->fetch_assoc()) {
            $targetClean = preg_replace('/[^\d]/', '', $row['phone']);
            
            $targetNorm = normalizeEgyptianPhone($targetClean);
            $senderNorm = normalizeEgyptianPhone($cleanSender);

            $target8 = (strlen($targetNorm) >= 8) ? substr($targetNorm, -8) : $targetNorm;
            $sender8 = (strlen($senderNorm) >= 8) ? substr($senderNorm, -8) : $senderNorm;

            // Physical sender check:
            // 1. If sender is a standard phone number (e.g. 201037011355), enforce strict match against website phone!
            // 2. If sender is a WhatsApp Multi-Device LID (starts with 447...), accept single-use token safely!
            $isLid = (strpos($cleanSender, '447') === 0 && strlen($cleanSender) >= 14);

            if (!empty($cleanSender) && !$isLid) {
                if ($target8 !== $sender8 && strpos($senderNorm, $target8) === false && strpos($targetNorm, $sender8) === false) {
                    sendJSON(['success' => false, 'message' => 'عذراً، رقم الواتساب الذي أرسلت منه لا يطابق رقم الهاتف المطلوب في الموقع.']);
                }
            }

            // Immediately mark verification as verified in the database
            $updateVerified = $conn->prepare("UPDATE phone_verifications SET is_verified = 1 WHERE id = ?");
            $updateVerified->bind_param("i", $row['id']);
            $updateVerified->execute();

            sendJSON(['success' => true, 'otp_code' => $row['otp_code'], 'verified' => true]);
        } else {
            sendJSON(['success' => false, 'message' => 'رمز الطلب غير صحيح أو انتهت صلاحيته. يرجى إعادة الطلب من الموقع.']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}

function verifyCustomWhatsAppOTP() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $code = sanitize($_POST['code'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);
        
        if (empty($cleanPhone) || empty($code)) {
            sendJSON(['success' => false, 'message' => 'البيانات غير كاملة']);
        }
        
        $conn = getDBConnection();
        
        $tableCheck = $conn->query("SHOW TABLES LIKE 'phone_verifications'");
        if ($tableCheck->num_rows === 0) {
            sendJSON(['success' => false, 'message' => 'كود التحقق غير صحيح']);
        }
        
        $normPhone = normalizeEgyptianPhone($cleanPhone);
        $last10 = (strlen($normPhone) >= 10) ? substr($normPhone, -10) : $normPhone;
        
        // Match OTP code for this phone number generated within the 24 hours interval (86400 seconds)
        $stmt = $conn->prepare("
            SELECT id FROM phone_verifications 
            WHERE (RIGHT(phone, 10) = ? OR phone = ? OR phone = ?) 
              AND otp_code = ? 
              AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
            ORDER BY id DESC LIMIT 1
        ");
        $stmt->bind_param("ssss", $last10, $cleanPhone, $normPhone, $code);
        $stmt->execute();
        $result = $stmt->get_result();
        
        if ($row = $result->fetch_assoc()) {
            $updateStmt = $conn->prepare("UPDATE phone_verifications SET is_verified = 1 WHERE id = ?");
            $updateStmt->bind_param("i", $row['id']);
            $updateStmt->execute();
            
            sendJSON(['success' => true, 'message' => 'تم التأكد من رقم الهاتف بنجاح']);
        } else {
            sendJSON(['success' => false, 'message' => 'كود التحقق غير صحيح أو انتهت صلاحيته (صلاحية الكود 24 ساعة)']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ في التحقق: ' . $e->getMessage()]);
    }
}

function checkWhatsAppVerificationStatus() {
    try {
        $rawToken = $_POST['token'] ?? $_GET['token'] ?? '';
        $token = sanitize($rawToken);
        if (preg_match('/REQ-[A-Z0-9]+/i', $rawToken, $m)) {
            $token = strtoupper($m[0]);
        }
        $phone = sanitize($_POST['phone'] ?? $_GET['phone'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);

        if (empty($token) && empty($cleanPhone)) {
            sendJSON(['success' => false, 'verified' => false, 'message' => 'الرمز أو رقم الهاتف مطلوب']);
        }

        $conn = getDBConnection();
        if (!empty($token)) {
            $stmt = $conn->prepare("
                SELECT id, is_verified, phone 
                FROM phone_verifications 
                WHERE request_token = ? 
                  AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
                ORDER BY id DESC LIMIT 1
            ");
            $stmt->bind_param("s", $token);
        } else {
            $stmt = $conn->prepare("
                SELECT id, is_verified, phone 
                FROM phone_verifications 
                WHERE (RIGHT(phone, 10) = RIGHT(?, 10) OR phone = ?) 
                  AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
                ORDER BY id DESC LIMIT 1
            ");
            $stmt->bind_param("ss", $cleanPhone, $cleanPhone);
        }
        $stmt->execute();
        $res = $stmt->get_result();

        if ($row = $res->fetch_assoc()) {
            $isVerified = intval($row['is_verified']) === 1;
            sendJSON([
                'success' => true,
                'verified' => $isVerified,
                'message' => $isVerified ? 'تم تأكيد رقم الهاتف بنجاح' : 'في انتظار إرسال الرسالة من تطبيق واتساب'
            ]);
        } else {
            sendJSON(['success' => false, 'verified' => false, 'message' => 'طلب التحقق غير موجود']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'verified' => false, 'message' => $e->getMessage()]);
    }
}

function getLatestPhoneOTP() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $cleanPhone = preg_replace('/[^\d]/', '', $phone);
        $last8 = (strlen($cleanPhone) >= 8) ? substr($cleanPhone, -8) : $cleanPhone;
        
        if (empty($cleanPhone)) {
            sendJSON(['success' => false, 'message' => 'رقم الهاتف مطلوب']);
        }
        
        $conn = getDBConnection();

        // Query active request created on the website for this phone line
        $stmt = $conn->prepare("
            SELECT otp_code FROM phone_verifications 
            WHERE (phone LIKE CONCAT('%', ?) OR RIGHT(phone, 8) = RIGHT(?, 8) OR phone = ?) 
              AND TIMESTAMPDIFF(SECOND, created_at, NOW()) BETWEEN 0 AND 86400
            ORDER BY id DESC LIMIT 1
        ");
        $stmt->bind_param("sss", $last8, $cleanPhone, $cleanPhone);
        $stmt->execute();
        $res = $stmt->get_result();
        
        if ($row = $res->fetch_assoc()) {
            sendJSON(['success' => true, 'otp_code' => $row['otp_code']]);
        } else {
            sendJSON(['success' => false, 'message' => 'عذراً، لا يوجد طلب كود نشط لهذا الرقم. يرجى إدخال رقم هاتفك في الموقع وطلب كود التحقق أولاً.']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'Error: ' . $e->getMessage()]);
    }
}



// ── Change/Set student password with old-password verification ───────────────

function changeStudentPassword()

{

    try {

        $studentId = intval($_POST['studentId'] ?? 0);

        $phone     = sanitize($_POST['phone'] ?? '');

        $oldPass   = $_POST['oldPassword'] ?? '';

        $newPass   = $_POST['newPassword'] ?? '';

        $isAdd     = ($_POST['isAdd'] ?? 'false') === 'true'; // true = no old pass needed



        if ($studentId === 0 || empty($phone) || empty($newPass)) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }

        if (strlen($newPass) < 6) {

            sendJSON(['success' => false, 'message' => 'كلمة المرور يجب أن تكون 6 أحرف على الأقل']);

            return;

        }



        $conn = getDBConnection();



        // Fetch current hash

        $stmt = $conn->prepare("SELECT password_hash FROM students WHERE id = ? LIMIT 1");

        $stmt->bind_param("i", $studentId);

        $stmt->execute();

        $row = $stmt->get_result()->fetch_assoc();

        $currentHash = $row['password_hash'] ?? '';



        if (!$isAdd) {

            // Verify old password

            if (empty($oldPass)) {

                sendJSON(['success' => false, 'message' => 'يرجى إدخال كلمة المرور الحالية']);

                return;

            }

            $oldHash = hash('sha256', $oldPass);

            if ($oldHash !== $currentHash && !password_verify($oldPass, $currentHash)) {

                sendJSON(['success' => false, 'message' => 'كلمة المرور الحالية غير صحيحة']);

                return;

            }

        } else {

            // isAdd mode — only allowed if account actually has no password yet

            if (!empty($currentHash)) {

                sendJSON(['success' => false, 'message' => 'الحساب لديه كلمة مرور بالفعل. استخدم تغيير كلمة المرور.']);

                return;

            }

        }



        $newHash = hash('sha256', $newPass);
        $upd = $conn->prepare("UPDATE students SET password_hash = ?, updated_at = NOW() WHERE id = ?");
        $upd->bind_param("si", $newHash, $studentId);

        if ($upd->execute()) {
            // Also sync password for siblings/linked accounts sharing phone, emergency, or sibling group
            $studentPhoneQuery = $conn->query("SELECT phone, emergency_phone FROM students WHERE id = {$studentId} LIMIT 1");
            if ($studentPhoneQuery && $spRow = $studentPhoneQuery->fetch_assoc()) {
                $pToLook = !empty($spRow['phone']) ? $spRow['phone'] : ($spRow['emergency_phone'] ?? '');
                if (!empty($pToLook)) {
                    $linked = findStudentsByPhoneOrSiblings($conn, $pToLook, true);
                    foreach ($linked as $lSt) {
                        if ((int)$lSt['id'] !== (int)$studentId) {
                            @$conn->query("UPDATE students SET password_hash = '{$newHash}', updated_at = NOW() WHERE id = " . (int)$lSt['id']);
                        }
                    }
                }
            }
            sendJSON(['success' => true, 'message' => $isAdd ? 'تم إضافة كلمة المرور بنجاح' : 'تم تغيير كلمة المرور بنجاح']);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في الحفظ: ' . $conn->error]);

        }



    } catch (Exception $e) {

        error_log("changeStudentPassword error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);

    }

}



function kidLoginByPhoneWithPassword() {
    try {
        $phone = sanitize($_POST['phone'] ?? '');
        $password = $_POST['password'] ?? '';
        $studentId = intval($_POST['studentId'] ?? 0);

        if (empty($phone) || empty($password)) {
            sendJSON(['success' => false, 'message' => 'رقم الهاتف وكلمة المرور مطلوبان']);
            return;
        }

        $sha256Hash = hash('sha256', $password);
        $conn = getDBConnection();

        // 1. Fetch all candidate accounts linked to this phone (including parent_phones, emergency, and sibling groups)
        $candidates = findStudentsByPhoneOrSiblings($conn, $phone, true);

        // If a specific studentId was given and not yet in candidates, load it as well
        if ($studentId > 0 && !isset($candidates[$studentId])) {
            $stmtSingle = $conn->prepare("
                SELECT s.id, s.name, s.address, s.phone, s.emergency_phone, s.parent_phones, s.birthday, s.email,
                       s.coupons, s.attendance_coupons, s.commitment_coupons, s.task_coupons,
                       s.image_url, s.church_id, s.class_id, s.custom_info, s.password_hash, s.gender, s.trip_points,
                       c.church_name,
                       COALESCE(c.church_type, 'kids') AS church_type,
                       COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class
                FROM students s
                LEFT JOIN churches c  ON s.church_id = c.id
                LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
                LEFT JOIN classes cl  ON cl.id = s.class_id
                WHERE s.id = ?
            ");
            if ($stmtSingle) {
                $stmtSingle->bind_param("i", $studentId);
                $stmtSingle->execute();
                $singleRes = $stmtSingle->get_result();
                if ($row = $singleRes->fetch_assoc()) {
                    $row['class'] = $row['class'] ?? '---';
                    $candidates[$row['id']] = $row;
                }
            }
        }

        if (empty($candidates)) {
            sendJSON(['success' => false, 'message' => 'لم يتم العثور على حساب بهذا الرقم', 'data' => []]);
            return;
        }

        // 2. Check if password matches ANY candidate in the linked accounts
        $authenticatedFamily = false;
        foreach ($candidates as $cand) {
            $storedHash = $cand['password_hash'] ?? '';
            if (!empty($storedHash)) {
                if ($storedHash === $sha256Hash || password_verify($password, $storedHash)) {
                    $authenticatedFamily = true;
                    break;
                }
            }
        }

        if (!$authenticatedFamily) {
            sendJSON(['success' => false, 'message' => 'كلمة المرور غير صحيحة', 'data' => []]);
            return;
        }

        // 3. Family authenticated! Synchronize password_hash across all sibling accounts if missing/bcrypt
        $students = [];
        foreach ($candidates as $cand) {
            $cId = (int)$cand['id'];
            $storedHash = $cand['password_hash'] ?? '';
            if (empty($storedHash) || password_verify($password, $storedHash)) {
                @$conn->query("UPDATE students SET password_hash = '" . $conn->real_escape_string($sha256Hash) . "' WHERE id = {$cId}");
            }
            $cand['birthday'] = formatDateFromDB($cand['birthday'] ?? '');
            $cand['class'] = $cand['class'] ?? '---';
            $cand['has_password'] = true;
            unset($cand['password_hash']);
            $students[] = $cand;
        }

        $vals = array_values($students);
        sendJSON([
            'success' => true,
            'data' => $vals,
            'users' => $vals,
            'user' => count($vals) === 1 ? $vals[0] : null,
            'message' => count($vals) > 1
                ? 'تم تسجيل الدخول بنجاح - ' . count($vals) . ' أطفال مرتبطين'
                : 'تم تسجيل الدخول بنجاح'
        ]);
    } catch (Throwable $e) {
        sendJSON(['success' => false, 'message' => 'خطأ في تسجيل الدخول: ' . $e->getMessage()]);
    }
}

function kidLogin()
{
    try {
        $usernameInput = sanitize($_POST['username'] ?? '');
        $password = $_POST['password'] ?? '';

        if (empty($usernameInput) || empty($password)) {
            sendJSON(['success' => false, 'message' => 'اسم المستخدم وكلمة المرور مطلوبان']);
            return;
        }

        $conn = getDBConnection();
        $cleanInput = preg_replace('/[^\d]/', '', $usernameInput);
        $isPhoneLike = strlen($cleanInput) >= 7;
        $sha256Hash = hash('sha256', $password);

        error_log("🔐 [kidLogin] input: '$usernameInput' | isPhone: " . ($isPhoneLike ? 'yes' : 'no'));

        $candidates = [];

        // 1. Search by phone (checking primary phone, emergency phone, parent phones, and sibling groups)
        if ($isPhoneLike) {
            $phoneCandidates = findStudentsByPhoneOrSiblings($conn, $usernameInput, true);
            foreach ($phoneCandidates as $id => $row) {
                $candidates[$id] = $row;
            }
        }

        // 2. Search by username in custom_info JSON
        $usernameClean = trim($usernameInput);
        if (!empty($usernameClean)) {
            $stmt2 = $conn->prepare("
                SELECT s.id, s.name, s.address, s.phone, s.emergency_phone, s.parent_phones, s.birthday, s.email,
                       s.coupons, s.attendance_coupons, s.commitment_coupons,
                       s.task_coupons, s.image_url, s.church_id, s.class_id,
                       s.custom_info, s.password_hash, s.gender, s.trip_points,
                       c.church_name,
                       COALESCE(c.church_type, 'kids') AS church_type,
                       COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class
                FROM students s
                LEFT JOIN churches c  ON s.church_id = c.id
                LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
                LEFT JOIN classes cl  ON cl.id = s.class_id
                WHERE JSON_UNQUOTE(JSON_EXTRACT(s.custom_info, '$.username')) = ?
                   OR JSON_UNQUOTE(JSON_EXTRACT(s.custom_info, '$.username')) = ?
            ");
            $usernameCleanLower = strtolower($usernameClean);
            $stmt2->bind_param("ss", $usernameClean, $usernameCleanLower);
            $stmt2->execute();
            $res2 = $stmt2->get_result();
            $userMatchedIds = [];
            while ($row = $res2->fetch_assoc()) {
                $row['class'] = $row['class'] ?? '---';
                if (!isset($candidates[$row['id']])) {
                    $candidates[$row['id']] = $row;
                }
                $userMatchedIds[] = (int)$row['id'];
            }

            // Also check siblings for username login
            if (!empty($userMatchedIds)) {
                $uIdList = implode(',', $userMatchedIds);
                $grpRes = @$conn->query("SELECT DISTINCT group_id FROM student_sibling_group_members WHERE student_id IN ({$uIdList})");
                if ($grpRes && $grpRes->num_rows > 0) {
                    $groupIds = [];
                    while ($gr = $grpRes->fetch_assoc()) {
                        if (!empty($gr['group_id'])) {
                            $groupIds[] = "'" . $conn->real_escape_string($gr['group_id']) . "'";
                        }
                    }
                    if (!empty($groupIds)) {
                        $grpIn = implode(',', $groupIds);
                        $sibRes = @$conn->query("
                            SELECT s.id, s.name, s.address, s.phone, s.emergency_phone, s.parent_phones, s.birthday, s.email,
                                   s.coupons, s.attendance_coupons, s.commitment_coupons,
                                   s.task_coupons, s.image_url, s.church_id, s.class_id,
                                   s.custom_info, s.password_hash, s.gender, s.trip_points,
                                   c.church_name,
                                   COALESCE(c.church_type, 'kids') AS church_type,
                                   COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class
                            FROM student_sibling_group_members ssgm
                            INNER JOIN students s ON s.id = ssgm.student_id
                            LEFT JOIN churches c  ON s.church_id = c.id
                            LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
                            LEFT JOIN classes cl  ON cl.id = s.class_id
                            WHERE ssgm.group_id IN ({$grpIn})
                        ");
                        if ($sibRes) {
                            while ($sRow = $sibRes->fetch_assoc()) {
                                $sRow['class'] = $sRow['class'] ?? '---';
                                if (!isset($candidates[$sRow['id']])) {
                                    $candidates[$sRow['id']] = $sRow;
                                }
                            }
                        }
                    }
                }
            }
        }

        error_log("🔐 [kidLogin] candidates before auth: " . count($candidates));

        if (empty($candidates)) {
            sendJSON(['success' => false, 'message' => 'اسم المستخدم أو رقم الهاتف أو كلمة المرور غير صحيحة', 'data' => []]);
            return;
        }

        // Check if ANY candidate has a matching password
        $authenticatedFamily = false;
        foreach ($candidates as $cand) {
            $storedHash = $cand['password_hash'] ?? '';
            if (!empty($storedHash)) {
                if ($storedHash === $sha256Hash || password_verify($password, $storedHash)) {
                    $authenticatedFamily = true;
                    break;
                }
            }
        }

        if (!$authenticatedFamily) {
            sendJSON(['success' => false, 'message' => 'كلمة المرور غير صحيحة', 'data' => []]);
            return;
        }

        // Synchronize and format authenticated students
        $authenticated = [];
        foreach ($candidates as $student) {
            $sId = (int)$student['id'];
            $storedHash = $student['password_hash'] ?? '';
            if (empty($storedHash) || password_verify($password, $storedHash)) {
                @$conn->query("UPDATE students SET password_hash = '" . $conn->real_escape_string($sha256Hash) . "' WHERE id = {$sId}");
            }
            $student['birthday'] = formatDateFromDB($student['birthday'] ?? '');
            $student['class'] = $student['class'] ?? '---';
            $student['has_password'] = true;
            unset($student['password_hash']);
            $authenticated[] = $student;
        }

        error_log("🔐 [kidLogin] authenticated: " . count($authenticated));

        $vals = array_values($authenticated);
        sendJSON([
            'success' => true,
            'data' => $vals,
            'users' => $vals,
            'user' => count($vals) === 1 ? $vals[0] : null,
            'message' => count($vals) > 1
                ? 'تم تسجيل الدخول بنجاح - ' . count($vals) . ' أطفال مرتبطين'
                : 'تم تسجيل الدخول بنجاح'
        ]);
    } catch (Throwable $e) {
        sendJSON(['success' => false, 'message' => 'خطأ في تسجيل الدخول: ' . $e->getMessage()]);
    }
}

function checkUsernameAvailable()

{

    try {

        $username = trim(sanitize($_POST['username'] ?? ''));

        if (empty($username)) {

            sendJSON(['available' => false, 'message' => 'اسم المستخدم مطلوب']);

            return;

        }

        if (!preg_match('/^[a-zA-Z0-9_]{3,30}$/', $username)) {

            sendJSON(['available' => false, 'message' => 'حروف إنجليزية وأرقام وشرطة سفلية فقط (3-30)']);

            return;

        }

        $conn = getDBConnection();



        // Check students table — username stored in custom_info JSON

        $s1 = $conn->prepare("SELECT id FROM students WHERE JSON_UNQUOTE(JSON_EXTRACT(custom_info, '$.username')) = ? LIMIT 1");

        if ($s1) {

            $s1->bind_param("s", $username);

            $s1->execute();

            if ($s1->get_result()->num_rows > 0) {

                sendJSON(['available' => false, 'message' => 'اسم المستخدم محجوز']);

                return;

            }

        }



        // Check pending_registrations

        $conn->query("ALTER TABLE pending_registrations ADD COLUMN IF NOT EXISTS username VARCHAR(100) DEFAULT NULL");

        $s2 = $conn->prepare("SELECT id FROM pending_registrations WHERE username = ? AND status = 'pending' LIMIT 1");

        if ($s2) {

            $s2->bind_param("s", $username);

            $s2->execute();

            if ($s2->get_result()->num_rows > 0) {

                sendJSON(['available' => false, 'message' => 'اسم المستخدم محجوز']);

                return;

            }

        }



        sendJSON(['available' => true, 'message' => 'اسم المستخدم متاح']);

    } catch (Exception $e) {

        sendJSON(['available' => false, 'message' => 'خطأ: ' . $e->getMessage()]);

    }

}



function getStudentProfile()

{

    try {

        $studentId = intval($_POST['studentId'] ?? $_GET['studentId'] ?? 0);



        if ($studentId === 0) {

            sendJSON(['success' => false, 'message' => 'معرف الطفل مطلوب']);

            return;

        }



        $conn = getDBConnection();
        ensureParentPhonesColumn($conn);

        $stmt = $conn->prepare("
            SELECT
                s.id, s.name, s.address, s.phone, s.birthday, s.email,
                s.coupons, s.attendance_coupons, s.commitment_coupons,
                s.task_coupons, s.image_url, s.church_id, s.class_id,
                s.custom_info, s.trip_points, s.gender, s.emergency_phone, s.parent_phones, s.medical_notes,
                c.church_name,
                COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class
            FROM students s
            LEFT JOIN churches c  ON s.church_id = c.id
            LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
            LEFT JOIN classes cl  ON cl.id = s.class_id
            WHERE s.id = ?
        ");
        $stmt->bind_param("i", $studentId);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($row = $result->fetch_assoc()) {
            // Parent phones parsing
            $row['parent_phones'] = normalizeParentPhones($row['parent_phones'] ?? '', $row['emergency_phone'] ?? '');

            // تنسيق تاريخ الميلاد
            $row['birthday'] = formatDateFromDB($row['birthday']);
            $row['class'] = $row['class'] ?? '---';

            $tripPoints = [];
            $tripPointsDetails = [];
            if (!empty($row['trip_points'])) {
                $tripPoints = json_decode($row['trip_points'], true) ?: [];
            }
            if (!empty($tripPoints)) {
                $tripIds = array_map('intval', array_keys($tripPoints));
                if (!empty($tripIds)) {
                    $inPlaceholder = implode(',', $tripIds);
                    $tripStmt = $conn->prepare("SELECT id, title FROM trips WHERE id IN ($inPlaceholder)");
                    $tripStmt->execute();
                    $tripResult = $tripStmt->get_result();
                    while ($tRow = $tripResult->fetch_assoc()) {
                        $tId = intval($tRow['id']);
                        $tripPointsDetails[] = [
                            'id' => $tId,
                            'title' => $tRow['title'],
                            'points' => intval($tripPoints[$tId] ?? 0)
                        ];
                    }
                }
            }
            $row['trip_points_details'] = $tripPointsDetails;

            ensurePaperExamTables($conn);
            $examsStmt = $conn->prepare("
                SELECT pe.id, pe.name, pe.total_degree, pe.class_ids, pe.reference_url, ped.degree, ped.answers_picture, pe.created_at
                FROM paper_exams pe
                LEFT JOIN paper_exam_degrees ped ON pe.id = ped.paper_exam_id AND ped.student_id = ?
                WHERE pe.church_id = ?
                ORDER BY pe.created_at DESC
            ");
            $examsStmt->bind_param("ii", $studentId, $row['church_id']);
            $examsStmt->execute();
            $examsRes = $examsStmt->get_result();
            $paperExams = [];
            $studentClassId = intval($row['class_id']);
            $studentClassName = trim($row['class'] ?? '');
            if ($studentClassId === 0 && !empty($studentClassName) && $studentClassName !== 'بدون فصل') {
                $cNameNorm = normalizeArabicClassName($studentClassName);
                
                // Fetch all classes of the church to find a normalized match
                $cStmt = $conn->prepare("SELECT id, arabic_name, code FROM church_classes WHERE church_id = ?");
                if ($cStmt) {
                    $cStmt->bind_param("i", $row['church_id']);
                    $cStmt->execute();
                    $cRes = $cStmt->get_result();
                    while ($cRow = $cRes->fetch_assoc()) {
                        if (normalizeArabicClassName($cRow['arabic_name']) === $cNameNorm || normalizeArabicClassName($cRow['code']) === $cNameNorm) {
                            $studentClassId = intval($cRow['id']);
                            break;
                        }
                    }
                    $cStmt->close();
                }
                
                // Fallback to system classes if still 0
                if ($studentClassId === 0) {
                    $cStmt2 = $conn->prepare("SELECT id, arabic_name, code FROM classes");
                    if ($cStmt2) {
                        $cStmt2->execute();
                        $cRes2 = $cStmt2->get_result();
                        while ($cRow2 = $cRes2->fetch_assoc()) {
                            if (normalizeArabicClassName($cRow2['arabic_name']) === $cNameNorm || normalizeArabicClassName($cRow2['code']) === $cNameNorm) {
                                $studentClassId = intval($cRow2['id']);
                                break;
                            }
                        }
                        $cStmt2->close();
                    }
                }
            }
            while ($exRow = $examsRes->fetch_assoc()) {
                $classIdsStr = trim($exRow['class_ids'] ?? '');
                
                // Resolve allowed class IDs & names for this exam
                $allowedClassIds = [];
                if ($classIdsStr !== '') {
                    $allowedClassIds = array_filter(array_map('intval', explode(',', $classIdsStr)));
                }
                
                $showExam = false;
                if ($exRow['degree'] !== null || $exRow['answers_picture'] !== null) {
                    // Always show if the kid already has a degree/picture registered
                    $showExam = true;
                } else if (empty($allowedClassIds)) {
                    // Assigned to ALL classes
                    $showExam = true;
                } else {
                    // Fetch matching class names/codes for allowed classes of this exam
                    $allowedClassNames = [];
                    $ccPlaceholders = implode(',', array_fill(0, count($allowedClassIds), '?'));
                    
                    // Custom classes
                    $ccStmt = $conn->prepare("SELECT arabic_name, code FROM church_classes WHERE id IN ($ccPlaceholders) AND church_id = ?");
                    if ($ccStmt) {
                        $ccParams = array_merge($allowedClassIds, [$row['church_id']]);
                        $ccTypes = str_repeat('i', count($allowedClassIds)) . 'i';
                        $ccStmt->bind_param($ccTypes, ...$ccParams);
                        $ccStmt->execute();
                        $ccRes = $ccStmt->get_result();
                        while ($ccRow = $ccRes->fetch_assoc()) {
                            if (!empty($ccRow['arabic_name'])) $allowedClassNames[] = $ccRow['arabic_name'];
                            if (!empty($ccRow['code'])) $allowedClassNames[] = $ccRow['code'];
                        }
                        $ccStmt->close();
                    }
                    
                    // Global classes
                    $gcStmt = $conn->prepare("SELECT arabic_name, code FROM classes WHERE id IN ($ccPlaceholders)");
                    if ($gcStmt) {
                        $gcTypes = str_repeat('i', count($allowedClassIds));
                        $gcStmt->bind_param($gcTypes, ...$allowedClassIds);
                        $gcStmt->execute();
                        $gcRes = $gcStmt->get_result();
                        while ($gcRow = $gcRes->fetch_assoc()) {
                            if (!empty($gcRow['arabic_name'])) $allowedClassNames[] = $gcRow['arabic_name'];
                            if (!empty($gcRow['code'])) $allowedClassNames[] = $gcRow['code'];
                        }
                        $gcStmt->close();
                    }
                    
                    $allowedClassNames = array_unique(array_filter($allowedClassNames));
                    $normAllowedNames = array_map('normalizeArabicClassName', $allowedClassNames);
                    $normStudentClassName = normalizeArabicClassName($studentClassName);
                    
                    if (in_array($studentClassId, $allowedClassIds)) {
                        $showExam = true;
                    } else if ($normStudentClassName !== '' && in_array($normStudentClassName, $normAllowedNames)) {
                        $showExam = true;
                    }
                }
                if ($showExam) {
                    $paperExams[] = [
                        'id' => intval($exRow['id']),
                        'name' => $exRow['name'],
                        'total_degree' => floatval($exRow['total_degree']),
                        'reference_url' => $exRow['reference_url'],
                        'degree' => $exRow['degree'] !== null ? floatval($exRow['degree']) : null,
                        'answers_picture' => $exRow['answers_picture'],
                        'created_at' => $exRow['created_at']
                    ];
                }
            }
            $examsStmt->close();
            $row['paper_exams'] = $paperExams;

            $tasksStmt = $conn->prepare("
                SELECT ts.id, ts.task_id, ts.score, ts.coupons_awarded, ts.submitted_at, t.title AS task_title, t.total_degree AS task_total_degree
                FROM task_submissions ts
                JOIN tasks t ON ts.task_id = t.id
                WHERE ts.student_id = ? AND ts.church_id = ?
                ORDER BY ts.submitted_at DESC
            ");
            $tasksStmt->bind_param("ii", $studentId, $row['church_id']);
            $tasksStmt->execute();
            $tasksRes = $tasksStmt->get_result();
            $studentTasks = [];
            while ($tRow = $tasksRes->fetch_assoc()) {
                $studentTasks[] = [
                    'id' => intval($tRow['id']),
                    'task_id' => intval($tRow['task_id']),
                    'score' => floatval($tRow['score']),
                    'coupons_awarded' => intval($tRow['coupons_awarded']),
                    'submitted_at' => $tRow['submitted_at'],
                    'task_title' => $tRow['task_title'],
                    'task_total_degree' => floatval($tRow['task_total_degree'])
                ];
            }
            $tasksStmt->close();
            $row['tasks'] = $studentTasks;

            sendJSON([

                'success' => true,

                'student' => $row,

                'user' => $row,

                'message' => 'تم تحميل الملف الشخصي'

            ]);

        } else {

            sendJSON([

                'success' => false,

                'message' => 'لم يتم العثور على الطفل'

            ]);

        }



    } catch (Exception $e) {

        error_log("getStudentProfile error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تحميل الملف الشخصي']);

    }
}

function ensurePaperExamTables($conn) {
    if (defined('SCHEMA_MIGRATED')) { return; }
    $conn->query("CREATE TABLE IF NOT EXISTS `paper_exams` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `church_id` int(11) NOT NULL,
        `class_id` int(11) DEFAULT NULL,
        `class_ids` varchar(500) DEFAULT NULL,
        `name` varchar(255) NOT NULL,
        `total_degree` int(11) NOT NULL,
        `reference_url` varchar(500) DEFAULT NULL,
        `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
        `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
        PRIMARY KEY (`id`),
        KEY `church_id` (`church_id`),
        KEY `class_id` (`class_id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    $conn->query("CREATE TABLE IF NOT EXISTS `paper_exam_degrees` (
        `id` int(11) NOT NULL AUTO_INCREMENT,
        `paper_exam_id` int(11) NOT NULL,
        `student_id` int(11) NOT NULL,
        `degree` float DEFAULT NULL,
        `answers_picture` varchar(500) DEFAULT NULL,
        `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
        `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
        PRIMARY KEY (`id`),
        UNIQUE KEY `exam_student` (`paper_exam_id`, `student_id`),
        KEY `student_id` (`student_id`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    // MySQL 5.7 safe column checks
    $checkCol = $conn->query("SHOW COLUMNS FROM `paper_exam_degrees` LIKE 'answers_picture'");
    if ($checkCol && $checkCol->num_rows === 0) {
        $conn->query("ALTER TABLE `paper_exam_degrees` ADD COLUMN `answers_picture` varchar(500) DEFAULT NULL AFTER `degree`");
    }

    $checkClassIds = $conn->query("SHOW COLUMNS FROM `paper_exams` LIKE 'class_ids'");
    if ($checkClassIds && $checkClassIds->num_rows === 0) {
        $conn->query("ALTER TABLE `paper_exams` ADD COLUMN `class_ids` varchar(500) DEFAULT NULL AFTER `class_id`");
    }

    $checkDeg = $conn->query("SHOW COLUMNS FROM `paper_exam_degrees` LIKE 'degree'");
    if ($checkDeg && $row = $checkDeg->fetch_assoc()) {
        if (strtoupper($row['Null']) === 'NO') {
            $conn->query("ALTER TABLE `paper_exam_degrees` MODIFY COLUMN `degree` float DEFAULT NULL");
        }
    }
}

function importPaperExamDegreesCSV() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);
    
    $churchId = getChurchId();
    $examId = intval($_POST['paper_exam_id'] ?? 0);
    
    if ($examId <= 0) {
        sendJSON(['success' => false, 'message' => 'معرف الامتحان مطلوب']);
    }
    
    // Check if exam exists
    $stmt = $conn->prepare("SELECT id, name, total_degree, church_id FROM paper_exams WHERE id = ?");
    $stmt->bind_param("i", $examId);
    $stmt->execute();
    $exam = $stmt->get_result()->fetch_assoc();
    $stmt->close();
    
    if (!$exam) {
        sendJSON(['success' => false, 'message' => "الامتحان غير موجود (معرف: {$examId})"]);
    }
    
    if (intval($exam['church_id']) !== $churchId) {
        sendJSON(['success' => false, 'message' => "الامتحان غير تابع لكنيستك (كنيسة الامتحان: {$exam['church_id']}، كنيسة الجلسة: {$churchId})"]);
    }
    
    if (!isset($_FILES['csv_file']) || $_FILES['csv_file']['error'] !== UPLOAD_ERR_OK) {
        sendJSON(['success' => false, 'message' => 'لم يتم رفع أي ملف']);
    }
    
    $fileTmpPath = $_FILES['csv_file']['tmp_name'];
    $file = fopen($fileTmpPath, 'r');
    if (!$file) {
        sendJSON(['success' => false, 'message' => 'فشل فتح الملف']);
    }
    
    // Detect UTF-8 BOM
    $bom = fread($file, 3);
    if ($bom !== "\xEF\xBB\xBF") {
        rewind($file);
    }
    
    // Read header row
    $headerRow = fgetcsv($file);
    if (!$headerRow) {
        fclose($file);
        sendJSON(['success' => false, 'message' => 'ملف CSV فارغ']);
    }
    
    // Normalize headers
    $headers = array_map(function ($h) {
        $cleaned = trim(str_replace('"', '', $h));
        $cleaned = str_replace("\xEF\xBB\xBF", "", $cleaned);
        return mb_strtolower($cleaned, 'UTF-8');
    }, $headerRow);
    
    $colId = false;
    $colName = false;
    $colDegree = false;
    
    foreach ($headers as $idx => $header) {
        if (in_array($header, ['id', 'student_id', 'معرف', 'كود', 'معرف الطفل'])) {
            $colId = $idx;
        } elseif (in_array($header, ['name', 'الاسم', 'الاسم كامل', 'اسم الطفل'])) {
            $colName = $idx;
        } elseif (in_array($header, ['degree', 'الدرجة', 'درجة', 'النتيجة', 'الدرجه'])) {
            $colDegree = $idx;
        }
    }
    
    // Fallbacks
    if ($colId === false && count($headers) > 0) {
        if (strpos($headers[0], 'id') !== false || strpos($headers[0], 'معرف') !== false) {
            $colId = 0;
        }
    }
    if ($colName === false && count($headers) > 1) {
        if (strpos($headers[1], 'الاسم') !== false || strpos($headers[1], 'name') !== false) {
            $colName = 1;
        }
    }
    if ($colDegree === false && count($headers) > 2) {
        if (strpos($headers[2], 'درجة') !== false || strpos($headers[2], 'degree') !== false) {
            $colDegree = 2;
        }
    }
    
    if ($colDegree === false) {
        if (count($headers) >= 2) {
            $colDegree = count($headers) - 1;
        } else {
            fclose($file);
            sendJSON(['success' => false, 'message' => 'تعذر تحديد عمود الدرجة في الملف. يرجى كتابة رأس العمود باسم "الالدرجة"']);
        }
    }
    
    if ($colId === false && $colName === false) {
        fclose($file);
        sendJSON(['success' => false, 'message' => 'تعذر تحديد عمود معرف الطفل أو اسمه. يرجى كتابة رأس العمود باسم "الاسم" أو "id"']);
    }
    
    // Get students for mapping
    $studentsList = [];
    if ($colName !== false) {
        $stmtStu = $conn->prepare("SELECT id, name FROM students WHERE church_id = ? AND COALESCE(enrollment_status, 'active') = 'active'");
        $stmtStu->bind_param("i", $churchId);
        $stmtStu->execute();
        $resStu = $stmtStu->get_result();
        while ($sRow = $resStu->fetch_assoc()) {
            $studentsList[] = [
                'id' => intval($sRow['id']),
                'name' => $sRow['name']
            ];
        }
        $stmtStu->close();
    }
    
    $importedCount = 0;
    $errors = [];
    $rowNum = 1;
    
    while (($row = fgetcsv($file)) !== false) {
        $rowNum++;
        if (empty($row) || (count($row) === 1 && empty($row[0]))) {
            continue;
        }
        
        $studentId = null;
        $studentName = '';
        
        if ($colId !== false && isset($row[$colId]) && trim($row[$colId]) !== '') {
            $candidateId = intval(trim($row[$colId]));
            $stmtCheck = $conn->prepare("SELECT id FROM students WHERE id = ? AND church_id = ?");
            $stmtCheck->bind_param("ii", $candidateId, $churchId);
            $stmtCheck->execute();
            $checkRes = $stmtCheck->get_result()->fetch_assoc();
            $stmtCheck->close();
            if ($checkRes) {
                $studentId = $candidateId;
            }
        }
        
        if (!$studentId && $colName !== false && isset($row[$colName]) && trim($row[$colName]) !== '') {
            $studentName = trim($row[$colName]);
            
            $bestMatchId = null;
            $bestMatchScore = 0;
            
            foreach ($studentsList as $sInfo) {
                $score = calculateFuzzyScorePHP($studentName, $sInfo['name']);
                if ($score > $bestMatchScore) {
                    $bestMatchScore = $score;
                    $bestMatchId = $sInfo['id'];
                }
            }
            
            if ($bestMatchScore >= 0.75) {
                $studentId = $bestMatchId;
            } else {
                $errors[] = "السطر $rowNum: لم يتم العثور على طفل مطابق للاسم '$studentName'";
                continue;
            }
        }
        
        if (!$studentId) {
            $errors[] = "السطر $rowNum: لم يتم العثور على طفل مطابق";
            continue;
        }
        
        $degreeVal = null;
        if ($colDegree !== false && isset($row[$colDegree]) && trim($row[$colDegree]) !== '') {
            $rawDegree = trim($row[$colDegree]);
            if (is_numeric($rawDegree)) {
                $degreeVal = floatval($rawDegree);
            }
        }
        
        if ($degreeVal === null) {
            $errors[] = "السطر $rowNum: الدرجة فارغة أو غير صالحة";
            continue;
        }
        
        if ($degreeVal > $exam['total_degree'] || $degreeVal < 0) {
            $errors[] = "السطر $rowNum: الدرجة ($degreeVal) تجاوزت الحد الكلي ({$exam['total_degree']})";
            continue;
        }
        
        $stmtSave = $conn->prepare("
            INSERT INTO paper_exam_degrees (paper_exam_id, student_id, degree)
            VALUES (?, ?, ?)
            ON DUPLICATE KEY UPDATE degree = VALUES(degree)
        ");
        $stmtSave->bind_param("iid", $examId, $studentId, $degreeVal);
        $stmtSave->execute();
        $stmtSave->close();
        
        $importedCount++;
    }
    
    fclose($file);
    
    $msg = "تم استيراد $importedCount درجات بنجاح.";
    if (!empty($errors)) {
        $msg .= " (تنبيهات: " . implode(", ", array_slice($errors, 0, 3));
        if (count($errors) > 3) {
            $msg .= " وأخرى";
        }
        $msg .= ")";
    }
    
    sendJSON([
        'success' => true,
        'message' => $msg,
        'imported_count' => $importedCount,
        'errors' => $errors
    ]);
}

function getPaperExams() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);
    $churchId = getChurchId();

    $stmt = $conn->prepare("
        SELECT pe.id, pe.name, pe.total_degree, pe.class_id, pe.class_ids, pe.reference_url, pe.created_at,
               COALESCE(cc.arabic_name, cl.arabic_name) AS class_name
        FROM paper_exams pe
        LEFT JOIN church_classes cc ON cc.id = pe.class_id AND cc.church_id = pe.church_id
        LEFT JOIN classes cl ON cl.id = pe.class_id
        WHERE pe.church_id = ?
        ORDER BY pe.created_at DESC
    ");
    $stmt->bind_param("i", $churchId);
    $stmt->execute();
    $res = $stmt->get_result();
    $exams = [];
    while ($row = $res->fetch_assoc()) {
        $exams[] = [
            'id' => intval($row['id']),
            'name' => $row['name'],
            'total_degree' => floatval($row['total_degree']),
            'class_id' => $row['class_id'] !== null ? intval($row['class_id']) : null,
            'class_ids' => $row['class_ids'],
            'class_name' => $row['class_name'] ?? 'كل الفصول',
            'reference_url' => $row['reference_url'],
            'created_at' => $row['created_at']
        ];
    }
    $stmt->close();
    sendJSON(['success' => true, 'exams' => $exams]);
}

function savePaperExam() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);

    $churchId = getChurchId();
    $id = intval($_POST['id'] ?? 0);
    $classId = isset($_POST['class_id']) && $_POST['class_id'] !== '' ? intval($_POST['class_id']) : null;
    $classIds = isset($_POST['class_ids']) ? trim($_POST['class_ids']) : null;
    $name = trim($_POST['name'] ?? '');
    $totalDegree = intval($_POST['total_degree'] ?? 0);

    if (empty($name) || $totalDegree <= 0) {
        sendJSON(['success' => false, 'message' => 'الرجاء إدخال اسم الامتحان والدرجة الكلية']);
    }

    $referenceUrl = null;
    if (isset($_FILES['reference_file']) && $_FILES['reference_file']['error'] === UPLOAD_ERR_OK) {
        $file = $_FILES['reference_file'];
        $allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        $fileType = mime_content_type($file['tmp_name']);
        if (!in_array($fileType, $allowedTypes)) {
            sendJSON(['success' => false, 'message' => 'نوع الملف غير مدعوم. المسموح به: صور، PDF، Word']);
        }
        $uploadDir = __DIR__ . '/uploads/exams/';
        if (!is_dir($uploadDir)) {
            mkdir($uploadDir, 0755, true);
        }
        $ext = pathinfo($file['name'], PATHINFO_EXTENSION);
        $filename = "exam_" . time() . "_" . bin2hex(random_bytes(4)) . "." . $ext;
        if (move_uploaded_file($file['tmp_name'], $uploadDir . $filename)) {
            $baseUrl = 'https://' . $_SERVER['HTTP_HOST'];
            $referenceUrl = $baseUrl . '/uploads/exams/' . $filename;
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في حفظ الملف المرفوع']);
        }
    }

    if ($id > 0) {
        if ($referenceUrl !== null) {
            // Delete all written student degrees for this exam so they can start again
            $delDeg = $conn->prepare("DELETE FROM paper_exam_degrees WHERE paper_exam_id = ?");
            $delDeg->bind_param("i", $id);
            $delDeg->execute();
            $delDeg->close();

            $stmt = $conn->prepare("UPDATE paper_exams SET name = ?, total_degree = ?, class_id = ?, class_ids = ?, reference_url = ? WHERE id = ? AND church_id = ?");
            $stmt->bind_param("siissii", $name, $totalDegree, $classId, $classIds, $referenceUrl, $id, $churchId);
        } else {
            $stmt = $conn->prepare("UPDATE paper_exams SET name = ?, total_degree = ?, class_id = ?, class_ids = ? WHERE id = ? AND church_id = ?");
            $stmt->bind_param("siisii", $name, $totalDegree, $classId, $classIds, $id, $churchId);
        }
        $stmt->execute();
        $stmt->close();
        if (function_exists('writeAuditLog')) {
            writeAuditLog('exam_edit', 'exam', $id, $name, null, null, "تعديل امتحان ورقي: " . $name);
        }
        $msg = $referenceUrl !== null ? 'تم تعديل الامتحان وحذف جميع درجات الطلاب السابقة بنجاح' : 'تم تعديل الامتحان بنجاح';
        sendJSON(['success' => true, 'message' => $msg, 'id' => $id]);
    } else {
        $stmt = $conn->prepare("INSERT INTO paper_exams (church_id, class_id, class_ids, name, total_degree, reference_url) VALUES (?, ?, ?, ?, ?, ?)");
        $stmt->bind_param("iissis", $churchId, $classId, $classIds, $name, $totalDegree, $referenceUrl);
        $stmt->execute();
        $newId = $stmt->insert_id;
        $stmt->close();
        if (function_exists('writeAuditLog')) {
            writeAuditLog('exam_add', 'exam', $newId, $name, null, null, "إضافة امتحان ورقي جديد: " . $name);
        }
        sendJSON(['success' => true, 'message' => 'تم إضافة الامتحان بنجاح', 'id' => $newId]);
    }
}

function deletePaperExam() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);
    $churchId = getChurchId();
    $id = intval($_POST['id'] ?? 0);

    if ($id <= 0) {
        sendJSON(['success' => false, 'message' => 'معرف الامتحان غير صالح']);
    }

    $check = $conn->prepare("SELECT name FROM paper_exams WHERE id = ? AND church_id = ?");
    $check->bind_param("ii", $id, $churchId);
    $check->execute();
    $exam = $check->get_result()->fetch_assoc();
    $check->close();

    if (!$exam) {
        sendJSON(['success' => false, 'message' => 'الامتحان غير موجود']);
    }

    $delDeg = $conn->prepare("DELETE FROM paper_exam_degrees WHERE paper_exam_id = ?");
    $delDeg->bind_param("i", $id);
    $delDeg->execute();
    $delDeg->close();

    $delExam = $conn->prepare("DELETE FROM paper_exams WHERE id = ? AND church_id = ?");
    $delExam->bind_param("ii", $id, $churchId);
    $delExam->execute();
    $delExam->close();

    if (function_exists('writeAuditLog')) {
        writeAuditLog('exam_delete', 'exam', $id, $exam['name'], null, null, "حذف امتحان ورقي: " . $exam['name']);
    }
    sendJSON(['success' => true, 'message' => 'تم حذف الامتحان وجميع درجاته بنجاح']);
}

function getPaperExamDegrees() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);
    $churchId = getChurchId();
    $examId = intval($_POST['paper_exam_id'] ?? 0);
    $classId = isset($_POST['class_id']) && $_POST['class_id'] !== '' ? intval($_POST['class_id']) : null;

    if ($examId <= 0) {
        sendJSON(['success' => false, 'message' => 'معرف الامتحان مطلوب']);
    }

    $check = $conn->prepare("SELECT name, total_degree, reference_url, class_id, class_ids FROM paper_exams WHERE id = ? AND church_id = ?");
    $check->bind_param("ii", $examId, $churchId);
    $check->execute();
    $exam = $check->get_result()->fetch_assoc();
    $check->close();

    if (!$exam) {
        sendJSON(['success' => false, 'message' => 'الامتحان غير موجود']);
    }

    // Check if uncle class navigation is restricted
    $uncleClassNavigation = 'all';
    $role = $_SESSION['uncle_role'] ?? '';
    $uncleId = $_SESSION['uncle_id'] ?? 0;

    $stmtSettings = $conn->prepare("SELECT uncle_class_navigation FROM church_settings WHERE church_id = ?");
    $stmtSettings->bind_param("i", $churchId);
    $stmtSettings->execute();
    $settRes = $stmtSettings->get_result()->fetch_assoc();
    if ($settRes) {
        $uncleClassNavigation = $settRes['uncle_class_navigation'] ?? 'all';
    }
    $stmtSettings->close();

    $isRestricted = ($uncleClassNavigation === 'own' && $uncleId > 0 && !in_array(strtolower($role), ['developer', 'dev', 'admin']));

    $sql = "
        SELECT s.id, s.name, s.image_url, s.gender,
               COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class_name,
               ped.degree, ped.answers_picture
        FROM students s
        LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
        LEFT JOIN classes cl ON cl.id = s.class_id
        LEFT JOIN paper_exam_degrees ped ON ped.paper_exam_id = ? AND ped.student_id = s.id
        WHERE s.church_id = ? AND COALESCE(s.enrollment_status, 'active') = 'active'
    ";
    
    $params = [$examId, $churchId];
    $types = "ii";

    // 1. Filter by target class ID if selected in filter dropdown
    if ($classId !== null && $classId > 0) {
        $sql .= " AND s.class_id = ?";
        $params[] = $classId;
        $types .= "i";
    }

    // 2. Filter by the exam's assigned classes (class_ids or class_id)
    $allowedClassIds = [];
    if (!empty($exam['class_ids'])) {
        $allowedClassIds = array_filter(array_map('intval', explode(',', $exam['class_ids'])));
    } elseif (!empty($exam['class_id'])) {
        $allowedClassIds = [intval($exam['class_id'])];
    }
    if (!empty($allowedClassIds)) {
        // Fetch matching class names/codes to support kids who only have the text class set
        $allowedClassNames = [];
        $ccPlaceholders = implode(',', array_fill(0, count($allowedClassIds), '?'));
        
        // 2a. Custom classes names
        $ccStmt = $conn->prepare("SELECT arabic_name, code FROM church_classes WHERE id IN ($ccPlaceholders) AND church_id = ?");
        $ccParams = array_merge($allowedClassIds, [$churchId]);
        $ccTypes = str_repeat('i', count($allowedClassIds)) . 'i';
        $ccStmt->bind_param($ccTypes, ...$ccParams);
        $ccStmt->execute();
        $ccRes = $ccStmt->get_result();
        while ($ccRow = $ccRes->fetch_assoc()) {
            if (!empty($ccRow['arabic_name'])) $allowedClassNames[] = $ccRow['arabic_name'];
            if (!empty($ccRow['code'])) $allowedClassNames[] = $ccRow['code'];
        }
        $ccStmt->close();

        // 2b. Global classes names
        $gcStmt = $conn->prepare("SELECT arabic_name, code FROM classes WHERE id IN ($ccPlaceholders)");
        $gcTypes = str_repeat('i', count($allowedClassIds));
        $gcStmt->bind_param($gcTypes, ...$allowedClassIds);
        $gcStmt->execute();
        $gcRes = $gcStmt->get_result();
        while ($gcRow = $gcRes->fetch_assoc()) {
            if (!empty($gcRow['arabic_name'])) $allowedClassNames[] = $gcRow['arabic_name'];
            if (!empty($gcRow['code'])) $allowedClassNames[] = $gcRow['code'];
        }
        $gcStmt->close();

        $allowedClassNames = array_unique(array_filter($allowedClassNames));
        $idPlaceholders = implode(',', array_fill(0, count($allowedClassIds), '?'));

        if (!empty($allowedClassNames)) {
            $namePlaceholders = implode(',', array_fill(0, count($allowedClassNames), '?'));
            $sql .= " AND (s.class_id IN ($idPlaceholders) OR COALESCE(cc.arabic_name, cl.arabic_name, s.class) IN ($namePlaceholders))";
            foreach ($allowedClassIds as $cid) {
                $params[] = $cid;
                $types .= "i";
            }
            foreach ($allowedClassNames as $cname) {
                $params[] = $cname;
                $types .= "s";
            }
        } else {
            $sql .= " AND s.class_id IN ($idPlaceholders)";
            foreach ($allowedClassIds as $cid) {
                $params[] = $cid;
                $types .= "i";
            }
        }
    }



    $sql .= " ORDER BY s.name ASC";

    $stmt = $conn->prepare($sql);
    $stmt->bind_param($types, ...$params);
    $stmt->execute();
    $res = $stmt->get_result();
    
    $students = [];
    while ($row = $res->fetch_assoc()) {
        $students[] = [
            'id' => intval($row['id']),
            'name' => $row['name'],
            'image_url' => $row['image_url'],
            'gender' => $row['gender'],
            'class_name' => $row['class_name'] ?? '---',
            'degree' => $row['degree'] !== null ? floatval($row['degree']) : null,
            'answers_picture' => $row['answers_picture']
        ];
    }
    $stmt->close();

    sendJSON([
        'success' => true,
        'exam' => [
            'id' => $examId,
            'name' => $exam['name'],
            'total_degree' => floatval($exam['total_degree']),
            'reference_url' => $exam['reference_url']
        ],
        'students' => $students
    ]);
}

function savePaperExamDegrees() {
    checkAuth();
    $conn = getDBConnection();
    ensurePaperExamTables($conn);
    $churchId = getChurchId();

    $examId = intval($_POST['paper_exam_id'] ?? 0);
    $degreesRaw = $_POST['degrees'] ?? '[]';
    $degrees = json_decode($degreesRaw, true);

    if ($examId <= 0) {
        sendJSON(['success' => false, 'message' => 'معرف الامتحان مطلوب']);
    }

    $check = $conn->prepare("SELECT name, total_degree FROM paper_exams WHERE id = ? AND church_id = ?");
    $check->bind_param("ii", $examId, $churchId);
    $check->execute();
    $exam = $check->get_result()->fetch_assoc();
    $check->close();

    if (!$exam) {
        sendJSON(['success' => false, 'message' => 'الامتحان غير موجود']);
    }

    if (!is_array($degrees)) {
        sendJSON(['success' => false, 'message' => 'بيانات الدرجات غير صالحة']);
    }

    $totalDegree = floatval($exam['total_degree']);

    $stmt = $conn->prepare("
        INSERT INTO paper_exam_degrees (paper_exam_id, student_id, degree)
        VALUES (?, ?, ?)
        ON DUPLICATE KEY UPDATE degree = VALUES(degree)
    ");

    $count = 0;
    foreach ($degrees as $item) {
        $studentId = intval($item['student_id'] ?? 0);
        $degreeStr = isset($item['degree']) && $item['degree'] !== '' ? $item['degree'] : null;
        if ($studentId <= 0) continue;

        if ($degreeStr === null || $degreeStr === '') {
            $stmtUpdate = $conn->prepare("
                UPDATE paper_exam_degrees 
                SET degree = NULL 
                WHERE paper_exam_id = ? AND student_id = ?
            ");
            $stmtUpdate->bind_param("ii", $examId, $studentId);
            $stmtUpdate->execute();
            $stmtUpdate->close();
        } else {
            $degree = floatval($degreeStr);
            if ($degree > $totalDegree) {
                sendJSON(['success' => false, 'message' => "الدرجة المدخلة ({$degree}) لا يمكن أن تزيد عن درجة الامتحان الكلية ({$totalDegree})"]);
            }
            if ($degree < 0) {
                sendJSON(['success' => false, 'message' => "الدرجة المدخلة لا يمكن أن تكون أقل من الصفر"]);
            }
            $stmt->bind_param("iid", $examId, $studentId, $degree);
            $stmt->execute();
            $count++;
        }
    }
    $stmt->close();

    // Clean up rows where both degree and answers_picture are NULL
    $conn->query("DELETE FROM paper_exam_degrees WHERE degree IS NULL AND answers_picture IS NULL");

    if (function_exists('writeAuditLog')) {
        writeAuditLog('exam_degrees_save', 'exam', $examId, $exam['name'], null, null, "تحديث درجات لعدد {$count} طفل");
    }
    sendJSON(['success' => true, 'message' => 'تم حفظ درجات الامتحان بنجاح']);
}

