function getTrips()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        if ($churchId <= 0) {

            sendJSON(['success' => true, 'trips' => [], 'count' => 0]);

            return;

        }

        $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? 'uncle');

        $isAdmin = in_array($role, ['developer', 'dev', 'admin', 'administrator'], true) || ($_SESSION['login_type'] ?? '') === 'church';

        $unclesViewRaw = $_POST['uncles_view'] ?? $_GET['uncles_view'] ?? '';

        $unclesView = in_array(strtolower((string) $unclesViewRaw), ['1', 'true', 'yes'], true);



        $status = sanitize($_POST['status'] ?? $_GET['status'] ?? '');

        $type = sanitize($_POST['type'] ?? $_GET['type'] ?? '');

        $ownOnlyRaw = $_POST['own_only'] ?? $_GET['own_only'] ?? '';

        $ownOnly = in_array(strtolower((string) $ownOnlyRaw), ['1', 'true', 'yes'], true);



        $conn = getDBConnection();
        ensureTripCollaborationRequestsTable($conn);



        $sql = "SELECT 

                    t.*,

                    u.name as created_by_name,

                    ch.church_name as owner_church_name,

                    (t.church_id = ?) as is_owner,

                    (SELECT COUNT(*) FROM trip_registrations WHERE trip_id = t.id AND cancelled = 0) as registered_count,

                    (SELECT COUNT(*) FROM trip_registrations WHERE trip_id = t.id AND cancelled = 0 AND payment_status = 'paid') as paid_count

                FROM trips t

                LEFT JOIN uncles u ON t.created_by = u.id

                LEFT JOIN churches ch ON ch.id = t.church_id

                WHERE ";



        if ($ownOnly) {

            $sql .= "t.church_id = ?";

            $params = [$churchId, $churchId];

            $types = "ii";

        } else {

            // Scalar JSON_CONTAINS at '$' avoids JSON_ARRAY false positives (e.g. id 1 matching 10)

            // Binds the parameter as an integer to avoid MariaDB syntax errors with CAST(? AS JSON)

            $sql .= "(t.church_id = ? OR JSON_CONTAINS(COALESCE(NULLIF(NULLIF(t.collaborating_churches, ''), '[]'), JSON_ARRAY()), ?))";

            $params = [$churchId, $churchId, (int) $churchId];

            $types = "iii";

        }



        if (!empty($status) && $status !== 'all') {

            $sql .= " AND t.status = ?";

            $params[] = $status;

            $types .= "s";

        }



        if (!empty($type) && $type !== 'all') {

            $sql .= " AND t.type = ?";

            $params[] = $type;

            $types .= "s";

        }



        $sql .= " ORDER BY 

                    CASE t.status

                        WHEN 'planned' THEN 1

                        WHEN 'active' THEN 2

                        WHEN 'completed' THEN 3

                        WHEN 'cancelled' THEN 4

                    END,

                    t.start_date DESC";



        $stmt = $conn->prepare($sql);

        $stmt->bind_param($types, ...$params);

        $stmt->execute();

        $result = $stmt->get_result();



        $trips = [];

        while ($row = $result->fetch_assoc()) {

            if (!$ownOnly && !churchIsTripParticipant($row, $churchId)) {

                continue;

            }

            if (($unclesView || !$isAdmin) && intval($row['hide_from_uncles'] ?? 0) === 1) {

                continue;

            }



            // Clean up self-collaboration on the fly:

            if (!empty($row['collaborating_churches'])) {

                $collabArr = json_decode($row['collaborating_churches'], true);

                if (is_array($collabArr)) {

                    $ownerChurchId = intval($row['church_id']);

                    $cleanedCollab = array_values(array_filter(array_map('intval', $collabArr), function($id) use ($ownerChurchId) {

                        return $id !== $ownerChurchId;

                    }));

                    if ($cleanedCollab !== $collabArr) {

                        $newCollabJson = json_encode($cleanedCollab, JSON_UNESCAPED_UNICODE);

                        $u = $conn->prepare("UPDATE trips SET collaborating_churches = ? WHERE id = ?");

                        $u->bind_param('si', $newCollabJson, $row['id']);

                        $u->execute();

                        $row['collaborating_churches'] = $newCollabJson;

                    }

                }

            }



            // حساب السعر بعد الخصم

            $finalPrice = $row['price'];

            if ($row['discount'] > 0) {

                if ($row['discount_type'] === 'percentage') {

                    $finalPrice = $row['price'] - ($row['price'] * $row['discount'] / 100);

                } else {

                    $finalPrice = max(0, $row['price'] - $row['discount']);

                }

            }



            $row['final_price'] = round($finalPrice, 2);

            $row['start_date_formatted'] = $row['start_date'] ? date('d/m/Y', strtotime($row['start_date'])) : '';

            $row['end_date_formatted'] = $row['end_date'] ? date('d/m/Y', strtotime($row['end_date'])) : '';

            $row['collaborators_list'] = getCollaboratingChurchesList($conn, $row['collaborating_churches'] ?? '', intval($row['church_id']), $row['collaboration_limits'] ?? '');

            $row['is_owner'] = intval($row['is_owner'] ?? 0);

            if (!empty($row['custom_field_icons'])) {

                $dec = json_decode($row['custom_field_icons'], true);

                $row['custom_field_icons'] = is_array($dec) ? $dec : [];

            } else {

                $row['custom_field_icons'] = [];

            }

            // If custom_fields is empty but icons are present, derive fields from the icon keys and persist

            if ((empty($row['custom_fields']) || in_array(strtolower(trim($row['custom_fields'])), ['0', 'null', 'undefined'], true)) && !empty($row['custom_field_icons'])) {

                $keys = array_keys($row['custom_field_icons']);

                $keys = array_filter(array_map('trim', $keys), function ($f) {

                    return $f !== '';

                });

                if (count($keys)) {

                    $derived = implode(',', $keys);

                    $row['custom_fields'] = $derived;

                    try {

                        $u = $conn->prepare("UPDATE trips SET custom_fields = ? WHERE id = ?");

                        $u->bind_param('si', $derived, $row['id']);

                        $u->execute();

                    } catch (Exception $e) {}

                }

            }

            if ((empty($row['rooms_config']) || $row['rooms_config'] === '[]' || $row['rooms_config'] === 'null') && !empty($row['custom_field_icons']['السكن'])) {
                $synConfig = synthesizeRoomsConfigFromIconsPHP($row['custom_field_icons']);
                if ($synConfig) {
                    $row['rooms_config'] = $synConfig;
                    $row['has_rooms'] = 1;
                    try {
                        $u = $conn->prepare("UPDATE trips SET rooms_config = ?, has_rooms = 1 WHERE id = ?");
                        $u->bind_param('si', $synConfig, $row['id']);
                        $u->execute();
                    } catch (Exception $e) {}
                }
            }

            if (!empty($row['has_rooms']) && !empty($row['rooms_config'])) {
                $sakenMeta = buildAccommodationCustomFieldMetaPHP($row['rooms_config']);
                if ($sakenMeta) {
                    $row['custom_field_icons']['السكن'] = $sakenMeta;
                }
            }



            $row['my_registration_limit'] = null;

            if (intval($row['church_id']) !== $churchId) {

                $limits = [];

                if (!empty($row['collaboration_limits'])) {

                    $limits = json_decode($row['collaboration_limits'], true);

                }

                if (is_array($limits) && isset($limits[strval($churchId)])) {

                    $row['my_registration_limit'] = intval($limits[strval($churchId)]);

                }

            }

            if (empty($row['image_url']) || in_array(strtolower(trim((string)$row['image_url'])), ['0', 'null', 'undefined', 'false', 'none'], true)) {
                $row['image_url'] = null;
            }

            $trips[] = $row;

        }



        sendJSON([

            'success' => true,

            'trips' => $trips,

            'count' => count($trips)

        ]);



    } catch (Exception $e) {

        error_log("getTrips error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في جلب الرحلات / المؤتمرات: ' . $e->getMessage()]);

    }

}



function addTrip()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $uncleId = $_SESSION['uncle_id'] ?? null;



        $title = sanitize($_POST['title'] ?? '');

        $description = sanitize($_POST['description'] ?? '');

        $type = sanitize($_POST['type'] ?? 'one_day');

        $startDate = sanitize($_POST['start_date'] ?? '');

        $endDate = sanitize($_POST['end_date'] ?? '');

        $price = floatval($_POST['price'] ?? 0);

        $discount = floatval($_POST['discount'] ?? 0);

        $discountType = sanitize($_POST['discount_type'] ?? 'percentage');

        $maxParticipants = intval($_POST['max_participants'] ?? 0);

        $status = sanitize($_POST['status'] ?? 'planned');

        $showRegisteredKids = isset($_POST['show_registered_kids']) ? intval($_POST['show_registered_kids']) : 1;

        $showRegisteredKids = $showRegisteredKids ? 1 : 0;

        $hideFromUncles = isset($_POST['hide_from_uncles']) ? intval($_POST['hide_from_uncles']) : 0;

        $hideFromUncles = $hideFromUncles ? 1 : 0;

        $kidsVisibility = sanitize($_POST['kids_visibility'] ?? 'auto_hide');
        if (!in_array($kidsVisibility, ['auto_hide', 'always', 'never'], true)) {
            $kidsVisibility = 'auto_hide';
        }

        $hasPointsGame = isset($_POST['has_points_game']) ? intval($_POST['has_points_game']) : 0;

        $hasPointsGame = $hasPointsGame ? 1 : 0;

        $hasRooms = isset($_POST['has_rooms']) ? intval($_POST['has_rooms']) : 0;

        $hasRooms = $hasRooms ? 1 : 0;

        $roomsConfig = $_POST['rooms_config'] ?? null;

        if ($roomsConfig === '' || $roomsConfig === 'null') {

            $roomsConfig = null;

        }

        $customFields = strip_tags(trim($_POST['custom_fields'] ?? ''));

        if (in_array(strtolower($customFields), ['0', 'null', 'undefined'], true)) {

            $customFields = '';

        }

        $customFields = implode(',', array_filter(array_map('trim', explode(',', $customFields)), function ($field) {

            return $field !== '';

        }));

        // custom_field_icons — includes nested sub_fields; sanitize scalars but preserve structure

        $customFieldIconsRaw = $_POST['custom_field_icons'] ?? '';

        $customFieldIcons = null;

        if (!empty($customFieldIconsRaw)) {

            $decoded = json_decode($customFieldIconsRaw, true);

            if (is_array($decoded)) {

                $sanitizedIcons = [];

                foreach ($decoded as $fieldName => $fieldMeta) {

                    $cleanName = strip_tags(trim((string) $fieldName));

                    if ($cleanName === '')

                        continue;

                    $sanitizedMeta = [

                        'icon' => strip_tags(trim($fieldMeta['icon'] ?? 'fas fa-tag')),

                        'type' => strip_tags(trim($fieldMeta['type'] ?? 'choices')),

                        'choices' => array_values(array_filter(

                            array_map(

                                function ($c) {

                                    return strip_tags(trim((string) $c));

                                },

                                is_array($fieldMeta['choices'] ?? null) ? $fieldMeta['choices'] : []

                            ),

                            function ($c) {

                                return $c !== '';

                            }

                        )),

                    ];

                    // Preserve sub_fields: can be choice-based map to arrays of objects [{name, icon, choices}] OR legacy {choice: {name: {icon, choices}}}

                    if (!empty($fieldMeta['sub_fields']) && is_array($fieldMeta['sub_fields'])) {

                        $cleanSubFields = [];

                        foreach ($fieldMeta['sub_fields'] as $key => $subData) {

                            $cleanKey = strip_tags(trim((string) $key));

                            if ($cleanKey === '' || !is_array($subData))

                                continue;



                            // If $subData is an array of objects (new format used by frontend)

                            if (isset($subData[0]) && is_array($subData[0])) {

                                $cleanSubFields[$cleanKey] = [];

                                foreach ($subData as $sf) {

                                    if (!is_array($sf))

                                        continue;

                                    $subName = strip_tags(trim((string) ($sf['name'] ?? '')));

                                    if ($subName === '')

                                        continue;

                                    $cleanSubFields[$cleanKey][] = [

                                        'name' => $subName,

                                        'icon' => strip_tags(trim((string) ($sf['icon'] ?? 'fas fa-tag'))),

                                        'type' => strip_tags(trim((string) ($sf['type'] ?? 'choices'))),

                                        'choices' => array_values(array_filter(

                                            array_map(function ($c) {

                                                return strip_tags(trim((string) $c));

                                            }, is_array($sf['choices'] ?? null) ? $sf['choices'] : []),

                                            function ($c) {

                                                return $c !== '';

                                            }

                                        ))

                                    ];

                                }

                            } else {

                                // Legacy format or direct name-indexed object

                                $cleanSubFields[$cleanKey] = [];

                                foreach ($subData as $subName => $subMeta) {

                                    $cleanSubName = strip_tags(trim((string) $subName));

                                    if ($cleanSubName === '')

                                        continue;

                                    $cleanSubFields[$cleanKey][$cleanSubName] = [

                                        'icon' => strip_tags(trim($subMeta['icon'] ?? 'fas fa-tag')),

                                        'type' => strip_tags(trim($subMeta['type'] ?? 'choices')),

                                        'choices' => array_values(array_filter(

                                            array_map(function ($c) {

                                                return strip_tags(trim((string) $c));

                                            }, is_array($subMeta['choices'] ?? null) ? $subMeta['choices'] : []),

                                            function ($c) {

                                                return $c !== '';

                                            }

                                        )),

                                    ];

                                }

                            }

                        }

                        if (!empty($cleanSubFields)) {

                            $sanitizedMeta['sub_fields'] = $cleanSubFields;

                        }

                    }

                    $sanitizedIcons[$cleanName] = $sanitizedMeta;

                }

                $customFieldIcons = json_encode($sanitizedIcons, JSON_UNESCAPED_UNICODE);

            }

        }

        // If custom fields are empty but icons were sent as keys, derive fields from icons keys

        if ((empty($customFields) || $customFields === '0') && !empty($customFieldIconsRaw)) {

            $tryDec = json_decode($customFieldIconsRaw, true);

            if (is_array($tryDec) && count($tryDec) > 0) {

                $keys = array_keys($tryDec);

                $keys = array_filter(array_map('trim', $keys), function ($f) {

                    return $f !== '';

                });

                if (count($keys)) {

                    $customFields = implode(',', $keys);

                }

            }

        }



        if (empty($title) || empty($startDate)) {

            sendJSON(['success' => false, 'message' => 'العنوان وتاريخ البدء مطلوبان']);

            return;

        }



        // تحويل التاريخ

        $dbStartDate = formatDateToDB($startDate);

        $dbEndDate = !empty($endDate) ? formatDateToDB($endDate) : null;



        if (!$dbStartDate) {

            sendJSON(['success' => false, 'message' => 'تاريخ البدء غير صحيح']);

            return;

        }



        $conn = getDBConnection();



        $rawImgUrl = isset($_POST['image_url']) ? trim((string)$_POST['image_url']) : '';
        $imageUrl = in_array(strtolower($rawImgUrl), ['0', 'null', 'undefined', 'false', 'none', ''], true) ? null : sanitize($rawImgUrl);

        if (isset($_FILES['trip_image'])) {
            if ($_FILES['trip_image']['error'] === UPLOAD_ERR_OK) {
                $uploadDir = __DIR__ . '/uploads/trips/';
                if (!is_dir($uploadDir)) {
                    @mkdir($uploadDir, 0777, true);
                }
                $origName = $_FILES['trip_image']['name'] ?? 'image.jpg';
                $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                if (!in_array($ext, ['jpg', 'jpeg', 'png', 'webp', 'gif'], true)) {
                    $ext = 'jpg';
                }
                $filename = 'trip_' . time() . '_' . uniqid() . '.' . $ext;
                $uploadPath = $uploadDir . $filename;

                $isImg = @getimagesize($_FILES['trip_image']['tmp_name']);
                $mime = function_exists('mime_content_type') ? @mime_content_type($_FILES['trip_image']['tmp_name']) : '';

                if ($isImg !== false || (is_string($mime) && strpos($mime, 'image/') === 0)) {
                    if (move_uploaded_file($_FILES['trip_image']['tmp_name'], $uploadPath)) {
                        $host = $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'sunday-school.rf.gd';
                        $imageUrl = "https://" . $host . "/uploads/trips/" . $filename;
                    }
                }
            } elseif ($_FILES['trip_image']['error'] !== UPLOAD_ERR_NO_FILE) {
                $errCode = $_FILES['trip_image']['error'];
                sendJSON(['success' => false, 'message' => 'فشل في رفع صورة الغلاف (كود الخطأ: ' . $errCode . '). اختر صورة بحجم أصغر.']);
                return;
            }
        }



        $stmt = $conn->prepare("

            INSERT INTO trips (

                church_id, title, description, type, 

                start_date, end_date, price, discount, 

                discount_type, max_participants, status, 

                image_url, created_by, show_registered_kids,

                has_points_game, custom_fields, custom_field_icons,

                has_rooms, rooms_config, hide_from_uncles, kids_visibility

            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)

        ");



        $stmt->bind_param(

            "isssssddsissiiissisis",

            $churchId,

            $title,

            $description,

            $type,

            $dbStartDate,

            $dbEndDate,

            $price,

            $discount,

            $discountType,

            $maxParticipants,

            $status,

            $imageUrl,

            $uncleId,

            $showRegisteredKids,

            $hasPointsGame,

            $customFields,

            $customFieldIcons,

            $hasRooms,

            $roomsConfig,

            $hideFromUncles,

            $kidsVisibility

        );



        if ($stmt->execute()) {

            $tripId = $conn->insert_id;

            // Save collaboration settings
            $collabLimitMode = sanitize($_POST['collab_limit_mode'] ?? 'open');
            $collabMax = isset($_POST['collab_max_participants']) && $_POST['collab_max_participants'] !== '' ? intval($_POST['collab_max_participants']) : null;
            $updStmt = $conn->prepare("UPDATE trips SET collab_limit_mode = ?, collab_max_participants = ? WHERE id = ?");
            if ($updStmt) {
                $updStmt->bind_param("sii", $collabLimitMode, $collabMax, $tripId);
                $updStmt->execute();
            }



            // تسجيل النشاط

            logActivity($churchId, $uncleId, 'add_trip', "إضافة رحلة: $title");



            // ► AUDIT

            auditTripAdd($tripId, $title, [

                'title' => $title,

                'type' => $type,

                'start_date' => $dbStartDate,

                'end_date' => $dbEndDate,

                'price' => $price,

                'discount' => $discount,

                'max_participants' => $maxParticipants,

                'status' => $status,

                'show_registered_kids' => $showRegisteredKids,

            ]);



            sendJSON([

                'success' => true,

                'message' => 'تم إضافة الرحلة بنجاح',

                'trip_id' => $tripId,

                'image_url' => $imageUrl

            ]);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في إضافة الرحلة: ' . $stmt->error]);

        }



    } catch (Exception $e) {

        error_log("addTrip error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في إضافة الرحلة: ' . $e->getMessage()]);

    }
}

function buildAccommodationCustomFieldMetaPHP($roomsConfig) {
    if (is_string($roomsConfig)) {
        $roomsConfig = json_decode($roomsConfig, true);
    }
    if (!is_array($roomsConfig) || empty($roomsConfig)) {
        return null;
    }

    $bldChoices = [];
    $subFieldsMap = [];

    foreach ($roomsConfig as $bld) {
        $bldName = trim((string)($bld['name'] ?? ''));
        if ($bldName === '') continue;

        $bldChoices[] = $bldName;
        $bldSubs = [];

        if (!empty($bld['has_floors']) && !empty($bld['floors']) && is_array($bld['floors'])) {
            $floorChoices = [];
            $allRoomNames = [];
            foreach ($bld['floors'] as $fl) {
                $flName = trim((string)($fl['name'] ?? ''));
                if ($flName !== '') {
                    $floorChoices[] = $flName;
                }
                if (!empty($fl['rooms']) && is_array($fl['rooms'])) {
                    foreach ($fl['rooms'] as $r) {
                        if (!empty($r['is_excluded'])) continue;
                        $rName = trim((string)($r['name'] ?? ''));
                        if ($rName !== '' && !in_array($rName, $allRoomNames, true)) {
                            $allRoomNames[] = $rName;
                        }
                    }
                }
            }
            if (count($floorChoices) > 0) {
                $bldSubs[] = [
                    'name' => 'الدور',
                    'icon' => 'fas fa-layer-group',
                    'type' => 'choices',
                    'choices' => array_values(array_unique($floorChoices))
                ];
            }
            if (count($allRoomNames) > 0) {
                $bldSubs[] = [
                    'name' => 'الغرفة',
                    'icon' => 'fas fa-door-closed',
                    'type' => 'choices',
                    'choices' => array_values($allRoomNames)
                ];
            }
        } elseif (!empty($bld['rooms']) && is_array($bld['rooms'])) {
            $roomChoices = [];
            foreach ($bld['rooms'] as $r) {
                if (!empty($r['is_excluded'])) continue;
                $rName = trim((string)($r['name'] ?? ''));
                if ($rName !== '' && !in_array($rName, $roomChoices, true)) {
                    $roomChoices[] = $rName;
                }
            }
            if (count($roomChoices) > 0) {
                $bldSubs[] = [
                    'name' => 'الغرفة',
                    'icon' => 'fas fa-door-closed',
                    'type' => 'choices',
                    'choices' => array_values($roomChoices)
                ];
            }
        }

        $subFieldsMap[$bldName] = $bldSubs;
    }

    if (empty($bldChoices)) return null;

    return [
        'icon' => 'fas fa-hotel',
        'type' => 'sub_group',
        'choices' => array_values(array_unique($bldChoices)),
        'sub_fields' => $subFieldsMap
    ];
}

function synthesizeRoomsConfigFromIconsPHP($customFieldIcons) {
    if (empty($customFieldIcons['السكن']) || !is_array($customFieldIcons['السكن'])) {
        return null;
    }
    $sakenMeta = $customFieldIcons['السكن'];
    if (($sakenMeta['type'] ?? '') !== 'sub_group' || empty($sakenMeta['choices']) || !is_array($sakenMeta['choices'])) {
        return null;
    }

    $subFields = $sakenMeta['sub_fields'] ?? [];
    $synthesizedConfig = [];

    foreach ($sakenMeta['choices'] as $bldName) {
        $bldNameStr = trim((string)$bldName);
        if ($bldNameStr === '') continue;

        $bldSubs = $subFields[$bldNameStr] ?? [];
        $floorField = null;
        $roomField = null;

        if (is_array($bldSubs)) {
            foreach ($bldSubs as $sf) {
                if (is_array($sf)) {
                    $name = $sf['name'] ?? '';
                    if ($name === 'الدور' && ($sf['type'] ?? '') === 'choices') {
                        $floorField = $sf;
                    }
                    if (($name === 'الغرفة' || $name === 'رقم الغرفة') && ($sf['type'] ?? '') === 'choices') {
                        $roomField = $sf;
                    }
                }
            }
        }

        if (!empty($floorField['choices']) && is_array($floorField['choices'])) {
            $floors = [];
            foreach ($floorField['choices'] as $floorName) {
                $fNameStr = trim((string)$floorName);
                if ($fNameStr === '') continue;

                $roomChoices = (!empty($roomField['choices']) && is_array($roomField['choices'])) ? $roomField['choices'] : ['1', '2', '3', '4'];
                $rooms = [];
                foreach ($roomChoices as $rName) {
                    $rNameStr = trim((string)$rName);
                    if ($rNameStr === '') continue;
                    $rooms[] = [
                        'name' => $rNameStr,
                        'capacity' => 4,
                        'is_excluded' => false,
                        'uncles' => []
                    ];
                }
                $floors[] = [
                    'name' => $fNameStr,
                    'rooms' => $rooms
                ];
            }
            $synthesizedConfig[] = [
                'name' => $bldNameStr,
                'has_floors' => true,
                'floors' => $floors
            ];
        } elseif (!empty($roomField['choices']) && is_array($roomField['choices'])) {
            $rooms = [];
            foreach ($roomField['choices'] as $rName) {
                $rNameStr = trim((string)$rName);
                if ($rNameStr === '') continue;
                $rooms[] = [
                    'name' => $rNameStr,
                    'capacity' => 4,
                    'is_excluded' => false,
                    'uncles' => []
                ];
            }
            $synthesizedConfig[] = [
                'name' => $bldNameStr,
                'has_floors' => false,
                'rooms' => $rooms
            ];
        } else {
            $synthesizedConfig[] = [
                'name' => $bldNameStr,
                'has_floors' => false,
                'rooms' => [
                    ['name' => '1', 'capacity' => 4, 'is_excluded' => false, 'uncles' => []],
                    ['name' => '2', 'capacity' => 4, 'is_excluded' => false, 'uncles' => []]
                ]
            ];
        }
    }

    return !empty($synthesizedConfig) ? json_encode($synthesizedConfig, JSON_UNESCAPED_UNICODE) : null;
}

function mergeRoomsConfigsPHP($newConfigJson, $oldConfigJson) {
    $newConfig = is_string($newConfigJson) ? json_decode($newConfigJson, true) : $newConfigJson;
    $oldConfig = is_string($oldConfigJson) ? json_decode($oldConfigJson, true) : $oldConfigJson;

    if (!is_array($oldConfig) || empty($oldConfig)) {
        return is_string($newConfigJson) ? $newConfigJson : json_encode($newConfig, JSON_UNESCAPED_UNICODE);
    }
    if (!is_array($newConfig) || empty($newConfig)) {
        return is_string($oldConfigJson) ? $oldConfigJson : json_encode($oldConfig, JSON_UNESCAPED_UNICODE);
    }

    $existingRoomsMap = [];
    foreach ($oldConfig as $bld) {
        $bldName = trim($bld['name'] ?? '');
        if (!empty($bld['has_floors']) && isset($bld['floors']) && is_array($bld['floors'])) {
            foreach ($bld['floors'] as $floor) {
                $floorName = trim($floor['name'] ?? '');
                if (isset($floor['rooms']) && is_array($floor['rooms'])) {
                    foreach ($floor['rooms'] as $room) {
                        $roomName = trim($room['name'] ?? '');
                        $key = "{$bldName}|{$floorName}|{$roomName}";
                        $existingRoomsMap[$key] = $room;
                    }
                }
            }
        } elseif (isset($bld['rooms']) && is_array($bld['rooms'])) {
            foreach ($bld['rooms'] as $room) {
                $roomName = trim($room['name'] ?? '');
                $key = "{$bldName}||{$roomName}";
                $existingRoomsMap[$key] = $room;
            }
        }
    }

    $mergedKeys = [];
    foreach ($newConfig as &$bld) {
        $bldName = trim($bld['name'] ?? '');
        if (!empty($bld['has_floors']) && isset($bld['floors']) && is_array($bld['floors'])) {
            foreach ($bld['floors'] as &$floor) {
                $floorName = trim($floor['name'] ?? '');
                if (isset($floor['rooms']) && is_array($floor['rooms'])) {
                    foreach ($floor['rooms'] as &$room) {
                        $roomName = trim($room['name'] ?? '');
                        $key = "{$bldName}|{$floorName}|{$roomName}";
                        if (isset($existingRoomsMap[$key])) {
                            $mergedKeys[$key] = true;
                            $oldRoom = $existingRoomsMap[$key];
                            $room = array_merge($room, $oldRoom);
                        }
                    }
                }
            }
        } elseif (isset($bld['rooms']) && is_array($bld['rooms'])) {
            foreach ($bld['rooms'] as &$room) {
                $roomName = trim($room['name'] ?? '');
                $key = "{$bldName}||{$roomName}";
                if (isset($existingRoomsMap[$key])) {
                    $mergedKeys[$key] = true;
                    $oldRoom = $existingRoomsMap[$key];
                    $room = array_merge($room, $oldRoom);
                }
            }
        }
    }
    unset($bld, $floor, $room);

    foreach ($oldConfig as $oldBld) {
        $bldName = trim($oldBld['name'] ?? '');
        $foundBldIdx = null;
        foreach ($newConfig as $idx => $nb) {
            if (trim($nb['name'] ?? '') === $bldName) {
                $foundBldIdx = $idx;
                break;
            }
        }
        if ($foundBldIdx === null) {
            $newConfig[] = $oldBld;
            continue;
        }

        if (!empty($oldBld['has_floors']) && isset($oldBld['floors']) && is_array($oldBld['floors'])) {
            foreach ($oldBld['floors'] as $oldFloor) {
                $floorName = trim($oldFloor['name'] ?? '');
                $foundFloorIdx = null;
                if (isset($newConfig[$foundBldIdx]['floors']) && is_array($newConfig[$foundBldIdx]['floors'])) {
                    foreach ($newConfig[$foundBldIdx]['floors'] as $fidx => $nf) {
                        if (trim($nf['name'] ?? '') === $floorName) {
                            $foundFloorIdx = $fidx;
                            break;
                        }
                    }
                }
                if ($foundFloorIdx === null) {
                    $newConfig[$foundBldIdx]['floors'][] = $oldFloor;
                    continue;
                }
                if (isset($oldFloor['rooms']) && is_array($oldFloor['rooms'])) {
                    foreach ($oldFloor['rooms'] as $oldRoom) {
                        $roomName = trim($oldRoom['name'] ?? '');
                        $key = "{$bldName}|{$floorName}|{$roomName}";
                        if (empty($mergedKeys[$key])) {
                            $newConfig[$foundBldIdx]['floors'][$foundFloorIdx]['rooms'][] = $oldRoom;
                        }
                    }
                }
            }
        } elseif (isset($oldBld['rooms']) && is_array($oldBld['rooms'])) {
            foreach ($oldBld['rooms'] as $oldRoom) {
                $roomName = trim($oldRoom['name'] ?? '');
                $key = "{$bldName}||{$roomName}";
                if (empty($mergedKeys[$key])) {
                    $newConfig[$foundBldIdx]['rooms'][] = $oldRoom;
                }
            }
        }
    }

    return json_encode($newConfig, JSON_UNESCAPED_UNICODE);
}

function updateTrip()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $tripId = intval($_POST['trip_id'] ?? 0);



        if ($tripId === 0) {

            sendJSON(['success' => false, 'message' => 'معرف الرحلة مطلوب']);

            return;

        }



        $conn = getDBConnection();
        $safeTripId = intval($tripId);
        @$conn->query("UPDATE trips SET image_url = NULL WHERE id = {$safeTripId} AND (image_url IN ('0', 'null', 'undefined', 'false', 'none', '') OR (image_url IS NOT NULL AND TRIM(image_url) = '0'))");

        $oldTrip = getTripSnapshot($tripId);
        if (!$oldTrip) {
            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
            return;
        }

        $rawImgUrl = isset($_POST['image_url']) ? trim((string)$_POST['image_url']) : null;
        if ($rawImgUrl !== null) {
            if (in_array(strtolower($rawImgUrl), ['0', 'null', 'undefined', 'false', 'none', ''], true)) {
                $imageUrl = null;
            } else {
                $imageUrl = sanitize($rawImgUrl);
            }
        } else {
            $imageUrl = $oldTrip['image_url'] ?? null;
        }
        if ($imageUrl !== null && in_array(strtolower(trim((string)$imageUrl)), ['0', 'null', 'undefined', 'false', 'none', ''], true)) {
            $imageUrl = null;
        }

        if (isset($_FILES['trip_image'])) {
            if ($_FILES['trip_image']['error'] === UPLOAD_ERR_OK) {
                $uploadDir = __DIR__ . '/uploads/trips/';
                if (!is_dir($uploadDir)) {
                    @mkdir($uploadDir, 0777, true);
                }
                $origName = $_FILES['trip_image']['name'] ?? 'image.jpg';
                $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                if (!in_array($ext, ['jpg', 'jpeg', 'png', 'webp', 'gif'], true)) {
                    $ext = 'jpg';
                }
                $filename = 'trip_' . time() . '_' . uniqid() . '.' . $ext;
                $uploadPath = $uploadDir . $filename;

                $isImg = @getimagesize($_FILES['trip_image']['tmp_name']);
                $mime = function_exists('mime_content_type') ? @mime_content_type($_FILES['trip_image']['tmp_name']) : '';

                if ($isImg !== false || (is_string($mime) && strpos($mime, 'image/') === 0)) {
                    if (move_uploaded_file($_FILES['trip_image']['tmp_name'], $uploadPath)) {
                        $host = $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'sunday-school.rf.gd';
                        $imageUrl = "https://" . $host . "/uploads/trips/" . $filename;
                    }
                }
            } elseif ($_FILES['trip_image']['error'] !== UPLOAD_ERR_NO_FILE) {
                $errCode = $_FILES['trip_image']['error'];
                sendJSON(['success' => false, 'message' => 'فشل في رفع صورة الغلاف (كود الخطأ: ' . $errCode . '). اختر صورة بحجم أصغر.']);
                return;
            }
        }

        $title = isset($_POST['title']) ? sanitize($_POST['title']) : ($oldTrip['title'] ?? '');
        $description = isset($_POST['description']) ? sanitize($_POST['description']) : ($oldTrip['description'] ?? '');
        $type = isset($_POST['type']) ? sanitize($_POST['type']) : ($oldTrip['type'] ?? 'one_day');
        $startDate = isset($_POST['start_date']) ? sanitize($_POST['start_date']) : ($oldTrip['start_date'] ?? '');
        $endDate = isset($_POST['end_date']) ? sanitize($_POST['end_date']) : ($oldTrip['end_date'] ?? '');

        $price = isset($_POST['price']) ? floatval($_POST['price']) : floatval($oldTrip['price'] ?? 0);
        $discount = isset($_POST['discount']) ? floatval($_POST['discount']) : floatval($oldTrip['discount'] ?? 0);
        $discountType = isset($_POST['discount_type']) ? sanitize($_POST['discount_type']) : ($oldTrip['discount_type'] ?? 'percentage');
        $maxParticipants = isset($_POST['max_participants']) ? intval($_POST['max_participants']) : intval($oldTrip['max_participants'] ?? 0);
        $status = isset($_POST['status']) ? sanitize($_POST['status']) : ($oldTrip['status'] ?? 'planned');

        $showRegisteredKids = isset($_POST['show_registered_kids']) ? intval($_POST['show_registered_kids']) : intval($oldTrip['show_registered_kids'] ?? 1);
        $showRegisteredKids = $showRegisteredKids ? 1 : 0;

        $hideFromUncles = isset($_POST['hide_from_uncles']) ? intval($_POST['hide_from_uncles']) : intval($oldTrip['hide_from_uncles'] ?? 0);
        $hideFromUncles = $hideFromUncles ? 1 : 0;

        $kidsVisibility = sanitize($_POST['kids_visibility'] ?? ($oldTrip['kids_visibility'] ?? 'auto_hide'));
        if (!in_array($kidsVisibility, ['auto_hide', 'always', 'never'], true)) {
            $kidsVisibility = 'auto_hide';
        }

        $hasPointsGame = isset($_POST['has_points_game']) ? intval($_POST['has_points_game']) : intval($oldTrip['has_points_game'] ?? 0);
        $hasPointsGame = $hasPointsGame ? 1 : 0;

        $hasRooms = isset($_POST['has_rooms']) ? intval($_POST['has_rooms']) : intval($oldTrip['has_rooms'] ?? 0);
        $hasRooms = $hasRooms ? 1 : 0;

        $incomingRoomsConfig = $_POST['rooms_config'] ?? null;
        $oldRoomsConfig = $oldTrip['rooms_config'] ?? null;

        if (isset($_POST['rooms_config']) && !empty($incomingRoomsConfig) && $incomingRoomsConfig !== 'null' && $incomingRoomsConfig !== '[]' && $incomingRoomsConfig !== '') {
            $roomsConfig = $incomingRoomsConfig;
        } else {
            $roomsConfig = (!empty($oldRoomsConfig) && $oldRoomsConfig !== 'null' && $oldRoomsConfig !== '[]') ? $oldRoomsConfig : null;
        }

        $pointsConfig = isset($_POST['points_config']) ? $_POST['points_config'] : ($oldTrip['points_config'] ?? null);
        if ($pointsConfig === '' || $pointsConfig === 'null') {
            $pointsConfig = null;
        }

        $customFields = isset($_POST['custom_fields']) ? strip_tags(trim($_POST['custom_fields'])) : ($oldTrip['custom_fields'] ?? '');
        if (in_array(strtolower($customFields), ['0', 'null', 'undefined'], true)) {
            $customFields = '';
        }
        $customFields = implode(',', array_filter(array_map('trim', explode(',', $customFields)), function ($field) {
            return $field !== '';
        }));

        // custom_field_icons — includes nested sub_fields; sanitize scalars but preserve structure

        $customFieldIconsRaw = $_POST['custom_field_icons'] ?? '';

        $customFieldIcons = null;

        if (!empty($customFieldIconsRaw)) {

            $decoded = json_decode($customFieldIconsRaw, true);

            if (is_array($decoded)) {

                $sanitizedIcons = [];

                foreach ($decoded as $fieldName => $fieldMeta) {

                    $cleanName = strip_tags(trim((string) $fieldName));

                    if ($cleanName === '')

                        continue;

                    $sanitizedMeta = [

                        'icon' => strip_tags(trim($fieldMeta['icon'] ?? 'fas fa-tag')),

                        'type' => strip_tags(trim($fieldMeta['type'] ?? 'choices')),

                        'choices' => array_values(array_filter(

                            array_map(

                                function ($c) {

                                    return strip_tags(trim((string) $c));

                                },

                                is_array($fieldMeta['choices'] ?? null) ? $fieldMeta['choices'] : []

                            ),

                            function ($c) {

                                return $c !== '';

                            }

                        )),

                    ];

                    // Preserve sub_fields: can be choice-based map to arrays of objects [{name, icon, choices}] OR legacy {choice: {name: {icon, choices}}}

                    if (!empty($fieldMeta['sub_fields']) && is_array($fieldMeta['sub_fields'])) {

                        $cleanSubFields = [];

                        foreach ($fieldMeta['sub_fields'] as $key => $subData) {

                            $cleanKey = strip_tags(trim((string) $key));

                            if ($cleanKey === '' || !is_array($subData))

                                continue;



                            // If $subData is an array of objects (new format used by frontend)

                            if (isset($subData[0]) && is_array($subData[0])) {

                                $cleanSubFields[$cleanKey] = [];

                                foreach ($subData as $sf) {

                                    if (!is_array($sf))

                                        continue;

                                    $subName = strip_tags(trim((string) ($sf['name'] ?? '')));

                                    if ($subName === '')

                                        continue;

                                    $cleanSubFields[$cleanKey][] = [

                                        'name' => $subName,

                                        'icon' => strip_tags(trim((string) ($sf['icon'] ?? 'fas fa-tag'))),

                                        'type' => strip_tags(trim((string) ($sf['type'] ?? 'choices'))),

                                        'choices' => array_values(array_filter(

                                            array_map(function ($c) {

                                                return strip_tags(trim((string) $c));

                                            }, is_array($sf['choices'] ?? null) ? $sf['choices'] : []),

                                            function ($c) {

                                                return $c !== '';

                                            }

                                        ))

                                    ];

                                }

                            } else {

                                // Legacy format or direct name-indexed object

                                $cleanSubFields[$cleanKey] = [];

                                foreach ($subData as $subName => $subMeta) {

                                    $cleanSubName = strip_tags(trim((string) $subName));

                                    if ($cleanSubName === '')

                                        continue;

                                    $cleanSubFields[$cleanKey][$cleanSubName] = [

                                        'icon' => strip_tags(trim($subMeta['icon'] ?? 'fas fa-tag')),

                                        'type' => strip_tags(trim($subMeta['type'] ?? 'choices')),

                                        'choices' => array_values(array_filter(

                                            array_map(function ($c) {

                                                return strip_tags(trim((string) $c));

                                            }, is_array($subMeta['choices'] ?? null) ? $subMeta['choices'] : []),

                                            function ($c) {

                                                return $c !== '';

                                            }

                                        )),

                                    ];

                                }

                            }

                        }

                        if (!empty($cleanSubFields)) {

                            $sanitizedMeta['sub_fields'] = $cleanSubFields;

                        }

                    }

                    $sanitizedIcons[$cleanName] = $sanitizedMeta;

                }

                $customFieldIcons = json_encode($sanitizedIcons, JSON_UNESCAPED_UNICODE);

            }

        }

        // If custom fields are empty but icons were sent, derive fields from the icon keys

        if ((empty($customFields) || $customFields === '0') && !empty($customFieldIconsRaw)) {

            $tryDec = json_decode($customFieldIconsRaw, true);

            if (is_array($tryDec) && count($tryDec) > 0) {

                $keys = array_keys($tryDec);

                $keys = array_filter(array_map('trim', $keys), function ($f) {

                    return $f !== '';

                });

                if (count($keys)) {

                    $customFields = implode(',', $keys);

                }

            }

        }



        if (empty($title) || empty($startDate)) {

            sendJSON(['success' => false, 'message' => 'العنوان وتاريخ البدء مطلوبان']);

            return;

        }



        $dbStartDate = formatDateToDB($startDate);

        $dbEndDate = !empty($endDate) ? formatDateToDB($endDate) : null;



        $conn = getDBConnection();





        $ownerChurchId = intval($oldTrip['church_id']);
        $isDev = isTripDeveloperViewer();
        $isOwner = ($churchId === $ownerChurchId || $isDev);

        if (!$isOwner) {
            if (!verifyTripParticipant($conn, $tripId, $churchId)) {
                sendJSON(['success' => false, 'message' => 'غير مصرح لك بتعديل هذه الرحلة']);
                return;
            }

            // Update rooms_config, has_rooms, custom_fields, and custom_field_icons for collaborated churches
            $stmt = $conn->prepare("
                UPDATE trips 
                SET rooms_config = ?, has_rooms = ?, custom_fields = ?, custom_field_icons = ?, updated_at = NOW()
                WHERE id = ?
            ");
            $stmt->bind_param("sissi", $roomsConfig, $hasRooms, $customFields, $customFieldIcons, $tripId);
        } else {
            if ($isDev) {
                $stmt = $conn->prepare("
                    UPDATE trips 
                    SET title = ?, description = ?, type = ?, 
                        start_date = ?, end_date = ?, price = ?, 
                        discount = ?, discount_type = ?, max_participants = ?, 
                        status = ?, show_registered_kids = ?, has_points_game = ?, custom_fields = ?, custom_field_icons = ?,
                        has_rooms = ?, rooms_config = ?, points_config = ?, hide_from_uncles = ?, kids_visibility = ?, image_url = ?, updated_at = NOW()
                    WHERE id = ?
                ");
                $stmt->bind_param(
                    "sssssddsisiiisississi",
                    $title,
                    $description,
                    $type,
                    $dbStartDate,
                    $dbEndDate,
                    $price,
                    $discount,
                    $discountType,
                    $maxParticipants,
                    $status,
                    $showRegisteredKids,
                    $hasPointsGame,
                    $customFields,
                    $customFieldIcons,
                    $hasRooms,
                    $roomsConfig,
                    $pointsConfig,
                    $hideFromUncles,
                    $kidsVisibility,
                    $imageUrl,
                    $tripId
                );
            } else {
                $stmt = $conn->prepare("
                    UPDATE trips 
                    SET title = ?, description = ?, type = ?, 
                        start_date = ?, end_date = ?, price = ?, 
                        discount = ?, discount_type = ?, max_participants = ?, 
                        status = ?, show_registered_kids = ?, has_points_game = ?, custom_fields = ?, custom_field_icons = ?,
                        has_rooms = ?, rooms_config = ?, points_config = ?, hide_from_uncles = ?, kids_visibility = ?, image_url = ?, updated_at = NOW()
                    WHERE id = ? AND church_id = ?
                ");
                $stmt->bind_param(
                    "sssssddsisiiisississii",
                    $title,
                    $description,
                    $type,
                    $dbStartDate,
                    $dbEndDate,
                    $price,
                    $discount,
                    $discountType,
                    $maxParticipants,
                    $status,
                    $showRegisteredKids,
                    $hasPointsGame,
                    $customFields,
                    $customFieldIcons,
                    $hasRooms,
                    $roomsConfig,
                    $pointsConfig,
                    $hideFromUncles,
                    $kidsVisibility,
                    $imageUrl,
                    $tripId,
                    $churchId
                );
            }
        }

        if ($stmt->execute()) {
            if ($isOwner) {
                // Save collaboration settings
                $collabLimitMode = sanitize($_POST['collab_limit_mode'] ?? 'open');
                $collabMax = isset($_POST['collab_max_participants']) && $_POST['collab_max_participants'] !== '' ? intval($_POST['collab_max_participants']) : null;
                $updStmt = $conn->prepare("UPDATE trips SET collab_limit_mode = ?, collab_max_participants = ? WHERE id = ?");
                if ($updStmt) {
                    $updStmt->bind_param("sii", $collabLimitMode, $collabMax, $tripId);
                    $updStmt->execute();
                }
            }

            // Auto-promote eligible waitlist children due to limit change
            while (promoteFirstEligibleFromWaitlist($conn, $tripId)) {
                // Keep promoting
            }

            // AFTER update, get new trip data

            $newTrip = getTripSnapshot($tripId);
            if (isset($newTrip['qr_template'])) {
                if (strlen($newTrip['qr_template']) > 50000 && strpos($newTrip['qr_template'], 'data:image') !== false) {
                    $cleanTpl = cleanAndExtractBase64FromTemplate($newTrip['qr_template']);
                    $updateSql = $conn->prepare("UPDATE trips SET qr_template = ? WHERE id = ?");
                    if ($updateSql) {
                        $updateSql->bind_param("si", $cleanTpl, $tripId);
                        $updateSql->execute();
                    }
                }
                unset($newTrip['qr_template']);
            }

            // ► AUDIT
            auditTripEdit($tripId, $oldTrip ?? [], $newTrip ?? []);

            sendJSON(['success' => true, 'message' => 'تم تحديث الرحلة بنجاح', 'image_url' => $imageUrl, 'trip' => $newTrip]);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في تحديث الرحلة: ' . $stmt->error]);

        }



    } catch (Exception $e) {

        error_log("updateTrip error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تحديث الرحلة: ' . $e->getMessage()]);

    }

}

function deleteTrip()

{

    try {

        checkAuth();

        if (!isAdminOrDevRole()) {

            sendJSON(['success' => false, 'message' => 'غير مصرح - فقط للمسؤولين والمطورين حذف الرحلات']);

            return;

        }



        $tripId = intval($_POST['trip_id'] ?? 0);

        if ($tripId === 0) {

            sendJSON(['success' => false, 'message' => 'معرف الرحلة مطلوب']);

            return;

        }



        $conn = getDBConnection();

        $oldTrip = getTripSnapshot($tripId);

        if (!$oldTrip) {

            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);

            return;

        }



        $churchId = getChurchId();

        if (!isDeveloperRole() && $churchId > 0 && intval($oldTrip['church_id'] ?? 0) !== $churchId) {

            sendJSON(['success' => false, 'message' => 'غير مصرح بحذف رحلة كنيسة أخرى']);

            return;

        }



        // التحقق من وجود تسجيلات

        $checkStmt = $conn->prepare("

            SELECT COUNT(*) as cnt FROM trip_registrations 

            WHERE trip_id = ? AND cancelled = 0

        ");

        $checkStmt->bind_param("i", $tripId);

        $checkStmt->execute();

        $result = $checkStmt->get_result();

        $count = $result->fetch_assoc()['cnt'];



        if ($count > 0) {

            sendJSON([

                'success' => false,

                'message' => "لا يمكن حذف الرحلة لأن هناك $count طفل مسجل. يمكن إلغاء الرحلة بدلاً من الحذف."

            ]);

            return;

        }



        $stmt = $conn->prepare("DELETE FROM trips WHERE id = ?");

        $stmt->bind_param("i", $tripId);



        if ($stmt->execute()) {

            auditTripDelete($tripId, $oldTrip ?? ['id' => $tripId]);

            sendJSON(['success' => true, 'message' => 'تم حذف الرحلة بنجاح']);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في حذف الرحلة']);

        }



    } catch (Exception $e) {

        error_log("deleteTrip error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في حذف الرحلة: ' . $e->getMessage()]);

    }

}

function getTripDetails()

{

    try {

        // Allow both church admins AND uncles to access trip details

        checkUncleAuth();

        $churchId = getChurchId();

        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);



        if ($tripId === 0) {

            sendJSON(['success' => false, 'message' => 'معرف الرحلة مطلوب']);

            return;

        }



        $conn = getDBConnection();

        ensureGuestsTable($conn);

        ensureRoomsSchema($conn);
        ensureTripCollaborationRequestsTable($conn);



        // معلومات الرحلة — no church_id filter so collaborators can also view

        $tripStmt = $conn->prepare("

            SELECT t.*, u.name as created_by_name, ch.church_name as owner_church_name

            FROM trips t

            LEFT JOIN uncles u ON t.created_by = u.id

            LEFT JOIN churches ch ON ch.id = t.church_id

            WHERE t.id = ?

        ");

        $tripStmt->bind_param("i", $tripId);

        $tripStmt->execute();

        $tripResult = $tripStmt->get_result();



        if ($tripResult->num_rows === 0) {

            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);

            return;

        }



        $trip = $tripResult->fetch_assoc();



        // Clean up self-collaboration on the fly:

        if (!empty($trip['collaborating_churches'])) {

            $collabArr = json_decode($trip['collaborating_churches'], true);

            if (is_array($collabArr)) {

                $ownerChurchId = intval($trip['church_id']);

                $cleanedCollab = array_values(array_filter(array_map('intval', $collabArr), function($id) use ($ownerChurchId) {

                    return $id !== $ownerChurchId;

                }));

                if ($cleanedCollab !== $collabArr) {

                    $newCollabJson = json_encode($cleanedCollab, JSON_UNESCAPED_UNICODE);

                    $u = $conn->prepare("UPDATE trips SET collaborating_churches = ? WHERE id = ?");

                    $u->bind_param('si', $newCollabJson, $trip['id']);

                    $u->execute();

                    $trip['collaborating_churches'] = $newCollabJson;

                }

            }

        }



        if (!isTripDeveloperViewer()) {

            if ($churchId <= 0) {

                sendJSON(['success' => false, 'message' => 'يجب تسجيل الدخول ككنيسة لعرض هذه الرحلة']);

                return;

            }

            if (!churchIsTripParticipant($trip, $churchId)) {

                buildTripAccessDeniedResponse($conn, $trip, $churchId);

                return;

            }

        }



        // حساب السعر بعد الخصم

        $finalPrice = $trip['price'];

        if ($trip['discount'] > 0) {

            if ($trip['discount_type'] === 'percentage') {

                $finalPrice = $trip['price'] - ($trip['price'] * $trip['discount'] / 100);

            } else {

                $finalPrice = max(0, $trip['price'] - $trip['discount']);

            }

        }

        $trip['final_price'] = round($finalPrice, 2);

        $totalPerKid = getTripTotalPerKid($conn, $tripId, $trip);

        $trip['total_per_kid'] = $totalPerKid;

        $trip['expenses_per_kid'] = round(getTripExpensesPerKid($conn, $tripId), 2);

        $trip['start_date_formatted'] = date('d/m/Y', strtotime($trip['start_date']));

        $trip['end_date_formatted'] = $trip['end_date'] ? date('d/m/Y', strtotime($trip['end_date'])) : '';

        // decode custom_field_icons JSON into array for JS

        if (!empty($trip['custom_field_icons'])) {

            $decoded = json_decode($trip['custom_field_icons'], true);

            $trip['custom_field_icons'] = is_array($decoded) ? $decoded : [];

        } else {

            $trip['custom_field_icons'] = [];

        }

        // If custom_fields is empty but icons exist, derive and persist custom_fields

        if ((empty($trip['custom_fields']) || in_array(strtolower(trim($trip['custom_fields'])), ['0', 'null', 'undefined'], true)) && !empty($trip['custom_field_icons'])) {

            $keys = array_keys($trip['custom_field_icons']);

            $keys = array_filter(array_map('trim', $keys), function ($f) {

                return $f !== '';

            });

            if (count($keys)) {

                $derived = implode(',', $keys);

                $trip['custom_fields'] = $derived;

                try {

                    $up = $conn->prepare("UPDATE trips SET custom_fields = ? WHERE id = ? AND church_id = ?");

                    $up->bind_param('sii', $derived, $tripId, $churchId);

                    $up->execute();

                } catch (Exception $e) {}

            }

        }

        if ((empty($trip['rooms_config']) || $trip['rooms_config'] === '[]' || $trip['rooms_config'] === 'null') && !empty($trip['custom_field_icons']['السكن'])) {
            $synConfig = synthesizeRoomsConfigFromIconsPHP($trip['custom_field_icons']);
            if ($synConfig) {
                $trip['rooms_config'] = $synConfig;
                $trip['has_rooms'] = 1;
                try {
                    $u = $conn->prepare("UPDATE trips SET rooms_config = ?, has_rooms = 1 WHERE id = ?");
                    $u->bind_param('si', $synConfig, $tripId);
                    $u->execute();
                } catch (Exception $e) {}
            }
        }

        if (!empty($trip['has_rooms']) && !empty($trip['rooms_config'])) {
            $sakenMeta = buildAccommodationCustomFieldMetaPHP($trip['rooms_config']);
            if ($sakenMeta) {
                $trip['custom_field_icons']['السكن'] = $sakenMeta;
            }
        }



        $registrations = [];
        $totalPaid = 0;
        $totalDonations = 0;
        $pendingAmount = 0;

        // Fetch all payments for this trip to build history and compute totals efficiently
        $paymentsStmt = $conn->prepare("
            SELECT tp.*, u.name as received_by_name
            FROM trip_payments tp
            LEFT JOIN uncles u ON tp.received_by = u.id
            JOIN trip_registrations tr ON tp.registration_id = tr.id
            WHERE tr.trip_id = ?
            ORDER BY tp.id ASC
        ");
        $paymentsStmt->bind_param("i", $tripId);
        $paymentsStmt->execute();
        $paymentsResult = $paymentsStmt->get_result();

        $allPayments = [];
        $paymentTotals = [];
        while ($p = $paymentsResult->fetch_assoc()) {
            $regId = intval($p['registration_id']);
            $allPayments[$regId][] = $p;
            if (empty($p['is_deleted'])) {
                if (!isset($paymentTotals[$regId])) {
                    $paymentTotals[$regId] = ['paid' => 0.0, 'donation' => 0.0];
                }
                $paymentTotals[$regId]['paid'] += floatval($p['amount']);
                $paymentTotals[$regId]['donation'] += floatval($p['donation']);
            }
        }

        // قائمة المسجلين (Fast indexed query)
        $regStmt = $conn->prepare("
            SELECT 
                tr.*,
                COALESCE(s.name, g.name, unc.name) as student_name,
                COALESCE(cc.arabic_name, gc.arabic_name, s.class, g.class, CASE WHEN tr.registration_type = 'uncle' THEN 'خادم' ELSE NULL END) as student_class,
                COALESCE(s.phone, g.phone, unc.phone) as student_phone,
                COALESCE(s.image_url, g.image_url, unc.image_url) as student_image,
                s.trip_points as student_trip_points,
                COALESCE(s.gender, g.gender, unc.gender) as student_gender,
                COALESCE(s.emergency_phone, g.guardian_name) as guest_guardian_name,
                u.name as registered_by_name,
                tr.payment_history,
                s.birthday as student_birthday,
                s.emergency_phone as student_emergency_phone,
                s.medical_notes as student_medical_notes,
                s.address as student_address,
                s.coupons as student_coupons,
                s.attendance_coupons as student_attendance_coupons,
                s.commitment_coupons as student_commitment_coupons,
                s.task_coupons as student_task_coupons,
                s.custom_info as student_custom_info,
                s.is_guest as student_is_guest,
                COALESCE(s.church_id, g.church_id, unc.church_id, tr.church_id, t.church_id) as student_church_id,
                ch.church_name as student_church_name,
                ch.church_name as church_name
            FROM trip_registrations tr
            JOIN trips t ON tr.trip_id = t.id
            LEFT JOIN students s ON tr.student_id = s.id
            LEFT JOIN guests g ON tr.guest_id = g.id
            LEFT JOIN uncles unc ON tr.uncle_id = unc.id
            LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id AND cc.is_active = 1
            LEFT JOIN classes gc ON gc.id = s.class_id
            LEFT JOIN uncles u ON tr.registered_by = u.id
            LEFT JOIN churches ch ON ch.id = COALESCE(s.church_id, g.church_id, unc.church_id, tr.church_id, t.church_id)
            WHERE tr.trip_id = ? AND tr.cancelled = 0
            ORDER BY tr.registration_date
        ");
        $regStmt->bind_param("i", $tripId);
        $regStmt->execute();
        $regResult = $regStmt->get_result();

        while ($row = $regResult->fetch_assoc()) {
            $regId = intval($row['id']);
            $row['total_paid'] = floatval($paymentTotals[$regId]['paid'] ?? 0);
            $row['total_donation'] = floatval($paymentTotals[$regId]['donation'] ?? 0);



            $tp = json_decode($row['student_trip_points'] ?? '{}', true);

            $row['is_naughty'] = $tp["n_{$tripId}"] ?? false;

            $row['trip_points_val'] = intval($tp[$tripId] ?? 0);



            // Build history from real trip_payments table

            $regPayments = $allPayments[$row['id']] ?? [];

            $history = [];

            foreach ($regPayments as $p) {

                $type = 'payment';

                if ($p['amount'] > 0 && (strpos($p['notes'], 'دفعة مقدمة') !== false)) {

                    $type = 'deposit';

                } elseif ($p['amount'] == 0 && $p['donation'] > 0) {

                    $type = 'donation';

                }



                $history[] = [

                    'id' => $p['id'],

                    'type' => $type,

                    'timestamp' => $p['payment_date'] ?? $p['created_at'] ?? null,

                    'amount' => floatval($p['amount']),

                    'donation' => floatval($p['donation']),

                    'payment_method' => $p['payment_method'],

                    'received_by' => $p['received_by_name'] ?: '—',

                    'notes' => $p['notes'],

                    'is_deleted' => intval($p['is_deleted'] ?? 0)

                ];

            }

            $row['payment_history'] = $history;



            $payStatus = tripPaymentStatusFromPaid($row['total_paid'], $totalPerKid);

            $row['remaining'] = $payStatus['remaining'];

            $row['payment_status'] = $payStatus['payment_status'];



            $totalPaid += $row['total_paid'];

            $totalDonations += $row['total_donation'];

            if ($row['remaining'] > 0) {

                $pendingAmount += $row['remaining'];

            }



            $registrations[] = $row;

        }



        ensureWaitlistTable($conn);

        $waitlist = getWaitlistData($tripId, $conn);

        $waitlistCollected = 0.0;

        $waitlistDonations = 0.0;

        $waitlistPending = 0.0;

        foreach ($waitlist as $w) {

            $waitlistCollected += floatval($w['total_paid'] ?? 0);

            $waitlistDonations += floatval($w['total_donation'] ?? 0);

            $waitlistPending += floatval($w['remaining'] ?? 0);

        }



        // Self-healing: if a student is both registered and waitlisted, delete them from waitlist
        $registeredStudentIds = array_column($registrations, 'student_id');
        $cleanWaitlist = [];
        $needWaitlistUpdate = false;
        foreach ($waitlist as $w) {
            $wStudentId = intval($w['student_id']);
            if (in_array($wStudentId, $registeredStudentIds, true)) {
                // Delete from DB waitlist table
                $delW = $conn->prepare("DELETE FROM trip_waitlist WHERE trip_id = ? AND student_id = ?");
                $delW->bind_param("ii", $tripId, $wStudentId);
                $delW->execute();
                $needWaitlistUpdate = true;
            } else {
                $cleanWaitlist[] = $w;
            }
        }
        if ($needWaitlistUpdate) {
            // Re-number remaining positions
            $conn->query("SET @pos := 0");
            $upd = $conn->prepare("UPDATE trip_waitlist SET position = (@pos := @pos + 1) WHERE trip_id = ? ORDER BY position ASC");
            $upd->bind_param("i", $tripId);
            $upd->execute();
            // Fetch updated waitlist
            $waitlist = getWaitlistData($tripId, $conn);
        }

        $trip['registrations'] = $registrations;

        $trip['waitlist'] = $waitlist;

        $participantCount = count($registrations) + count($waitlist);

        $trip['stats'] = [

            'registered' => count($registrations),

            'waitlist_count' => count($waitlist),

            'participant_count' => $participantCount,

            'paid_count' => count(array_filter($registrations, function ($r) {

                return $r['payment_status'] === 'paid';

            })),

            'partial_count' => count(array_filter($registrations, function ($r) {

                return $r['payment_status'] === 'partial';

            })),

            'pending_count' => count(array_filter($registrations, function ($r) {

                return $r['payment_status'] === 'pending';

            })),

            'total_collected' => round($totalPaid + $waitlistCollected, 2),

            'registration_collected' => round($totalPaid, 2),

            'waitlist_collected' => round($waitlistCollected, 2),

            'total_donations' => round($totalDonations + $waitlistDonations, 2),

            'registration_pending' => round($pendingAmount, 2),

            'waitlist_pending' => round($waitlistPending, 2),

            'pending_amount' => round($pendingAmount + $waitlistPending, 2),

            'total_expected' => round($totalPerKid * $participantCount, 2),

            'registration_expected' => round($totalPerKid * count($registrations), 2),

            'waitlist_expected' => round($totalPerKid * count($waitlist), 2),

            'total_per_kid' => $totalPerKid,

        ];



        $trip['collaborators_list'] = getCollaboratingChurchesList($conn, $trip['collaborating_churches'] ?? '', intval($trip['church_id']), $trip['collaboration_limits'] ?? '');

        $trip['is_owner'] = ($churchId > 0 && intval($trip['church_id']) === $churchId) ? 1 : 0;

        $unclePhoto = null;
        if (!empty($_SESSION['uncle_id'])) {
            $uStmt = $conn->prepare("SELECT image_url FROM uncles WHERE id = ? LIMIT 1");
            $uStmt->bind_param("i", $_SESSION['uncle_id']);
            $uStmt->execute();
            $uRes = $uStmt->get_result();
            if ($uRes && $uRow = $uRes->fetch_assoc()) {
                $unclePhoto = $uRow['image_url'];
            }
        }

        sendJSON([

            'success' => true,

            'trip' => $trip,

            'user_role' => $_SESSION['uncle_role'] ?? 'uncle',

            'uncle_id' => $_SESSION['uncle_id'] ?? null,

            'uncle_name' => $_SESSION['uncle_name'] ?? null,

            'uncle_photo' => $unclePhoto

        ]);



    } catch (Exception $e) {

        error_log("getTripDetails error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في جلب تفاصيل الرحلة: ' . $e->getMessage()]);

    }

}



function bulkUpdateCustomData()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $tripId = intval($_POST['trip_id'] ?? 0);

        $rawData = $_POST['data'] ?? '';



        if ($tripId === 0 || empty($rawData)) {

            sendJSON(['success' => false, 'message' => 'معرف الرحلة والبيانات مطلوبان']);

            return;

        }



        $updates = json_decode($rawData, true);

        if (!is_array($updates)) {

            sendJSON(['success' => false, 'message' => 'تنسيق البيانات غير صالح']);

            return;

        }



        $conn = getDBConnection();

        if (!verifyTripParticipant($conn, $tripId, $churchId) && !isTripDeveloperViewer()) {

            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة أو غير مصرح بها', 'debug_church_id' => $churchId]);

            return;

        }



        $updateStmt = $conn->prepare("UPDATE trip_registrations SET custom_data = ? WHERE id = ? AND trip_id = ? AND cancelled = 0");

        if (!$updateStmt) {

            sendJSON(['success' => false, 'message' => 'فشل إعداد الاستعلام']);

            return;

        }



        $updatedCount = 0;
        $debugRows = [];

        foreach ($updates as $row) {

            $registrationId = intval($row['registration_id'] ?? 0);

            $customData = $row['custom_data'] ?? [];

            if ($registrationId <= 0 || !is_array($customData)) {
                $debugRows[] = ['reg_id' => $registrationId, 'skipped' => 'invalid_id_or_no_customdata'];
                continue;

            }

            if (!verifyRegistrationParticipant($conn, $registrationId, $churchId)) {
                $debugRows[] = ['reg_id' => $registrationId, 'skipped' => 'verify_failed', 'church_id' => $churchId];
                continue;

            }



            $getStmt = $conn->prepare("SELECT custom_data FROM trip_registrations WHERE id = ?");
            $getStmt->bind_param("i", $registrationId);
            $getStmt->execute();
            $currResult = $getStmt->get_result();
            $existing = [];
            if ($currResult && $rowObj = $currResult->fetch_assoc()) {
                $existing = json_decode($rowObj['custom_data'] ?? '[]', true) ?: [];
            }
            $getStmt->close();

            foreach ($customData as $key => $value) {
                // Preserve key structure — Arabic field names + __sub__ separators
                $fieldKey = strip_tags(trim((string) $key));
                if ($fieldKey === '') {
                    continue;
                }
                $cleanVal = strip_tags(trim((string) $value));
                // Only store if a value was selected, delete if explicitly cleared
                if ($cleanVal !== '') {
                    $existing[$fieldKey] = $cleanVal;
                } else {
                    unset($existing[$fieldKey]);
                }
            }

            $json = !empty($existing) ? json_encode($existing, JSON_UNESCAPED_UNICODE) : null;

            $updateStmt->bind_param('sii', $json, $registrationId, $tripId);

            if ($updateStmt->execute()) {
                $updatedCount++;
                $debugRows[] = ['reg_id' => $registrationId, 'status' => 'updated', 'new_data' => $existing];
            } else {
                $debugRows[] = ['reg_id' => $registrationId, 'status' => 'execute_failed'];
            }

        }



        sendJSON(['success' => true, 'updated' => $updatedCount, 'debug' => $debugRows, 'church_id_used' => $churchId]);

    } catch (Exception $e) {

        error_log("bulkUpdateCustomData error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تحديث البيانات: ' . $e->getMessage()]);

    }

}



// ── WAITLIST HELPERS ──────────────────────────────────────────────────────────

function ensureWaitlistTable($conn)

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        CREATE TABLE IF NOT EXISTS `trip_waitlist` (

            `id`          INT AUTO_INCREMENT PRIMARY KEY,

            `trip_id`     INT NOT NULL,

            `student_id`  INT NOT NULL,

            `church_id`   INT NOT NULL,

            `added_by`    INT DEFAULT NULL,

            `position`    INT NOT NULL DEFAULT 1,

            `notes`       TEXT DEFAULT NULL,

            `deposit`     DECIMAL(10,2) DEFAULT 0,

            `donation`    DECIMAL(10,2) DEFAULT 0,

            `custom_data` TEXT DEFAULT NULL,

            `payment_history` TEXT DEFAULT NULL,

            `added_at`    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

            UNIQUE KEY `uq_trip_student` (`trip_id`, `student_id`),

            KEY `idx_trip_pos` (`trip_id`, `position`),

            KEY `idx_church` (`church_id`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci

    ");



    // Add payment_history column if it does not exist

    $check = $conn->query("SHOW COLUMNS FROM `trip_waitlist` LIKE 'payment_history'");

    if ($check && $check->num_rows == 0) {

        $conn->query("ALTER TABLE `trip_waitlist` ADD COLUMN `payment_history` TEXT DEFAULT NULL");

    }

}



function getTripDiscountedBasePrice($trip)

{

    $finalPrice = floatval($trip['price'] ?? 0);

    if (floatval($trip['discount'] ?? 0) > 0) {

        if (($trip['discount_type'] ?? '') === 'percentage') {

            $finalPrice = $finalPrice - ($finalPrice * floatval($trip['discount']) / 100);

        } else {

            $finalPrice = max(0, $finalPrice - floatval($trip['discount']));

        }

    }

    return round($finalPrice, 2);

}



function getTripExpensesPerKid($conn, $tripId)
{
    $stmt = @$conn->prepare("SELECT COALESCE(SUM(per_kid), 0) AS exp_total FROM trip_expenses WHERE trip_id = ?");

    if (!$stmt) {

        return 0.0;

    }

    $stmt->bind_param("i", $tripId);

    $stmt->execute();

    $row = $stmt->get_result()->fetch_assoc();

    return floatval($row['exp_total'] ?? 0);

}



function getTripTotalPerKid($conn, $tripId, $trip = null)

{

    if ($trip === null) {

        $stmt = $conn->prepare("SELECT price, discount, discount_type FROM trips WHERE id = ? LIMIT 1");

        $stmt->bind_param("i", $tripId);

        $stmt->execute();

        $trip = $stmt->get_result()->fetch_assoc() ?: [];

    }

    return round(getTripDiscountedBasePrice($trip) + getTripExpensesPerKid($conn, $tripId), 2);

}



function parseWaitlistPaymentHistory($raw)

{

    if (is_array($raw)) {

        return $raw;

    }

    if ($raw === null || $raw === '') {

        return [];

    }

    $decoded = json_decode($raw, true);

    return is_array($decoded) ? $decoded : [];

}



function computeWaitlistPaymentTotals(array $historyArray)

{

    $totalPaid = 0.0;

    $totalDonation = 0.0;

    foreach ($historyArray as $p) {

        if (intval($p['is_deleted'] ?? 0) === 1) {

            continue;

        }

        if (($p['type'] ?? '') === 'donation') {

            $totalDonation += floatval($p['donation'] ?? 0);

        } else {

            $totalPaid += floatval($p['amount'] ?? 0);

        }

    }

    return [

        'total_paid' => round($totalPaid, 2),

        'total_donation' => round($totalDonation, 2),

    ];

}



function tripPaymentStatusFromPaid($totalPaid, $totalPerKid)

{

    $remaining = round(max(0, $totalPerKid - $totalPaid), 2);

    if (abs($remaining) < 0.01) {

        return ['payment_status' => 'paid', 'remaining' => 0.0];

    }

    if ($totalPaid > 0.01) {

        return ['payment_status' => 'partial', 'remaining' => $remaining];

    }

    return ['payment_status' => 'pending', 'remaining' => $remaining];

}



function enrichWaitlistRow(array $row, $totalPerKid)

{

    $history = parseWaitlistPaymentHistory($row['payment_history'] ?? null);

    $totals = computeWaitlistPaymentTotals($history);

    $deposit = floatval($row['deposit'] ?? 0);

    $donationField = floatval($row['donation'] ?? 0);



    if (empty($history) && $deposit > 0) {

        $totals['total_paid'] = $deposit;

        $totals['total_donation'] = $donationField;

    } elseif ($totals['total_paid'] < $deposit - 0.01) {

        $totals['total_paid'] = $deposit;

    }

    if ($totals['total_donation'] < $donationField - 0.01) {

        $totals['total_donation'] = $donationField;

    }



    $status = tripPaymentStatusFromPaid($totals['total_paid'], $totalPerKid);

    $row['payment_history'] = $history;

    $row['total_paid'] = $totals['total_paid'];

    $row['total_donation'] = $totals['total_donation'];

    $row['deposit'] = $totals['total_paid'];

    $row['donation'] = $totals['total_donation'];

    $row['remaining'] = $status['remaining'];

    $row['payment_status'] = $status['payment_status'];

    return $row;

}



function fetchRegistrationPaymentsAsHistory($conn, $registrationId)

{

    $history = [];

    $stmt = $conn->prepare("

        SELECT id, amount, donation, payment_method, received_by, notes, payment_date, is_deleted

        FROM trip_payments

        WHERE registration_id = ?

        ORDER BY id ASC

    ");

    if (!$stmt) {

        return $history;

    }

    $stmt->bind_param("i", $registrationId);

    $stmt->execute();

    $result = $stmt->get_result();

    while ($p = $result->fetch_assoc()) {

        if (intval($p['is_deleted'] ?? 0) === 1) {

            continue;

        }

        $amount = floatval($p['amount'] ?? 0);

        $donation = floatval($p['donation'] ?? 0);

        $type = 'payment';

        if ($amount > 0 && strpos((string) ($p['notes'] ?? ''), 'دفعة مقدمة') !== false) {

            $type = 'deposit';

        } elseif ($amount <= 0 && $donation > 0) {

            $type = 'donation';

        }

        $history[] = [

            'id' => $p['id'],

            'type' => $type,

            'timestamp' => $p['payment_date'] ?? date('c'),

            'amount' => $amount,

            'donation' => $donation,

            'payment_method' => $p['payment_method'] ?? 'cash',

            'received_by' => $p['received_by'],

            'notes' => $p['notes'] ?? '',

            'is_deleted' => 0,

        ];

    }

    return $history;

}



function normalizeTripPaymentDate($raw)

{

    if (empty($raw)) {

        return date('Y-m-d H:i:s');

    }

    $ts = strtotime($raw);

    if ($ts === false) {

        return date('Y-m-d H:i:s');

    }

    return date('Y-m-d H:i:s', $ts);

}



function syncTripRegistrationPaymentStatus($conn, $registrationId, $totalPerKid)

{

    $stmt = $conn->prepare("SELECT COALESCE(SUM(amount), 0) AS total_paid FROM trip_payments WHERE registration_id = ? AND is_deleted = 0");

    $stmt->bind_param("i", $registrationId);

    $stmt->execute();

    $totalPaid = floatval($stmt->get_result()->fetch_assoc()['total_paid'] ?? 0);

    $status = tripPaymentStatusFromPaid($totalPaid, $totalPerKid);

    $sync = $conn->prepare("UPDATE trip_registrations SET payment_status = ? WHERE id = ?");

    $sync->bind_param("si", $status['payment_status'], $registrationId);

    $sync->execute();

    return $status;

}



function getWaitlistNextPosition($conn, $tripId)

{

    $stmt = $conn->prepare("SELECT COALESCE(MAX(position), 0) + 1 AS next_pos FROM trip_waitlist WHERE trip_id = ?");

    $stmt->bind_param("i", $tripId);

    $stmt->execute();

    return (int) $stmt->get_result()->fetch_assoc()['next_pos'];

}



function promoteWaitlistEntry($conn, $waiting, $tripId)
{


    

    

    

    

    

    



    $totalPerKid = getTripTotalPerKid($conn, $tripId);

    $waiting = enrichWaitlistRow($waiting, $totalPerKid);



    $deposit = floatval($waiting['total_paid'] ?? $waiting['deposit'] ?? 0);

    $notes = $waiting['notes'] ?? '';

    $customData = $waiting['custom_data'];

    $addedBy = $waiting['added_by'];

    $studentId = intval($waiting['student_id']);

    $historyArray = parseWaitlistPaymentHistory($waiting['payment_history'] ?? null);

    $paymentsToInsert = [];



    foreach ($historyArray as $p) {

        if (intval($p['is_deleted'] ?? 0) === 1) {

            continue;

        }

        $paymentsToInsert[] = $p;

    }



    $historyPaid = 0.0;

    foreach ($paymentsToInsert as $p) {

        if (($p['type'] ?? '') !== 'donation') {

            $historyPaid += floatval($p['amount'] ?? 0);

        }

    }



    if ($deposit > $historyPaid + 0.01) {

        $paymentsToInsert[] = [

            'type' => 'deposit',

            'timestamp' => date('c'),

            'amount' => round($deposit - $historyPaid, 2),

            'donation' => 0,

            'payment_method' => 'cash',

            'received_by' => $addedBy,

            'notes' => 'دفعة مقدمة - ترقية من قائمة الانتظار',

            'is_deleted' => 0,

        ];

    } elseif (empty($paymentsToInsert) && $deposit > 0.01) {

        $paymentsToInsert[] = [

            'type' => 'deposit',

            'timestamp' => date('c'),

            'amount' => $deposit,

            'donation' => 0,

            'payment_method' => 'cash',

            'received_by' => $addedBy,

            'notes' => 'دفعة مقدمة - ترقية من قائمة الانتظار',

            'is_deleted' => 0,

        ];

    }



    $paymentStatus = $waiting['payment_status'] ?? 'pending';



    // Remove any old cancelled registration for this student on this trip

    $del = $conn->prepare("DELETE FROM trip_registrations WHERE trip_id = ? AND student_id = ? AND cancelled = 1");

    $del->bind_param("ii", $tripId, $studentId);

    $del->execute();



    // Insert a normal registration (preserve deposit + payment status from waitlist)

    $ins = $conn->prepare("

        INSERT INTO trip_registrations (trip_id, student_id, registered_by, deposit, notes, custom_data, payment_status)

        VALUES (?, ?, ?, ?, ?, ?, ?)

    ");

    $ins->bind_param("iiidsss", $tripId, $studentId, $addedBy, $deposit, $notes, $customData, $paymentStatus);

    if (!$ins->execute()) {

        return null;

    }



    $registrationId = $conn->insert_id;

    $newHistoryArray = [];



    foreach ($paymentsToInsert as $p) {

        $pAmt = floatval($p['amount'] ?? 0);

        $pDon = floatval($p['donation'] ?? 0);

        $pMethod = $p['payment_method'] ?? 'cash';
        // Normalize payment method to standard enum values allowed by trip_payments table
        $validMethods = ['cash', 'card', 'bank_transfer', 'other'];
        if (!in_array($pMethod, $validMethods)) {
            $pMethod = 'cash';
        }

        $pNotes = $p['notes'] ?? '';

        $pDate = normalizeTripPaymentDate($p['timestamp'] ?? null);

        $receivedBy = intval($p['received_by'] ?? $addedBy ?? 0);

        if ($receivedBy <= 0) {

            $receivedBy = intval($addedBy ?? 0);

        }

        // Validate that receivedBy exists in uncles table to avoid foreign key constraint failure
        $dbReceivedBy = null;
        if ($receivedBy > 0) {
            $checkUncle = $conn->prepare("SELECT id FROM uncles WHERE id = ?");
            $checkUncle->bind_param("i", $receivedBy);
            $checkUncle->execute();
            if ($checkUncle->get_result()->num_rows > 0) {
                $dbReceivedBy = $receivedBy;
            }
        }

        $ps = $conn->prepare("

            INSERT INTO trip_payments (registration_id, amount, donation, payment_method, received_by, notes, payment_date)

            VALUES (?, ?, ?, ?, ?, ?, ?)

        ");

        $ps->bind_param("iddsiss", $registrationId, $pAmt, $pDon, $pMethod, $dbReceivedBy, $pNotes, $pDate);

        $ps->execute();

        $realPaymentId = $conn->insert_id;



        $newHistoryArray[] = [

            'id' => $realPaymentId,

            'type' => $p['type'] ?? (($pAmt > 0) ? 'payment' : 'donation'),

            'timestamp' => $pDate,

            'amount' => $pAmt,

            'donation' => $pDon,

            'payment_method' => $pMethod,

            'received_by' => $receivedBy,

            'notes' => $pNotes,

            'is_deleted' => 0,

        ];

    }



    $updatedHistoryJson = json_encode($newHistoryArray, JSON_UNESCAPED_UNICODE);

    $updHist = $conn->prepare("UPDATE trip_registrations SET payment_history = ? WHERE id = ?");

    $updHist->bind_param("si", $updatedHistoryJson, $registrationId);

    $updHist->execute();



    syncTripRegistrationPaymentStatus($conn, $registrationId, $totalPerKid);

    if (function_exists('auditTripWaitlistPromotion')) {
        auditTripWaitlistPromotion($tripId, $studentId, $waiting['student_name'] ?? '', $registrationId, $deposit);
    }



    // Remove from waitlist

    $delW = $conn->prepare("DELETE FROM trip_waitlist WHERE trip_id = ? AND student_id = ?");

    $delW->bind_param("ii", $tripId, $studentId);

    $delW->execute();



    // Re-number remaining positions

    $conn->query("SET @pos := 0");

    $upd = $conn->prepare("UPDATE trip_waitlist SET position = (@pos := @pos + 1) WHERE trip_id = ? ORDER BY position ASC");

    $upd->bind_param("i", $tripId);

    $upd->execute();



    return [

        'student_id' => $studentId,

        'student_name' => $waiting['student_name'],

        'student_image' => $waiting['student_image'],

        'registration_id' => $registrationId,

        'total_paid' => $deposit,

        'payment_status' => $paymentStatus,

    ];


}

function promoteFirstEligibleFromWaitlist($conn, $tripId, $restrictChurchId = null)
{
    // 1. Get the trip details
    $tripStmt = $conn->prepare("SELECT church_id, max_participants, collaboration_limits, collab_limit_mode, collab_max_participants FROM trips WHERE id = ?");
    $tripStmt->bind_param("i", $tripId);
    $tripStmt->execute();
    $trip = $tripStmt->get_result()->fetch_assoc();
    if (!$trip) return null;

    $ownerChurchId = intval($trip['church_id']);
    $maxParticipants = intval($trip['max_participants']);
    $collabLimitMode = $trip['collab_limit_mode'] ?? 'open';
    $collabMax = intval($trip['collab_max_participants'] ?? 0);

    $limits = [];
    if (!empty($trip['collaboration_limits'])) {
        $limits = json_decode($trip['collaboration_limits'], true);
    }

    // 2. Fetch all waitlist entries in order
    if ($restrictChurchId !== null) {
        $wStmt = $conn->prepare("
            SELECT tw.*, s.name AS student_name, s.image_url AS student_image
            FROM trip_waitlist tw
            JOIN students s ON s.id = tw.student_id
            WHERE tw.trip_id = ? AND tw.church_id = ?
            ORDER BY tw.position ASC
        ");
        $wStmt->bind_param("ii", $tripId, $restrictChurchId);
    } else {
        $wStmt = $conn->prepare("
            SELECT tw.*, s.name AS student_name, s.image_url AS student_image
            FROM trip_waitlist tw
            JOIN students s ON s.id = tw.student_id
            WHERE tw.trip_id = ?
            ORDER BY tw.position ASC
        ");
        $wStmt->bind_param("i", $tripId);
    }
    $wStmt->execute();
    $waitlist = $wStmt->get_result()->fetch_all(MYSQLI_ASSOC);

    if (empty($waitlist)) return null;

    // Fetch collaborator registrations count
    $collabCount = 0;
    if ($collabLimitMode === 'limited') {
        $collabCountStmt = $conn->prepare("
            SELECT COUNT(*) as cnt
            FROM trip_registrations tr
            LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
            LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
            WHERE tr.trip_id = ? 
              AND tr.cancelled = 0
              AND COALESCE(s.church_id, g.church_id) != ?
        ");
        $collabCountStmt->bind_param("ii", $tripId, $ownerChurchId);
        $collabCountStmt->execute();
        $collabCount = (int) $collabCountStmt->get_result()->fetch_assoc()['cnt'];
    }

    // We will evaluate kids one by one in position order
    foreach ($waitlist as $waiting) {
        $studentChurchId = intval($waiting['church_id']);

        // A. Check individual church limit
        if ($studentChurchId === $ownerChurchId) {
            // Check owner capacity
            $ownerCountStmt = $conn->prepare("
                SELECT COUNT(*) as cnt
                FROM trip_registrations tr
                LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
                LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
                WHERE tr.trip_id = ? 
                  AND tr.cancelled = 0
                  AND COALESCE(s.church_id, g.church_id) = ?
            ");
            $ownerCountStmt->bind_param("ii", $tripId, $ownerChurchId);
            $ownerCountStmt->execute();
            $ownerCount = (int) $ownerCountStmt->get_result()->fetch_assoc()['cnt'];
            if ($maxParticipants > 0 && $ownerCount >= $maxParticipants) {
                // Owner capacity full, skip this kid
                continue;
            }
        } else {
            // Check collab church limit
            $churchLimit = isset($limits[strval($studentChurchId)]) ? intval($limits[strval($studentChurchId)]) : null;
            if ($churchLimit !== null) {
                $cntStmt = $conn->prepare("
                    SELECT COUNT(*) as cnt
                    FROM trip_registrations tr
                    LEFT JOIN students s ON tr.student_id = s.id AND tr.registration_type != 'guest'
                    LEFT JOIN guests g ON tr.guest_id = g.id AND tr.registration_type = 'guest'
                    WHERE tr.trip_id = ? 
                      AND tr.cancelled = 0
                      AND COALESCE(s.church_id, g.church_id) = ?
                ");
                $cntStmt->bind_param("ii", $tripId, $studentChurchId);
                $cntStmt->execute();
                $churchActiveCount = (int) $cntStmt->get_result()->fetch_assoc()['cnt'];
                if ($churchActiveCount >= $churchLimit) {
                    // Collaborator limit exceeded, skip this kid
                    continue;
                }
            }

            // Check collab group limit
            if ($collabLimitMode === 'limited' && $collabMax > 0 && $collabCount >= $collabMax) {
                // Overall collaborator capacity full, skip this kid
                continue;
            }
        }

        // If we reach here, this child is eligible for promotion!
        return promoteWaitlistEntry($conn, $waiting, $tripId);
    }

    return null;
}



function promoteFirstFromWaitlist($conn, $tripId, $churchId)
{
    // Get the first student in the waitlist
    $stmt = $conn->prepare("
        SELECT tw.*, s.name AS student_name, s.image_url AS student_image
        FROM trip_waitlist tw
        JOIN students s ON s.id = tw.student_id
        WHERE tw.trip_id = ?
        ORDER BY tw.position ASC
        LIMIT 1
    ");
    $stmt->bind_param("i", $tripId);
    $stmt->execute();
    $waiting = $stmt->get_result()->fetch_assoc();
    if (!$waiting) {
        return null;
    }
    return promoteWaitlistEntry($conn, $waiting, $tripId);
}


function promoteSpecificFromWaitlistAction()
{
    try {
        checkAuth();
        $churchId = getChurchId();
        $tripId = intval($_POST['trip_id'] ?? 0);
        $waitlistId = intval($_POST['waitlist_id'] ?? 0);

        if (!$tripId || !$waitlistId) {
            sendJSON(['success' => false, 'message' => 'trip_id و waitlist_id مطلوبان']);
            return;
        }

        $conn = getDBConnection();
        $tripStmt = $conn->prepare("SELECT church_id, max_participants, title, collaboration_limits FROM trips WHERE id = ?");
        $tripStmt->bind_param("i", $tripId);
        $tripStmt->execute();
        $trip = $tripStmt->get_result()->fetch_assoc();
        if (!$trip) {
            sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']);
            return;
        }

        $ownerChurchId = intval($trip['church_id']);
        
        $wStmt = $conn->prepare("
            SELECT tw.*, s.name AS student_name, s.image_url AS student_image
            FROM trip_waitlist tw
            JOIN students s ON s.id = tw.student_id
            WHERE tw.id = ? AND tw.trip_id = ?
        ");
        $wStmt->bind_param("ii", $waitlistId, $tripId);
        $wStmt->execute();
        $waiting = $wStmt->get_result()->fetch_assoc();
        if (!$waiting) {
            sendJSON(['success' => false, 'message' => 'لم يتم العثور على هذا الطفل في قائمة الانتظار']);
            return;
        }

        $studentChurchId = intval($waiting['church_id']);

        if ($churchId !== $ownerChurchId && $churchId !== $studentChurchId) {
            sendJSON(['success' => false, 'message' => 'غير مصرح لك بترقية هذا الطفل']);
            return;
        }

        $promoted = promoteWaitlistEntry($conn, $waiting, $tripId);
        if ($promoted) {
            sendJSON([
                'success' => true,
                'message' => "تم ترقية الطفل {$waiting['student_name']} إلى التسجيل الرئيسي بنجاح",
                'promoted_student_name' => $waiting['student_name'],
                'promoted_student_image' => $waiting['student_image']
            ]);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في ترقية الطفل']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}




function getWaitlistData($tripId, $conn)

{

    ensureWaitlistTable($conn);

    $totalPerKid = getTripTotalPerKid($conn, $tripId);

    $stmt = $conn->prepare("

        SELECT tw.*, s.name AS student_name, s.phone AS student_phone, s.image_url AS student_image,

               COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS student_class,

               s.gender AS student_gender,

               s.birthday as student_birthday,

               s.emergency_phone as student_emergency_phone,

               s.medical_notes as student_medical_notes,

               s.address as student_address,

               s.coupons as student_coupons,

               s.attendance_coupons as student_attendance_coupons,

               s.commitment_coupons as student_commitment_coupons,

               s.task_coupons as student_task_coupons,

               s.custom_info as student_custom_info,

               s.church_id as student_church_id

        FROM trip_waitlist tw

        JOIN students s ON s.id = tw.student_id

        LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id

        LEFT JOIN classes cl ON cl.id = s.class_id

        WHERE tw.trip_id = ?

        ORDER BY tw.position ASC

    ");

    $stmt->bind_param("i", $tripId);

    $stmt->execute();

    $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

    $enriched = [];

    foreach ($rows as $row) {

        $enriched[] = enrichWaitlistRow($row, $totalPerKid);

    }

    return $enriched;

}



