function getClassUncles()

{

    try {

        $churchId = getChurchId();

        $className = sanitize($_POST['class'] ?? '');



        if (empty($className)) {

            sendJSON(['success' => true, 'uncles' => []]);

            return;

        }



        $conn = getDBConnection();



        // Ensure table exists (safe guard)

        $conn->query("CREATE TABLE IF NOT EXISTS `uncle_class_assignments` (

            `id`         INT AUTO_INCREMENT PRIMARY KEY,

            `uncle_id`   INT NOT NULL,

            `church_id`  INT NOT NULL,

            `class_name` VARCHAR(100) NOT NULL,

            `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

            UNIQUE KEY `uq_uncle_class` (`uncle_id`, `church_id`, `class_name`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");



        $stmt = $conn->prepare("

            SELECT u.id, u.name, u.image_url, u.role, u.username

            FROM uncle_class_assignments a

            JOIN uncles u ON a.uncle_id = u.id

            WHERE a.church_id = ? AND a.class_name = ?

              AND (u.deleted IS NULL OR u.deleted = 0) AND u.role NOT IN ('developer', 'dev')

            ORDER BY

                CASE u.role

                    WHEN 'admin' THEN 1

                    WHEN 'developer' THEN 2

                    ELSE 3

                END, u.name

        ");

        $stmt->bind_param("is", $churchId, $className);

        $stmt->execute();

        $uncles = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);



        sendJSON(['success' => true, 'uncles' => $uncles]);



    } catch (Exception $e) {

        error_log("getClassUncles error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في جلب معلمي الفصل']);

    }

}



/**

 * Assign an uncle to a class.

 * POST: uncleId, class (class name)

 */

function assignUncleToClass()

{

    try {

        $churchId = getChurchId();

        $uncleId = intval($_POST['uncleId'] ?? 0);

        $className = sanitize($_POST['class'] ?? '');



        if (!$uncleId || empty($className)) {

            sendJSON(['success' => false, 'message' => 'بيانات ناقصة']);

            return;

        }



        $conn = getDBConnection();



        // Ensure table exists

        $conn->query("CREATE TABLE IF NOT EXISTS `uncle_class_assignments` (

            `id`         INT AUTO_INCREMENT PRIMARY KEY,

            `uncle_id`   INT NOT NULL,

            `church_id`  INT NOT NULL,

            `class_name` VARCHAR(100) NOT NULL,

            `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

            UNIQUE KEY `uq_uncle_class` (`uncle_id`, `church_id`, `class_name`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");



        // Verify uncle belongs to this church

        $checkStmt = $conn->prepare("

            SELECT id FROM uncles

            WHERE id = ? AND church_id = ?

              AND (deleted IS NULL OR deleted = 0)

        ");

        $checkStmt->bind_param("ii", $uncleId, $churchId);

        $checkStmt->execute();

        if ($checkStmt->get_result()->num_rows === 0) {

            sendJSON(['success' => false, 'message' => 'المعلم غير موجود في هذه الكنيسة']);

            return;

        }



        $stmt = $conn->prepare("

            INSERT IGNORE INTO uncle_class_assignments (uncle_id, church_id, class_name)

            VALUES (?, ?, ?)

        ");

        $stmt->bind_param("iis", $uncleId, $churchId, $className);



        if ($stmt->execute()) {

            sendJSON(['success' => true, 'message' => 'تم تعيين المعلم للفصل']);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في التعيين: ' . $stmt->error]);

        }



    } catch (Exception $e) {

        error_log("assignUncleToClass error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تعيين المعلم: ' . $e->getMessage()]);

    }

}



/**

 * Remove an uncle from a class assignment.

 * POST: uncleId, class (class name)

 */

function removeUncleFromClass()

{

    try {

        $churchId = getChurchId();

        $uncleId = intval($_POST['uncleId'] ?? 0);

        $className = sanitize($_POST['class'] ?? '');



        if (!$uncleId || empty($className)) {

            sendJSON(['success' => false, 'message' => 'بيانات ناقصة']);

            return;

        }



        $conn = getDBConnection();



        $stmt = $conn->prepare("

            DELETE FROM uncle_class_assignments

            WHERE uncle_id = ? AND church_id = ? AND class_name = ?

        ");

        $stmt->bind_param("iis", $uncleId, $churchId, $className);



        if ($stmt->execute()) {

            sendJSON(['success' => true, 'message' => 'تم إزالة المعلم من الفصل']);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في الإزالة: ' . $stmt->error]);

        }



    } catch (Exception $e) {

        error_log("removeUncleFromClass error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في إزالة المعلم: ' . $e->getMessage()]);

    }

}

// ===== GET UNCLE CLASSES =====

function getUncleClasses($uncleId)

{

    $conn = getDBConnection();

    $stmt = $conn->prepare("

        SELECT class_name

        FROM uncle_class_assignments

        WHERE uncle_id = ?

        ORDER BY class_name

    ");

    $stmt->bind_param("i", $uncleId);

    $stmt->execute();

    $result = $stmt->get_result();



    $classes = [];

    while ($row = $result->fetch_assoc()) {

        $classes[] = ['class_name' => $row['class_name']];

    }

    return $classes;

}



// ===== SAVE UNCLE CLASSES =====

function saveUncleClasses($uncleId, $churchId, $classes)

{

    $conn = getDBConnection();



    // Delete existing classes

    $deleteStmt = $conn->prepare("DELETE FROM uncle_class_assignments WHERE uncle_id = ?");

    $deleteStmt->bind_param("i", $uncleId);

    $deleteStmt->execute();



    // Insert new classes

    if (!empty($classes) && is_array($classes)) {

        $insertStmt = $conn->prepare("

            INSERT INTO uncle_class_assignments (uncle_id, church_id, class_name) 

            VALUES (?, ?, ?)

        ");



        foreach ($classes as $class) {

            if (!empty($class)) {

                $className = is_array($class) ? ($class['class_name'] ?? $class['arabic_name'] ?? $class['code'] ?? $class['name'] ?? '') : $class;

                $className = sanitize($className);

                if (!empty($className)) {

                    $insertStmt->bind_param("iis", $uncleId, $churchId, $className);

                    $insertStmt->execute();

                }

            }

        }

    }



    return true;

}



// ===== CLASS GRADE ORDER & ANNUAL GRADE-UP =====



function ensureChurchClassesOrderColumn($conn): void

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        ALTER TABLE church_classes

        ADD COLUMN IF NOT EXISTS `order` INT NOT NULL DEFAULT 0

        COMMENT 'Grade sequence (lowest = youngest)'

        AFTER display_order

    ");

}



function ensureChurchSettingsAutoGradeColumns($conn): void

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `auto_grade_month` TINYINT UNSIGNED NULL DEFAULT NULL

        COMMENT '1-12; month for annual grade-up'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `auto_grade_day` TINYINT UNSIGNED NULL DEFAULT NULL

        COMMENT '1-31; day for annual grade-up'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `last_auto_grade_year` SMALLINT UNSIGNED NULL DEFAULT NULL

        COMMENT 'Last year auto grade-up ran'");

}



/**

 * Ordered class list for a church (youngest → oldest).

 * Uses church_classes.`order` when custom; global classes use display_order.

 */

function getOrderedClassListForChurch(int $churchId): array

{

    $conn = getDBConnection();

    ensureChurchClassesOrderColumn($conn);



    $chk = $conn->prepare("SELECT COUNT(*) AS cnt FROM church_classes WHERE church_id = ? AND is_active = 1");

    $chk->bind_param("i", $churchId);

    $chk->execute();

    $hasCustom = (int) $chk->get_result()->fetch_assoc()['cnt'] > 0;



    if ($hasCustom) {

        $stmt = $conn->prepare("

            SELECT id, arabic_name, code,

                   COALESCE(NULLIF(`order`, 0), display_order) AS sort_order

            FROM church_classes

            WHERE church_id = ? AND is_active = 1

            ORDER BY sort_order ASC, arabic_name ASC

        ");

        $stmt->bind_param("i", $churchId);

    } else {

        $stmt = $conn->prepare("

            SELECT id, arabic_name, code, display_order AS sort_order

            FROM classes

            ORDER BY display_order ASC, arabic_name ASC

        ");

    }

    $stmt->execute();

    return $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

}



/**

 * Promote active students to next class; highest class → خريجين.

 */

function gradeUpStudentsForChurch(int $churchId): array

{

    $conn = getDBConnection();

    ensureStudentGraduateSchema($conn);

    $ordered = getOrderedClassListForChurch($churchId);

    if (count($ordered) < 1) {

        return [

            'promoted' => 0,

            'graduated' => 0,

            'unchanged' => 0,

            'message' => 'يجب وجود فصل واحد على الأقل',

        ];

    }



    $topClassId = (int) $ordered[count($ordered) - 1]['id'];

    $nextById = [];

    for ($i = 0; $i < count($ordered) - 1; $i++) {

        $nextById[(int) $ordered[$i]['id']] = $ordered[$i + 1];

    }



    $stmt = $conn->prepare("

        SELECT id, class_id FROM students

        WHERE church_id = ? AND COALESCE(enrollment_status, 'active') = 'active'

    ");

    $stmt->bind_param("i", $churchId);

    $stmt->execute();

    $students = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);



    $upd = $conn->prepare("

        UPDATE students

        SET class_id = ?, class = ?, enrollment_status = 'active', updated_at = NOW()

        WHERE id = ? AND church_id = ?

    ");

    $topClassName = $ordered[count($ordered) - 1]['arabic_name'] ?? '';

    $gradStmt = $conn->prepare("

        UPDATE students

        SET graduate_from_class_id = class_id,

            graduate_from_class = ?,

            class_id = 0,

            class = 'خريجين',

            enrollment_status = 'graduate',

            updated_at = NOW()

        WHERE id = ? AND church_id = ? AND class_id = ?

    ");



    $promoted = 0;

    $graduated = 0;

    $unchanged = 0;

    foreach ($students as $s) {

        $sid = (int) $s['id'];

        $cid = (int) $s['class_id'];



        if ($cid === $topClassId) {

            $gradStmt->bind_param("siii", $topClassName, $sid, $churchId, $topClassId);

            if ($gradStmt->execute() && $gradStmt->affected_rows > 0) {

                $graduated++;

            } else {

                $unchanged++;

            }

            continue;

        }



        if (!isset($nextById[$cid])) {

            $unchanged++;

            continue;

        }

        $next = $nextById[$cid];

        $nextId = (int) $next['id'];

        $nextName = $next['arabic_name'];

        $upd->bind_param("isii", $nextId, $nextName, $sid, $churchId);

        if ($upd->execute() && $upd->affected_rows > 0) {

            $promoted++;

        } else {

            $unchanged++;

        }

    }



    return [

        'promoted' => $promoted,

        'graduated' => $graduated,

        'unchanged' => $unchanged,

        'top_class' => $ordered[count($ordered) - 1]['arabic_name'] ?? '',

    ];

}



/**

 * Run scheduled grade-up for all churches whose date has passed this year.

 * Safe to call on login / session restore (idempotent per calendar year).

 */

function maybeRunScheduledGradeUps($conn): void

{

    try {

        ensureChurchSettingsTable($conn);

        ensureChurchSettingsAutoGradeColumns($conn);



        $now = new DateTime('today');

        $year = (int) $now->format('Y');

        $month = (int) $now->format('n');

        $day = (int) $now->format('j');



        $res = $conn->query("

            SELECT church_id, auto_grade_month, auto_grade_day, last_auto_grade_year

            FROM church_settings

            WHERE auto_grade_month IS NOT NULL

              AND auto_grade_day IS NOT NULL

              AND auto_grade_month BETWEEN 1 AND 12

              AND auto_grade_day BETWEEN 1 AND 31

        ");

        if (!$res) {

            return;

        }



        $markStmt = $conn->prepare("

            UPDATE church_settings SET last_auto_grade_year = ? WHERE church_id = ?

        ");



        while ($row = $res->fetch_assoc()) {

            $churchId = (int) $row['church_id'];

            $targetMonth = (int) $row['auto_grade_month'];

            $targetDay = (int) $row['auto_grade_day'];

            $lastYear = (int) ($row['last_auto_grade_year'] ?? 0);



            if ($lastYear >= $year) {

                continue;

            }

            if ($month < $targetMonth || ($month === $targetMonth && $day < $targetDay)) {

                continue;

            }



            $result = gradeUpStudentsForChurch($churchId);

            if (($result['promoted'] ?? 0) > 0 || ($result['graduated'] ?? 0) > 0 || ($result['unchanged'] ?? 0) > 0) {

                $markStmt->bind_param("ii", $year, $churchId);

                $markStmt->execute();

                writeAuditLog(

                    'auto_grade_up',

                    'students',

                    $churchId,

                    'نقل سنوي تلقائي للفصول',

                    null,

                    null,

                    json_encode($result, JSON_UNESCAPED_UNICODE)

                );

            }

        }

    } catch (Exception $e) {

        error_log('maybeRunScheduledGradeUps: ' . $e->getMessage());

    }

}



function runBackgroundGradeUpChecks(): void

{

    if (!empty($_SESSION['_grade_up_scheduled_checked'])) {

        return;

    }

    $_SESSION['_grade_up_scheduled_checked'] = true;

    try {

        $conn = getDBConnection();

        maybeRunScheduledGradeUps($conn);

    } catch (Exception $e) {

        error_log('runBackgroundGradeUpChecks: ' . $e->getMessage());

    }

}



function gradeUpAllKids()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'معرف الكنيسة مطلوب']);

            return;

        }



        $result = gradeUpStudentsForChurch($churchId);

        if (isset($result['message'])) {

            sendJSON(['success' => false, 'message' => $result['message']]);

            return;

        }



        writeAuditLog(

            'manual_grade_up',

            'students',

            $churchId,

            'نقل يدوي للفصول — سنة دراسية جديدة',

            null,

            null,

            json_encode($result, JSON_UNESCAPED_UNICODE)

        );



        $msg = "تم نقل {$result['promoted']} طفل إلى الفصل التالي";

        if (!empty($result['graduated'])) {

            $msg .= " — و{$result['graduated']} إلى قسم الخريجين";

        }

        if (!empty($result['unchanged'])) {

            $msg .= " ({$result['unchanged']} بدون تغيير)";

        }



        sendJSON([

            'success' => true,

            'message' => $msg,

            'promoted' => $result['promoted'],

            'graduated' => $result['graduated'] ?? 0,

            'unchanged' => $result['unchanged'],

            'top_class' => $result['top_class'] ?? '',

        ]);

    } catch (Exception $e) {

        error_log('gradeUpAllKids: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في نقل الفصول']);

    }

}



// ===== GRADUATES (خريجين) & CROSS-CHURCH TRANSFERS =====



function ensureStudentGraduateSchema($conn): void

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("ALTER TABLE students ADD COLUMN IF NOT EXISTS

        `enrollment_status` VARCHAR(20) NOT NULL DEFAULT 'active'

        COMMENT 'active | graduate'");

    $conn->query("ALTER TABLE students ADD COLUMN IF NOT EXISTS

        `graduate_from_class_id` INT NULL DEFAULT NULL

        COMMENT 'Class id before graduating'");

    $conn->query("ALTER TABLE students ADD COLUMN IF NOT EXISTS

        `graduate_from_class` VARCHAR(100) NULL DEFAULT NULL

        COMMENT 'Class name before graduating'");

    $conn->query("

        CREATE TABLE IF NOT EXISTS `student_transfer_requests` (

            `id` int(11) NOT NULL AUTO_INCREMENT,

            `from_church_id` int(11) NOT NULL,

            `to_church_id` int(11) NOT NULL,

            `from_student_id` int(11) DEFAULT NULL,

            `student_name` varchar(100) NOT NULL DEFAULT '',

            `student_snapshot` longtext NOT NULL,

            `status` enum('pending','accepted','rejected') NOT NULL DEFAULT 'pending',

            `target_class_id` int(11) DEFAULT NULL,

            `accepted_student_id` int(11) DEFAULT NULL,

            `created_at` timestamp NOT NULL DEFAULT current_timestamp(),

            `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),

            PRIMARY KEY (`id`),

            KEY `idx_str_to_pending` (`to_church_id`,`status`),

            KEY `idx_str_from` (`from_church_id`,`status`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci

    ");

}



function getFirstClassIdForChurch(int $churchId): int

{

    $ordered = getOrderedClassListForChurch($churchId);

    return !empty($ordered[0]['id']) ? (int) $ordered[0]['id'] : 0;

}



function purgeStudentRelatedRows($conn, int $studentId): void

{

    $deleteAttendanceStmt = $conn->prepare("DELETE FROM attendance WHERE student_id = ?");

    $deleteAttendanceStmt->bind_param("i", $studentId);

    $deleteAttendanceStmt->execute();



    $tableCheck = $conn->query("SHOW TABLES LIKE 'coupon_logs'");

    if ($tableCheck && $tableCheck->num_rows > 0) {

        $deleteLogsStmt = $conn->prepare("DELETE FROM coupon_logs WHERE student_id = ?");

        $deleteLogsStmt->bind_param("i", $studentId);

        $deleteLogsStmt->execute();

    }



    if ($conn->query("SHOW TABLES LIKE 'student_sibling_group_members'")->num_rows > 0) {

        $sg = $conn->prepare("DELETE FROM student_sibling_group_members WHERE student_id = ?");

        $sg->bind_param("i", $studentId);

        $sg->execute();

    }

}



function removeStudentFromChurch($conn, int $studentId, int $churchId): bool

{

    purgeStudentRelatedRows($conn, $studentId);

    $deleteStmt = $conn->prepare("DELETE FROM students WHERE id = ? AND church_id = ?");

    $deleteStmt->bind_param("ii", $studentId, $churchId);

    $deleteStmt->execute();

    return $deleteStmt->affected_rows > 0;

}



/**

 * Resolve which class a graduate should return to (by saved id, then by saved name).

 */

function resolveGraduateRestoreClass($conn, int $churchId, int $classId, string $className): ?array

{

    if ($classId > 0) {

        $cc = $conn->prepare("

            SELECT id, arabic_name FROM church_classes

            WHERE id = ? AND church_id = ? AND is_active = 1 LIMIT 1

        ");

        $cc->bind_param("ii", $classId, $churchId);

        $cc->execute();

        if ($row = $cc->get_result()->fetch_assoc()) {

            return ['id' => (int) $row['id'], 'name' => $row['arabic_name']];

        }

        $gc = $conn->prepare("SELECT id, arabic_name FROM classes WHERE id = ? LIMIT 1");

        $gc->bind_param("i", $classId);

        $gc->execute();

        if ($row = $gc->get_result()->fetch_assoc()) {

            return ['id' => (int) $row['id'], 'name' => $row['arabic_name']];

        }

    }



    $name = trim($className);

    if ($name !== '' && $name !== 'خريجين') {

        $byName = $conn->prepare("

            SELECT id, arabic_name FROM church_classes

            WHERE church_id = ? AND arabic_name = ? AND is_active = 1 LIMIT 1

        ");

        $byName->bind_param("is", $churchId, $name);

        $byName->execute();

        if ($row = $byName->get_result()->fetch_assoc()) {

            return ['id' => (int) $row['id'], 'name' => $row['arabic_name']];

        }

        $gByName = $conn->prepare("SELECT id, arabic_name FROM classes WHERE arabic_name = ? LIMIT 1");

        $gByName->bind_param("s", $name);

        $gByName->execute();

        if ($row = $gByName->get_result()->fetch_assoc()) {

            return ['id' => (int) $row['id'], 'name' => $row['arabic_name']];

        }

    }



    return null;

}



function restoreGraduateToClass()

{

    try {

        $churchId = getChurchId();

        $studentId = intval($_POST['studentId'] ?? 0);

        if (!$churchId || !$studentId) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);



        $stmt = $conn->prepare("

            SELECT id, name, graduate_from_class_id, graduate_from_class

            FROM students

            WHERE id = ? AND church_id = ? AND enrollment_status = 'graduate'

            LIMIT 1

        ");

        $stmt->bind_param("ii", $studentId, $churchId);

        $stmt->execute();

        $student = $stmt->get_result()->fetch_assoc();

        if (!$student) {

            sendJSON(['success' => false, 'message' => 'الخريج غير موجود']);

            return;

        }



        $fromId = (int) ($student['graduate_from_class_id'] ?? 0);

        $fromName = trim($student['graduate_from_class'] ?? '');

        $target = resolveGraduateRestoreClass($conn, $churchId, $fromId, $fromName);



        if (!$target) {

            sendJSON([

                'success' => false,

                'message' => 'لا يمكن تحديد الفصل السابق'

                    . ($fromName ? ' («' . $fromName . '»)' : '')

                    . ' — تأكد أن الفصل ما زال موجوداً',

            ]);

            return;

        }



        $upd = $conn->prepare("

            UPDATE students

            SET class_id = ?,

                class = ?,

                enrollment_status = 'active',

                graduate_from_class_id = NULL,

                graduate_from_class = NULL,

                updated_at = NOW()

            WHERE id = ? AND church_id = ?

        ");

        $upd->bind_param("isii", $target['id'], $target['name'], $studentId, $churchId);

        if ($upd->execute() && $upd->affected_rows > 0) {

            writeAuditLog(

                'restore_graduate',

                'students',

                $studentId,

                $student['name'],

                null,

                null,

                'class:' . $target['name']

            );

            sendJSON([

                'success' => true,

                'message' => 'تمت إعادة ' . $student['name'] . ' إلى فصل «' . $target['name'] . '»',

                'class_name' => $target['name'],

            ]);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في إعادة الطفل للفصل']);

        }

    } catch (Exception $e) {

        error_log('restoreGraduateToClass: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في إعادة الطفل للفصل']);

    }

}



function getChurchesForTransfer()

{

    try {

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'معرف الكنيسة مطلوب']);

            return;

        }

        $conn = getDBConnection();

        $stmt = $conn->prepare("

            SELECT id, church_name, church_code

            FROM churches

            WHERE id != ?

            ORDER BY church_name ASC

        ");

        $stmt->bind_param("i", $churchId);

        $stmt->execute();

        $churches = [];

        $res = $stmt->get_result();

        while ($row = $res->fetch_assoc()) {

            $churches[] = [

                'id' => (int) $row['id'],

                'name' => $row['church_name'],

                'code' => $row['church_code'],

            ];

        }

        sendJSON(['success' => true, 'churches' => $churches]);

    } catch (Exception $e) {

        error_log('getChurchesForTransfer: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في جلب الكنائس']);

    }

}



function getGraduates()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'معرف الكنيسة مطلوب']);

            return;

        }

        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);



        $stmt = $conn->prepare("

            SELECT s.id, s.name, s.phone, s.birthday, s.coupons, s.custom_info, s.image_url,

                   s.gender, s.address, s.emergency_phone, s.medical_notes, s.class_id,

                   s.graduate_from_class_id, s.graduate_from_class,

                   s.created_at, s.updated_at

            FROM students s

            WHERE s.church_id = ? AND s.enrollment_status = 'graduate'

            ORDER BY s.name

        ");

        $stmt->bind_param("i", $churchId);

        $stmt->execute();

        $graduates = [];

        $res = $stmt->get_result();

        while ($row = $res->fetch_assoc()) {

            $fromId = (int) ($row['graduate_from_class_id'] ?? 0);

            $fromName = trim($row['graduate_from_class'] ?? '');

            $canRestore = resolveGraduateRestoreClass($conn, $churchId, $fromId, $fromName) !== null;

            $row['can_restore'] = $canRestore;

            $row['previous_class'] = $fromName ?: null;

            $graduates[] = $row;

        }



        $inStmt = $conn->prepare("

            SELECT r.id, r.student_name, r.status, r.created_at,

                   fc.church_name AS from_church_name

            FROM student_transfer_requests r

            JOIN churches fc ON fc.id = r.from_church_id

            WHERE r.to_church_id = ? AND r.status = 'pending'

            ORDER BY r.created_at DESC

        ");

        $inStmt->bind_param("i", $churchId);

        $inStmt->execute();

        $incoming = $inStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        $outStmt = $conn->prepare("

            SELECT r.id, r.student_name, r.status, r.created_at,

                   tc.church_name AS to_church_name

            FROM student_transfer_requests r

            JOIN churches tc ON tc.id = r.to_church_id

            WHERE r.from_church_id = ? AND r.status = 'pending'

            ORDER BY r.created_at DESC

        ");

        $outStmt->bind_param("i", $churchId);

        $outStmt->execute();

        $outgoing = $outStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        $classes = getOrderedClassListForChurch($churchId);

        $defaultClassId = getFirstClassIdForChurch($churchId);



        sendJSON([

            'success' => true,

            'graduates' => $graduates,

            'incoming_transfers' => $incoming,

            'outgoing_transfers' => $outgoing,

            'classes' => $classes,

            'default_class_id' => $defaultClassId,

        ]);

    } catch (Exception $e) {

        error_log('getGraduates: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تحميل الخريجين']);

    }

}



function deleteGraduateStudent()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $studentId = intval($_POST['studentId'] ?? 0);

        if (!$churchId || !$studentId) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);

        $chk = $conn->prepare("SELECT name FROM students WHERE id = ? AND church_id = ? AND enrollment_status = 'graduate' LIMIT 1");

        $chk->bind_param("ii", $studentId, $churchId);

        $chk->execute();

        $row = $chk->get_result()->fetch_assoc();

        if (!$row) {

            sendJSON(['success' => false, 'message' => 'الطفل غير موجود في قسم الخريجين']);

            return;

        }



        $conn->begin_transaction();

        if (removeStudentFromChurch($conn, $studentId, $churchId)) {

            $conn->commit();

            writeAuditLog('delete_graduate', 'students', $studentId, $row['name']);

            sendJSON(['success' => true, 'message' => 'تم حذف بيانات الخريج']);

        } else {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل الحذف']);

        }

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log('deleteGraduateStudent: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في الحذف']);

    }

}



function exportGraduateStudent()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $studentId = intval($_REQUEST['studentId'] ?? $_POST['studentId'] ?? 0);

        if (!$churchId || !$studentId) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);

        $stmt = $conn->prepare("SELECT * FROM students WHERE id = ? AND church_id = ? AND enrollment_status = 'graduate' LIMIT 1");

        $stmt->bind_param("ii", $studentId, $churchId);

        $stmt->execute();

        $row = $stmt->get_result()->fetch_assoc();

        if (!$row) {

            sendJSON(['success' => false, 'message' => 'الطفل غير موجود في قسم الخريجين']);

            return;

        }

        unset($row['password_hash']);



        header('Content-Type: application/json; charset=utf-8');

        header('Content-Disposition: attachment; filename="graduate_' . $studentId . '_' . date('Y-m-d') . '.json"');

        echo json_encode($row, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);

        exit;

    } catch (Exception $e) {

        error_log('exportGraduateStudent: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في التصدير']);

    }

}



function sendGraduateToChurch()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $studentId = intval($_POST['studentId'] ?? 0);

        $toChurchCode = sanitize($_POST['to_church_code'] ?? '');



        if (!$churchId || !$studentId || empty($toChurchCode)) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);



        $stmt = $conn->prepare("SELECT * FROM students WHERE id = ? AND church_id = ? AND enrollment_status = 'graduate' LIMIT 1");

        $stmt->bind_param("ii", $studentId, $churchId);

        $stmt->execute();

        $student = $stmt->get_result()->fetch_assoc();

        if (!$student) {

            sendJSON(['success' => false, 'message' => 'الطفل غير موجود في قسم الخريجين']);

            return;

        }



        $cStmt = $conn->prepare("SELECT id, church_name FROM churches WHERE church_code = ? LIMIT 1");

        $cStmt->bind_param("s", $toChurchCode);

        $cStmt->execute();

        $toChurch = $cStmt->get_result()->fetch_assoc();

        if (!$toChurch) {

            sendJSON(['success' => false, 'message' => 'رمز الكنيسة غير صحيح']);

            return;

        }

        $toChurchId = (int) $toChurch['id'];

        if ($toChurchId === $churchId) {

            sendJSON(['success' => false, 'message' => 'لا يمكن الإرسال لنفس الكنيسة']);

            return;

        }



        $dup = $conn->prepare("

            SELECT id FROM student_transfer_requests

            WHERE from_student_id = ? AND to_church_id = ? AND status = 'pending' LIMIT 1

        ");

        $dup->bind_param("ii", $studentId, $toChurchId);

        $dup->execute();

        if ($dup->get_result()->num_rows > 0) {

            sendJSON(['success' => false, 'message' => 'يوجد طلب معلق بالفعل لهذا الطفل']);

            return;

        }



        unset($student['password_hash']);

        $snapshotJson = json_encode($student, JSON_UNESCAPED_UNICODE);

        $studentName = $student['name'] ?? '';



        $conn->begin_transaction();

        $ins = $conn->prepare("

            INSERT INTO student_transfer_requests

                (from_church_id, to_church_id, from_student_id, student_name, student_snapshot, status)

            VALUES (?, ?, ?, ?, ?, 'pending')

        ");

        $ins->bind_param("iiiss", $churchId, $toChurchId, $studentId, $studentName, $snapshotJson);

        if (!$ins->execute()) {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل إنشاء طلب النقل']);

            return;

        }



        if (!removeStudentFromChurch($conn, $studentId, $churchId)) {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل إزالة سجل الخريج']);

            return;

        }



        $conn->commit();

        writeAuditLog('graduate_transfer_send', 'students', $studentId, $studentName, null, null, 'to:' . $toChurch['church_name']);

        sendJSON([

            'success' => true,

            'message' => 'تم إرسال الطلب إلى ' . $toChurch['church_name'] . ' — بانتظار الموافقة',

        ]);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log('sendGraduateToChurch: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في إرسال الطلب']);

    }

}



function respondGraduateTransfer()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $requestId = intval($_POST['request_id'] ?? 0);

        $decision = sanitize($_POST['decision'] ?? '');

        $classId = intval($_POST['class_id'] ?? 0);



        if (!$churchId || !$requestId || !in_array($decision, ['accept', 'reject'], true)) {

            sendJSON(['success' => false, 'message' => 'بيانات غير صالحة']);

            return;

        }



        $conn = getDBConnection();

        ensureStudentGraduateSchema($conn);



        $rStmt = $conn->prepare("

            SELECT * FROM student_transfer_requests

            WHERE id = ? AND to_church_id = ? AND status = 'pending' LIMIT 1

        ");

        $rStmt->bind_param("ii", $requestId, $churchId);

        $rStmt->execute();

        $req = $rStmt->get_result()->fetch_assoc();

        if (!$req) {

            sendJSON(['success' => false, 'message' => 'الطلب غير موجود أو تمت معالجته']);

            return;

        }



        if ($decision === 'reject') {

            $upd = $conn->prepare("UPDATE student_transfer_requests SET status = 'rejected', updated_at = NOW() WHERE id = ?");

            $upd->bind_param("i", $requestId);

            $upd->execute();

            writeAuditLog('graduate_transfer_reject', 'students', $requestId, $req['student_name'] ?? '');

            sendJSON(['success' => true, 'message' => 'تم رفض طلب النقل']);

            return;

        }



        if ($classId <= 0) {

            $classId = getFirstClassIdForChurch($churchId);

        }

        if ($classId <= 0) {

            sendJSON(['success' => false, 'message' => 'لا توجد فصول في الكنيسة — أضف فصلاً أولاً']);

            return;

        }



        $snapshot = json_decode($req['student_snapshot'], true);

        if (!is_array($snapshot) || empty($snapshot['name'])) {

            sendJSON(['success' => false, 'message' => 'بيانات الطفل غير صالحة']);

            return;

        }



        $className = '';

        $hasCustom = $conn->prepare("SELECT arabic_name FROM church_classes WHERE id = ? AND church_id = ? AND is_active = 1");

        $hasCustom->bind_param("ii", $classId, $churchId);

        $hasCustom->execute();

        if ($cr = $hasCustom->get_result()->fetch_assoc()) {

            $className = $cr['arabic_name'];

        } else {

            $g = $conn->prepare("SELECT arabic_name FROM classes WHERE id = ?");

            $g->bind_param("i", $classId);

            $g->execute();

            if ($gr = $g->get_result()->fetch_assoc()) {

                $className = $gr['arabic_name'];

            }

        }



        $name = sanitize($snapshot['name']);

        $gender = in_array($snapshot['gender'] ?? '', ['male', 'female'], true) ? $snapshot['gender'] : 'male';

        $phone = sanitize($snapshot['phone'] ?? '');

        $address = sanitize($snapshot['address'] ?? '');

        $emergency = sanitize($snapshot['emergency_phone'] ?? '');

        $medical = sanitize($snapshot['medical_notes'] ?? '');

        $birthday = !empty($snapshot['birthday']) ? $snapshot['birthday'] : null;

        $customInfo = !empty($snapshot['custom_info']) ? $snapshot['custom_info'] : null;

        $imageUrl = $snapshot['image_url'] ?? null;

        $coupons = intval($snapshot['coupons'] ?? 0);

        $attC = intval($snapshot['attendance_coupons'] ?? 0);

        $comC = intval($snapshot['commitment_coupons'] ?? 0);

        $taskC = intval($snapshot['task_coupons'] ?? 0);



        $conn->begin_transaction();

        $addedByType = 'transfer';
        $ins = $conn->prepare("

            INSERT INTO students

                (church_id, name, gender, class_id, class, address, phone, emergency_phone,

                 medical_notes, birthday, coupons, attendance_coupons, commitment_coupons,

                 task_coupons, image_url, custom_info, enrollment_status, added_by)

            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?)

        ");

        $ins->bind_param(

            "ississssssiiiisss",

            $churchId,

            $name,

            $gender,

            $classId,

            $className,

            $address,

            $phone,

            $emergency,

            $medical,

            $birthday,

            $coupons,

            $attC,

            $comC,

            $taskC,

            $imageUrl,

            $customInfo,

            $addedByType

        );

        if (!$ins->execute()) {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل إضافة الطفل: ' . $ins->error]);

            return;

        }

        $newStudentId = (int) $conn->insert_id;



        $upd = $conn->prepare("

            UPDATE student_transfer_requests

            SET status = 'accepted', target_class_id = ?, accepted_student_id = ?, updated_at = NOW()

            WHERE id = ?

        ");

        $upd->bind_param("iii", $classId, $newStudentId, $requestId);

        $upd->execute();



        $conn->commit();

        writeAuditLog('graduate_transfer_accept', 'students', $newStudentId, $name, null, null, 'class:' . $className);

        sendJSON([

            'success' => true,

            'message' => 'تم قبول الطفل وإضافته إلى ' . ($className ?: 'الفصل المحدد'),

            'student_id' => $newStudentId,

        ]);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log('respondGraduateTransfer: ' . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في معالجة الطلب']);

    }

}



// ===== CHURCH SETTINGS (attendance day + combined class + more) =====



/**

 * Ensure the church_settings table exists with all needed columns.

 */

function ensureChurchSettingsTable($conn)

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        CREATE TABLE IF NOT EXISTS `church_settings` (

            `id`                     INT AUTO_INCREMENT PRIMARY KEY,

            `church_id`              INT NOT NULL UNIQUE,

            `attendance_day`         TINYINT NOT NULL DEFAULT 5

                                     COMMENT '1=Mon 2=Tue 3=Wed 4=Thu 5=Fri 6=Sat 7=Sun',

            `uncle_class_navigation` VARCHAR(10) NOT NULL DEFAULT 'all'

                                     COMMENT 'all | own',

            `combined_class_groups`  TEXT DEFAULT NULL

                                     COMMENT 'JSON array of {label, classes[]} groups',

            `custom_field`           TEXT DEFAULT NULL

                                     COMMENT 'JSON {name,icon} — one custom info field per church',

            `view_mode`              VARCHAR(10) NOT NULL DEFAULT 'classes'

                                     COMMENT 'classes | all | both',

            `coupons_enabled`        TINYINT NOT NULL DEFAULT 1

                                     COMMENT '0=disabled, 1=enabled',

            `coupons_count`          INT NOT NULL DEFAULT 100

                                     COMMENT 'number of coupons awarded on attendance',

            `coupon_presets`         VARCHAR(255) NOT NULL DEFAULT '10,30,50,100'

                                     COMMENT 'comma separated quick coupon adjustment values',

            `allowed_view_uncles`    TEXT DEFAULT NULL

                                     COMMENT 'comma separated usernames allowed to view uncles view',

            `uncle_fees_enabled`     TINYINT NOT NULL DEFAULT 1

                                     COMMENT '0=disabled, 1=enabled',

            `updated_at`             TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci

    ");

    // Safe migrations for existing installs

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `custom_field` TEXT DEFAULT NULL

        COMMENT 'JSON {name,icon} — one custom info field per church'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `view_mode` VARCHAR(10) NOT NULL DEFAULT 'classes'

        COMMENT 'classes | all | both'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `coupons_enabled` TINYINT NOT NULL DEFAULT 1

        COMMENT '0=disabled, 1=enabled'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `coupons_count` INT NOT NULL DEFAULT 100

        COMMENT 'number of coupons awarded on attendance'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `coupon_presets` VARCHAR(255) NOT NULL DEFAULT '10,30,50,100'

        COMMENT 'comma separated quick coupon adjustment values'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `allowed_view_uncles` TEXT DEFAULT NULL

        COMMENT 'comma separated usernames allowed to view uncles view'");

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS

        `uncle_fees_enabled` TINYINT NOT NULL DEFAULT 1

        COMMENT '0=disabled, 1=enabled'");

    ensureChurchSettingsAutoGradeColumns($conn);

    $conn->query("ALTER TABLE church_settings ADD COLUMN IF NOT EXISTS `qr_template` LONGTEXT DEFAULT NULL COMMENT 'JSON string of QR card design template'");
    $conn->query("ALTER TABLE trips ADD COLUMN IF NOT EXISTS `qr_template` LONGTEXT DEFAULT NULL COMMENT 'JSON string of QR card design template'");

}



function getChurchSettings()

{

    try {

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => true, 'settings' => getDefaultChurchSettings()]);

            return;

        }

        $conn = getDBConnection();

        ensureChurchSettingsTable($conn);



        $stmt = $conn->prepare("SELECT * FROM church_settings WHERE church_id = ?");

        $stmt->bind_param("i", $churchId);

        $stmt->execute();

        $row = $stmt->get_result()->fetch_assoc();



        if (!$row) {

            // Auto-create default row

            $conn->prepare("INSERT IGNORE INTO church_settings (church_id) VALUES (?)")

                ->bind_param("i", $churchId);

            $conn->query("INSERT IGNORE INTO church_settings (church_id) VALUES ($churchId)");

            $row = ['church_id' => $churchId] + getDefaultChurchSettings();

        }



        $rawCf = !empty($row['custom_field']) ? json_decode($row['custom_field'], true) : null;

        // Normalize: always return array of field objects or null

        $customFields = null;

        if (is_array($rawCf)) {

            if (isset($rawCf[0]) && is_array($rawCf[0])) {

                $customFields = $rawCf; // already an array

            } elseif (!empty($rawCf['name'])) {

                $customFields = [$rawCf]; // wrap single object in array

            }

        }



        $settings = [

            'attendance_day' => (int) ($row['attendance_day'] ?? 5),

            'uncle_class_navigation' => $row['uncle_class_navigation'] ?? 'all',

            'combined_class_groups' => $row['combined_class_groups']

                ? json_decode($row['combined_class_groups'], true) ?? []

                : [],

            'custom_field' => $customFields,

            'custom_fields' => $customFields, // alias for clarity

            'view_mode' => $row['view_mode'] ?? 'classes',

            'auto_kids_approval' => false, // will be overridden below

            'auto_grade_month' => isset($row['auto_grade_month']) ? (int) $row['auto_grade_month'] : null,

            'auto_grade_day' => isset($row['auto_grade_day']) ? (int) $row['auto_grade_day'] : null,

            'last_auto_grade_year' => isset($row['last_auto_grade_year']) ? (int) $row['last_auto_grade_year'] : null,

            'coupons_enabled' => isset($row['coupons_enabled']) ? (int) $row['coupons_enabled'] : 1,

            'coupons_count' => isset($row['coupons_count']) ? (int) $row['coupons_count'] : 100,

            'coupon_presets' => $row['coupon_presets'] ?? '10,30,50,100',

            'allowed_view_uncles' => $row['allowed_view_uncles'] ?? '',

            'uncle_fees_enabled' => isset($row['uncle_fees_enabled']) ? (int) $row['uncle_fees_enabled'] : 1,

            'qr_template' => $row['qr_template'] ?? null,

        ];



        // Load auto_kids_approval from churches.settings JSON

        $csStmt = $conn->prepare("SELECT settings FROM churches WHERE id = ? LIMIT 1");

        $csStmt->bind_param("i", $churchId);

        $csStmt->execute();

        $csRow = $csStmt->get_result()->fetch_assoc();

        if ($csRow && !empty($csRow['settings'])) {

            $cs = json_decode($csRow['settings'], true);

            $settings['auto_kids_approval'] = !empty($cs['auto_kids_approval']);

        }

        $settings['church_id'] = $churchId;
        $nameStmt = $conn->prepare("SELECT church_name FROM churches WHERE id = ? LIMIT 1");
        $nameStmt->bind_param("i", $churchId);
        $nameStmt->execute();
        $nameRow = $nameStmt->get_result()->fetch_assoc();
        $settings['church_name'] = $nameRow['church_name'] ?? '';

        sendJSON(['success' => true, 'settings' => $settings]);

    } catch (Exception $e) {

        error_log("getChurchSettings error: " . $e->getMessage());

        sendJSON(['success' => true, 'settings' => getDefaultChurchSettings()]);

    }

}



function getDefaultChurchSettings(): array

{

    return [

        'attendance_day' => 5,

        'uncle_class_navigation' => 'all',

        'combined_class_groups' => [],

        'custom_field' => null,

        'view_mode' => 'classes',

        'auto_grade_month' => null,

        'auto_grade_day' => null,

        'last_auto_grade_year' => null,

        'coupons_enabled' => 1,

        'coupons_count' => 100,

        'coupon_presets' => '10,30,50,100',

        'allowed_view_uncles' => '',

        'uncle_fees_enabled' => 1,

    ];

}

function cleanAndExtractBase64FromTemplate($templateStr) {
    if (empty($templateStr) || !is_string($templateStr)) return $templateStr;
    if (strlen($templateStr) < 1000) return $templateStr;

    $decoded = json_decode($templateStr, true);
    if (!is_array($decoded)) return $templateStr;

    $uploadDir = __DIR__ . '/uploads/qr_templates/';
    if (!is_dir($uploadDir)) {
        @mkdir($uploadDir, 0777, true);
    }

    $host = $_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? 'sunday-school.rf.gd';

    $replaceBase64 = function (&$item) use (&$replaceBase64, $uploadDir, $host) {
        if (is_string($item)) {
            if (preg_match('/^data:image\/(png|jpeg|jpg|webp|gif);base64,(.+)$/is', $item, $matches)) {
                $ext = strtolower($matches[1]);
                if ($ext === 'jpeg') $ext = 'jpg';
                $binData = base64_decode($matches[2]);
                if ($binData !== false && strlen($binData) > 0) {
                    $filename = 'qr_bg_' . time() . '_' . uniqid() . '.' . $ext;
                    $filePath = $uploadDir . $filename;
                    if (@file_put_contents($filePath, $binData) !== false) {
                        $item = "https://" . $host . "/uploads/qr_templates/" . $filename;
                    }
                }
            }
        } elseif (is_array($item)) {
            foreach ($item as $k => &$v) {
                $replaceBase64($v);
            }
        }
    };

    $replaceBase64($decoded);
    return json_encode($decoded, JSON_UNESCAPED_UNICODE);
}

function saveQRTemplate()
{
    try {
        checkUncleAuth();
        $churchId = getChurchId();
        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);
        $target = sanitize($_POST['target'] ?? $_GET['target'] ?? '');
        $template = $_POST['template'] ?? '';

        if (empty($template)) {
            $rawInput = @file_get_contents('php://input');
            if (!empty($rawInput)) {
                parse_str($rawInput, $parsedInput);
                if (!empty($parsedInput['template'])) {
                    $template = $parsedInput['template'];
                    $target = $target ?: sanitize($parsedInput['target'] ?? '');
                    $tripId = $tripId ?: intval($parsedInput['trip_id'] ?? 0);
                } else {
                    $jsonInput = @json_decode($rawInput, true);
                    if (is_array($jsonInput) && !empty($jsonInput['template'])) {
                        $template = is_string($jsonInput['template']) ? $jsonInput['template'] : json_encode($jsonInput['template'], JSON_UNESCAPED_UNICODE);
                        $target = $target ?: sanitize($jsonInput['target'] ?? '');
                        $tripId = $tripId ?: intval($jsonInput['trip_id'] ?? 0);
                    }
                }
            }
        }

        if (empty($template)) {
            sendJSON(['success' => false, 'message' => 'بيانات القالب مطلوبة']);
            return;
        }

        $template = cleanAndExtractBase64FromTemplate($template);

        $conn = getDBConnection();
        ensureChurchSettingsTable($conn);

        if ($target === 'trip' && $tripId > 0) {
            $stmt = $conn->prepare("UPDATE trips SET qr_template = ? WHERE id = ?");
            $stmt->bind_param("si", $template, $tripId);
            if ($stmt->execute()) {
                sendJSON(['success' => true, 'message' => 'تم حفظ قالب الرحلة بنجاح', 'target' => 'trip', 'trip_id' => $tripId]);
            } else {
                sendJSON(['success' => false, 'message' => 'فشل حفظ قالب الرحلة: ' . $stmt->error]);
            }
        } else {
            // Ensure the church_settings row exists
            $check = $conn->prepare("SELECT 1 FROM church_settings WHERE church_id = ? LIMIT 1");
            $check->bind_param("i", $churchId);
            $check->execute();
            if ($check->get_result()->num_rows === 0) {
                $ins = $conn->prepare("INSERT IGNORE INTO church_settings (church_id) VALUES (?)");
                $ins->bind_param("i", $churchId);
                $ins->execute();
            }

            $stmt = $conn->prepare("UPDATE church_settings SET qr_template = ? WHERE church_id = ?");
            $stmt->bind_param("si", $template, $churchId);
            if ($stmt->execute()) {
                sendJSON(['success' => true, 'message' => 'تم حفظ قالب الكنيسة بنجاح', 'target' => 'church']);
            } else {
                sendJSON(['success' => false, 'message' => 'فشل حفظ قالب الكنيسة: ' . $stmt->error]);
            }
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}

function getQRTemplates()
{
    try {
        checkUncleAuth();
        $churchId = getChurchId();
        $tripId = intval($_POST['trip_id'] ?? $_GET['trip_id'] ?? 0);

        $conn = getDBConnection();
        ensureChurchSettingsTable($conn);

        // 1. Church template
        $churchStmt = $conn->prepare("SELECT qr_template FROM church_settings WHERE church_id = ?");
        $churchStmt->bind_param("i", $churchId);
        $churchStmt->execute();
        $churchRow = $churchStmt->get_result()->fetch_assoc();
        $churchTemplate = $churchRow['qr_template'] ?? null;

        if (!empty($churchTemplate) && strlen($churchTemplate) > 50000 && strpos($churchTemplate, 'data:image') !== false) {
            $churchTemplate = cleanAndExtractBase64FromTemplate($churchTemplate);
            $updateSql = $conn->prepare("UPDATE church_settings SET qr_template = ? WHERE church_id = ?");
            if ($updateSql) {
                $updateSql->bind_param("si", $churchTemplate, $churchId);
                $updateSql->execute();
            }
        }

        // 2. Trip template
        $tripTemplate = null;
        if ($tripId > 0) {
            $tripStmt = $conn->prepare("SELECT qr_template FROM trips WHERE id = ?");
            $tripStmt->bind_param("i", $tripId);
            $tripStmt->execute();
            $tripRow = $tripStmt->get_result()->fetch_assoc();
            $tripTemplate = $tripRow['qr_template'] ?? null;

            if (!empty($tripTemplate) && strlen($tripTemplate) > 50000 && strpos($tripTemplate, 'data:image') !== false) {
                $tripTemplate = cleanAndExtractBase64FromTemplate($tripTemplate);
                $updateSql = $conn->prepare("UPDATE trips SET qr_template = ? WHERE id = ?");
                if ($updateSql) {
                    $updateSql->bind_param("si", $tripTemplate, $tripId);
                    $updateSql->execute();
                }
            }
        }

        // 3. Other trips templates metadata (lightweight)
        $otherTrips = [];
        $othersStmt = $conn->prepare("SELECT id, title, qr_template FROM trips WHERE church_id = ? AND qr_template IS NOT NULL AND id != ?");
        $othersStmt->bind_param("ii", $churchId, $tripId);
        $othersStmt->execute();
        $res = $othersStmt->get_result();
        while ($row = $res->fetch_assoc()) {
            $tName = '';
            if (!empty($row['qr_template'])) {
                $decoded = json_decode($row['qr_template'], true);
                if (is_array($decoded) && !empty($decoded['templateName'])) {
                    $tName = $decoded['templateName'];
                }
            }
            $otherTrips[] = [
                'id' => $row['id'],
                'title' => $row['title'],
                'templateName' => $tName
            ];
        }

        sendJSON([
            'success' => true,
            'church_template' => $churchTemplate,
            'trip_template' => $tripTemplate,
            'other_trips' => $otherTrips
        ]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}



function saveChurchSettings()

{

    try {

        $churchId = getChurchId();

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'معرف الكنيسة مطلوب']);

            return;

        }

        $conn = getDBConnection();

        ensureChurchSettingsTable($conn);



        $attendanceDay = intval($_POST['attendance_day'] ?? 5);

        $uncleClassNav = sanitize($_POST['uncle_class_navigation'] ?? 'all');

        $combinedGroupsRaw = $_POST['combined_class_groups'] ?? '[]';

        $customFieldRaw = $_POST['custom_field'] ?? '';

        $viewMode = sanitize($_POST['view_mode'] ?? 'classes');

        $autoKidsApproval = !empty($_POST['auto_kids_approval']) && $_POST['auto_kids_approval'] === '1';

        $hasAutoGradeFields = array_key_exists('auto_grade_month', $_POST)

            || array_key_exists('auto_grade_day', $_POST);

        $autoGradeMonth = null;

        $autoGradeDay = null;

        if ($hasAutoGradeFields) {

            $autoGradeMonthRaw = $_POST['auto_grade_month'] ?? '';

            $autoGradeDayRaw = $_POST['auto_grade_day'] ?? '';

            $autoGradeMonth = ($autoGradeMonthRaw === '' || $autoGradeMonthRaw === '0')

                ? null : max(1, min(12, intval($autoGradeMonthRaw)));

            $autoGradeDay = ($autoGradeDayRaw === '' || $autoGradeDayRaw === '0')

                ? null : max(1, min(31, intval($autoGradeDayRaw)));

        }



        // Validate

        if ($attendanceDay < 1 || $attendanceDay > 7)

            $attendanceDay = 5;

        if (!in_array($uncleClassNav, ['all', 'own']))

            $uncleClassNav = 'all';

        if (!in_array($viewMode, ['classes', 'all', 'both']))

            $viewMode = 'classes';



        $combinedGroups = json_decode($combinedGroupsRaw, true);

        if (!is_array($combinedGroups))

            $combinedGroups = [];

        $combinedGroupsJson = json_encode($combinedGroups, JSON_UNESCAPED_UNICODE);



        // Validate custom fields: supports either a single {name,icon} object OR an array of them

        $customFieldJson = null;

        if (!empty($customFieldRaw)) {

            $cf = json_decode($customFieldRaw, true);

            if (is_array($cf)) {

                // Array of fields: [{name,icon}, ...]

                if (isset($cf[0]) && is_array($cf[0])) {

                    $cleaned = [];

                    foreach ($cf as $i => $field) {

                        if (!empty($field['name'])) {

                            // Assign a stable key if not already set — based on index

                            $stableKey = !empty($field['key']) ? sanitize($field['key']) : ('field_' . $i);

                            $cleaned[] = [

                                'name' => mb_substr(sanitize($field['name']), 0, 50),

                                'icon' => sanitize($field['icon'] ?? 'fa-info-circle'),

                                'key' => $stableKey,

                            ];

                        }

                    }

                    if (!empty($cleaned)) {

                        $customFieldJson = json_encode($cleaned, JSON_UNESCAPED_UNICODE);

                    }

                    // Single field object: {name, icon}

                } elseif (!empty($cf['name'])) {

                    $stableKey = !empty($cf['key']) ? sanitize($cf['key']) : 'field_0';

                    $cleaned = [

                        'name' => mb_substr(sanitize($cf['name']), 0, 50),

                        'icon' => sanitize($cf['icon'] ?? 'fa-info-circle'),

                        'key' => $stableKey,

                    ];

                    $customFieldJson = json_encode([$cleaned], JSON_UNESCAPED_UNICODE);

                }

            }

        }



        $couponsEnabled = isset($_POST['coupons_enabled']) ? intval($_POST['coupons_enabled']) : 1;

        $couponsCount = isset($_POST['coupons_count']) ? intval($_POST['coupons_count']) : 100;

        $couponPresets = sanitize($_POST['coupon_presets'] ?? '10,30,50,100');

        $allowedViewUncles = sanitize($_POST['allowed_view_uncles'] ?? '');

        $uncleFeesEnabled = isset($_POST['uncle_fees_enabled']) ? intval($_POST['uncle_fees_enabled']) : 1;

        if ($hasAutoGradeFields) {

            $stmt = $conn->prepare("

                INSERT INTO church_settings

                    (church_id, attendance_day, uncle_class_navigation, combined_class_groups, custom_field, view_mode,

                     auto_grade_month, auto_grade_day, coupons_enabled, coupons_count, coupon_presets, allowed_view_uncles, uncle_fees_enabled)

                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)

                ON DUPLICATE KEY UPDATE

                    attendance_day         = VALUES(attendance_day),

                    uncle_class_navigation = VALUES(uncle_class_navigation),

                    combined_class_groups  = VALUES(combined_class_groups),

                    custom_field           = VALUES(custom_field),

                    view_mode              = VALUES(view_mode),

                    auto_grade_month       = VALUES(auto_grade_month),

                    auto_grade_day         = VALUES(auto_grade_day),

                    coupons_enabled        = VALUES(coupons_enabled),

                    coupons_count          = VALUES(coupons_count),

                    coupon_presets         = VALUES(coupon_presets),

                    allowed_view_uncles    = VALUES(allowed_view_uncles),

                    uncle_fees_enabled     = VALUES(uncle_fees_enabled),

                    updated_at             = NOW()

            ");

            $stmt->bind_param(

                "iissssiiiissi",

                $churchId,

                $attendanceDay,

                $uncleClassNav,

                $combinedGroupsJson,

                $customFieldJson,

                $viewMode,

                $autoGradeMonth,

                $autoGradeDay,

                $couponsEnabled,

                $couponsCount,

                $couponPresets,

                $allowedViewUncles,

                $uncleFeesEnabled

            );

        } else {

            $stmt = $conn->prepare("

                INSERT INTO church_settings

                    (church_id, attendance_day, uncle_class_navigation, combined_class_groups, custom_field, view_mode,

                     coupons_enabled, coupons_count, coupon_presets, allowed_view_uncles, uncle_fees_enabled)

                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)

                ON DUPLICATE KEY UPDATE

                    attendance_day         = VALUES(attendance_day),

                    uncle_class_navigation = VALUES(uncle_class_navigation),

                    combined_class_groups  = VALUES(combined_class_groups),

                    custom_field           = VALUES(custom_field),

                    view_mode              = VALUES(view_mode),

                    coupons_enabled        = VALUES(coupons_enabled),

                    coupons_count          = VALUES(coupons_count),

                    coupon_presets         = VALUES(coupon_presets),

                    allowed_view_uncles    = VALUES(allowed_view_uncles),

                    uncle_fees_enabled     = VALUES(uncle_fees_enabled),

                    updated_at             = NOW()

            ");

            $stmt->bind_param(

                "iissssiissi",

                $churchId,

                $attendanceDay,

                $uncleClassNav,

                $combinedGroupsJson,

                $customFieldJson,

                $viewMode,

                $couponsEnabled,

                $couponsCount,

                $couponPresets,

                $allowedViewUncles,

                $uncleFeesEnabled

            );

        }



        if ($stmt->execute()) {

            if ($hasAutoGradeFields && ($autoGradeMonth === null || $autoGradeDay === null)) {

                $clr = $conn->prepare("

                    UPDATE church_settings

                    SET auto_grade_month = NULL, auto_grade_day = NULL

                    WHERE church_id = ?

                ");

                $clr->bind_param("i", $churchId);

                $clr->execute();

            }

            // Save auto_kids_approval in churches.settings JSON

            $csStmt2 = $conn->prepare("SELECT settings FROM churches WHERE id = ? LIMIT 1");

            $csStmt2->bind_param("i", $churchId);

            $csStmt2->execute();

            $csRow2 = $csStmt2->get_result()->fetch_assoc();

            $existingSettings = [];

            if ($csRow2 && !empty($csRow2['settings'])) {

                $existingSettings = json_decode($csRow2['settings'], true) ?? [];

            }

            $existingSettings['auto_kids_approval'] = $autoKidsApproval;

            $newSettingsJson = json_encode($existingSettings, JSON_UNESCAPED_UNICODE);

            $updStmt = $conn->prepare("UPDATE churches SET settings = ? WHERE id = ?");

            $updStmt->bind_param("si", $newSettingsJson, $churchId);

            $updStmt->execute();



            sendJSON(['success' => true, 'message' => 'تم حفظ الإعدادات بنجاح']);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في حفظ الإعدادات: ' . $stmt->error]);

        }

    } catch (Exception $e) {

        error_log("saveChurchSettings error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في حفظ الإعدادات: ' . $e->getMessage()]);

    }

}



/**

 * Uncle dashboard: Get data for a combined class group.

 * POST: group_label (string) — the label of the combined group

 * The API looks up combined_class_groups from church_settings and returns

 * all students from all classes in the group as a single merged list.

 */

function getUncleClassView()

{

    try {

        $churchId = getChurchId();

        $groupLabel = sanitize($_POST['group_label'] ?? '');



        if (empty($groupLabel)) {

            sendJSON(['success' => false, 'message' => 'اسم المجموعة مطلوب']);

            return;

        }



        $conn = getDBConnection();

        ensureChurchSettingsTable($conn);



        // Load combined groups for this church

        $stmt = $conn->prepare("SELECT combined_class_groups FROM church_settings WHERE church_id = ?");

        $stmt->bind_param("i", $churchId);

        $stmt->execute();

        $row = $stmt->get_result()->fetch_assoc();

        $groups = $row ? json_decode($row['combined_class_groups'] ?? '[]', true) : [];



        // Find the matching group

        $targetGroup = null;

        foreach ($groups as $g) {

            if (($g['label'] ?? '') === $groupLabel) {

                $targetGroup = $g;

                break;

            }

        }



        if (!$targetGroup || empty($targetGroup['classes'])) {

            sendJSON(['success' => false, 'message' => 'المجموعة غير موجودة أو فارغة']);

            return;

        }



        $classNames = array_map('trim', (array) $targetGroup['classes']);

        if (empty($classNames)) {

            sendJSON(['success' => false, 'message' => 'لا توجد فصول في هذه المجموعة']);

            return;

        }



        // Resolve class IDs for the given names (custom + global)

        $churchClasses = getClassesForChurch($churchId);

        $classIdMap = [];

        foreach ($churchClasses as $c) {

            $classIdMap[mb_strtolower($c['arabic_name'])] = $c['id'];

        }



        $classIds = [];

        foreach ($classNames as $cn) {

            $key = mb_strtolower($cn);

            if (isset($classIdMap[$key])) {

                $classIds[] = (int) $classIdMap[$key];

            }

        }



        if (empty($classIds)) {

            sendJSON(['success' => false, 'message' => 'لم يتم العثور على فصول مطابقة']);

            return;

        }



        $placeholders = implode(',', array_fill(0, count($classIds), '?'));

        $types = str_repeat('i', count($classIds) + 1); // +1 for church_id



        $sql = "

            SELECT 

                s.id, s.name, s.phone, s.birthday, s.coupons,

                s.attendance_coupons, s.commitment_coupons, s.image_url, s.class_id,

                COALESCE(cc.arabic_name, gc.arabic_name, s.class) AS class_name,

                COALESCE(cc.code, gc.code) AS class_code

            FROM students s

            LEFT JOIN church_classes cc ON s.class_id = cc.id AND cc.church_id = s.church_id AND cc.is_active = 1

            LEFT JOIN classes gc        ON s.class_id = gc.id

            WHERE s.church_id = ? AND s.class_id IN ($placeholders)

            ORDER BY COALESCE(cc.display_order, gc.display_order, 999), s.name

        ";



        $bindValues = array_merge([$churchId], $classIds);

        $stmt2 = $conn->prepare($sql);

        $stmt2->bind_param($types, ...$bindValues);

        $stmt2->execute();

        $result = $stmt2->get_result();



        $students = [];

        while ($r = $result->fetch_assoc()) {

            $studentData = [

                'الاسم' => $r['name'],

                'الفصل' => $r['class_name'] ?? '',

                '_classId' => (int) $r['class_id'],

                '_classCode' => $r['class_code'] ?? '',

                'رقم التليفون' => $r['phone'] ?? '',

                'عيد الميلاد' => formatDateFromDB($r['birthday']),

                'كوبونات' => (int) $r['coupons'],

                'كوبونات الحضور' => (int) $r['attendance_coupons'],

                'كوبونات الالتزام' => (int) $r['commitment_coupons'],

                'صورة' => $r['image_url'] ?? '',

                '_studentId' => (int) $r['id'],

                '_allAttendance' => [],

            ];



            // Load recent attendance

            $attStmt = $conn->prepare("

                SELECT attendance_date, status FROM attendance

                WHERE student_id = ?

                ORDER BY attendance_date DESC LIMIT 50

            ");

            $attStmt->bind_param("i", $r['id']);

            $attStmt->execute();

            $attResult = $attStmt->get_result();

            while ($att = $attResult->fetch_assoc()) {

                $d = formatDateFromDB($att['attendance_date']);

                $v = $att['status'] === 'present' ? 'ح' : 'غ';

                $studentData[$d] = $v;

                $studentData['_allAttendance'][$d] = $v;

            }



            $students[] = $studentData;

        }



        sendJSON([

            'success' => true,

            'students' => $students,

            'group_label' => $groupLabel,

            'class_names' => $classNames,

            'count' => count($students),

        ]);



    } catch (Exception $e) {

        error_log("getUncleClassView error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في تحميل بيانات المجموعة: ' . $e->getMessage()]);

    }

}

// ── Delete a single audit log entry (admin only) ─────────────

function deleteAuditLog()

{

    try {

        $churchId = getChurchId();

        $logId = intval($_POST['log_id'] ?? 0);

        if (!$logId) {

            sendJSON(['success' => false, 'message' => 'معرف السجل مطلوب']);

            return;

        }

        $conn = getDBConnection();

        $stmt = $conn->prepare("DELETE FROM audit_logs WHERE id = ? AND church_id = ?");

        $stmt->bind_param("ii", $logId, $churchId);

        if ($stmt->execute() && $stmt->affected_rows > 0) {

            sendJSON(['success' => true, 'message' => 'تم حذف السجل']);

        } else {

            sendJSON(['success' => false, 'message' => 'لم يتم العثور على السجل']);

        }

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);

    }

}



function reinsertRecordInternal($tableName, $row, $conn) {
    if (empty($row) || !is_array($row)) return false;
    
    $fields = [];
    $placeholders = [];
    $types = '';
    $params = [];
    
    foreach ($row as $key => $val) {
        if (strpos($key, '_') === 0) continue; // skip nested snapshots
        $fields[] = "`$key`";
        $placeholders[] = "?";
        $params[] = $val;
        
        if (is_int($val)) $types .= 'i';
        elseif (is_float($val)) $types .= 'd';
        else $types .= 's';
    }
    
    $sql = "INSERT INTO `$tableName` (" . implode(', ', $fields) . ") VALUES (" . implode(', ', $placeholders) . ")";
    $stmt = $conn->prepare($sql);
    if (!$stmt) {
        throw new Exception("Reinsert failed preparing query for $tableName: " . $conn->error);
    }
    
    $stmt->bind_param($types, ...$params);
    return $stmt->execute();
}

function restoreSingleAuditLogInternal($logId, $churchId, $conn, $targetStudentId = 0)
{
    try {
        if (!$logId) {
            return ['success' => false, 'message' => 'معرف السجل مطلوب'];
        }
        if (!$churchId) {
            $churchId = getChurchId();
        }
        if (!$conn) {
            $conn = getDBConnection();
        }



        // 1. Fetch the log entry
        if (isDeveloperRole()) {
            $stmt = $conn->prepare("SELECT * FROM audit_logs WHERE id = ?");
            $stmt->bind_param("i", $logId);
            $stmt->execute();
            $log = $stmt->get_result()->fetch_assoc();
            if ($log && !empty($log['church_id'])) {
                $churchId = (int)$log['church_id'];
            }
        } else {
            $stmt = $conn->prepare("SELECT * FROM audit_logs WHERE id = ? AND church_id = ?");
            $stmt->bind_param("ii", $logId, $churchId);
            $stmt->execute();
            $log = $stmt->get_result()->fetch_assoc();
        }



        if (!$log) {

            return ['success' => false, 'message' => 'لم يتم العثور على السجل'];

        }



        $action = $log['action'];

        $entity = $log['entity'];

        $entityId = $log['entity_id'];

        $oldData = !empty($log['old_data']) ? json_decode($log['old_data'], true) : null;

        $newData = !empty($log['new_data']) ? json_decode($log['new_data'], true) : null;



        if (empty($oldData) && empty($newData)) {
            // Attempt fallback extraction if log notes/description contains date or action details
            $logNotes = ($log['notes'] ?? '') . ' ' . ($log['description'] ?? '') . ' ' . ($log['entity_name'] ?? '');
            if ($action === 'bulk_attendance_save' || strpos($logNotes, 'حضور') !== false) {
                preg_match('/(\d{4}-\d{2}-\d{2})/', $logNotes, $mDate);
                $attDate = $mDate[1] ?? date('Y-m-d', strtotime($log['created_at']));
                $churchId = intval($log['church_id']);
                $targetStudentId = intval($targetStudentId ?: ($_POST['target_student_id'] ?? 0));
                
                if ($targetStudentId > 0) {
                    $chkAtt = $conn->prepare("SELECT status FROM attendance WHERE student_id = ? AND attendance_date = ?");
                    $chkAtt->bind_param("is", $targetStudentId, $attDate);
                    $chkAtt->execute();
                    $attRow = $chkAtt->get_result()->fetch_assoc();
                    if ($attRow) {
                        if ($attRow['status'] === 'present') {
                            $conn->query("UPDATE students SET attendance_coupons = GREATEST(0, attendance_coupons - 100), coupons = GREATEST(0, coupons - 100) WHERE id = $targetStudentId");
                        }
                        $conn->query("DELETE FROM attendance WHERE student_id = $targetStudentId AND attendance_date = '$attDate'");
                    }
                    return ['success' => true, 'message' => "تم استرجاع وتراجع سجل حضور الطفل لهذا التاريخ ($attDate) بنجاح"];
                } else {
                    $getPresent = $conn->prepare("SELECT student_id FROM attendance WHERE church_id = ? AND attendance_date = ? AND status = 'present'");
                    $getPresent->bind_param("is", $churchId, $attDate);
                    $getPresent->execute();
                    $resPresent = $getPresent->get_result();
                    while ($pRow = $resPresent->fetch_assoc()) {
                        $pSid = intval($pRow['student_id']);
                        $conn->query("UPDATE students SET attendance_coupons = GREATEST(0, attendance_coupons - 100), coupons = GREATEST(0, coupons - 100) WHERE id = $pSid");
                    }
                    
                    $delAtt = $conn->prepare("DELETE FROM attendance WHERE church_id = ? AND attendance_date = ?");
                    $delAtt->bind_param("is", $churchId, $attDate);
                    $delAtt->execute();
                    $affectedRows = $delAtt->affected_rows;
                    return ['success' => true, 'message' => "تم استرجاع وتراجع سجلات حضور وغياب التاريخ ($attDate) لعدد $affectedRows طفل بنجاح"];
                }
            }
            return ['success' => false, 'message' => 'لا توجد بيانات تاريخية لاسترجاعها لهذا السجل'];
        }



        $reverted = false;
        $msg = "تم استرجاع العملية بنجاح";

        if (!$targetStudentId) {
            $targetStudentId = intval($_POST['target_student_id'] ?? 0);
        }

        if ($entity === 'bulk_action') {
            if (!is_array($oldData)) {
                return ['success' => false, 'message' => 'بيانات السجل الجماعي غير صالحة'];
            }

            if ($targetStudentId > 0) {
                $filtered = [];
                foreach ($oldData as $item) {
                    if (intval($item['id'] ?? 0) === $targetStudentId) {
                        $filtered[] = $item;
                        break;
                    }
                }
                if (empty($filtered)) {
                    return ['success' => false, 'message' => 'الطفل المحدد غير موجود في هذه العملية الجماعية'];
                }
                $oldData = $filtered;
            }

            $conn->begin_transaction();
            $revertedCount = 0;

            foreach ($oldData as $item) {
                $sid = intval($item['id'] ?? 0);
                $sName = $item['name'] ?? '';
                if (!$sid) continue;

                if ($action === 'bulk_student_delete') {
                    $snapshot = $item['old_data'] ?? null;
                    if (!$snapshot) continue;

                    $chk = $conn->prepare("SELECT id FROM students WHERE id = ?");
                    $chk->bind_param("i", $sid);
                    $chk->execute();
                    if ($chk->get_result()->num_rows > 0) {
                        continue;
                    }

                    $whitelist = ['id', 'church_id', 'name', 'gender', 'class_id', 'class', 'address', 'phone', 'emergency_phone', 'parent_phones', 'medical_notes', 'birthday', 'coupons', 'attendance_coupons', 'commitment_coupons', 'task_coupons', 'image_url', 'custom_info', 'email', 'added_by'];
                    $fields = [];
                    $placeholders = [];
                    $types = '';
                    $params = [];
                    foreach ($snapshot as $key => $val) {
                        if (in_array($key, $whitelist, true)) {
                            $fields[] = "`$key`";
                            $placeholders[] = "?";
                            $params[] = $val;
                            if (is_int($val)) $types .= 'i';
                            elseif (is_float($val)) $types .= 'd';
                            else $types .= 's';
                        }
                    }

                    if (!empty($fields)) {
                        $sql = "INSERT INTO students (" . implode(', ', $fields) . ", created_at) VALUES (" . implode(', ', $placeholders) . ", NOW())";
                        $ins = $conn->prepare($sql);
                        $ins->bind_param($types, ...$params);
                        if ($ins->execute()) {
                            $revertedCount++;
                            if (!empty($snapshot['image_url'])) {
                                recoverRevertedImageFile($snapshot['image_url']);
                            }

                            // Restore related attendance from snapshot if present
                            if (isset($snapshot['_attendance_history']) && is_array($snapshot['_attendance_history'])) {
                                $insAtt = $conn->prepare("
                                    INSERT INTO attendance (student_id, church_id, attendance_date, status, uncle_id, created_at)
                                    VALUES (?, ?, ?, ?, ?, NOW())
                                    ON DUPLICATE KEY UPDATE status = VALUES(status), uncle_id = VALUES(uncle_id)
                                ");
                                foreach ($snapshot['_attendance_history'] as $att) {
                                    $uId = $att['uncle_id'] ?? null;
                                    $insAtt->bind_param("iissi", $sid, $churchId, $att['attendance_date'], $att['status'], $uId);
                                    $insAtt->execute();
                                }
                            } else {
                                // Fallback: Reconstruct attendance from audit logs
                                recoverStudentAttendanceFromAuditLogs($sid, $churchId, $conn);
                            }

                            // Restore sibling groups if present
                            if (isset($snapshot['_sibling_groups']) && is_array($snapshot['_sibling_groups'])) {
                                $insSib = $conn->prepare("INSERT INTO student_sibling_group_members (student_id, group_id) VALUES (?, ?)");
                                foreach ($snapshot['_sibling_groups'] as $groupId) {
                                    $insSib->bind_param("ii", $sid, $groupId);
                                    $insSib->execute();
                                }
                            }
                        }
                    }
                } elseif ($action === 'bulk_student_class_update') {
                    $oldClassId = intval($item['old_data']['class_id'] ?? 0);
                    $oldClass = $item['old_data']['class'] ?? '';
                    
                    $chk = $conn->prepare("SELECT id FROM students WHERE id = ? AND church_id = ?");
                    $chk->bind_param("ii", $sid, $churchId);
                    $chk->execute();
                    if ($chk->get_result()->num_rows === 0) {
                        continue;
                    }

                    $upd = $conn->prepare("UPDATE students SET class_id = ?, class = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                    $upd->bind_param("isii", $oldClassId, $oldClass, $sid, $churchId);
                    if ($upd->execute()) {
                        $revertedCount++;
                    }
                } elseif ($action === 'bulk_student_coupon_update') {
                    $chk = $conn->prepare("SELECT coupons, commitment_coupons FROM students WHERE id = ? AND church_id = ?");
                    $chk->bind_param("ii", $sid, $churchId);
                    $chk->execute();
                    $stu = $chk->get_result()->fetch_assoc();
                    if (!$stu) continue;

                    $oldTotal = intval($item['old_data']['coupons'] ?? 0);
                    $newTotal = intval($item['new_data']['coupons'] ?? 0);
                    $diff = $oldTotal - $newTotal;
                    $newCommitment = intval($stu['commitment_coupons']) + $diff;
                    if ($newCommitment < 0) $newCommitment = 0;

                    $upd = $conn->prepare("UPDATE students SET coupons = ?, commitment_coupons = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                    $upd->bind_param("iiii", $oldTotal, $newCommitment, $sid, $churchId);
                    if ($upd->execute()) {
                        $uncleId = $_SESSION['uncle_id'] ?? null;
                        $logStmt = $conn->prepare("
                            INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type)
                            VALUES (?, ?, ?, ?, ?, 'manual')
                        ");
                        $logStmt->bind_param("iiiii", $sid, $uncleId, $newTotal, $oldTotal, $diff);
                        $logStmt->execute();
                        $revertedCount++;
                    }
                } elseif ($action === 'bulk_attendance_save') {
                    $oldStatus = $item['old_data']['status'] ?? 'pending';
                    $newStatus = $item['new_data']['status'] ?? 'pending';
                    $attDate = $item['date'] ?? null;
                    if (!$attDate) continue;

                    $chkStu = $conn->prepare("SELECT id, name, coupons, attendance_coupons, commitment_coupons, task_coupons FROM students WHERE id = ? AND church_id = ?");
                    $chkStu->bind_param("ii", $sid, $churchId);
                    $chkStu->execute();
                    $student = $chkStu->get_result()->fetch_assoc();
                    if (!$student) continue;

                    $currentAttCoupons = intval($student['attendance_coupons']);
                    $commitmentCoupons = intval($student['commitment_coupons']);
                    $taskCoupons = intval($student['task_coupons']);

                    if ($oldStatus === 'pending') {
                        $del = $conn->prepare("DELETE FROM attendance WHERE student_id = ? AND attendance_date = ?");
                        $del->bind_param("is", $sid, $attDate);
                        $del->execute();
                        
                        if ($newStatus === 'present') {
                            $newAtt = max(0, $currentAttCoupons - 100);
                            $newTotal = $newAtt + $commitmentCoupons + $taskCoupons;
                            $upd = $conn->prepare("UPDATE students SET attendance_coupons=?, coupons=? WHERE id=?");
                            $upd->bind_param("iii", $newAtt, $newTotal, $sid);
                            $upd->execute();
                        }
                        $revertedCount++;
                    } else {
                        $ins = $conn->prepare("
                            INSERT INTO attendance (student_id, church_id, attendance_date, status, uncle_id)
                            VALUES (?, ?, ?, ?, ?)
                            ON DUPLICATE KEY UPDATE status = VALUES(status), uncle_id = VALUES(uncle_id)
                        ");
                        $uncleId = $_SESSION['uncle_id'] ?? null;
                        $ins->bind_param("iissi", $sid, $churchId, $attDate, $oldStatus, $uncleId);
                        if ($ins->execute()) {
                            if ($oldStatus === 'present' && $newStatus !== 'present') {
                                $newAtt = $currentAttCoupons + 100;
                                $newTotal = $newAtt + $commitmentCoupons + $taskCoupons;
                                $upd = $conn->prepare("UPDATE students SET attendance_coupons=?, coupons=? WHERE id=?");
                                $upd->bind_param("iii", $newAtt, $newTotal, $sid);
                                $upd->execute();
                            } elseif ($oldStatus !== 'present' && $newStatus === 'present') {
                                $newAtt = max(0, $currentAttCoupons - 100);
                                $newTotal = $newAtt + $commitmentCoupons + $taskCoupons;
                                $upd = $conn->prepare("UPDATE students SET attendance_coupons=?, coupons=? WHERE id=?");
                                $upd->bind_param("iii", $newAtt, $newTotal, $sid);
                                $upd->execute();
                            }
                            $revertedCount++;
                        }
                    }
                } elseif ($action === 'bulk_note_add') {
                    $chk = $conn->prepare("SELECT custom_info FROM students WHERE id = ? AND church_id = ?");
                    $chk->bind_param("ii", $sid, $churchId);
                    $chk->execute();
                    $student = $chk->get_result()->fetch_assoc();
                    if ($student) {
                        $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
                        if (is_array($customInfo) && isset($customInfo['_notes']) && is_array($customInfo['_notes'])) {
                            $foundIdx = -1;
                            $targetNoteId = $item['note']['id'] ?? '';
                            foreach ($customInfo['_notes'] as $idx => $note) {
                                if (($note['id'] ?? '') === $targetNoteId) {
                                    $foundIdx = $idx;
                                    break;
                                }
                            }
                            if ($foundIdx !== -1) {
                                array_splice($customInfo['_notes'], $foundIdx, 1);
                                $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);
                                $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                                $upd->bind_param("sii", $customInfoJson, $sid, $churchId);
                                if ($upd->execute()) {
                                    $revertedCount++;
                                }
                            }
                        }
                    }
                }
            }

            if ($revertedCount > 0) {
                $conn->commit();
                $reverted = true;
                
                if ($targetStudentId > 0) {
                    $msg = "تم استرجاع العملية للطفل بنجاح";
                    $notes = "استرجاع الطفل " . ($oldData[0]['name'] ?? '') . " فقط من العملية: " . ($log['notes'] ?? $action);
                } else {
                    $msg = "تم استرجاع العملية الجماعية بالكامل لـ $revertedCount من الأطفال بنجاح";
                    $notes = "استرجاع العملية الجماعية بالكامل: " . ($log['notes'] ?? $action);
                }
                
                writeAuditLog(
                    'audit_restore',
                    'audit_logs',
                    $logId,
                    $action,
                    null,
                    null,
                    $notes
                );

                return ['success' => true, 'message' => $msg];
            } else {
                $conn->rollback();
                return ['success' => false, 'message' => 'لم يتم استرجاع أي طفل. ربما تم استرجاعهم بالفعل أو غير موجودين.'];
            }
        }

        if ($entity === 'student') {

            if ($action === 'note_add') {
                $chk = $conn->prepare("SELECT custom_info FROM students WHERE id = ? AND church_id = ?");
                $chk->bind_param("ii", $entityId, $churchId);
                $chk->execute();
                $student = $chk->get_result()->fetch_assoc();
                if ($student) {
                    $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
                    if (is_array($customInfo) && isset($customInfo['_notes']) && is_array($customInfo['_notes'])) {
                        $foundIdx = -1;
                        foreach ($customInfo['_notes'] as $idx => $note) {
                            if (($note['id'] ?? '') === ($newData['id'] ?? '')) {
                                $foundIdx = $idx;
                                break;
                            }
                        }
                        if ($foundIdx !== -1) {
                            array_splice($customInfo['_notes'], $foundIdx, 1);
                            $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);
                            $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                            $upd->bind_param("sii", $customInfoJson, $entityId, $churchId);
                            if ($upd->execute()) {
                                $reverted = true;
                                $msg = "تم التراجع عن إضافة الملاحظة وحذفها بنجاح";
                            }
                        }
                    }
                }
            } elseif ($action === 'note_delete') {
                $chk = $conn->prepare("SELECT custom_info FROM students WHERE id = ? AND church_id = ?");
                $chk->bind_param("ii", $entityId, $churchId);
                $chk->execute();
                $student = $chk->get_result()->fetch_assoc();
                if ($student) {
                    $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
                    if (!is_array($customInfo)) {
                        $customInfo = [];
                    }
                    if (!isset($customInfo['_notes']) || !is_array($customInfo['_notes'])) {
                        $customInfo['_notes'] = [];
                    }
                    $duplicate = false;
                    foreach ($customInfo['_notes'] as $note) {
                        if (($note['id'] ?? '') === ($oldData['id'] ?? '')) {
                            $duplicate = true;
                            break;
                        }
                    }
                    if (!$duplicate && !empty($oldData)) {
                        $customInfo['_notes'][] = $oldData;
                        $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);
                        $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                        $upd->bind_param("sii", $customInfoJson, $entityId, $churchId);
                        if ($upd->execute()) {
                            $reverted = true;
                            $msg = "تم استرجاع الملاحظة المحذوفة بنجاح";
                        }
                    }
                }
            } elseif ($action === 'student_merge') {
                $targetId = intval($oldData['target_id'] ?? 0);
                $duplicateId = intval($oldData['duplicate_id'] ?? 0);
                $targetSnapshot = $oldData['target_snapshot'] ?? null;
                $duplicateSnapshot = $oldData['duplicate_snapshot'] ?? null;
                
                if (!$targetId || !$duplicateId || !$targetSnapshot || !$duplicateSnapshot) {
                    return ['success' => false, 'message' => 'بيانات الدمج التاريخية غير صالحة للاسترجاع'];
                }
                
                $conn->begin_transaction();
                try {
                    // 1. Delete all records for both IDs in related tables to get a clean slate
                    $deleteTables = [
                        'attendance' => 'student_id',
                        'student_sibling_group_members' => 'student_id',
                        'task_submissions' => 'student_id',
                        'exam_starts' => 'student_id',
                        'coupon_logs' => 'student_id',
                        'coupon_withdrawals' => 'student_id',
                        'trip_waitlist' => 'student_id'
                    ];
                    
                    foreach ($deleteTables as $tbl => $col) {
                        $delStmt = $conn->prepare("DELETE FROM `$tbl` WHERE `$col` = ? OR `$col` = ?");
                        $delStmt->bind_param("ii", $targetId, $duplicateId);
                        $delStmt->execute();
                    }
                    
                    // Clear trip registrations & payments for both kids
                    $getRegs = $conn->prepare("SELECT id FROM trip_registrations WHERE student_id = ? OR student_id = ?");
                    $getRegs->bind_param("ii", $targetId, $duplicateId);
                    $getRegs->execute();
                    $regRes = $getRegs->get_result();
                    $regIds = [];
                    while ($r = $regRes->fetch_assoc()) {
                        $regIds[] = intval($r['id']);
                    }
                    
                    if (!empty($regIds)) {
                        $regIdsStr = implode(',', $regIds);
                        $conn->query("DELETE FROM trip_payments WHERE registration_id IN ($regIdsStr)");
                        $conn->query("DELETE FROM trip_registrations WHERE id IN ($regIdsStr)");
                    }
                    
                    // 2. Revert Profiles (delete first then insert)
                    $conn->query("DELETE FROM students WHERE id = $targetId");
                    $conn->query("DELETE FROM students WHERE id = $duplicateId");
                    
                    // 3. Re-insert both students profiles
                    reinsertRecordInternal('students', $targetSnapshot, $conn);
                    reinsertRecordInternal('students', $duplicateSnapshot, $conn);

                    // Restore image files if present
                    if (!empty($targetSnapshot['image_url'])) {
                        recoverRevertedImageFile($targetSnapshot['image_url']);
                    }
                    if (!empty($duplicateSnapshot['image_url'])) {
                        recoverRevertedImageFile($duplicateSnapshot['image_url']);
                    }
                    
                    // 4. Restore related data for both snapshots
                    $snapshots = [$targetSnapshot, $duplicateSnapshot];
                    foreach ($snapshots as $snap) {
                        $sid = intval($snap['id']);
                        
                        // Attendance
                        if (isset($snap['_attendance_history']) && is_array($snap['_attendance_history'])) {
                            foreach ($snap['_attendance_history'] as $att) {
                                $att['student_id'] = $sid;
                                if (empty($att['church_id'])) {
                                    $att['church_id'] = $churchId;
                                }
                                reinsertRecordInternal('attendance', $att, $conn);
                            }
                        }
                        
                        // Sibling Groups
                        if (isset($snap['_sibling_groups']) && is_array($snap['_sibling_groups'])) {
                            $insSib = $conn->prepare("INSERT INTO student_sibling_group_members (student_id, group_id) VALUES (?, ?)");
                            foreach ($snap['_sibling_groups'] as $groupId) {
                                $insSib->bind_param("ii", $sid, $groupId);
                                $insSib->execute();
                            }
                        }
                        
                        // Task Submissions
                        if (isset($snap['_task_submissions']) && is_array($snap['_task_submissions'])) {
                            foreach ($snap['_task_submissions'] as $task) {
                                reinsertRecordInternal('task_submissions', $task, $conn);
                            }
                        }
                        
                        // Exam Starts
                        if (isset($snap['_exam_starts']) && is_array($snap['_exam_starts'])) {
                            foreach ($snap['_exam_starts'] as $exam) {
                                reinsertRecordInternal('exam_starts', $exam, $conn);
                            }
                        }
                        
                        // Coupon Withdrawals
                        if (isset($snap['_coupon_withdrawals']) && is_array($snap['_coupon_withdrawals'])) {
                            foreach ($snap['_coupon_withdrawals'] as $w) {
                                reinsertRecordInternal('coupon_withdrawals', $w, $conn);
                            }
                        }
                        
                        // Coupon Logs
                        if (isset($snap['_coupon_logs']) && is_array($snap['_coupon_logs'])) {
                            foreach ($snap['_coupon_logs'] as $clog) {
                                reinsertRecordInternal('coupon_logs', $clog, $conn);
                            }
                        }
                        
                        // Trip waitlist
                        if (isset($snap['_trip_waitlist']) && is_array($snap['_trip_waitlist'])) {
                            foreach ($snap['_trip_waitlist'] as $wait) {
                                reinsertRecordInternal('trip_waitlist', $wait, $conn);
                            }
                        }
                        
                        // Trip registrations & payments
                        if (isset($snap['_trip_registrations']) && is_array($snap['_trip_registrations'])) {
                            foreach ($snap['_trip_registrations'] as $reg) {
                                $payments = $reg['_payments'] ?? [];
                                unset($reg['_payments']);
                                
                                reinsertRecordInternal('trip_registrations', $reg, $conn);
                                
                                foreach ($payments as $pay) {
                                    reinsertRecordInternal('trip_payments', $pay, $conn);
                                }
                            }
                        }
                    }
                    
                    $conn->commit();
                    $reverted = true;
                    $msg = "تم التراجع عن عملية الدمج بنجاح واستعادة كلا الطفلين لسيرتهما الأولى";
                    
                } catch (Exception $txEx) {
                    $conn->rollback();
                    throw $txEx;
                }
            } elseif ($action === 'student_edit') {

                if (empty($oldData)) {

                    return ['success' => false, 'message' => 'لا توجد بيانات سابقة لاسترجاعها'];

                }

                // Check if student still exists

                $chk = $conn->prepare("SELECT id FROM students WHERE id = ?");

                $chk->bind_param("i", $entityId);

                $chk->execute();

                if ($chk->get_result()->num_rows === 0) {

                    return ['success' => false, 'message' => 'لا يمكن الاسترجاع: الطفل غير موجود حالياً'];

                }

                // If image_url is being reverted
                if (isset($oldData['image_url']) || isset($newData['image_url'])) {
                    $oldImg = $oldData['image_url'] ?? '';
                    $newImg = $newData['image_url'] ?? '';
                    if ($oldImg !== $newImg) {
                        restoreRevertedImageFile($oldImg, $newImg);
                    }
                }



                // Update using whitelisted columns
                $whitelist = ['name', 'gender', 'class_id', 'class', 'address', 'phone', 'emergency_phone', 'parent_phones', 'medical_notes', 'birthday', 'coupons', 'attendance_coupons', 'commitment_coupons', 'task_coupons', 'image_url', 'custom_info', 'email'];
                $updates = [];
                $types = '';
                $params = [];
                foreach ($oldData as $key => $val) {
                    if (in_array($key, $whitelist, true)) {
                        $updates[] = "`$key` = ?";
                        $params[] = $val;
                        if (is_int($val)) $types .= 'i';
                        elseif (is_float($val)) $types .= 'd';
                        else $types .= 's';
                    }
                }

                if (!empty($updates)) {
                    $sql = "UPDATE students SET " . implode(', ', $updates) . ", updated_at = NOW() WHERE id = ?";
                    $types .= 'i';
                    $params[] = $entityId;
                    $upd = $conn->prepare($sql);
                    $upd->bind_param($types, ...$params);
                    if ($upd->execute()) {
                        $reverted = true;
                        $msg = "تم استرجاع بيانات الطفل بنجاح";
                    }
                } else {
                    return ['success' => false, 'message' => 'لم يتم العثور على حقول قابلة للتحديث'];
                }
            } elseif ($action === 'student_delete') {
                if (empty($oldData)) {
                    return ['success' => false, 'message' => 'لا توجد بيانات سابقة لإعادة الإدخال'];
                }
                // Check if student ID already exists
                $chk = $conn->prepare("SELECT id FROM students WHERE id = ?");
                $chk->bind_param("i", $entityId);
                $chk->execute();
                if ($chk->get_result()->num_rows > 0) {
                    return ['success' => false, 'message' => 'الطفل موجود بالفعل في قاعدة البيانات ولا حاجة لاسترجاعه'];
                }

                // Re-insert using whitelisted columns + id + church_id
                $whitelist = ['id', 'church_id', 'name', 'gender', 'class_id', 'class', 'address', 'phone', 'emergency_phone', 'parent_phones', 'medical_notes', 'birthday', 'coupons', 'attendance_coupons', 'commitment_coupons', 'task_coupons', 'image_url', 'custom_info', 'email', 'added_by'];

                $fields = [];

                $placeholders = [];

                $types = '';

                $params = [];

                foreach ($oldData as $key => $val) {

                    if (in_array($key, $whitelist, true)) {

                        $fields[] = "`$key`";

                        $placeholders[] = "?";

                        $params[] = $val;

                        if (is_int($val)) $types .= 'i';

                        elseif (is_float($val)) $types .= 'd';

                        else $types .= 's';

                    }

                }



                if (!empty($fields)) {

                    $sql = "INSERT INTO students (" . implode(', ', $fields) . ", created_at) VALUES (" . implode(', ', $placeholders) . ", NOW())";

                    $ins = $conn->prepare($sql);

                    $ins->bind_param($types, ...$params);

                    if ($ins->execute()) {
                        $reverted = true;
                        $msg = "تم إعادة تسجيل الطفل المحذوف بنجاح";
                        if (!empty($oldData['image_url'])) {
                            recoverRevertedImageFile($oldData['image_url']);
                        }

                        // Restore related attendance from snapshot if present
                        if (isset($oldData['_attendance_history']) && is_array($oldData['_attendance_history'])) {
                            $insAtt = $conn->prepare("
                                INSERT INTO attendance (student_id, church_id, attendance_date, status, uncle_id, created_at)
                                VALUES (?, ?, ?, ?, ?, NOW())
                                ON DUPLICATE KEY UPDATE status = VALUES(status), uncle_id = VALUES(uncle_id)
                            ");
                            foreach ($oldData['_attendance_history'] as $att) {
                                $uId = $att['uncle_id'] ?? null;
                                $insAtt->bind_param("iissi", $entityId, $churchId, $att['attendance_date'], $att['status'], $uId);
                                $insAtt->execute();
                            }
                        } else {
                            // Fallback: Reconstruct attendance from audit logs
                            recoverStudentAttendanceFromAuditLogs($entityId, $churchId, $conn);
                        }

                        // Restore sibling groups if present
                        if (isset($oldData['_sibling_groups']) && is_array($oldData['_sibling_groups'])) {
                            $insSib = $conn->prepare("INSERT INTO student_sibling_group_members (student_id, group_id) VALUES (?, ?)");
                            foreach ($oldData['_sibling_groups'] as $groupId) {
                                $insSib->bind_param("ii", $entityId, $groupId);
                                $insSib->execute();
                            }
                        }
                    }

                } else {

                    return ['success' => false, 'message' => 'لم يتم العثور على بيانات صالحة لإعادة الإدخال'];

                }

            } elseif ($action === 'student_add') {

                // Undoing a student add is deleting the student, but only if they have no other registrations/attendance to avoid issues

                $chkAtt = $conn->prepare("SELECT id FROM attendance WHERE student_id = ?");

                $chkAtt->bind_param("i", $entityId);

                $chkAtt->execute();

                if ($chkAtt->get_result()->num_rows > 0) {

                    return ['success' => false, 'message' => 'لا يمكن التراجع عن إضافة الطفل لوجود سجلات حضور مسجلة له'];

                }



                $chkReg = $conn->prepare("SELECT id FROM trip_registrations WHERE student_id = ?");

                $chkReg->bind_param("i", $entityId);

                $chkReg->execute();

                if ($chkReg->get_result()->num_rows > 0) {

                    return ['success' => false, 'message' => 'لا يمكن التراجع عن إضافة الطفل لوجود تسجيلات رحلات مسجلة له'];

                }



                $del = $conn->prepare("DELETE FROM students WHERE id = ? AND church_id = ?");

                $del->bind_param("ii", $entityId, $churchId);

                if ($del->execute() && $del->affected_rows > 0) {

                    $reverted = true;

                    $msg = "تم التراجع عن إضافة الطفل وحذفه بنجاح";

                } else {

                    return ['success' => false, 'message' => 'لم يتم العثور على الطفل لحذفه'];

                }

            }

        } elseif ($entity === 'coupon') {

            if ($action === 'coupon_edit') {

                // coupons: oldTotal -> newTotal

                // We should read the student's current coupon count

                $chk = $conn->prepare("SELECT coupons, commitment_coupons FROM students WHERE id = ?");

                $chk->bind_param("i", $entityId);

                $chk->execute();

                $stu = $chk->get_result()->fetch_assoc();

                if (!$stu) {

                    return ['success' => false, 'message' => 'الطفل غير موجود'];

                }



                $oldTotal = intval($oldData['coupons'] ?? 0);

                $newTotal = intval($newData['coupons'] ?? 0);

                $diff = $oldTotal - $newTotal; // Reversing difference



                $newCommitment = intval($stu['commitment_coupons']) + $diff;



                $upd = $conn->prepare("UPDATE students SET coupons = ?, commitment_coupons = ?, updated_at = NOW() WHERE id = ?");

                $upd->bind_param("iii", $oldTotal, $newCommitment, $entityId);

                if ($upd->execute()) {

                    // Insert a reverse coupon log

                    $uncleId = $_SESSION['uncle_id'] ?? null;

                    $logStmt = $conn->prepare("

                        INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type)

                        VALUES (?, ?, ?, ?, ?, 'manual')

                    ");

                    $logStmt->bind_param("iiiii", $entityId, $uncleId, $newTotal, $oldTotal, $diff);

                    $logStmt->execute();



                    $reverted = true;

                    $msg = "تم استرجاع رصيد الكوبونات بنجاح";

                }

            } elseif ($action === 'coupon_withdraw') {
                $stmt = $conn->prepare("SELECT id FROM coupon_withdrawals WHERE student_id = ? AND is_refunded = 0 ORDER BY created_at DESC, id DESC LIMIT 1");
                $stmt->bind_param("i", $entityId);
                $stmt->execute();
                $resW = $stmt->get_result()->fetch_assoc();
                if (!$resW) {
                    return ['success' => false, 'message' => 'لم يتم العثور على عملية سحب نشطة قابلة للتراجع لهذا الطفل'];
                }
                $withdrawalId = intval($resW['id']);
                
                $stmt = $conn->prepare("SELECT * FROM coupon_withdrawals WHERE id = ? FOR UPDATE");
                $stmt->bind_param("i", $withdrawalId);
                $stmt->execute();
                $w = $stmt->get_result()->fetch_assoc();
                if (!$w) {
                    throw new Exception('عملية السحب غير موجودة');
                }
                if ($w['is_refunded']) {
                    throw new Exception('تم استرجاع هذه العملية بالفعل');
                }

                $amount = intval($w['amount']);
                $att = intval($w['att_amount'] ?? 0);
                $com = intval($w['com_amount'] ?? 0);
                $tsk = intval($w['tsk_amount'] ?? 0);

                // Update student
                $upd = $conn->prepare("UPDATE students SET coupons = coupons + ?, attendance_coupons = attendance_coupons + ?, commitment_coupons = commitment_coupons + ?, task_coupons = task_coupons + ? WHERE id = ?");
                $upd->bind_param("iiiii", $amount, $att, $com, $tsk, $entityId);
                if (!$upd->execute()) {
                    throw new Exception('فشل استعادة الكوبونات للطفل');
                }

                // Mark as refunded
                $mark = $conn->prepare("UPDATE coupon_withdrawals SET is_refunded = 1, refunded_at = NOW() WHERE id = ?");
                $mark->bind_param("i", $withdrawalId);
                if (!$mark->execute()) {
                    throw new Exception('فشل تحديث حالة السحب');
                }

                // Retrieve student name for log if not loaded
                $studentName = '';
                $stuStmt = $conn->prepare("SELECT name FROM students WHERE id = ?");
                $stuStmt->bind_param("i", $entityId);
                $stuStmt->execute();
                $stuRes = $stuStmt->get_result()->fetch_assoc();
                if ($stuRes) {
                    $studentName = $stuRes['name'];
                }

                // Write audit log
                writeAuditLog('coupon_refund', 'coupon', $entityId, $studentName, null, ['amount' => $amount], "تراجع عن السحب: استرجاع $amount كوبون (عملية #$withdrawalId)");
                $reverted = true;
                $msg = "تم التراجع عن عملية السحب بنجاح وإعادة الكوبونات للطفل";
            }

        } elseif ($entity === 'attendance') {

            // Restore attendance

            if ($action === 'attendance_add' || $action === 'attendance_edit') {

                $attDate = $oldData['date'] ?? $newData['date'] ?? null;

                $oldStatus = $oldData['status'] ?? 'pending';



                if (!$attDate) {

                    return ['success' => false, 'message' => 'تاريخ الغياب غير محدد في السجل'];

                }



                if ($oldStatus === 'pending') {

                    // If it was pending (or cleared), we delete the record

                    $del = $conn->prepare("DELETE FROM attendance WHERE student_id = ? AND attendance_date = ?");

                    $del->bind_param("is", $entityId, $attDate);

                    $del->execute();

                    $reverted = true;

                    $msg = "تم إلغاء سجل الحضور بنجاح";

                } else {

                    // Upsert status

                    $chk = $conn->prepare("SELECT id FROM attendance WHERE student_id = ? AND attendance_date = ?");

                    $chk->bind_param("is", $entityId, $attDate);

                    $chk->execute();

                    $res = $chk->get_result();



                    if ($res->num_rows > 0) {

                        $attId = $res->fetch_assoc()['id'];

                        $upd = $conn->prepare("UPDATE attendance SET status = ?, updated_at = NOW() WHERE id = ?");

                        $upd->bind_param("si", $oldStatus, $attId);

                        $upd->execute();

                    } else {

                        $ins = $conn->prepare("INSERT INTO attendance (student_id, church_id, attendance_date, status, uncle_id, created_at) VALUES (?, ?, ?, ?, ?, NOW())");

                        $uncleId = $_SESSION['uncle_id'] ?? null;

                        $ins->bind_param("iissi", $entityId, $churchId, $attDate, $oldStatus, $uncleId);

                        $ins->execute();

                    }

                    $reverted = true;

                    $msg = "تم استرجاع حالة الحضور بنجاح";

                }

            } elseif ($action === 'attendance_delete') {

                // Re-insert row from oldData

                $attDate = $oldData['attendance_date'] ?? null;

                $status = $oldData['status'] ?? 'present';

                if (!$attDate) {

                    return ['success' => false, 'message' => 'بيانات الحضور غير كاملة'];

                }



                $ins = $conn->prepare("INSERT INTO attendance (student_id, church_id, attendance_date, status, uncle_id, created_at) VALUES (?, ?, ?, ?, ?, NOW())");

                $uncleId = $_SESSION['uncle_id'] ?? null;

                $ins->bind_param("iissi", $entityId, $churchId, $attDate, $status, $uncleId);

                if ($ins->execute()) {

                    $reverted = true;

                    $msg = "تم استرجاع سجل الحضور المحذوف بنجاح";

                }

            }

        } elseif ($entity === 'uncle') {
            if ($action === 'uncle_delete') {
                $stmt = $conn->prepare("UPDATE uncles SET deleted = 0 WHERE id = ? AND church_id = ?");
                $stmt->bind_param("ii", $entityId, $churchId);
                if ($stmt->execute() && $stmt->affected_rows > 0) {
                    $reverted = true;
                    $msg = "تم استرجاع الخادم المحذوف بنجاح";
                    if (!empty($oldData['image_url'])) {
                        recoverRevertedImageFile($oldData['image_url']);
                    }
                }
            } elseif ($action === 'uncle_add') {
                $stmt = $conn->prepare("SELECT image_url FROM uncles WHERE id = ? AND church_id = ?");
                $stmt->bind_param("ii", $entityId, $churchId);
                $stmt->execute();
                $uncleRow = $stmt->get_result()->fetch_assoc();
                $imgUrl = $uncleRow['image_url'] ?? '';

                $del = $conn->prepare("DELETE FROM uncles WHERE id = ? AND church_id = ?");
                $del->bind_param("ii", $entityId, $churchId);
                if ($del->execute() && $del->affected_rows > 0) {
                    $reverted = true;
                    $msg = "تم التراجع عن إضافة الخادم وحذفه بنجاح";
                    if (!empty($imgUrl)) {
                        $path = $imgUrl;
                        if (strpos($path, 'https://') === 0 || strpos($path, 'http://') === 0) {
                            $parsed = parse_url($path);
                            $path = $parsed['path'] ?? '';
                        }
                        $realFile = __DIR__ . $path;
                        if (is_file($realFile)) {
                            @unlink($realFile);
                        }
                    }
                }
            } elseif ($action === 'uncle_edit') {
                if (empty($oldData)) {
                    return ['success' => false, 'message' => 'لا توجد بيانات سابقة لاسترجاعها'];
                }

                if (isset($oldData['image_url']) || isset($newData['image_url'])) {
                    $oldImg = $oldData['image_url'] ?? '';
                    $newImg = $newData['image_url'] ?? '';
                    if ($oldImg !== $newImg) {
                        restoreRevertedImageFile($oldImg, $newImg);
                    }
                }

                $whitelist = ['name', 'email', 'role', 'image_url', 'deleted'];
                $updates = [];
                $types = '';
                $params = [];
                foreach ($oldData as $key => $val) {
                    if (in_array($key, $whitelist, true)) {
                        $updates[] = "`$key` = ?";
                        $params[] = $val;
                        if (is_int($val)) $types .= 'i';
                        elseif (is_float($val)) $types .= 'd';
                        else $types .= 's';
                    }
                }

                if (!empty($updates)) {
                    $sql = "UPDATE uncles SET " . implode(', ', $updates) . " WHERE id = ? AND church_id = ?";
                    $types .= 'ii';
                    $params[] = $entityId;
                    $params[] = $churchId;
                    $upd = $conn->prepare($sql);
                    $upd->bind_param($types, ...$params);
                    if ($upd->execute()) {
                        $reverted = true;
                        $msg = "تم استرجاع بيانات الخادم بنجاح";
                    }
                } else {
                    return ['success' => false, 'message' => 'لم يتم العثور على حقول قابلة للتحديث'];
                }
            }
        }



        if ($reverted) {

            // Write audit log for the restore action

            writeAuditLog(

                'audit_restore',

                'audit_logs',

                $logId,

                $action,

                null,

                null,

                "استرجاع العملية: " . ($log['notes'] ?? $action)

            );

            return ['success' => true, 'message' => $msg];

        } else {

            return ['success' => false, 'message' => 'نوع العملية غير مدعوم حالياً للاسترجاع التلقائي'];

        }



    } catch (Exception $e) {

        return ['success' => false, 'message' => 'خطأ أثناء الاسترجاع: ' . $e->getMessage()];

    }


}


function restoreAuditLog()
{
    try {
        $churchId = getChurchId();
        $logId = intval($_POST['log_id'] ?? 0);
        if (!$logId) {
            sendJSON(['success' => false, 'message' => 'معرف السجل مطلوب']);
            return;
        }

        $conn = getDBConnection();
        $res = restoreSingleAuditLogInternal($logId, $churchId, $conn, intval($_POST['target_student_id'] ?? 0));
        sendJSON($res);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ أثناء الاسترجاع: ' . $e->getMessage()]);
    }
}


function bulkRestoreAuditLogs()
{
    try {
        $churchId = getChurchId();
        $logIdsStr = sanitize($_POST['log_ids'] ?? '');
        if (empty($logIdsStr)) {
            sendJSON(['success' => false, 'message' => 'لم يتم تحديد أي سجلات لاسترجاعها']);
            return;
        }

        $logIds = array_map('intval', explode(',', $logIdsStr));
        $logIds = array_filter($logIds);
        if (empty($logIds)) {
            sendJSON(['success' => false, 'message' => 'سجلات غير صالحة']);
            return;
        }

        $conn = getDBConnection();
        // Sort descending to restore in reverse chronological order
        rsort($logIds);

        $successCount = 0;
        $failedLogs = [];

        foreach ($logIds as $logId) {
            $res = restoreSingleAuditLogInternal($logId, $churchId, $conn);
            if ($res['success']) {
                $successCount++;
            } else {
                $failedLogs[] = "السجل #$logId: " . $res['message'];
            }
        }

        if ($successCount > 0) {
            $msg = "تم استرجاع $successCount من العمليات بنجاح";
            if (!empty($failedLogs)) {
                $msg .= ". وفشل: " . implode(', ', $failedLogs);
            }
            sendJSON(['success' => true, 'message' => $msg]);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل استرجاع العمليات: ' . implode(', ', $failedLogs)]);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}


function bulkDeleteAuditLogs()
{
    try {
        $churchId = getChurchId();
        $logIdsStr = sanitize($_POST['log_ids'] ?? '');
        if (empty($logIdsStr)) {
            sendJSON(['success' => false, 'message' => 'لم يتم تحديد أي سجلات لحذفها']);
            return;
        }

        $logIds = array_map('intval', explode(',', $logIdsStr));
        $logIds = array_filter($logIds);
        if (empty($logIds)) {
            sendJSON(['success' => false, 'message' => 'سجلات غير صالحة']);
            return;
        }

        $conn = getDBConnection();
        $placeholders = implode(',', array_fill(0, count($logIds), '?'));
        $types = str_repeat('i', count($logIds)) . 'i';
        $bindValues = array_merge($logIds, [$churchId]);

        $stmt = $conn->prepare("DELETE FROM audit_logs WHERE id IN ($placeholders) AND church_id = ?");
        $stmt->bind_param($types, ...$bindValues);
        if ($stmt->execute()) {
            $deletedCount = $stmt->affected_rows;
            sendJSON(['success' => true, 'message' => "تم حذف $deletedCount من السجلات بنجاح"]);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في حذف السجلات']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}




function getLastAuditLog()

{

    try {

        $churchId = getChurchId();

        $uncleId = $_SESSION['uncle_id'] ?? null;

        if (!$uncleId) {

            sendJSON(['success' => false, 'message' => 'غير مصرح']);

            return;

        }

        $conn = getDBConnection();

        // Get the latest log entry created by this uncle in the last 10 seconds

        // Restorable actions: student_add, student_edit, student_delete, coupon_edit, attendance_add, attendance_edit, attendance_delete

        $stmt = $conn->prepare("

            SELECT id, action, entity, entity_name, notes 

            FROM audit_logs 

            WHERE church_id = ? 

              AND uncle_id = ? 

              AND action IN ('student_add', 'student_edit', 'student_delete', 'coupon_edit', 'attendance_add', 'attendance_edit', 'attendance_delete', 'bulk_student_delete', 'bulk_student_class_update', 'bulk_student_coupon_update', 'bulk_attendance_save', 'student_merge')

              AND created_at >= NOW() - INTERVAL 10 SECOND

            ORDER BY id DESC LIMIT 1

        ");

        $stmt->bind_param("ii", $churchId, $uncleId);

        $stmt->execute();

        $res = $stmt->get_result();

        if ($res->num_rows > 0) {

            $log = $res->fetch_assoc();

            sendJSON(['success' => true, 'log' => $log]);

        } else {

            sendJSON(['success' => false, 'message' => 'لا توجد عمليات مؤخرة']);

        }

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function bulkDeleteStudents()

{

    try {

        $churchId = getChurchId();

        $studentIdsRaw = $_POST['student_ids'] ?? '';

        if (empty($studentIdsRaw)) {

            sendJSON(['success' => false, 'message' => 'لم يتم تحديد أطفال']);

            return;

        }



        $studentIds = array_filter(array_map('intval', explode(',', $studentIdsRaw)));

        if (empty($studentIds)) {

            sendJSON(['success' => false, 'message' => 'معرفات الأطفال غير صالحة']);

            return;

        }



        $conn = getDBConnection();

        $conn->begin_transaction();



        $successCount = 0;

        foreach ($studentIds as $studentId) {

            // Check existence and ownership

            $getStmt = $conn->prepare("SELECT name, image_url FROM students WHERE id = ? AND church_id = ?");

            $getStmt->bind_param("ii", $studentId, $churchId);

            $getStmt->execute();

            $student = $getStmt->get_result()->fetch_assoc();



            if ($student) {

                $studentName = $student['name'];

                $studentImageUrl = $student['image_url'];



                // Get snapshot before deleting

                $studentSnapshot = getStudentSnapshot($studentId);



                // Purge relationships

                purgeStudentRelatedRows($conn, $studentId);



                // Delete student

                $del = $conn->prepare("DELETE FROM students WHERE id = ? AND church_id = ?");

                $del->bind_param("ii", $studentId, $churchId);

                if ($del->execute() && $del->affected_rows > 0) {

                    // Clean image file

                    if ($studentImageUrl) {

                        deleteUploadedFile($studentImageUrl);

                    }



                    // Audit deletion

                    auditStudentDelete($studentId, $studentSnapshot ?? ['id' => $studentId, 'name' => $studentName]);

                    $successCount++;

                }

            }

        }



        $conn->commit();

        sendJSON(['success' => true, 'message' => "تم حذف $successCount من الأطفال بنجاح"]);

    } catch (Exception $e) {

        if (isset($conn)) $conn->rollback();

        sendJSON(['success' => false, 'message' => 'خطأ أثناء الحذف الجماعي: ' . $e->getMessage()]);

    }

}



function bulkUpdateStudentsClass()

{

    try {

        $churchId = getChurchId();

        $studentIdsRaw = $_POST['student_ids'] ?? '';

        $classId = intval($_POST['class_id'] ?? 0);



        if (empty($studentIdsRaw) || !$classId) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $studentIds = array_filter(array_map('intval', explode(',', $studentIdsRaw)));

        if (empty($studentIds)) {

            sendJSON(['success' => false, 'message' => 'معرفات الأطفال غير صالحة']);

            return;

        }



        $conn = getDBConnection();



        // Resolve class name

        // Check custom church classes first

        $classRow = null;

        $cChk = $conn->prepare("SELECT id, arabic_name FROM church_classes WHERE id = ? AND church_id = ? AND is_active = 1 LIMIT 1");

        $cChk->bind_param("ii", $classId, $churchId);

        $cChk->execute();

        $classRow = $cChk->get_result()->fetch_assoc();



        if (!$classRow) {

            // Check global classes

            $gChk = $conn->prepare("SELECT id, arabic_name FROM classes WHERE id = ? LIMIT 1");

            $gChk->bind_param("i", $classId);

            $gChk->execute();

            $classRow = $gChk->get_result()->fetch_assoc();

        }



        if (!$classRow) {

            sendJSON(['success' => false, 'message' => 'الفصل المحدد غير موجود']);

            return;

        }



        $className = $classRow['arabic_name'];



        $conn->begin_transaction();

        $successCount = 0;



        foreach ($studentIds as $studentId) {

            // Verify student in church

            $chk = $conn->prepare("SELECT id FROM students WHERE id = ? AND church_id = ?");

            $chk->bind_param("ii", $studentId, $churchId);

            $chk->execute();

            if ($chk->get_result()->num_rows > 0) {

                // Get before snapshot

                $beforeSnapshot = getStudentSnapshot($studentId);



                // Update student class

                $upd = $conn->prepare("UPDATE students SET class_id = ?, class = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");

                $upd->bind_param("isii", $classId, $className, $studentId, $churchId);

                if ($upd->execute()) {

                    // Get after snapshot

                    $afterSnapshot = getStudentSnapshot($studentId);



                    // Audit

                    auditStudentEdit($studentId, $beforeSnapshot ?? [], $afterSnapshot ?? []);

                    $successCount++;

                }

            }

        }



        $conn->commit();

        sendJSON(['success' => true, 'message' => "تم نقل $successCount من الأطفال إلى فصل \"$className\" بنجاح"]);

    } catch (Exception $e) {

        if (isset($conn)) $conn->rollback();

        sendJSON(['success' => false, 'message' => 'خطأ أثناء نقل الأطفال: ' . $e->getMessage()]);

    }

}



function bulkUpdateStudentsCoupons()

{

    try {

        $churchId = getChurchId();

        $studentIdsRaw = $_POST['student_ids'] ?? '';

        $changeAmount = intval($_POST['change_amount'] ?? 0);

        $reason = trim($_POST['reason'] ?? 'تعديل جماعي');

        $uncleId = $_SESSION['uncle_id'] ?? null;



        if (empty($studentIdsRaw) || !$changeAmount) {

            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);

            return;

        }



        $studentIds = array_filter(array_map('intval', explode(',', $studentIdsRaw)));

        if (empty($studentIds)) {

            sendJSON(['success' => false, 'message' => 'معرفات الأطفال غير صالحة']);

            return;

        }



        $conn = getDBConnection();

        $conn->begin_transaction();



        $successCount = 0;

        foreach ($studentIds as $studentId) {

            // Verify and load current coupons

            $chk = $conn->prepare("SELECT name, coupons, attendance_coupons, commitment_coupons, task_coupons FROM students WHERE id = ? AND church_id = ?");

            $chk->bind_param("ii", $studentId, $churchId);

            $chk->execute();

            $student = $chk->get_result()->fetch_assoc();



            if ($student) {

                $oldCount = intval($student['coupons']);

                $currentAttendance = intval($student['attendance_coupons']);

                $currentTask = intval($student['task_coupons'] ?? 0);

                

                $newCount = max(0, $oldCount + $changeAmount);

                $newCommitment = $newCount - $currentAttendance - $currentTask;

                if ($newCommitment < 0) {

                    $newCommitment = 0;

                }



                $upd = $conn->prepare("UPDATE students SET coupons = ?, commitment_coupons = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");

                $upd->bind_param("iiii", $newCount, $newCommitment, $studentId, $churchId);

                if ($upd->execute()) {

                    // Log coupon history

                    $logStmt = $conn->prepare("

                        INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type)

                        VALUES (?, ?, ?, ?, ?, 'manual')

                    ");

                    $actualChange = $newCount - $oldCount;

                    $logStmt->bind_param("iiiii", $studentId, $uncleId, $oldCount, $newCount, $actualChange);

                    $logStmt->execute();



                    // Collect for consolidated bulk audit log
                    $bulkCouponLogs[] = [
                        'id' => $studentId,
                        'name' => $student['name'],
                        'old_data' => ['coupons' => $oldCount],
                        'new_data' => ['coupons' => $newCount]
                    ];

                    $successCount++;

                }

            }

        }

        if (!empty($bulkCouponLogs)) {
            writeAuditLog(
                'bulk_student_coupon_update',
                'bulk_action',
                null,
                "تعديل كوبونات لعدد " . count($bulkCouponLogs) . " طفل",
                $bulkCouponLogs,
                $bulkCouponLogs,
                "تعديل كوبونات جماعي لعدد " . count($bulkCouponLogs) . " طفل ($reason)"
            );
        }

        $conn->commit();

        sendJSON(['success' => true, 'message' => "تم تعديل الكوبونات لـ $successCount من الأطفال بنجاح"]);

    } catch (Exception $e) {

        if (isset($conn)) $conn->rollback();

        sendJSON(['success' => false, 'message' => 'خطأ أثناء تعديل الكوبونات: ' . $e->getMessage()]);

    }

}


function addStudentNote()
{
    try {
        $churchId = getChurchId();
        $studentId = intval($_POST['studentId'] ?? 0);
        $title = trim($_POST['title'] ?? '');
        $description = trim($_POST['description'] ?? '');
        $date = trim($_POST['date'] ?? '');

        if (!$studentId || empty($title) || empty($description)) {
            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);
            return;
        }

        if (empty($date)) {
            $date = date('Y-m-d');
        }

        $conn = getDBConnection();
        $stmt = $conn->prepare("SELECT name, custom_info FROM students WHERE id = ? AND church_id = ?");
        $stmt->bind_param("ii", $studentId, $churchId);
        $stmt->execute();
        $student = $stmt->get_result()->fetch_assoc();

        if (!$student) {
            sendJSON(['success' => false, 'message' => 'الطفل غير موجود']);
            return;
        }

        $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
        if (!is_array($customInfo)) {
            $customInfo = [];
        }

        if (!isset($customInfo['_notes']) || !is_array($customInfo['_notes'])) {
            $customInfo['_notes'] = [];
        }

        $noteId = uniqid('note_', true);
        $newNote = [
            'id' => $noteId,
            'title' => sanitize($title),
            'description' => sanitize($description),
            'date' => sanitize($date),
            'created_by' => $_SESSION['uncle_name'] ?? 'خادم',
            'created_at' => date('Y-m-d H:i:s')
        ];

        $customInfo['_notes'][] = $newNote;
        $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);

        $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
        $upd->bind_param("sii", $customInfoJson, $studentId, $churchId);

        if ($upd->execute()) {
            writeAuditLog('note_add', 'student', $studentId, $student['name'], null, $newNote, "إضافة ملاحظة: " . $title);
            sendJSON(['success' => true, 'message' => 'تم إضافة الملاحظة بنجاح']);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في حفظ الملاحظة']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}

function deleteStudentNote()
{
    try {
        $churchId = getChurchId();
        $studentId = intval($_POST['studentId'] ?? 0);
        $noteId = trim($_POST['noteId'] ?? '');

        if (!$studentId || empty($noteId)) {
            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);
            return;
        }

        $conn = getDBConnection();
        $stmt = $conn->prepare("SELECT name, custom_info FROM students WHERE id = ? AND church_id = ?");
        $stmt->bind_param("ii", $studentId, $churchId);
        $stmt->execute();
        $student = $stmt->get_result()->fetch_assoc();

        if (!$student) {
            sendJSON(['success' => false, 'message' => 'الطفل غير موجود']);
            return;
        }

        $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
        if (!is_array($customInfo) || !isset($customInfo['_notes']) || !is_array($customInfo['_notes'])) {
            sendJSON(['success' => false, 'message' => 'لا توجد ملاحظات لحذفها']);
            return;
        }

        $foundIdx = -1;
        foreach ($customInfo['_notes'] as $idx => $note) {
            if (($note['id'] ?? '') === $noteId) {
                $foundIdx = $idx;
                break;
            }
        }

        if ($foundIdx === -1) {
            sendJSON(['success' => false, 'message' => 'الملاحظة غير موجودة']);
            return;
        }

        $oldNote = $customInfo['_notes'][$foundIdx];
        array_splice($customInfo['_notes'], $foundIdx, 1);
        $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);

        $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
        $upd->bind_param("sii", $customInfoJson, $studentId, $churchId);

        if ($upd->execute()) {
            writeAuditLog('note_delete', 'student', $studentId, $student['name'], $oldNote, null, "حذف ملاحظة: " . ($oldNote['title'] ?? ''));
            sendJSON(['success' => true, 'message' => 'تم حذف الملاحظة بنجاح']);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في حذف الملاحظة']);
        }
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}

function bulkAddStudentNotes()
{
    try {
        $churchId = getChurchId();
        $studentIdsRaw = $_POST['student_ids'] ?? '';
        $title = trim($_POST['title'] ?? '');
        $description = trim($_POST['description'] ?? '');
        $date = trim($_POST['date'] ?? '');

        if (empty($studentIdsRaw) || empty($title) || empty($description)) {
            sendJSON(['success' => false, 'message' => 'بيانات غير كاملة']);
            return;
        }

        if (empty($date)) {
            $date = date('Y-m-d');
        }

        $studentIds = array_filter(array_map('intval', explode(',', $studentIdsRaw)));
        if (empty($studentIds)) {
            sendJSON(['success' => false, 'message' => 'معرفات الأطفال غير صالحة']);
            return;
        }

        $conn = getDBConnection();
        $conn->begin_transaction();

        $successCount = 0;
        $auditData = [];

        foreach ($studentIds as $studentId) {
            $stmt = $conn->prepare("SELECT name, custom_info FROM students WHERE id = ? AND church_id = ?");
            $stmt->bind_param("ii", $studentId, $churchId);
            $stmt->execute();
            $student = $stmt->get_result()->fetch_assoc();

            if ($student) {
                $customInfo = !empty($student['custom_info']) ? json_decode($student['custom_info'], true) : [];
                if (!is_array($customInfo)) {
                    $customInfo = [];
                }

                if (!isset($customInfo['_notes']) || !is_array($customInfo['_notes'])) {
                    $customInfo['_notes'] = [];
                }

                $noteId = uniqid('note_', true);
                $newNote = [
                    'id' => $noteId,
                    'title' => sanitize($title),
                    'description' => sanitize($description),
                    'date' => sanitize($date),
                    'created_by' => $_SESSION['uncle_name'] ?? 'خادم',
                    'created_at' => date('Y-m-d H:i:s')
                ];

                $customInfo['_notes'][] = $newNote;
                $customInfoJson = json_encode($customInfo, JSON_UNESCAPED_UNICODE);

                $upd = $conn->prepare("UPDATE students SET custom_info = ?, updated_at = NOW() WHERE id = ? AND church_id = ?");
                $upd->bind_param("sii", $customInfoJson, $studentId, $churchId);

                if ($upd->execute()) {
                    $auditData[] = [
                        'id' => $studentId,
                        'name' => $student['name'],
                        'note' => $newNote
                    ];
                    $successCount++;
                }
            }
        }

        if ($successCount > 0) {
            $conn->commit();
            writeAuditLog('bulk_note_add', 'bulk_action', null, null, null, $auditData, "إضافة ملاحظة جماعية: " . $title);
            sendJSON(['success' => true, 'message' => "تم إضافة الملاحظة لـ $successCount من الأطفال بنجاح"]);
        } else {
            $conn->rollback();
            sendJSON(['success' => false, 'message' => 'فشل إضافة الملاحظة الجماعية']);
        }
    } catch (Exception $e) {
        if (isset($conn)) $conn->rollback();
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}



// ── Helper to append audit_type filtering SQL ────────────────
function appendAuditTypeClause($auditType, &$conditions, &$params, &$types)
{
    $auditType = trim(strtolower($auditType));
    if (empty($auditType) || $auditType === 'all') {
        return;
    }
    if ($auditType === 'logins' || $auditType === 'login' || $auditType === 'auth') {
        $conditions[] = "((entity IN ('auth', 'church', 'uncle') AND action LIKE 'login%') OR action IN ('login', 'login_church', 'login_uncle', 'logout'))";
    } elseif ($auditType === 'attendance') {
        $conditions[] = "(entity = 'attendance' OR action LIKE 'attendance%')";
    } elseif ($auditType === 'coupon') {
        $conditions[] = "(entity = 'coupon' OR action LIKE 'coupon%')";
    } elseif ($auditType === 'student') {
        $conditions[] = "(entity = 'student' OR action LIKE 'student%')";
    } elseif ($auditType === 'uncle') {
        $conditions[] = "(entity = 'uncle' OR action LIKE 'uncle%')";
    } elseif ($auditType === 'trip') {
        $conditions[] = "(entity IN ('trip', 'trip_registration') OR action LIKE 'trip%')";
    } elseif ($auditType === 'announcement') {
        $conditions[] = "(entity = 'announcement' OR action LIKE 'announcement%')";
    } elseif ($auditType === 'registration') {
        $conditions[] = "(entity = 'registration' OR action LIKE 'registration%')";
    } else {
        $conditions[] = "(entity = ? OR action = ?)";
        $params[] = $auditType;
        $params[] = $auditType;
        $types .= "ss";
    }
}

// ── Clear all audit logs for this church or global ────────────
function clearAllAuditLogs()
{
    devCleanAuditLogs();
}

// ── Clean audit logs with audit_type & duration/mode filters ──
function devCleanAuditLogs()
{
    checkAuth();
    try {
        $role = $_SESSION['uncle_role'] ?? 'uncle';
        $target = sanitize($_POST['target'] ?? 'current'); // 'current' or 'all'

        // Non-developers can only delete logs for their current church
        if ($role !== 'developer' && $role !== 'dev') {
            $target = 'current';
        }

        $auditType = sanitize($_POST['audit_type'] ?? $_POST['entity'] ?? 'all');
        $rangeType = sanitize($_POST['range_type'] ?? $_POST['clean_mode'] ?? 'duration'); // 'duration', 'delete_all', 'range'
        $durationValue = sanitize($_POST['duration_value'] ?? ''); // '1_month', '3_months', '6_months', '1_year', 'custom_days'
        $customDays = intval($_POST['custom_days'] ?? 0);
        $dateFrom = sanitize($_POST['date_from'] ?? '');
        $dateTo = sanitize($_POST['date_to'] ?? '');

        $conn = getDBConnection();
        $query = "DELETE FROM audit_logs WHERE ";
        $conditions = [];
        $params = [];
        $types = "";

        // 1. Church Target Condition
        if ($target === 'current') {
            $churchId = getChurchId();
            $conditions[] = "church_id = ?";
            $params[] = $churchId;
            $types .= "i";
        }

        // 2. Audit Type Filter
        appendAuditTypeClause($auditType, $conditions, $params, $types);

        // 3. Range / Duration Condition
        if ($rangeType === 'duration') {
            $interval = "";
            if ($durationValue === '1_month') {
                $interval = "INTERVAL 1 MONTH";
            } elseif ($durationValue === '3_months') {
                $interval = "INTERVAL 3 MONTH";
            } elseif ($durationValue === '6_months') {
                $interval = "INTERVAL 6 MONTH";
            } elseif ($durationValue === '1_year') {
                $interval = "INTERVAL 1 YEAR";
            } elseif ($durationValue === 'custom_days' && $customDays > 0) {
                $interval = "INTERVAL ? DAY";
            }

            if (empty($interval)) {
                sendJSON(['success' => false, 'message' => 'تحديد الفترة غير صالح']);
                return;
            }

            if ($durationValue === 'custom_days') {
                $conditions[] = "created_at < NOW() - $interval";
                $params[] = $customDays;
                $types .= "i";
            } else {
                $conditions[] = "created_at < NOW() - $interval";
            }
        } elseif ($rangeType === 'range') {
            if ($dateFrom && $dateTo) {
                $conditions[] = "DATE(created_at) BETWEEN ? AND ?";
                $params[] = $dateFrom;
                $params[] = $dateTo;
                $types .= "ss";
            } elseif ($dateFrom) {
                $conditions[] = "DATE(created_at) >= ?";
                $params[] = $dateFrom;
                $types .= "s";
            } elseif ($dateTo) {
                $conditions[] = "DATE(created_at) <= ?";
                $params[] = $dateTo;
                $types .= "s";
            } else {
                sendJSON(['success' => false, 'message' => 'يجب تحديد نطاق التواريخ']);
                return;
            }
        } elseif ($rangeType === 'delete_all' || $rangeType === 'all') {
            // Delete all matching audit logs of that type without date restriction
        } else {
            sendJSON(['success' => false, 'message' => 'نوع النطاق غير صالح']);
            return;
        }

        if (empty($conditions)) {
            sendJSON(['success' => false, 'message' => 'لم يتم تحديد شروط الحذف']);
            return;
        }

        $query .= implode(" AND ", $conditions);
        $stmt = $conn->prepare($query);

        if (!$stmt) {
            throw new Exception("Failed to prepare statement: " . $conn->error);
        }

        if (!empty($params)) {
            $stmt->bind_param($types, ...$params);
        }

        if ($stmt->execute()) {
            $deleted = $stmt->affected_rows;
            if ($deleted > 0) {
                @$conn->query("OPTIMIZE TABLE audit_logs");
            }

            $logNotes = "نوع السجل: $auditType | المستهدف: " . ($target === 'all' ? 'جميع الكنائس' : 'الكنيسة الحالية');
            if ($rangeType === 'delete_all' || $rangeType === 'all') {
                $logNotes .= " | تفاصيل: حذف الكل";
            } elseif ($rangeType === 'duration') {
                $logNotes .= " | أقدم من: " . ($durationValue === 'custom_days' ? "$customDays يوم" : $durationValue);
            } else {
                $logNotes .= " | بين $dateFrom و $dateTo";
            }
            $logNotes .= " | المحذوف: $deleted سجل";

            writeAuditLog(
                'clean_audit_logs',
                'system',
                null,
                'System Logs',
                null,
                null,
                "قام الخادم بتنظيف سجلات العمليات. $logNotes"
            );

            sendJSON(['success' => true, 'message' => "تم حذف $deleted سجل بنجاح", 'deleted' => $deleted]);
        } else {
            throw new Exception("Execute failed: " . $stmt->error);
        }

    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}

// ── Get audit log cleanup stats for developer or church admin ──
function devGetAuditCleanupStats()
{
    checkAuth();
    try {
        $role = $_SESSION['uncle_role'] ?? 'uncle';
        $target = sanitize($_POST['target'] ?? 'current'); // 'current' or 'all'

        if ($role !== 'developer' && $role !== 'dev') {
            $target = 'current';
        }

        $auditType = sanitize($_POST['audit_type'] ?? $_POST['entity'] ?? 'all');
        $rangeType = sanitize($_POST['range_type'] ?? $_POST['clean_mode'] ?? 'duration'); // 'duration', 'delete_all', 'range'
        $durationValue = sanitize($_POST['duration_value'] ?? ''); // '1_month', '3_months', '6_months', '1_year', 'custom_days'
        $customDays = intval($_POST['custom_days'] ?? 0);
        $dateFrom = sanitize($_POST['date_from'] ?? '');
        $dateTo = sanitize($_POST['date_to'] ?? '');

        $conn = getDBConnection();

        // 1. Calculate Total count and size for church/scope
        $totalQuery = "SELECT COUNT(*) as total_count, 
                      COALESCE(SUM(OCTET_LENGTH(IFNULL(old_data, '')) + OCTET_LENGTH(IFNULL(new_data, '')) + OCTET_LENGTH(IFNULL(notes, '')) + OCTET_LENGTH(IFNULL(uncle_name, '')) + OCTET_LENGTH(IFNULL(action, '')) + OCTET_LENGTH(IFNULL(entity, '')) + OCTET_LENGTH(IFNULL(entity_name, '')) + OCTET_LENGTH(IFNULL(ip_address, '')) + OCTET_LENGTH(IFNULL(user_agent, '')) + 80), 0) as total_size 
                      FROM audit_logs";

        $totalStmt = null;
        if ($target === 'current') {
            $churchId = getChurchId();
            $totalQuery .= " WHERE church_id = ?";
            $totalStmt = $conn->prepare($totalQuery);
            $totalStmt->bind_param("i", $churchId);
        } else {
            $totalStmt = $conn->prepare($totalQuery);
        }

        $totalStmt->execute();
        $totalRes = $totalStmt->get_result()->fetch_assoc();
        $totalCount = intval($totalRes['total_count']);
        $totalSize = floatval($totalRes['total_size']);

        // 2. Calculate Delete count and size
        $deleteQuery = "SELECT COUNT(*) as delete_count, 
                       COALESCE(SUM(OCTET_LENGTH(IFNULL(old_data, '')) + OCTET_LENGTH(IFNULL(new_data, '')) + OCTET_LENGTH(IFNULL(notes, '')) + OCTET_LENGTH(IFNULL(uncle_name, '')) + OCTET_LENGTH(IFNULL(action, '')) + OCTET_LENGTH(IFNULL(entity, '')) + OCTET_LENGTH(IFNULL(entity_name, '')) + OCTET_LENGTH(IFNULL(ip_address, '')) + OCTET_LENGTH(IFNULL(user_agent, '')) + 80), 0) as delete_size 
                       FROM audit_logs WHERE ";

        $conditions = [];
        $params = [];
        $types = "";

        if ($target === 'current') {
            $churchId = getChurchId();
            $conditions[] = "church_id = ?";
            $params[] = $churchId;
            $types .= "i";
        }

        appendAuditTypeClause($auditType, $conditions, $params, $types);

        if ($rangeType === 'duration') {
            $interval = "";
            if ($durationValue === '1_month') {
                $interval = "INTERVAL 1 MONTH";
            } elseif ($durationValue === '3_months') {
                $interval = "INTERVAL 3 MONTH";
            } elseif ($durationValue === '6_months') {
                $interval = "INTERVAL 6 MONTH";
            } elseif ($durationValue === '1_year') {
                $interval = "INTERVAL 1 YEAR";
            } elseif ($durationValue === 'custom_days' && $customDays > 0) {
                $interval = "INTERVAL ? DAY";
            }

            if (empty($interval)) {
                sendJSON(['success' => false, 'message' => 'تحديد الفترة غير صالح']);
                return;
            }

            if ($durationValue === 'custom_days') {
                $conditions[] = "created_at < NOW() - $interval";
                $params[] = $customDays;
                $types .= "i";
            } else {
                $conditions[] = "created_at < NOW() - $interval";
            }
        } elseif ($rangeType === 'range') {
            if ($dateFrom && $dateTo) {
                $conditions[] = "DATE(created_at) BETWEEN ? AND ?";
                $params[] = $dateFrom;
                $params[] = $dateTo;
                $types .= "ss";
            } elseif ($dateFrom) {
                $conditions[] = "DATE(created_at) >= ?";
                $params[] = $dateFrom;
                $types .= "s";
            } elseif ($dateTo) {
                $conditions[] = "DATE(created_at) <= ?";
                $params[] = $dateTo;
                $types .= "s";
            } else {
                sendJSON(['success' => false, 'message' => 'يجب تحديد نطاق التواريخ']);
                return;
            }
        } elseif ($rangeType === 'delete_all' || $rangeType === 'all') {
            // Delete all matching audit logs of that type without date restriction
        } else {
            sendJSON(['success' => false, 'message' => 'نوع النطاق غير صالح']);
            return;
        }

        if (empty($conditions)) {
            sendJSON(['success' => false, 'message' => 'لم يتم تحديد شروط الحذف']);
            return;
        }

        $deleteQuery .= implode(" AND ", $conditions);
        $deleteStmt = $conn->prepare($deleteQuery);

        if (!$deleteStmt) {
            throw new Exception("Failed to prepare delete stats query: " . $conn->error);
        }

        if (!empty($params)) {
            $deleteStmt->bind_param($types, ...$params);
        }

        $deleteStmt->execute();
        $deleteRes = $deleteStmt->get_result()->fetch_assoc();
        $deleteCount = intval($deleteRes['delete_count']);
        $deleteSize = floatval($deleteRes['delete_size']);

        $remainingCount = max(0, $totalCount - $deleteCount);
        $remainingSize = max(0.0, $totalSize - $deleteSize);

        sendJSON([
            'success' => true,
            'total_count' => $totalCount,
            'total_size' => $totalSize,
            'delete_count' => $deleteCount,
            'delete_size' => $deleteSize,
            'remaining_count' => $remainingCount,
            'remaining_size' => $remainingSize
        ]);

    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => 'خطأ: ' . $e->getMessage()]);
    }
}



// ── Get activity logs for the currently logged-in uncle ───────

function getUncleActivityLogs()
{
    try {
        $conn = getDBConnection();
        $churchId = getChurchId();
        $limit = max(10, min(500, intval($_POST['limit'] ?? 100)));

        $uncleId = intval($_SESSION['uncle_id'] ?? 0);
        $isDev = isDeveloperRole();
        $isAdmin = isAdminOrDevRole();

        // 1. Developer view
        if ($isDev) {
            if ($churchId > 0) {
                $stmt = $conn->prepare("
                    SELECT id, action, entity, entity_id, entity_name,
                           uncle_name, notes, ip_address, created_at
                    FROM audit_logs
                    WHERE (church_id = ? OR church_id = 0)
                    ORDER BY created_at DESC
                    LIMIT ?
                ");
                $stmt->bind_param("ii", $churchId, $limit);
            } else {
                $stmt = $conn->prepare("
                    SELECT id, action, entity, entity_id, entity_name,
                           uncle_name, notes, ip_address, created_at
                    FROM audit_logs
                    ORDER BY created_at DESC
                    LIMIT ?
                ");
                $stmt->bind_param("i", $limit);
            }
            $stmt->execute();
            $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
            sendJSON(['success' => true, 'logs' => $rows, 'total' => count($rows)]);
            return;
        }

        // 2. Church admin or church login without specific uncle_id
        if ($isAdmin || (!$uncleId && $churchId)) {
            $stmt = $conn->prepare("
                SELECT id, action, entity, entity_id, entity_name,
                       uncle_name, notes, ip_address, created_at
                FROM audit_logs
                WHERE (church_id = ? OR church_id = 0)
                ORDER BY created_at DESC
                LIMIT ?
            ");
            $stmt->bind_param("ii", $churchId, $limit);
            $stmt->execute();
            $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
            sendJSON(['success' => true, 'logs' => $rows, 'total' => count($rows)]);
            return;
        }

        if (!$uncleId) {
            sendJSON(['success' => false, 'message' => 'غير مصرح - يرجى تسجيل الدخول']);
            return;
        }

        // 3. Regular uncle view
        if ($churchId > 0) {
            $stmt = $conn->prepare("
                SELECT id, action, entity, entity_id, entity_name,
                       uncle_name, notes, ip_address, created_at
                FROM audit_logs
                WHERE uncle_id = ? AND (church_id = ? OR church_id = 0)
                ORDER BY created_at DESC
                LIMIT ?
            ");
            $stmt->bind_param("iii", $uncleId, $churchId, $limit);
        } else {
            $stmt = $conn->prepare("
                SELECT id, action, entity, entity_id, entity_name,
                       uncle_name, notes, ip_address, created_at
                FROM audit_logs
                WHERE uncle_id = ?
                ORDER BY created_at DESC
                LIMIT ?
            ");
            $stmt->bind_param("ii", $uncleId, $limit);
        }

        $stmt->execute();
        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        sendJSON(['success' => true, 'logs' => $rows, 'total' => count($rows)]);

    } catch (Exception $e) {
        error_log("getUncleActivityLogs error: " . $e->getMessage());
        sendJSON(['success' => false, 'message' => 'خطأ في تحميل السجل: ' . $e->getMessage()]);
    }
}



// ═══════════════════════════════════════════════════════════════

//  CHURCH REGISTRATION KEY SYSTEM

// ═══════════════════════════════════════════════════════════════



function ensureRegKeyTable($conn)

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        CREATE TABLE IF NOT EXISTS church_reg_keys (

            id             INT AUTO_INCREMENT PRIMARY KEY,

            reg_key        VARCHAR(64) NOT NULL UNIQUE,

            label          VARCHAR(255) DEFAULT '',

            created_by     INT DEFAULT 0,

            created_at     DATETIME DEFAULT CURRENT_TIMESTAMP,

            used_at        DATETIME DEFAULT NULL,

            used_by_church INT DEFAULT NULL,

            is_revoked     TINYINT(1) DEFAULT 0,

            notes          TEXT DEFAULT NULL

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4

    ");

}



// DEV ONLY — generate a one-time church registration link

function generateChurchRegKey()

{

    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? '');

    if (!in_array($role, ['developer', 'dev', 'admin', 'administrator'])) {

        sendJSON(['success' => false, 'message' => 'غير مصرح - للمطورين فقط']);

        return;

    }

    $label = sanitize($_POST['label'] ?? '');

    $createdBy = intval($_SESSION['uncle_id'] ?? $_SESSION['user_id'] ?? 0);

    $conn = getDBConnection();

    ensureRegKeyTable($conn);

    $key = bin2hex(random_bytes(24));

    $stmt = $conn->prepare("INSERT INTO church_reg_keys (reg_key, label, created_by) VALUES (?, ?, ?)");

    $stmt->bind_param("ssi", $key, $label, $createdBy);

    if ($stmt->execute()) {

        $proto = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';

        $base = $proto . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost');

        $regUrl = $base . '/church-register.html?key=' . $key;

        sendJSON(['success' => true, 'key' => $key, 'reg_url' => $regUrl, 'message' => 'تم توليد الرابط بنجاح']);

    } else {

        sendJSON(['success' => false, 'message' => 'فشل في توليد المفتاح: ' . $conn->error]);

    }

}



// DEV ONLY — list all generated keys

function listChurchRegKeys()

{

    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? '');

    if (!in_array($role, ['developer', 'dev', 'admin', 'administrator'])) {

        sendJSON(['success' => false, 'message' => 'غير مصرح']);

        return;

    }

    $conn = getDBConnection();

    ensureRegKeyTable($conn);

    $result = $conn->query("

        SELECT k.*, c.church_name AS church_name

        FROM church_reg_keys k

        LEFT JOIN churches c ON c.id = k.used_by_church

        ORDER BY k.created_at DESC

    ");



    if (!$result) {

        sendJSON(['success' => false, 'message' => 'حدث خطأ في قاعدة البيانات: ' . $conn->error]);

        return;

    }



    $keys = [];

    $proto = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';

    $base = $proto . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost');

    while ($row = $result->fetch_assoc()) {

        $row['reg_url'] = $base . '/church-register.html?key=' . $row['reg_key'];

        $keys[] = $row;

    }

    sendJSON(['success' => true, 'keys' => $keys]);

}



// DEV ONLY — revoke (or restore) a key

function revokeChurchRegKey()

{

    $role = strtolower($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? '');

    if (!in_array($role, ['developer', 'dev', 'admin', 'administrator'])) {

        sendJSON(['success' => false, 'message' => 'غير مصرح']);

        return;

    }

    $key = sanitize($_POST['key'] ?? '');

    $revoke = intval($_POST['revoke'] ?? 1);

    if (empty($key)) {

        sendJSON(['success' => false, 'message' => 'المفتاح مطلوب']);

        return;

    }

    $conn = getDBConnection();

    ensureRegKeyTable($conn);

    $stmt = $conn->prepare("UPDATE church_reg_keys SET is_revoked = ? WHERE reg_key = ?");

    $stmt->bind_param("is", $revoke, $key);

    if ($stmt->execute() && $stmt->affected_rows > 0) {

        sendJSON(['success' => true, 'message' => $revoke ? 'تم إلغاء الرابط' : 'تم استعادة الرابط']);

    } else {

        sendJSON(['success' => false, 'message' => 'المفتاح غير موجود']);

    }

}



// PUBLIC — validate a key before showing the registration form

function validateChurchRegKey()

{

    $key = sanitize($_POST['key'] ?? '');

    if (empty($key)) {

        sendJSON(['success' => true, 'valid' => false, 'reason' => 'missing']);

        return;

    }

    $conn = getDBConnection();

    ensureRegKeyTable($conn);

    $stmt = $conn->prepare("SELECT id, is_revoked, used_at FROM church_reg_keys WHERE reg_key = ? LIMIT 1");

    $stmt->bind_param("s", $key);

    $stmt->execute();

    $row = $stmt->get_result()->fetch_assoc();

    if (!$row) {

        sendJSON(['success' => true, 'valid' => false, 'reason' => 'not_found']);

        return;

    }

    if ($row['is_revoked']) {

        sendJSON(['success' => true, 'valid' => false, 'reason' => 'revoked']);

        return;

    }

    if ($row['used_at']) {

        sendJSON(['success' => true, 'valid' => false, 'reason' => 'already_used']);

        return;

    }

    sendJSON(['success' => true, 'valid' => true]);

}



// PUBLIC — create church + admin uncle atomically, then mark key as used

function createChurchWithAdmin()

{

    $key = sanitize($_POST['reg_key'] ?? '');

    $isApproved = empty($key) ? 0 : 1;

    $conn = getDBConnection();

    ensureChurchApprovedColumn($conn);

    $conn->begin_transaction();

    try {

        if (!empty($key)) {

            // Lock & validate

            $stmt = $conn->prepare("SELECT id, is_revoked, used_at FROM church_reg_keys WHERE reg_key = ? LIMIT 1 FOR UPDATE");

            $stmt->bind_param("s", $key);

            $stmt->execute();

            $keyRow = $stmt->get_result()->fetch_assoc();

            if (!$keyRow)

                throw new Exception('مفتاح التسجيل غير صالح');

            if ($keyRow['is_revoked'])

                throw new Exception('تم إلغاء هذا الرابط');

            if ($keyRow['used_at'])

                throw new Exception('تم استخدام هذا الرابط مسبقاً');

        }



        // Inputs

        $churchName = sanitize($_POST['church_name'] ?? '');

        $churchCity = sanitize($_POST['church_city'] ?? '');

        $churchEmail = sanitize($_POST['church_email'] ?? '');

        $churchPhone = sanitize($_POST['church_phone'] ?? '');

        $churchType = in_array($_POST['church_type'] ?? '', ['kids', 'youth']) ? $_POST['church_type'] : 'kids';

        $adminName = sanitize($_POST['admin_name'] ?? '');

        $adminPhone = sanitize($_POST['admin_phone'] ?? '');

        $adminPassword = $_POST['admin_password'] ?? '';

        $adminEmail = sanitize($_POST['admin_email'] ?? '');

        $adminClass = sanitize($_POST['admin_class'] ?? 'الكل');



        if (empty($churchName))

            throw new Exception('اسم الكنيسة مطلوب');

        if (empty($adminName))

            throw new Exception('اسم المسؤول مطلوب');

        if (empty($adminPhone))

            throw new Exception('رقم تليفون المسؤول مطلوب');

        if (strlen($adminPassword) < 6)

            throw new Exception('كلمة المرور يجب أن تكون 6 أحرف على الأقل');



        // Check phone not already used

        $chk = $conn->prepare("SELECT id FROM uncles WHERE phone = ? LIMIT 1");

        $chk->bind_param("s", $adminPhone);

        $chk->execute();

        if ($chk->get_result()->fetch_assoc())

            throw new Exception('رقم التليفون مستخدم بالفعل في كنيسة أخرى');



        // Generate unique church code from name

        $baseCode = preg_replace('/[^a-z0-9]/i', '', str_replace(' ', '_', strtolower(iconv('UTF-8', 'ASCII//TRANSLIT', $churchName))));

        $churchCode = $baseCode ?: 'church' . time();

        $codeCheck = $conn->prepare("SELECT id FROM churches WHERE church_code = ? LIMIT 1");

        $codeCheck->bind_param("s", $churchCode);

        $codeCheck->execute();

        if ($codeCheck->get_result()->fetch_assoc()) {

            $churchCode .= '_' . rand(100, 999);

        }



        // Create church — password for direct church login (same hashing as addChurch)

        $hashedChurchPw = hash('sha256', $adminPassword);

        $insChurch = $conn->prepare("

            INSERT INTO churches (church_name, church_code, admin_email, password, password_hash, church_type, is_approved, created_at)

            VALUES (?, ?, ?, ?, ?, ?, ?, NOW())

        ");

        $insChurch->bind_param("ssssssi", $churchName, $churchCode, $churchEmail, $hashedChurchPw, $hashedChurchPw, $churchType, $isApproved);

        if (!$insChurch->execute())

            throw new Exception('فشل إنشاء الكنيسة: ' . $conn->error);

        $newChurchId = $conn->insert_id;



        // Create admin uncle

        $hashedUnclePw = hash('sha256', $adminPassword);

        $adminUsername = sanitize($_POST['admin_username'] ?? '') ?: $adminPhone;



        $insUncle = $conn->prepare("

            INSERT INTO uncles (church_id, name, phone, username, password, password_hash, email, class, role, is_active, created_at)

            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'admin', 1, NOW())

        ");

        $insUncle->bind_param("isssssss", $newChurchId, $adminName, $adminPhone, $adminUsername, $hashedUnclePw, $hashedUnclePw, $adminEmail, $adminClass);

        if (!$insUncle->execute())

            throw new Exception('فشل إنشاء حساب المسؤول: ' . $conn->error);

        $newUncleId = $conn->insert_id;



        // Assign default class to the admin uncle

        $insAssign = $conn->prepare("

            INSERT INTO uncle_class_assignments (uncle_id, church_id, class_name)

            VALUES (?, ?, ?)

        ");

        $insAssign->bind_param("iis", $newUncleId, $newChurchId, $adminClass);

        $insAssign->execute();



        // Initialize church_settings for this church and set the admin uncle as allowed to manage uncles

        $adminUsernameLower = strtolower($adminUsername);

        $insSettings = $conn->prepare("

            INSERT INTO church_settings (church_id, allowed_view_uncles)

            VALUES (?, ?)

            ON DUPLICATE KEY UPDATE allowed_view_uncles = VALUES(allowed_view_uncles)

        ");

        $insSettings->bind_param("is", $newChurchId, $adminUsernameLower);

        $insSettings->execute();



        // Mark key used

        if (!empty($key)) {

            $useStmt = $conn->prepare("UPDATE church_reg_keys SET used_at = NOW(), church_id = ? WHERE reg_key = ?");

            $useStmt->bind_param("is", $newChurchId, $key);

            $useStmt->execute();

        }



        $conn->commit();



        // Notify developer about new church registration (fire-and-forget)

        _sendNewChurchNotification($churchName, $adminName, $adminPhone, $churchEmail, $churchType);



        sendJSON([

            'success' => true,

            'message' => 'تم إنشاء الكنيسة بنجاح',

            'church_id' => $newChurchId,

            'church_name' => $churchName,

            'pending' => !$isApproved

        ]);

    } catch (Exception $e) {

        $conn->rollback();

        error_log("createChurchWithAdmin error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function toggleChurchApproval()

{

    checkAuth();

    try {

        $role = $_SESSION['uncle_role'] ?? 'uncle';

        if ($role !== 'developer' && $role !== 'dev') {

            sendJSON(['success' => false, 'message' => 'غير مصرح']);

            return;

        }

        $churchId = (int)($_POST['church_id'] ?? 0);

        $isApproved = (int)($_POST['is_approved'] ?? 0);

        

        $conn = getDBConnection();

        ensureChurchApprovedColumn($conn);

        $stmt = $conn->prepare("UPDATE churches SET is_approved = ? WHERE id = ?");

        $stmt->bind_param("ii", $isApproved, $churchId);

        if ($stmt->execute()) {

            sendJSON(['success' => true, 'message' => 'تم تحديث حالة تفعيل الكنيسة بنجاح']);

        } else {

            sendJSON(['success' => false, 'message' => 'فشل في تحديث حالة تفعيل الكنيسة']);

        }

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// PUBLIC — get basic church info for kid-register page

function getPublicChurchInfo()

{

    $churchId = intval($_POST['church_id'] ?? $_GET['church_id'] ?? 0);
    $churchCode = sanitize($_POST['church_code'] ?? $_GET['church_code'] ?? '');

    if (!$churchId && empty($churchCode)) {

        sendJSON(['success' => false, 'message' => 'معرف أو رمز الكنيسة مطلوب']);

        return;

    }

    $conn = getDBConnection();

    $row = findChurchRow($conn, $churchCode, $churchId);

    if (!$row) {

        sendJSON(['success' => false, 'message' => 'الكنيسة غير موجودة']);

        return;

    }

    sendJSON([
        'success' => true, 
        'church_id' => $row['id'], 
        'church_name' => $row['church_name'], 
        'church_code' => $row['church_code'], 
        'church_type' => $row['church_type'] ?? 'kids'
    ]);

}



// PUBLIC — check registration status by phone (for kid-register page)

function checkRegistrationStatus()

{

    $phone = sanitize($_POST['phone'] ?? '');

    $churchId = intval($_POST['church_id'] ?? 0);

    if (empty($phone)) {

        sendJSON(['success' => false, 'message' => 'رقم التليفون مطلوب']);

        return;

    }

    $conn = getDBConnection();



    // Check pending_registrations table (primary table used by submitRegistrationRequest)

    $tableCheck = $conn->query("SHOW TABLES LIKE 'pending_registrations'");

    if (!$tableCheck || $tableCheck->num_rows === 0) {

        sendJSON(['success' => true, 'registrations' => []]);

        return;

    }



    if ($churchId) {

        $stmt = $conn->prepare("

            SELECT id, name, class, status, created_at

            FROM pending_registrations

            WHERE phone = ? AND church_id = ?

            ORDER BY created_at DESC

        ");

        $stmt->bind_param("si", $phone, $churchId);

    } else {

        $stmt = $conn->prepare("

            SELECT id, name, class, status, created_at

            FROM pending_registrations

            WHERE phone = ?

            ORDER BY created_at DESC

        ");

        $stmt->bind_param("s", $phone);

    }

    $stmt->execute();

    $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

    sendJSON(['success' => true, 'registrations' => $rows]);

}



