function ensureTaskSubmissionsIsDeletedColumn($conn)
{
    static $done = false;
    if ($done) return;
    $done = true;
    try {
        $chk = $conn->query("SHOW COLUMNS FROM task_submissions LIKE 'is_deleted'");
        if ($chk && $chk->num_rows === 0) {
            $conn->query("ALTER TABLE task_submissions ADD is_deleted TINYINT(1) DEFAULT 0");
        }
        $chkDate = $conn->query("SHOW COLUMNS FROM task_submissions LIKE 'deleted_at'");
        if ($chkDate && $chkDate->num_rows === 0) {
            $conn->query("ALTER TABLE task_submissions ADD deleted_at DATETIME NULL");
        }
    } catch (Throwable $e) {}
}

// ─── getTasks ──────────────────────────────────────────────────

function _resolveTaskClassNames($conn, $churchId, $classId, $classIdsStr, $fallbackName = '')
{
    $classIdsStr = trim((string)$classIdsStr);
    $cIds = array_values(array_unique(array_filter(array_map('intval', explode(',', $classIdsStr)), function($v) { return $v >= 0; })));

    if (in_array(0, $cIds) || ($classId == 0 && empty($cIds))) {
        return ['names' => ['كل الفصول'], 'label' => 'كل الفصول', 'ids' => ['0']];
    }

    if (empty($cIds) && $classId > 0) {
        $cIds = [$classId];
    }

    if (!empty($cIds)) {
        static $cachedChurchClasses = [];
        if (!isset($cachedChurchClasses[$churchId])) {
            $cachedChurchClasses[$churchId] = [];
            $cRes = $conn->query("SELECT id, arabic_name FROM church_classes WHERE church_id = " . intval($churchId) . " UNION SELECT id, arabic_name FROM classes");
            if ($cRes) {
                while ($cRow = $cRes->fetch_assoc()) {
                    $cachedChurchClasses[$churchId][(int)$cRow['id']] = $cRow['arabic_name'];
                }
            }
        }
        $names = [];
        foreach ($cIds as $cid) {
            if (isset($cachedChurchClasses[$churchId][$cid]) && !in_array($cachedChurchClasses[$churchId][$cid], $names)) {
                $names[] = $cachedChurchClasses[$churchId][$cid];
            }
        }
        if (empty($names) && !empty($fallbackName)) {
            $names = array_values(array_filter(array_map('trim', explode('،', $fallbackName))));
        }
        if (!empty($names)) {
            return [
                'names' => $names,
                'label' => implode('، ', $names),
                'ids'   => array_map('strval', $cIds)
            ];
        }
    }

    $finalName = !empty($fallbackName) ? $fallbackName : 'كل الفصول';
    return ['names' => [$finalName], 'label' => $finalName, 'ids' => array_map('strval', $cIds)];
}

function getTasks()
{
    try {
        $conn = getDBConnection();
        $churchId = getChurchId();
        $uncleId = $_SESSION['uncle_id'] ?? null;
        $uncleRole = strtolower($_SESSION['uncle_role'] ?? '');
        $className = sanitize($_POST['class_name'] ?? '');
        ensureTaskSubmissionsIsDeletedColumn($conn);
        $isAdmin = in_array($uncleRole, ['admin', 'developer', 'church']);

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS class_ids VARCHAR(255) NULL AFTER class_id");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_name VARCHAR(255) NULL");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_icon VARCHAR(255) NULL");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS shuffle_answers TINYINT(1) NOT NULL DEFAULT 0");

        $taskCols = [];
        $colRes = $conn->query("SHOW COLUMNS FROM tasks");
        while ($cr = $colRes->fetch_assoc())
            $taskCols[] = $cr['Field'];

        $hasNoDeadline = in_array('no_deadline', $taskCols);
        $hasClassIds = in_array('class_ids', $taskCols);
        $hasGroupName = in_array('group_name', $taskCols);
        $hasGroupIcon = in_array('group_icon', $taskCols);
        $hasShuffleAnswers = in_array('shuffle_answers', $taskCols);

        $sql = "
            SELECT
                t.id, t.uncle_id, t.class_id, t.title, t.description,
                t.start_date, t.end_date, t.time_limit, t.timer_behavior,
                t.total_degree, t.max_coupons, t.coupon_matrix,
                t.status, t.assign_to, t.specific_ids,
                t.shuffle, " . ($hasShuffleAnswers ? "t.shuffle_answers, " : "") . "t.show_result, t.show_answers, t.allow_review" . ($hasNoDeadline ? ", t.no_deadline" : "") . ($hasClassIds ? ", t.class_ids" : "") . ($hasGroupName ? ", t.group_name" : "") . ($hasGroupIcon ? ", t.group_icon" : "") . ",
                t.created_at,
                CASE
                    WHEN t.class_id = 0 THEN 'كل الفصول'
                    ELSE COALESCE(cc.arabic_name, '')
                END AS class_name,
                u.name AS uncle_name
            FROM tasks t
            LEFT JOIN church_classes cc ON cc.id = t.class_id AND cc.church_id = t.church_id
            LEFT JOIN uncles u ON u.id = t.uncle_id
            WHERE t.church_id = ?
        ";

        $params = [$churchId];
        $types = 'i';

        if (!$isAdmin && $uncleId) {
            $sql .= " AND t.uncle_id = ?";
            $params[] = (int) $uncleId;
            $types .= 'i';
        }

        if ($className && $className !== 'كل الفصول') {
            if ($hasClassIds) {
                $cStmt = $conn->prepare("SELECT id FROM church_classes WHERE church_id = ? AND arabic_name = ? LIMIT 1");
                $cStmt->bind_param('is', $churchId, $className);
                $cStmt->execute();
                $cId = (int)($cStmt->get_result()->fetch_assoc()['id'] ?? 0);
                if (!$cId) {
                    $cStmt2 = $conn->prepare("SELECT id FROM classes WHERE arabic_name = ? LIMIT 1");
                    $cStmt2->bind_param('s', $className);
                    $cStmt2->execute();
                    $cId = (int)($cStmt2->get_result()->fetch_assoc()['id'] ?? 0);
                }

                $sql .= " AND (t.class_id = 0 OR FIND_IN_SET('0', t.class_ids) OR cc.arabic_name = ? OR (? > 0 AND FIND_IN_SET(?, t.class_ids)))";
                $params[] = $className;
                $params[] = $cId;
                $params[] = $cId;
                $types .= 'sii';
            } else {
                $sql .= " AND (cc.arabic_name = ? OR t.class_id = 0)";
                $params[] = $className;
                $types .= 's';
            }
        }

        $sql .= " ORDER BY t.created_at DESC";

        $stmt = $conn->prepare($sql);
        $stmt->bind_param($types, ...$params);
        $stmt->execute();
        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

        foreach ($rows as &$r) {
            $resolved = _resolveTaskClassNames($conn, $churchId, $r['class_id'] ?? 0, $r['class_ids'] ?? '', $r['class_name'] ?? '');
            $r['class_name'] = $resolved['label'];
            $r['class_ids'] = implode(',', $resolved['ids']);
            $r['class_names'] = $resolved['names'];
        }
        unset($r);



        $taskIds = array_column($rows, 'id');

        $questions = [];

        $submissions = [];



        if ($taskIds) {
            $inList = implode(',', array_map('intval', $taskIds));

            // Auto-reconcile coupons if any submission in these tasks has score > 0 but coupons_awarded = 0 or is_graded = 0
            $chkNeedsFix = $conn->query("
                SELECT DISTINCT ts.task_id 
                FROM task_submissions ts 
                WHERE ts.task_id IN ($inList) 
                  AND (ts.is_deleted IS NULL OR ts.is_deleted = 0)
                  AND ts.score > 0 
                  AND (ts.coupons_awarded = 0 OR ts.is_graded = 0)
                LIMIT 20
            ");
            if ($chkNeedsFix && $chkNeedsFix->num_rows > 0) {
                while ($cRow = $chkNeedsFix->fetch_assoc()) {
                    syncTaskSubmissionsForTask($conn, (int)$cRow['task_id'], $uncleId);
                }
            }

            $qRes = $conn->query("
                SELECT id, task_id, question_type, question_text, options, correct_index, degree, sort_order, image_url
                FROM task_questions WHERE task_id IN ($inList)
                ORDER BY task_id, sort_order
            ");
            while ($r = $qRes->fetch_assoc()) {
                $questions[$r['task_id']][] = $r;
            }

            $sRes = $conn->query("
                SELECT ts.id, ts.task_id, ts.student_id, ts.score, ts.coupons_awarded, ts.submitted_at,
                       ts.answers, ts.open_scores, ts.correction_notes, ts.is_graded,
                       s.name AS student_name,
                       COALESCE(s.coupons, 0) AS student_total_coupons,
                       COALESCE(s.task_coupons, 0) AS student_task_coupons
                FROM task_submissions ts
                LEFT JOIN students s ON s.id = ts.student_id
                WHERE ts.task_id IN ($inList) AND (ts.is_deleted IS NULL OR ts.is_deleted = 0)
                ORDER BY ts.submitted_at DESC
            ");
            while ($r = $sRes->fetch_assoc()) {
                $submissions[$r['task_id']][] = $r;
            }
        }



        foreach ($rows as &$t) {

            $t['no_deadline'] = isset($t['no_deadline']) ? (int) $t['no_deadline'] : 0;

            $t['questions'] = $questions[$t['id']] ?? [];

            $t['submissions'] = $submissions[$t['id']] ?? [];

        }

        unset($t);



        sendJSON(['success' => true, 'tasks' => $rows]);

    } catch (Exception $e) {

        error_log("getTasks error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── getTaskDetail ─────────────────────────────────────────────

function getTaskDetail()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$taskId) {

            sendJSON(['success' => false, 'message' => 'task_id مطلوب']);

            return;

        }



        $stmt = $conn->prepare("

            SELECT t.*,

                   CASE

                       WHEN t.class_id = 0 THEN 'كل الفصول'

                       ELSE COALESCE(cc.arabic_name,'')

                   END AS class_name,

                   u.name AS uncle_name

            FROM tasks t

            LEFT JOIN church_classes cc ON cc.id = t.class_id AND cc.church_id = t.church_id

            LEFT JOIN uncles u ON u.id = t.uncle_id

            WHERE t.id = ? AND t.church_id = ?

        ");

        $stmt->bind_param('ii', $taskId, $churchId);

        $stmt->execute();

        $task = $stmt->get_result()->fetch_assoc();

        if ($task) {
            $task['no_deadline'] = isset($task['no_deadline']) ? (int) $task['no_deadline'] : 0;
            $task['shuffle'] = isset($task['shuffle']) ? (int) $task['shuffle'] : 0;
            $task['shuffle_answers'] = isset($task['shuffle_answers']) ? (int) $task['shuffle_answers'] : 0;

            $resolved = _resolveTaskClassNames($conn, $churchId, $task['class_id'] ?? 0, $task['class_ids'] ?? '', $task['class_name'] ?? '');
            $task['class_name'] = $resolved['label'];
            $task['class_ids'] = implode(',', $resolved['ids']);
            $task['class_names'] = $resolved['names'];
        }

        if (!$task) {

            sendJSON(['success' => false, 'message' => 'التاسك غير موجودة']);

            return;

        }



        $qStmt = $conn->prepare("

            SELECT id, task_id, question_type, question_text, options, correct_index, degree, sort_order, image_url

            FROM task_questions WHERE task_id = ? ORDER BY sort_order

        ");

        $qStmt->bind_param('i', $taskId);

        $qStmt->execute();

        $task['questions'] = $qStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        $sStmt = $conn->prepare("

            SELECT ts.*, s.name AS student_name

            FROM task_submissions ts

            LEFT JOIN students s ON s.id = ts.student_id

            WHERE ts.task_id = ? AND (ts.is_deleted IS NULL OR ts.is_deleted = 0)

            ORDER BY ts.submitted_at DESC

        ");

        $sStmt->bind_param('i', $taskId);

        $sStmt->execute();

        $task['submissions'] = $sStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        sendJSON(['success' => true, 'task' => $task]);

    } catch (Exception $e) {

        error_log("getTaskDetail error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── createTask ────────────────────────────────────────────────

function createTask()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $uncleId = (int) ($_SESSION['uncle_id'] ?? 0);



        $title = sanitize($_POST['title'] ?? '');

        $description = sanitize($_POST['description'] ?? '');

        $className = sanitize($_POST['class_name'] ?? '');

        $classId = (int) ($_POST['class_id'] ?? 0);

        $assignTo = in_array($_POST['assign_to'] ?? 'all', ['all', 'specific']) ? $_POST['assign_to'] : 'all';

        $specificIds = $_POST['specific_ids'] ?? '[]';

        $startDate = sanitize($_POST['start_date'] ?? '');

        $endDateRaw = trim($_POST['end_date'] ?? '');

        $noDeadline = (int) ($_POST['no_deadline'] ?? 0) ? 1 : 0;

        $endDate = $noDeadline ? '9999-12-31 23:59:59' : ($endDateRaw !== '' ? sanitize($endDateRaw) : null);

        $timeLimit = !empty($_POST['time_limit']) ? (int) $_POST['time_limit'] : null;

        $timerBeh = in_array($_POST['timer_behavior'] ?? 'submit', ['submit', 'lock']) ? $_POST['timer_behavior'] : 'submit';

        $totalDegree = (int) ($_POST['total_degree'] ?? 0);

        $maxCoupons = (int) ($_POST['max_coupons'] ?? 0);

        $couponMatrix = $_POST['coupon_matrix'] ?? '[]';

        $status = in_array($_POST['status'] ?? 'published', ['draft', 'published']) ? $_POST['status'] : 'published';

        $shuffle = (int) ($_POST['shuffle'] ?? 0);

        $shuffleAnswers = (int) ($_POST['shuffle_answers'] ?? 0);

        $showResult = (int) ($_POST['show_result'] ?? 1);

        $showAnswers = (int) ($_POST['show_answers'] ?? 0);

        $allowReview = (int) ($_POST['allow_review'] ?? 1);

        $questionsJson = $_POST['questions'] ?? '[]';

        $groupName = sanitize($_POST['group_name'] ?? '');

        $groupIcon = sanitize($_POST['group_icon'] ?? '');



        if (!$title) {

            sendJSON(['success' => false, 'message' => 'العنوان مطلوب']);

            return;

        }

        if (!$startDate) {

            sendJSON(['success' => false, 'message' => 'تاريخ البداية مطلوب']);

            return;

        }

        if (!$endDate) {

            sendJSON(['success' => false, 'message' => 'الموعد النهائي مطلوب']);

            return;

        }



        if (!$classId && $className) {

            $cStmt = $conn->prepare("SELECT id FROM church_classes WHERE church_id=? AND arabic_name=? LIMIT 1");

            $cStmt->bind_param('is', $churchId, $className);

            $cStmt->execute();

            $cRow = $cStmt->get_result()->fetch_assoc();

            if ($cRow)

                $classId = (int) $cRow['id'];

        }



        $classIdsRaw = sanitize($_POST['class_ids'] ?? '');
        $parsedIds = array_values(array_unique(array_filter(array_map('intval', explode(',', $classIdsRaw)), function($v){ return $v >= 0; })));
        if (empty($parsedIds)) {
            if ($classId > 0) $parsedIds = [$classId];
            else $parsedIds = [0];
        }
        if (in_array(0, $parsedIds)) {
            $classId = 0;
            $classIds = '0';
        } else {
            $classId = $parsedIds[0];
            $classIds = implode(',', $parsedIds);
        }

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS no_deadline TINYINT(1) NOT NULL DEFAULT 0 AFTER end_date");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS class_ids VARCHAR(255) NULL AFTER class_id");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_name VARCHAR(255) NULL");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_icon VARCHAR(255) NULL");
        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS shuffle_answers TINYINT(1) NOT NULL DEFAULT 0");
        $conn->begin_transaction();

        $stmt = $conn->prepare("
            INSERT INTO tasks
                (church_id, uncle_id, class_id, class_ids, title, description,
                 start_date, end_date, no_deadline, time_limit, timer_behavior,
                 total_degree, max_coupons, coupon_matrix,
                 status, assign_to, specific_ids,
                 shuffle, shuffle_answers, show_result, show_answers, allow_review,
                 group_name, group_icon, created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())
        ");
        $stmt->bind_param(
            'iiisssssiisiissssiiiiiss',
            $churchId,
            $uncleId,
            $classId,
            $classIds,
            $title,
            $description,
            $startDate,
            $endDate,
            $noDeadline,
            $timeLimit,
            $timerBeh,
            $totalDegree,
            $maxCoupons,
            $couponMatrix,
            $status,
            $assignTo,
            $specificIds,
            $shuffle,
            $shuffleAnswers,
            $showResult,
            $showAnswers,
            $allowReview,
            $groupName,
            $groupIcon
        );
        $stmt->execute();
        $taskId = $conn->insert_id;

        $questions = json_decode($questionsJson, true) ?: [];
        _insertTaskQuestions($conn, $taskId, $questions);

        $conn->commit();

        if ($status === 'published') {
            $extra = ['notifType' => 'task', 'task_id' => $taskId, 'url' => '/user/profile/'];
            if ($assignTo === 'specific') {
                $dec = json_decode($specificIds, true);
                if (is_array($dec) && !empty($dec)) {
                    $cleanIds = implode(',', array_map('intval', $dec));
                    $extra['student_ids'] = $cleanIds;
                }
            } else {
                if ($classId === 0 || $classIds === '0') {
                    $extra['class_ids'] = null;
                } else {
                    $extra['class_ids'] = $classIds;
                }
            }
            _sendWebPushToKids($conn, $churchId, 'تاسك جديد 📝', "تاسك جديد: {$title}", $extra);

            // Also insert announcement for in-app notification feed
            try {
                $annText = "تاسك جديد: \"{$title}\"";
                $annStmt = $conn->prepare("INSERT INTO announcements (church_id, type, text, link, class, is_active, created_at) VALUES (?, 'task', ?, '/user/profile/', ?, 1, NOW())");
                if ($annStmt) {
                    if ($classId === 0 || $classIds === '0') {
                        $allCls = 'كل الفصول';
                        $annStmt->bind_param('iss', $churchId, $annText, $allCls);
                        $annStmt->execute();
                    } else {
                        $targetNames = [];
                        $qCls = $conn->query("SELECT arabic_name FROM church_classes WHERE id IN ($classIds) AND church_id = $churchId UNION SELECT arabic_name FROM classes WHERE id IN ($classIds)");
                        if ($qCls) {
                            while ($qr = $qCls->fetch_assoc()) {
                                if (!empty($qr['arabic_name'])) $targetNames[] = $qr['arabic_name'];
                            }
                        }
                        if (empty($targetNames) && !empty($className)) {
                            $targetNames = array_values(array_filter(array_map('trim', explode('،', $className))));
                        }
                        foreach ($targetNames as $tn) {
                            $annStmt->bind_param('iss', $churchId, $annText, $tn);
                            $annStmt->execute();
                        }
                    }
                }
            } catch (Exception $annEx) {}
        }

        if (function_exists('writeAuditLog')) {

            writeAuditLog('create', 'task', $taskId, $title);

        }



        sendJSON(['success' => true, 'task_id' => $taskId, 'message' => 'تم إنشاء التاسك']);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("createTask error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── deleteSubmission ──────────────────────────────────────────

function deleteSubmission()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $subId = (int) ($_POST['submission_id'] ?? 0);



        if (!$subId) {

            sendJSON(['success' => false, 'message' => 'submission_id مطلوب']);

            return;

        }



        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_deleted TINYINT(1) DEFAULT 0");

        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS deleted_at DATETIME NULL");



        // Load submission so we can reverse coupons

        $sel = $conn->prepare("

            SELECT ts.student_id, ts.coupons_awarded, ts.task_id, t.title

            FROM task_submissions ts

            JOIN tasks t ON t.id = ts.task_id

            WHERE ts.id = ? AND ts.church_id = ? AND (ts.is_deleted IS NULL OR ts.is_deleted = 0)

        ");

        $sel->bind_param('ii', $subId, $churchId);

        $sel->execute();

        $sub = $sel->get_result()->fetch_assoc();

        if (!$sub) {

            sendJSON(['success' => false, 'message' => 'السجل غير موجود أو غير مصرح']);

            return;

        }



        $conn->begin_transaction();



        // Reverse task_coupons ONLY — never touch total coupons

        $awarded = (int) $sub['coupons_awarded'];

        $uncleId = (int) ($_SESSION['uncle_id'] ?? 0);

        if ($awarded > 0) {

            $stuStmt = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");

            $stuStmt->bind_param('i', $sub['student_id']);

            $stuStmt->execute();

            $stu = $stuStmt->get_result()->fetch_assoc();

            if ($stu) {

                $newTask = max(0, (int) $stu['task_coupons'] - $awarded);

                $newTotal = $newTask + (int) $stu['attendance_coupons'] + (int) $stu['commitment_coupons'];

                $conn->query("UPDATE students SET task_coupons={$newTask}, coupons={$newTotal} WHERE id={$sub['student_id']}");

                // Log the reversal so the audit trail is complete

                $negAwarded = -$awarded;

                $reason = "حذف إجابة تاسك #{$sub['task_id']}: {$sub['title']}";

                $logStmt = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");

                $logStmt->bind_param('iiiiss', $sub['student_id'], $uncleId, $stu['task_coupons'], $newTask, $negAwarded, $reason);

                $logStmt->execute();



                // ► AUDIT

                auditCouponChange($sub['student_id'], $stu['name'] ?? '', (int) $stu['coupons'], $newTotal, $reason);

            }

        }



        // Soft delete the submission (also delete exam_start record so student can retake if needed)

        $conn->query("UPDATE task_submissions SET is_deleted = 1, deleted_at = NOW() WHERE id={$subId}");

        $conn->query("DELETE FROM exam_starts WHERE task_id={$sub['task_id']} AND student_id={$sub['student_id']}");



        $conn->commit();



        if (function_exists('writeAuditLog')) {

            writeAuditLog('delete', 'submission', $subId, "إجابة على: {$sub['title']}");

        }



        sendJSON([

            'success' => true,

            'message' => 'تم حذف الإجابة وعكس الكوبونات',

            'submission_id' => $subId,

            'task_id' => (int)$sub['task_id'],

            'student_id' => (int)$sub['student_id'],

            'coupons_reversed' => $awarded

        ]);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("deleteSubmission error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── restoreSubmission ─────────────────────────────────────────

function restoreSubmission()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $subId = (int) ($_POST['submission_id'] ?? 0);

        if (!$subId) {

            sendJSON(['success' => false, 'message' => 'submission_id مطلوب']);

