            FROM task_submissions ts

            JOIN tasks t ON t.id = ts.task_id

            WHERE ts.id = ? AND ts.church_id = ? AND ts.is_deleted = 1

        ");

        $sel->bind_param('ii', $subId, $churchId);

        $sel->execute();

        $sub = $sel->get_result()->fetch_assoc();

        if (!$sub) {

            sendJSON(['success' => false, 'message' => 'لم يتم العثور على الإجابة المحذوفة']);

            return;

        }



        $conn->begin_transaction();



        $awarded = (int) $sub['coupons_awarded'];

        $uncleId = (int) ($_SESSION['uncle_id'] ?? 0);



        if ($awarded > 0) {

            $stuStmt = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");

            $stuStmt->bind_param('i', $sub['student_id']);

            $stuStmt->execute();

            $stu = $stuStmt->get_result()->fetch_assoc();

            if ($stu) {

                $newTask = (int) $stu['task_coupons'] + $awarded;

                $newTotal = $newTask + (int) $stu['attendance_coupons'] + (int) $stu['commitment_coupons'];

                $conn->query("UPDATE students SET task_coupons={$newTask}, coupons={$newTotal} WHERE id={$sub['student_id']}");



                $reason = "تراجع عن حذف إجابة تاسك #{$sub['task_id']}: {$sub['title']}";

                $logStmt = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");

                $logStmt->bind_param('iiiiss', $sub['student_id'], $uncleId, $stu['task_coupons'], $newTask, $awarded, $reason);

                $logStmt->execute();



                auditCouponChange($sub['student_id'], $stu['name'] ?? '', (int) $stu['coupons'], $newTotal, $reason);

            }

        }



        $conn->query("UPDATE task_submissions SET is_deleted = 0, deleted_at = NULL WHERE id = {$subId}");



        $conn->commit();



        if (function_exists('writeAuditLog')) {

            writeAuditLog('restore', 'submission', $subId, "تراجع عن حذف إجابة: {$sub['title']}");

        }



        sendJSON([

            'success' => true,

            'message' => 'تم التراجع وإعادة الإجابة بنجاح 🎉',

            'task_id' => (int)$sub['task_id'],

            'student_id' => (int)$sub['student_id']

        ]);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("restoreSubmission error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}

/**
 * Calculate task coupons earned based on score, total degree, and coupon matrix / milestones.
 * Uses descending-threshold milestone matching to eliminate integer gaps and handles empty matrices.
 */
function calculateTaskCoupons($score, $totalDegree, $couponMatrix, $maxCoupons = 0)
{
    $totalDegree = (float) $totalDegree;
    $score = (float) $score;
    $maxCoupons = (int) $maxCoupons;

    if ($totalDegree <= 0) {
        $pct = ($score > 0) ? 100.0 : 0.0;
    } else {
        $pct = ($score / $totalDegree) * 100.0;
    }
    if ($pct > 100.0) $pct = 100.0;
    if ($pct < 0.0) $pct = 0.0;

    $matrix = [];
    if (is_array($couponMatrix)) {
        $matrix = $couponMatrix;
    } elseif (is_string($couponMatrix) && trim($couponMatrix) !== '') {
        $decoded = json_decode($couponMatrix, true);
        if (is_array($decoded)) {
            $matrix = $decoded;
        }
    }

    $effectiveMax = ($maxCoupons > 0) ? $maxCoupons : 100;
    $standardMilestones = [
        ['pct' => 95.0, 'val' => $effectiveMax],
        ['pct' => 85.0, 'val' => (int) round($effectiveMax * 0.50)],
        ['pct' => 70.0, 'val' => (int) round($effectiveMax * 0.30)],
        ['pct' => 50.0, 'val' => (int) round($effectiveMax * 0.10)],
    ];

    $milestones = [];
    foreach ($matrix as $item) {
        if (!is_array($item)) continue;
        $threshold = isset($item['from']) ? (float)$item['from'] : (isset($item['pct']) ? (float)$item['pct'] : 0.0);
        $val = isset($item['val']) ? (int)$item['val'] : (isset($item['coupons']) ? (int)$item['coupons'] : 0);
        if ($val > 0) {
            $milestones[] = [
                'pct' => $threshold,
                'val' => $val
            ];
        }
    }

    if (empty($milestones)) {
        $milestones = $standardMilestones;
    }

    usort($milestones, function ($a, $b) {
        if ($b['pct'] == $a['pct']) {
            return $b['val'] <=> $a['val'];
        }
        return ($b['pct'] > $a['pct']) ? 1 : -1;
    });

    $roundedIntPct = (int) round($pct);

    foreach ($milestones as $m) {
        // Match if raw percentage >= threshold (with float epsilon) OR rounded integer reaches threshold
        if ($pct >= ($m['pct'] - 0.001) || $roundedIntPct >= (int)$m['pct']) {
            return (int) $m['val'];
        }
    }

    // Lowest percentage milestone always covers that percent and anything under it (as long as score > 0)
    if ($score > 0 && !empty($milestones)) {
        $lowestMilestone = end($milestones);
        return (int) $lowestMilestone['val'];
    }

    return 0;
}

/**
 * Automatically finalize submissions and award coupons for tasks that have no open/review questions (or already graded).
 * Ensures students never get 0 coupons for full marks or slight lower marks due to matrix gaps.
 */
function syncTaskSubmissionsForTask($conn, $taskId, $actingUncleId = 0)
{
    $taskId = (int) $taskId;
    if ($taskId <= 0) return;

    $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_graded TINYINT(1) NOT NULL DEFAULT 0");
    $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS coupons_awarded INT NOT NULL DEFAULT 0");
    $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS graded_by_uncle_id INT DEFAULT NULL");
    $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS graded_at DATETIME DEFAULT NULL");

    // Check questions of this task
    $qStmt = $conn->prepare("SELECT id, question_type, correct_index, degree FROM task_questions WHERE task_id=? ORDER BY sort_order ASC, id ASC");
    if (!$qStmt) return;
    $qStmt->bind_param('i', $taskId);
    $qStmt->execute();
    $questions = $qStmt->get_result()->fetch_all(MYSQLI_ASSOC);
    $qStmt->close();

    $hasOpenQuestions = false;
    $totalQuestionDegrees = 0;
    foreach ($questions as $q) {
        $deg = isset($q['degree']) ? (int) $q['degree'] : 1;
        if ($deg > 0) $totalQuestionDegrees += $deg;
        // Only open questions with positive degree require manual grading
        if (($q['question_type'] ?? 'mcq') === 'open' && $deg > 0) {
            $hasOpenQuestions = true;
        }
    }

    // Load task metadata
    $tStmt = $conn->prepare("SELECT total_degree, max_coupons, coupon_matrix, church_id FROM tasks WHERE id=? LIMIT 1");
    if (!$tStmt) return;
    $tStmt->bind_param('i', $taskId);
    $tStmt->execute();
    $task = $tStmt->get_result()->fetch_assoc();
    $tStmt->close();
    if (!$task) return;

    $totalDegree = (int) ($task['total_degree'] ?? 0);
    if ($totalDegree <= 0 && $totalQuestionDegrees > 0) {
        $totalDegree = $totalQuestionDegrees;
        $conn->query("UPDATE tasks SET total_degree={$totalDegree} WHERE id={$taskId}");
    }
    $maxCoupons = (int) ($task['max_coupons'] ?? 0);
    $couponMatrix = $task['coupon_matrix'] ?? '[]';

    // Find submissions for this task that are not deleted
    $subStmt = $conn->prepare("
        SELECT id, student_id, answers, score, coupons_awarded, is_graded, open_scores 
        FROM task_submissions 
        WHERE task_id=? AND (is_deleted IS NULL OR is_deleted = 0)
    ");
    if (!$subStmt) return;
    $subStmt->bind_param('i', $taskId);
    $subStmt->execute();
    $subs = $subStmt->get_result()->fetch_all(MYSQLI_ASSOC);
    $subStmt->close();

    foreach ($subs as $s) {
        $oldCoupons = (int)($s['coupons_awarded'] ?? 0);
        $oldIsGraded = (int)($s['is_graded'] ?? 0);
        $oldScore = (int)($s['score'] ?? 0);

        // If the task has open questions that require manual review and this submission has not been graded yet,
        // it must wait for the servant to grade it.
        if ($hasOpenQuestions && $oldIsGraded !== 1) {
            continue;
        }

        $answers = json_decode($s['answers'] ?? '{}', true) ?: [];
        $mcqScore = 0;
        foreach ($questions as $q) {
            $deg = isset($q['degree']) ? (int)$q['degree'] : 1;
            if ($deg <= 0 || ($q['question_type'] ?? 'mcq') === 'open' || $q['correct_index'] === null) continue;
            $given = $answers[$q['id']] ?? $answers[(string)$q['id']] ?? null;
            if ($given !== null && (int)$given === (int)$q['correct_index']) {
                $mcqScore += $deg;
            }
        }

        $openScore = 0;
        if (!empty($s['open_scores'])) {
            $openScores = json_decode($s['open_scores'], true) ?: [];
            foreach ($openScores as $os) {
                $openScore += (int)$os;
            }
        }

        $finalScore = $mcqScore + $openScore;
        if ($oldScore > 0 && ($finalScore <= 0 || $oldScore > $finalScore)) {
            $finalScore = $oldScore;
        }

        $coupons = calculateTaskCoupons($finalScore, $totalDegree, $couponMatrix, $maxCoupons);
        $couponDiff = $coupons - $oldCoupons;

        if ($oldIsGraded !== 1 || $oldCoupons !== $coupons || $oldScore !== $finalScore) {
            $upd = $conn->prepare("
                UPDATE task_submissions 
                SET score=?, coupons_awarded=?, is_graded=1,
                    graded_by_uncle_id = IF(? > 0 AND (graded_by_uncle_id IS NULL OR graded_by_uncle_id = 0), ?, graded_by_uncle_id),
                    graded_at = IF(graded_at IS NULL, NOW(), graded_at)
                WHERE id=?
            ");
            if ($upd) {
                $upd->bind_param('iiiii', $finalScore, $coupons, $actingUncleId, $actingUncleId, $s['id']);
                $upd->execute();
                $upd->close();
            }

            // Check student balance and existing logs
            $stuQ = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");
            if ($stuQ) {
                $stuQ->bind_param('i', $s['student_id']);
                $stuQ->execute();
                $stu = $stuQ->get_result()->fetch_assoc();
                $stuQ->close();
                if ($stu) {
                    $logChk = $conn->prepare("SELECT COUNT(*) as c FROM coupon_logs WHERE student_id=? AND change_type='task' AND reason LIKE ?");
                    $reasonSearch = "%#{$taskId}%";
                    $logChk->bind_param('is', $s['student_id'], $reasonSearch);
                    $logChk->execute();
                    $hasLog = (int)($logChk->get_result()->fetch_assoc()['c'] ?? 0) > 0;
                    $logChk->close();

                    // Credit missing coupons (either the positive diff or if student never had log and task_coupons < coupons)
                    $toCredit = 0;
                    if (!$hasLog && $coupons > 0 && (int)$stu['task_coupons'] < $coupons) {
                        $toCredit = $coupons;
                    } elseif ($couponDiff > 0) {
                        $toCredit = $couponDiff;
                    }

                    if ($toCredit > 0) {
                        $newTask = (int)$stu['task_coupons'] + $toCredit;
                        $newTotal = $newTask + (int)$stu['attendance_coupons'] + (int)$stu['commitment_coupons'];
                        $conn->query("UPDATE students SET task_coupons={$newTask}, coupons={$newTotal} WHERE id={$s['student_id']}");
                        
                        $reason = "اعتماد نتيجة تاسك #{$taskId}: {$finalScore}/{$totalDegree} (+{$toCredit} كوبون)";
                        $log = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");
                        if ($log) {
                            $log->bind_param('iiiiss', $s['student_id'], $actingUncleId, $stu['task_coupons'], $newTask, $toCredit, $reason);
                            $log->execute();
                            $log->close();
                        }

                        if (function_exists('auditCouponChange')) {
                            auditCouponChange($s['student_id'], $stu['name'] ?? '', (int)$stu['coupons'], $newTotal, $reason);
                        }
                    }
                }
            }
        }
    }
}

/**
 * Retroactively reconciles all tasks and submissions that do not require manual review.
 * Fixes 0 coupons awarded for full marks / slight lower marks across the entire church.
 */
function retroactiveFixTaskCoupons($conn, $churchId = 0, $actingUncleId = 0)
{
    $churchFilter = ($churchId > 0) ? "WHERE church_id = " . (int)$churchId : "";
    $tRes = $conn->query("SELECT id FROM tasks {$churchFilter} ORDER BY id ASC");
    if (!$tRes) return ['success' => false, 'fixed_tasks' => 0];

    $fixedCount = 0;
    while ($tRow = $tRes->fetch_assoc()) {
        $taskId = (int)$tRow['id'];
        syncTaskSubmissionsForTask($conn, $taskId, $actingUncleId);
        $fixedCount++;
    }

    return ['success' => true, 'fixed_tasks' => $fixedCount];
}

// ─── updateTask ────────────────────────────────────────────────

function updateTask()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $uncleId = (int) ($_SESSION['uncle_id'] ?? 0);

        $uncleRole = strtolower($_SESSION['uncle_role'] ?? '');

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$taskId) {

            sendJSON(['success' => false, 'message' => 'task_id مطلوب']);

            return;

        }



        if (!in_array($uncleRole, ['admin', 'developer', 'church'])) {

            $chk = $conn->prepare("SELECT uncle_id FROM tasks WHERE id=? AND church_id=?");

            $chk->bind_param('ii', $taskId, $churchId);

            $chk->execute();

            $r = $chk->get_result()->fetch_assoc();

            if (!$r || (int) $r['uncle_id'] !== $uncleId) {

                sendJSON(['success' => false, 'message' => 'غير مصرح بتعديل هذا التاسك']);

                return;

            }

        }



        $title = sanitize($_POST['title'] ?? '');

        $description = sanitize($_POST['description'] ?? '');

        $className = sanitize($_POST['class_name'] ?? '');

        $classId = (int) ($_POST['class_id'] ?? 0);

        $assignTo = in_array($_POST['assign_to'] ?? 'all', ['all', 'specific']) ? $_POST['assign_to'] : 'all';

        $specificIds = $_POST['specific_ids'] ?? '[]';

        $startDate = sanitize($_POST['start_date'] ?? '');

        $endDateRaw = trim($_POST['end_date'] ?? '');

        $noDeadline = (int) ($_POST['no_deadline'] ?? 0) ? 1 : 0;

        $endDate = $noDeadline ? '9999-12-31 23:59:59' : sanitize($endDateRaw);

        $timeLimit = !empty($_POST['time_limit']) ? (int) $_POST['time_limit'] : null;

        $timerBeh = in_array($_POST['timer_behavior'] ?? 'submit', ['submit', 'lock']) ? $_POST['timer_behavior'] : 'submit';

        $totalDegree = (int) ($_POST['total_degree'] ?? 0);

        $maxCoupons = (int) ($_POST['max_coupons'] ?? 0);

        $couponMatrix = $_POST['coupon_matrix'] ?? '[]';

        $status = in_array($_POST['status'] ?? 'published', ['draft', 'published', 'archived']) ? $_POST['status'] : 'published';

        $shuffle = (int) ($_POST['shuffle'] ?? 0);

        $shuffleAnswers = (int) ($_POST['shuffle_answers'] ?? 0);

        $showResult = (int) ($_POST['show_result'] ?? 1);

        $showAnswers = (int) ($_POST['show_answers'] ?? 0);

        $allowReview = (int) ($_POST['allow_review'] ?? 1);

        $questionsJson = $_POST['questions'] ?? '[]';

        $groupName = sanitize($_POST['group_name'] ?? '');

        $groupIcon = sanitize($_POST['group_icon'] ?? '');



        if (!$classId && $className) {

            $cStmt = $conn->prepare("SELECT id FROM church_classes WHERE church_id=? AND arabic_name=? LIMIT 1");

            $cStmt->bind_param('is', $churchId, $className);

            $cStmt->execute();

            $cRow = $cStmt->get_result()->fetch_assoc();

            if ($cRow)

                $classId = (int) $cRow['id'];

        }



        $classIdsRaw = sanitize($_POST['class_ids'] ?? '');
        $parsedIds = array_values(array_unique(array_filter(array_map('intval', explode(',', $classIdsRaw)), function($v){ return $v >= 0; })));
        if (empty($parsedIds)) {
            if ($classId > 0) $parsedIds = [$classId];
            else $parsedIds = [0];
        }
        if (in_array(0, $parsedIds)) {
            $classId = 0;
            $classIds = '0';
        } else {
            $classId = $parsedIds[0];
            $classIds = implode(',', $parsedIds);
        }

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS no_deadline TINYINT(1) NOT NULL DEFAULT 0 AFTER end_date");

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS class_ids VARCHAR(255) NULL AFTER class_id");

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_name VARCHAR(255) NULL");

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_icon VARCHAR(255) NULL");

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS shuffle_answers TINYINT(1) NOT NULL DEFAULT 0");

        $conn->begin_transaction();



        $stmt = $conn->prepare("

            UPDATE tasks SET

                class_id=?, class_ids=?, title=?, description=?,

                start_date=?, end_date=?, no_deadline=?, time_limit=?, timer_behavior=?,

                total_degree=?, max_coupons=?, coupon_matrix=?,

                status=?, assign_to=?, specific_ids=?,

                shuffle=?, shuffle_answers=?, show_result=?, show_answers=?, allow_review=?,

                group_name=?, group_icon=?,

                updated_at=NOW()

            WHERE id=? AND church_id=?

        ");

        $stmt->bind_param(

            'isssssiisiissssiiiiissii',

            $classId,

            $classIds,

            $title,

            $description,

            $startDate,

            $endDate,

            $noDeadline,

            $timeLimit,

            $timerBeh,

            $totalDegree,

            $maxCoupons,

            $couponMatrix,

            $status,

            $assignTo,

            $specificIds,

            $shuffle,

            $shuffleAnswers,

            $showResult,

            $showAnswers,

            $allowReview,

            $groupName,

            $groupIcon,

            $taskId,

            $churchId

        );

        $stmt->execute();



        // Load existing questions for this task to preserve their IDs across edits
        $oldQsStmt = $conn->prepare("SELECT id, sort_order FROM task_questions WHERE task_id=? ORDER BY sort_order ASC, id ASC");
        $oldQsStmt->bind_param('i', $taskId);
        $oldQsStmt->execute();
        $oldQs = $oldQsStmt->get_result()->fetch_all(MYSQLI_ASSOC);
        $existingQids = array_column($oldQs, 'id');
        $unclaimedOldIds = $existingQids;

        $questions = json_decode($questionsJson, true) ?: [];
        $keptQids = [];
        $oldToNewMap = [];

        $updQStmt = $conn->prepare("UPDATE task_questions SET question_type=?, question_text=?, options=?, correct_index=?, degree=?, sort_order=?, image_url=? WHERE id=? AND task_id=?");
        $insQStmt = $conn->prepare("INSERT INTO task_questions (task_id, question_type, question_text, options, correct_index, degree, sort_order, image_url) VALUES (?, ?, ?, ?, ?, ?, ?, ?)");

        foreach ($questions as $i => $q) {
            $type = in_array($q['question_type'] ?? 'mcq', ['mcq', 'open', 'tf']) ? $q['question_type'] : 'mcq';
            $text = $q['question_text'] ?? '';
            $opts = $type === 'open' ? '[]' : (is_array($q['options']) ? json_encode($q['options'], JSON_UNESCAPED_UNICODE) : ($q['options'] ?? '[]'));
            $correct = ($type === 'open') ? null : (int) ($q['correct_index'] ?? 0);
            $degree = isset($q['degree']) ? max(0, (int) $q['degree']) : 1;
            $order = (int) ($q['sort_order'] ?? $i);
            $imageUrl = $q['image_url'] ?? '';

            $targetId = null;
            if (!empty($q['id']) && in_array((int)$q['id'], $unclaimedOldIds)) {
                $targetId = (int)$q['id'];
            } elseif (!empty($unclaimedOldIds)) {
                $targetId = array_shift($unclaimedOldIds);
            }

            if ($targetId !== null) {
                $unclaimedOldIds = array_values(array_filter($unclaimedOldIds, fn($id) => $id !== $targetId));
                $keptQids[] = $targetId;
                $updQStmt->bind_param('ssssiisii', $type, $text, $opts, $correct, $degree, $order, $imageUrl, $targetId, $taskId);
                $updQStmt->execute();
                if (!empty($q['id']) && (int)$q['id'] !== $targetId) {
                    $oldToNewMap[(int)$q['id']] = $targetId;
                }
            } else {
                $insQStmt->bind_param('issssiis', $taskId, $type, $text, $opts, $correct, $degree, $order, $imageUrl);
                $insQStmt->execute();
                $newId = (int)$conn->insert_id;
                $keptQids[] = $newId;
                if (!empty($q['id'])) {
                    $oldToNewMap[(int)$q['id']] = $newId;
                }
            }
        }

        // Delete questions that were removed
        $toDelete = array_diff($existingQids, $keptQids);
        if (!empty($toDelete)) {
            $inList = implode(',', array_map('intval', $toDelete));
            $conn->query("DELETE FROM task_questions WHERE id IN ($inList) AND task_id=$taskId");
        }

        // Load questions in final sort order
        $newQsStmt = $conn->prepare("SELECT id, question_type, correct_index, degree, sort_order FROM task_questions WHERE task_id=? ORDER BY sort_order ASC, id ASC");
        $newQsStmt->bind_param('i', $taskId);
        $newQsStmt->execute();
        $newQs = $newQsStmt->get_result()->fetch_all(MYSQLI_ASSOC);

        $hasAnyOpenQuestions = false;
        foreach ($newQs as $q) {
            if (($q['question_type'] ?? 'mcq') === 'open' && (int)($q['degree'] ?? 1) > 0) {
                $hasAnyOpenQuestions = true;
                break;
            }
        }

        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_graded TINYINT(1) NOT NULL DEFAULT 0");
        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS graded_by_uncle_id INT DEFAULT NULL");
        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS graded_at DATETIME DEFAULT NULL");

        // Load all submissions for this task
        $allSubsStmt = $conn->prepare("SELECT id, student_id, answers, score AS old_score, coupons_awarded AS old_coupons, open_scores, correction_notes, is_graded FROM task_submissions WHERE task_id=? AND (is_deleted IS NULL OR is_deleted = 0)");
        $allSubsStmt->bind_param('i', $taskId);
        $allSubsStmt->execute();
        $allSubs = $allSubsStmt->get_result()->fetch_all(MYSQLI_ASSOC);

        $newMatrix = json_decode($couponMatrix, true) ?: [];

        foreach ($allSubs as $sub) {
            $answers = json_decode($sub['answers'] ?? '{}', true) ?: [];
            $openScores = json_decode($sub['open_scores'] ?? '{}', true) ?: [];
            $corrNotes = json_decode($sub['correction_notes'] ?? '{}', true) ?: [];

            $newAnswers = [];
            foreach ($answers as $qid => $ansVal) {
                $newQid = $oldToNewMap[(int)$qid] ?? $qid;
                $newAnswers[$newQid] = $ansVal;
            }

            $newOpenScores = [];
            foreach ($openScores as $qid => $scoreVal) {
                $newQid = $oldToNewMap[(int)$qid] ?? $qid;
                $newOpenScores[$newQid] = $scoreVal;
            }

            $newCorrNotes = [];
            foreach ($corrNotes as $qid => $noteVal) {
                $newQid = $oldToNewMap[(int)$qid] ?? $qid;
                $newCorrNotes[$newQid] = $noteVal;
            }

            $answersJson = json_encode($newAnswers, JSON_UNESCAPED_UNICODE);
            $openScoresJson = json_encode($newOpenScores, JSON_UNESCAPED_UNICODE);
            $corrNotesJson = !empty($newCorrNotes) ? json_encode($newCorrNotes, JSON_UNESCAPED_UNICODE) : null;

            $mcqScore = 0;
            $openScore = 0;
            $hasUnscoredOpenQ = false;

            foreach ($newQs as $q) {
                if (($q['question_type'] ?? 'mcq') === 'open') {
                    if ((int)($q['degree'] ?? 1) <= 0) continue;
                    $qidStr = (string) $q['id'];
                    if (isset($newOpenScores[$q['id']]) && $newOpenScores[$q['id']] !== null && $newOpenScores[$q['id']] !== '') {
                        $openScore += (int) $newOpenScores[$q['id']];
                    } elseif (isset($newOpenScores[$qidStr]) && $newOpenScores[$qidStr] !== null && $newOpenScores[$qidStr] !== '') {
                        $openScore += (int) $newOpenScores[$qidStr];
                    } else {
                        $hasUnscoredOpenQ = true;
                    }
                } else {
                    if ($q['correct_index'] === null)
                        continue;

                    $given = $newAnswers[$q['id']] ?? $newAnswers[(string) $q['id']] ?? null;
                    if ($given !== null && (int) $given === (int) $q['correct_index']) {
                        $mcqScore += (int) $q['degree'];
                    }
                }
            }

            $newScore = $mcqScore + $openScore;

            // Determine if submission is finalized/graded:
            // If after edit there are NO open review questions in the task, it is ALWAYS graded (is_graded = 1)!
            if (!$hasAnyOpenQuestions) {
                $isGraded = 1;
            } elseif (!$hasUnscoredOpenQ) {
                $isGraded = 1;
            } else {
                $isGraded = 0;
            }

            // Compute new coupons from matrix (only awarded if graded)
            $newCoupons = ($isGraded === 1) ? calculateTaskCoupons($newScore, $totalDegree, $newMatrix, $maxCoupons) : 0;

            $oldScore = (int) $sub['old_score'];
            $oldCoupons = (int) $sub['old_coupons'];
            $oldIsGraded = (int) ($sub['is_graded'] ?? 0);
            $couponDiff = $newCoupons - $oldCoupons;

            // Update submission score, coupons, is_graded, and rewritten answers/scores/notes
            $updSub = $conn->prepare("
                UPDATE task_submissions 
                SET score=?, coupons_awarded=?, answers=?, open_scores=?, correction_notes=?, is_graded=?,
                    graded_by_uncle_id = IF(?=1 AND (graded_by_uncle_id IS NULL OR graded_by_uncle_id=0), ?, graded_by_uncle_id),
                    graded_at = IF(?=1 AND graded_at IS NULL, NOW(), graded_at)
                WHERE id=?
            ");
            $updSub->bind_param('iisssiiiii', $newScore, $newCoupons, $answersJson, $openScoresJson, $corrNotesJson, $isGraded, $isGraded, $uncleId, $isGraded, $sub['id']);
            $updSub->execute();

            // Apply coupon diff to student
            if ($couponDiff !== 0) {
                $stuQ2 = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");
                $stuQ2->bind_param('i', $sub['student_id']);
                $stuQ2->execute();
                $stu2 = $stuQ2->get_result()->fetch_assoc();

                if ($stu2) {
                    $newTask2 = max(0, (int) $stu2['task_coupons'] + $couponDiff);
                    $newTotal2 = $newTask2 + (int) $stu2['attendance_coupons'] + (int) $stu2['commitment_coupons'];

                    $conn->query("UPDATE students SET task_coupons={$newTask2}, coupons={$newTotal2} WHERE id={$sub['student_id']}");

                    // Log
                    if ($oldIsGraded === 0 && $isGraded === 1) {
                        $reason2 = "اعتماد نتيجة تاسك #{$taskId}: {$newScore}/{$totalDegree} (+{$couponDiff} كوبون)";
                    } else {
                        $reason2 = "تحديث تاسك #{$taskId}: تعديل درجة {$oldScore}→{$newScore}";
                    }

                    $log2 = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");
                    $log2->bind_param('iiiiss', $sub['student_id'], $uncleId, $stu2['task_coupons'], $newTask2, $couponDiff, $reason2);
                    $log2->execute();

                    // ► AUDIT
                    auditCouponChange($sub['student_id'], $stu2['name'] ?? '', (int) $stu2['coupons'], $newTotal2, $reason2);
                }
            }
        }

        // Send announcement to notify kids of the update
        if ($status === 'published') {
            $notifiedClass = '';
            $notifiedStudents = '';
            if ($assignTo === 'specific') {
                $specArray = json_decode($specificIds, true) ?: [];
                if (!empty($specArray)) {
                    $specIdsStr = implode(',', array_map('intval', $specArray));
                    $stuQ = $conn->query("SELECT name FROM students WHERE id IN ($specIdsStr) AND church_id = $churchId");
                    $names = [];
                    while ($sRow = $stuQ->fetch_assoc()) {
                        $names[] = $sRow['name'];
                    }
                    $notifiedStudents = implode(',', $names);
                }
            } else {
                if ($classId == 0) {
                    $notifiedClass = 'الجميع';
                } else {
                    $classIdsArray = array_filter(array_map('intval', explode(',', $classIds)));
                    if (!empty($classIdsArray)) {
                        $classIdsStr = implode(',', $classIdsArray);
                        $classQ = $conn->query("SELECT arabic_name FROM church_classes WHERE id IN ($classIdsStr) AND church_id = $churchId");
                        $classNames = [];
                        while ($cRow = $classQ->fetch_assoc()) {
                            $classNames[] = $cRow['arabic_name'];
                        }
                        $notifiedClass = implode(',', $classNames);
                    } else {
                        $notifiedClass = $className; // fallback
                    }
                }
            }

            // Check if there's any target class or student
            if ($notifiedClass !== '' || $notifiedStudents !== '') {
                $annText = "تم تعديل التاسك: " . $title . " وتحديث الكوبونات الخاصة بها.";
                $annStmt = $conn->prepare("INSERT INTO announcements (church_id, type, text, link, class, student_names, is_active, created_at) VALUES (?, 'task', ?, '', ?, ?, 1, NOW())");
                $annStmt->bind_param('isss', $churchId, $annText, $notifiedClass, $notifiedStudents);
                $annStmt->execute();
            }

            $extra = ['notifType' => 'task', 'url' => '/user/'];
            if ($assignTo === 'specific') {
                $dec = json_decode($specificIds, true);
                if (is_array($dec) && !empty($dec)) {
                    $cleanIds = implode(',', array_map('intval', $dec));
                    $extra['student_ids'] = $cleanIds;
                }
            } else {
                if ($classId === 0 || $classIds === '0') {
                    $extra['class_ids'] = null;
                } else {
                    $extra['class_ids'] = $classIds;
                }
            }
            _sendWebPushToKids($conn, $churchId, 'تحديث تاسك 📝', "تم تحديث التاسك: {$title}", $extra);
        }

        $conn->commit();



        if (function_exists('writeAuditLog')) {

            writeAuditLog('update', 'task', $taskId, $title);

        }



        sendJSON(['success' => true, 'message' => 'تم تحديث التاسك وإعادة حساب نتائج الأطفال']);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("updateTask error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── bulkClassifyTasks ──────────────────────────────────────────

function bulkClassifyTasks()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $taskIds = json_decode($_POST['task_ids'] ?? '[]', true) ?: [];

        $groupName = sanitize($_POST['group_name'] ?? '');

        $groupIcon = sanitize($_POST['group_icon'] ?? 'fa-folder');



        if (empty($taskIds)) {

            sendJSON(['success' => false, 'message' => 'لم يتم تحديد أي تاسكات']);

            return;

        }



        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_name VARCHAR(255) NULL");

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS group_icon VARCHAR(255) NULL");



        $placeholders = implode(',', array_fill(0, count($taskIds), '?'));

        $types = 'ss' . str_repeat('i', count($taskIds)) . 'i';



        $stmt = $conn->prepare("UPDATE tasks SET group_name = ?, group_icon = ? WHERE id IN ($placeholders) AND church_id = ?");



        $bindParams = array_merge([$groupName, $groupIcon], array_map('intval', $taskIds), [$churchId]);

        $stmt->bind_param($types, ...$bindParams);

        $stmt->execute();



        sendJSON(['success' => true, 'message' => 'تم تصنيف التاسكات المحددة بنجاح']);

    } catch (Exception $e) {

        error_log("bulkClassifyTasks error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── deleteTask ────────────────────────────────────────────────

function deleteTask()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $uncleId = (int) ($_SESSION['uncle_id'] ?? 0);

        $uncleRole = strtolower($_SESSION['uncle_role'] ?? '');

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$taskId) {

            sendJSON(['success' => false, 'message' => 'task_id مطلوب']);

            return;

        }



        if (!in_array($uncleRole, ['admin', 'developer', 'church'])) {

            $chk = $conn->prepare("SELECT uncle_id FROM tasks WHERE id=? AND church_id=?");

            $chk->bind_param('ii', $taskId, $churchId);

            $chk->execute();

            $r = $chk->get_result()->fetch_assoc();

            if (!$r || (int) $r['uncle_id'] !== $uncleId) {

                sendJSON(['success' => false, 'message' => 'غير مصرح']);

                return;

            }

        }



        // reverse_coupons=1 -> withdraw coupons from kids, reverse_coupons=0 -> keep them

        $reverseCoupons = isset($_POST['reverse_coupons']) ? (int) $_POST['reverse_coupons'] : 1;



        $conn->begin_transaction();



        // Handle coupons for all submissions before deleting

        $totalReversed = 0;

        $subsStmt = $conn->prepare("SELECT student_id, coupons_awarded FROM task_submissions WHERE task_id=? AND coupons_awarded > 0");

        $subsStmt->bind_param('i', $taskId);

        $subsStmt->execute();

        $subsRows = $subsStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        foreach ($subsRows as $subRow) {

            $awarded = (int) $subRow['coupons_awarded'];

            if ($awarded <= 0)

                continue;



            if ($reverseCoupons) {

                // Withdraw the coupons from the student

                $stuQ = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");

                $stuQ->bind_param('i', $subRow['student_id']);

                $stuQ->execute();

                $stu = $stuQ->get_result()->fetch_assoc();

                if ($stu) {

                    $newTask = max(0, (int) $stu['task_coupons'] - $awarded);

                    $newTotal = $newTask + (int) $stu['attendance_coupons'] + (int) $stu['commitment_coupons'];

                    $conn->query("UPDATE students SET task_coupons={$newTask}, coupons={$newTotal} WHERE id={$subRow['student_id']}");

                    $totalReversed += $awarded;

                    $reason = "حذف تاسك #{$taskId} (مع سحب الكوبونات)";

                    $negAwarded = -$awarded;

                    $log = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");

                    $log->bind_param('iiiiss', $subRow['student_id'], $uncleId, $stu['task_coupons'], $newTask, $negAwarded, $reason);

                    $log->execute();



                    // ► AUDIT

                    auditCouponChange($subRow['student_id'], $stu['name'] ?? '', (int) $stu['coupons'], $newTotal, $reason);

                }

            } else {

                // Keep the coupons — just log that the task was removed but coupons were retained

                $stuQ = $conn->prepare("SELECT task_coupons FROM students WHERE id=? LIMIT 1");

                $stuQ->bind_param('i', $subRow['student_id']);

                $stuQ->execute();

                $stu = $stuQ->get_result()->fetch_assoc();

                if ($stu) {

                    $reason = "حذف تاسك #{$taskId} (الكوبونات محتفظ بها)";

                    $zero = 0;

                    $log = $conn->prepare("INSERT INTO coupon_logs (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason) VALUES (?,?,?,?,?,'task',?)");

                    $log->bind_param('iiiiss', $subRow['student_id'], $uncleId, $stu['task_coupons'], $stu['task_coupons'], $zero, $reason);

                    $log->execute();

                }

            }

        }



        // Also delete exam_starts

        $conn->query("DELETE FROM exam_starts WHERE task_id = " . $taskId);

        // Delete children

        $conn->query("DELETE FROM task_questions   WHERE task_id = " . $taskId);

        $conn->query("DELETE FROM task_submissions WHERE task_id = " . $taskId);



        $del = $conn->prepare("DELETE FROM tasks WHERE id=? AND church_id=?");

        $del->bind_param('ii', $taskId, $churchId);

        $del->execute();



        $conn->commit();



        if (function_exists('writeAuditLog')) {

            writeAuditLog('delete', 'task', $taskId, 'deleted');

        }



        $msg = $reverseCoupons ? 'تم حذف التاسك وسحب الكوبونات' : 'تم حذف التاسك والكوبونات محتفظ بها';

        sendJSON(['success' => true, 'message' => $msg, 'coupons_reversed' => $totalReversed, 'reverse_coupons' => $reverseCoupons]);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("deleteTask error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── getStudentTasks (kid-facing) ──────────────────────────────

function getStudentTasks()

{

    try {

        $conn = getDBConnection();

        $studentId = (int) ($_POST['student_id'] ?? 0);

        $churchId = (int) ($_POST['church_id'] ?? getChurchId());



        if (!$studentId) {

            sendJSON(['success' => false, 'message' => 'student_id مطلوب']);

            return;

        }



        // Get student class_id and class name
        $sStmt = $conn->prepare("SELECT id, class_id, class FROM students WHERE id=? AND church_id=? LIMIT 1");
        $sStmt->bind_param('ii', $studentId, $churchId);
        $sStmt->execute();
        $stu = $sStmt->get_result()->fetch_assoc();
        if (!$stu) {
            sendJSON(['success' => false, 'message' => 'الطفل غير موجود']);
            return;
        }

        $classId = (int) ($stu['class_id'] ?? 0);
        $studentClassName = trim((string)($stu['class'] ?? ''));

        // If classId is missing/0 but student has class name, resolve it from church_classes / classes
        if ($classId <= 0 && !empty($studentClassName)) {
            $cLookup = $conn->prepare("SELECT id FROM church_classes WHERE church_id=? AND (arabic_name=? OR code=?) UNION SELECT id FROM classes WHERE (arabic_name=? OR code=?) LIMIT 1");
            $cLookup->bind_param('issss', $churchId, $studentClassName, $studentClassName, $studentClassName, $studentClassName);
            $cLookup->execute();
            $cFound = $cLookup->get_result()->fetch_assoc();
            if ($cFound && !empty($cFound['id'])) {
                $classId = (int)$cFound['id'];
                @$conn->query("UPDATE students SET class_id = {$classId} WHERE id = {$studentId} AND church_id = {$churchId}");
            }
        } elseif ($classId > 0 && empty($studentClassName)) {
            $cLookup = $conn->prepare("SELECT arabic_name FROM church_classes WHERE id=? AND church_id=? UNION SELECT arabic_name FROM classes WHERE id=? LIMIT 1");
            $cLookup->bind_param('iii', $classId, $churchId, $classId);
            $cLookup->execute();
            $cFound = $cLookup->get_result()->fetch_assoc();
            if ($cFound && !empty($cFound['arabic_name'])) {
                $studentClassName = trim($cFound['arabic_name']);
                @$conn->query("UPDATE students SET class = '" . $conn->real_escape_string($studentClassName) . "' WHERE id = {$studentId} AND church_id = {$churchId}");
            }
        }

        // Collect all related class IDs for this student (handles church_classes vs global classes)
        $studentClassIds = [];
        if ($classId > 0) {
            $studentClassIds[] = $classId;
        }
        if (!empty($studentClassName)) {
            $cLookupAll = $conn->prepare("SELECT id FROM church_classes WHERE church_id=? AND (arabic_name=? OR code=?) UNION SELECT id FROM classes WHERE (arabic_name=? OR code=?)");
            $cLookupAll->bind_param('issss', $churchId, $studentClassName, $studentClassName, $studentClassName, $studentClassName);
            $cLookupAll->execute();
            $cAllRes = $cLookupAll->get_result();
            while ($cRow = $cAllRes->fetch_assoc()) {
                if (!empty($cRow['id'])) $studentClassIds[] = (int)$cRow['id'];
            }
        }
        $studentClassIds = array_values(array_unique(array_filter($studentClassIds)));

        $conn->query("ALTER TABLE tasks ADD COLUMN IF NOT EXISTS class_ids VARCHAR(255) NULL AFTER class_id");

        // Detect which optional task columns exist using SHOW COLUMNS (no information_schema needed)
        $allCols = [];
        $colRes = $conn->query("SHOW COLUMNS FROM tasks");
        while ($cr = $colRes->fetch_assoc())
            $allCols[] = $cr['Field'];

        $hasStatus = in_array('status', $allCols);
        $hasAssignTo = in_array('assign_to', $allCols);
        $hasTimer = in_array('timer_behavior', $allCols);
        $hasShuffle = in_array('shuffle', $allCols);
        $hasShuffleAnswers = in_array('shuffle_answers', $allCols);
        $hasShow = in_array('show_result', $allCols);
        $hasShowAnswers = in_array('show_answers', $allCols);
        $hasReview = in_array('allow_review', $allCols);
        $hasIsActive = in_array('is_active', $allCols);
        $hasNoDeadline = in_array('no_deadline', $allCols);
        $hasClassIds = in_array('class_ids', $allCols);

        // Build SELECT dynamically based on existing columns
        $sel = "t.id, t.title, t.description, t.start_date, t.end_date,
                t.time_limit, t.total_degree, t.max_coupons, t.coupon_matrix,
                CASE
                    WHEN t.class_id = 0 THEN 'كل الفصول'
                    ELSE COALESCE(cc.arabic_name,'')
                END AS class_name";
        if ($hasStatus)
            $sel .= ", t.status";
        if ($hasAssignTo)
            $sel .= ", t.assign_to, t.specific_ids";
        if ($hasTimer)
            $sel .= ", t.timer_behavior";
        if ($hasShuffle)
            $sel .= ", t.shuffle";
        if ($hasShuffleAnswers)
            $sel .= ", t.shuffle_answers";
        if ($hasShow)
            $sel .= ", t.show_result";
        if ($hasShowAnswers)
            $sel .= ", t.show_answers";
        if ($hasReview)
            $sel .= ", t.allow_review";
        if ($hasNoDeadline)
            $sel .= ", t.no_deadline";
        if ($hasClassIds)
            $sel .= ", t.class_ids";

        // Build WHERE — show all tasks (active, upcoming, expired) so kids can see their history
        // Matches if task is for all classes, or matches student's class_id or class name
        $classConds = [
            "t.class_id = 0"
        ];
        if ($hasClassIds) {
            $classConds[] = "FIND_IN_SET('0', REPLACE(COALESCE(t.class_ids, ''), ' ', ''))";
        }
        $stmtParams = [$churchId];
        $stmtTypes = 'i';

        foreach ($studentClassIds as $scId) {
            $classConds[] = "t.class_id = {$scId}";
            if ($hasClassIds) {
                $classConds[] = "FIND_IN_SET('{$scId}', REPLACE(COALESCE(t.class_ids, ''), ' ', ''))";
            }
        }

        if (!empty($studentClassName)) {
            $classConds[] = "cc.arabic_name = ?";
            $stmtParams[] = $studentClassName;
            $stmtTypes .= 's';

            if ($hasClassIds) {
                $classConds[] = "EXISTS (
                    SELECT 1 FROM church_classes sub_cc 
                    WHERE sub_cc.church_id = ? AND sub_cc.arabic_name = ? 
                    AND (t.class_id = sub_cc.id OR FIND_IN_SET(sub_cc.id, REPLACE(COALESCE(t.class_ids, ''), ' ', '')))
                )";
                $stmtParams[] = $churchId;
                $stmtParams[] = $studentClassName;
                $stmtTypes .= 'is';
            }
        }

        $where = "t.church_id = ? AND (" . implode(' OR ', $classConds) . ")";

        if ($hasStatus)
            $where .= " AND (t.status = 'published' OR t.status IS NULL)";
        if ($hasIsActive)
            $where .= " AND (t.is_active IS NULL OR t.is_active = 1)";

        $stmt = $conn->prepare("
            SELECT $sel
            FROM tasks t
            LEFT JOIN church_classes cc ON cc.id = t.class_id
            WHERE $where
            ORDER BY
                CASE WHEN t.end_date IS NULL OR " . ($hasNoDeadline ? "t.no_deadline = 1" : "0=1") . " THEN 1 ELSE 0 END,
                t.end_date ASC,
                t.start_date DESC
        ");
        $stmt->bind_param($stmtTypes, ...$stmtParams);
        $stmt->execute();
        $tasks = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

        foreach ($tasks as &$t) {
            $resolved = _resolveTaskClassNames($conn, $churchId, $t['class_id'] ?? 0, $t['class_ids'] ?? '', $t['class_name'] ?? '');
            $t['class_name'] = $resolved['label'];
            $t['class_ids'] = implode(',', $resolved['ids']);
            $t['class_names'] = $resolved['names'];
        }
        unset($t);



        // Filter by specific_ids if assign_to column exists

        if ($hasAssignTo) {

            $tasks = array_values(array_filter($tasks, function ($t) use ($studentId) {

                if (($t['assign_to'] ?? 'all') === 'all')

                    return true;

                $ids = json_decode($t['specific_ids'] ?? '[]', true) ?: [];

                return in_array((int) $studentId, array_map('intval', $ids));

            }));

        }



        // Detect task_questions columns

        $qCols = [];

        $qColRes = $conn->query("SHOW COLUMNS FROM task_questions");

        while ($cr = $qColRes->fetch_assoc())

            $qCols[] = $cr['Field'];

        $qHasDegree = in_array('degree', $qCols);

        $qHasOrder = in_array('sort_order', $qCols);

        $qHasCorrect = in_array('correct_index', $qCols);

        $qHasType = in_array('question_type', $qCols);

        $qHasImageUrl = in_array('image_url', $qCols);



        // Always include question_type and image_url — they are essential for rendering

        $qSel = "id, question_text, options";

        if ($qHasType)

            $qSel .= ", question_type";

        if ($qHasDegree)

            $qSel .= ", degree";

        if ($qHasOrder)

            $qSel .= ", sort_order";

        if ($qHasCorrect)

            $qSel .= ", correct_index";

        if ($qHasImageUrl)

            $qSel .= ", image_url";



        // Detect task_submissions columns

        $sCols = [];

        $sColRes = $conn->query("SHOW COLUMNS FROM task_submissions");

        while ($cr = $sColRes->fetch_assoc())

            $sCols[] = $cr['Field'];

        $sHasScore = in_array('score', $sCols);

        $sHasCoupons = in_array('coupons_awarded', $sCols);

        $sHasSubmitAt = in_array('submitted_at', $sCols);

        $sHasIsGraded = in_array('is_graded', $sCols);



        $sSel = "id";

        if ($sHasScore)

            $sSel .= ", score";

        if ($sHasCoupons)

            $sSel .= ", coupons_awarded";

        if ($sHasSubmitAt)

            $sSel .= ", submitted_at";

        if ($sHasIsGraded)

            $sSel .= ", is_graded";



        // Attach questions and submissions

        foreach ($tasks as &$t) {

            $t['timer_behavior'] = $t['timer_behavior'] ?? 'submit';

            $t['shuffle'] = isset($t['shuffle']) ? (int) $t['shuffle'] : 0;

            $t['shuffle_answers'] = isset($t['shuffle_answers']) ? (int) $t['shuffle_answers'] : 0;

            $t['show_result'] = isset($t['show_result']) ? (int) $t['show_result'] : 1;

            $t['show_answers'] = isset($t['show_answers']) ? (int) $t['show_answers'] : 0;

            $t['allow_review'] = isset($t['allow_review']) ? (int) $t['allow_review'] : 1;

            $t['no_deadline'] = isset($t['no_deadline']) ? (int) $t['no_deadline'] : 0;

            $t['assign_to'] = $t['assign_to'] ?? 'all';

            $t['specific_ids'] = $t['specific_ids'] ?? '[]';



            $qStmt = $conn->prepare("SELECT $qSel FROM task_questions WHERE task_id=? ORDER BY " . ($qHasOrder ? 'sort_order' : 'id'));

            $qStmt->bind_param('i', $t['id']);

            $qStmt->execute();

            $qs = $qStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            foreach ($qs as &$q) {

                $q['question_type'] = $q['question_type'] ?? 'mcq';

                $q['degree'] = isset($q['degree']) ? (int) $q['degree'] : 1;

                $q['sort_order'] = isset($q['sort_order']) ? (int) $q['sort_order'] : 0;

                $q['image_url'] = $q['image_url'] ?? '';

                // open questions must have correct_index = null (graded manually)

                if ($q['question_type'] === 'open') {

                    $q['correct_index'] = null;

                } else {

                    $q['correct_index'] = isset($q['correct_index']) ? (int) $q['correct_index'] : 0;

                }

            }

            unset($q);

            $t['questions'] = $qs;



            $subStmt = $conn->prepare("SELECT $sSel FROM task_submissions WHERE task_id=? AND student_id=? AND (is_deleted IS NULL OR is_deleted = 0) LIMIT 1");

            $subStmt->bind_param('ii', $t['id'], $studentId);

            $subStmt->execute();

            $subRow = $subStmt->get_result()->fetch_assoc();

            if ($subRow) {
                $hasOpenQsInTask = false;
                foreach ($qs as $chkQ) {
                    if (($chkQ['question_type'] ?? 'mcq') === 'open' && (int)($chkQ['degree'] ?? 1) > 0) {
                        $hasOpenQsInTask = true;
                        break;
                    }
                }
                if (!$hasOpenQsInTask && ((int)($subRow['is_graded'] ?? 0) === 0 || (int)($subRow['coupons_awarded'] ?? 0) === 0)) {
                    syncTaskSubmissionsForTask($conn, $t['id']);
                    // Re-read updated submission
                    $refStmt = $conn->prepare("SELECT score, coupons_awarded, is_graded, submitted_at FROM task_submissions WHERE id=? LIMIT 1");
                    if ($refStmt) {
                        $refStmt->bind_param('i', $subRow['id']);
                        $refStmt->execute();
                        $refRow = $refStmt->get_result()->fetch_assoc();
                        $refStmt->close();
                        if ($refRow) {
                            $subRow['score'] = $refRow['score'];
                            $subRow['coupons_awarded'] = $refRow['coupons_awarded'];
                            $subRow['is_graded'] = $refRow['is_graded'];
                        }
                    }
                }

                $mySubmission = [
                    'id' => $subRow['id'],
                    'score' => isset($subRow['score']) ? (int) $subRow['score'] : 0,
                    'coupons_awarded' => isset($subRow['coupons_awarded']) ? (int) $subRow['coupons_awarded'] : 0,
                    'is_graded' => !$hasOpenQsInTask ? 1 : (isset($subRow['is_graded']) ? (int) $subRow['is_graded'] : 0),
                    'submitted_at' => $subRow['submitted_at'] ?? null,
                ];



                // If show_answers is ON, attach the student's answers AND the correct answers

                // so both the kid view and uncle review can highlight right/wrong answers

                // Fetch full answers blob from DB so student answers are always retained
                $ansStmt = $conn->prepare("SELECT answers, open_scores, correction_notes FROM task_submissions WHERE id=? LIMIT 1");
                $ansStmt->bind_param('i', $subRow['id']);
                $ansStmt->execute();
                $ansRow = $ansStmt->get_result()->fetch_assoc();
                $mySubmission['answers'] = $ansRow ? json_decode($ansRow['answers'] ?? '{}', true) : [];
                $mySubmission['open_scores'] = $ansRow ? json_decode($ansRow['open_scores'] ?? '{}', true) : [];
                $mySubmission['correction_notes'] = $ansRow ? json_decode($ansRow['correction_notes'] ?? '{}', true) : [];

                // Attach correct answers only if show_answers is ON
                if (!empty($t['show_answers'])) {
                    $correctMap = [];
                    foreach ($t['questions'] as $q) {
                        if ($q['question_type'] !== 'open') {
                            $correctMap[$q['id']] = (int) $q['correct_index'];
                        }
                    }
                    $mySubmission['correct_answers'] = $correctMap;
                }



                $t['my_submission'] = $mySubmission;

            } else {

                $t['my_submission'] = null;

            }

        }

        unset($t);



        sendJSON(['success' => true, 'tasks' => $tasks]);

    } catch (Exception $e) {

        error_log("getStudentTasks error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── submitTaskAnswers (kid-facing) ────────────────────────────

function submitTaskAnswers()

{

    try {

        $conn = getDBConnection();

        $studentId = (int) ($_POST['student_id'] ?? 0);

        $churchId = (int) ($_POST['church_id'] ?? getChurchId());

        $taskId = (int) ($_POST['task_id'] ?? 0);

        $answersJson = $_POST['answers'] ?? '{}';

        $timeTaken = isset($_POST['time_taken_sec']) ? (int) $_POST['time_taken_sec'] : null;



        if (!$studentId || !$taskId) {

            sendJSON(['success' => false, 'message' => 'بيانات ناقصة']);

            return;

        }



        // Duplicate submission check (ignore deleted submissions)
        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_deleted TINYINT(1) DEFAULT 0");
        $chk = $conn->prepare("SELECT id FROM task_submissions WHERE task_id=? AND student_id=? AND (is_deleted IS NULL OR is_deleted = 0)");
        $chk->bind_param('ii', $taskId, $studentId);
        $chk->execute();
        if ($chk->get_result()->num_rows > 0) {
            sendJSON(['success' => false, 'message' => 'لقد أرسلت إجاباتك بالفعل']);
            return;
        }



        // Load task

        $tStmt = $conn->prepare("SELECT * FROM tasks WHERE id=? AND church_id=? AND status='published' LIMIT 1");

        $tStmt->bind_param('ii', $taskId, $churchId);

        $tStmt->execute();

        $task = $tStmt->get_result()->fetch_assoc();

        if (!$task) {

            sendJSON(['success' => false, 'message' => 'التاسك غير متاحة']);

            return;

        }



        // Load questions with correct answers

        $qStmt = $conn->prepare("SELECT id, question_type, correct_index, degree FROM task_questions WHERE task_id=? ORDER BY sort_order");

        $qStmt->bind_param('i', $taskId);

        $qStmt->execute();

        $questions = $qStmt->get_result()->fetch_all(MYSQLI_ASSOC);



        // Score & open question check

        $answers = json_decode($answersJson, true) ?: [];

        $score = 0;

        $hasOpenQuestions = false;



        foreach ($questions as $q) {
            $qType = $q['question_type'] ?? 'mcq';
            $deg = isset($q['degree']) ? (int) $q['degree'] : 1;

            // Questions with 0 degree are non-marked (surveys, feedback, bonus) — neglected in score and do not require manual review
            if ($deg <= 0) {
                continue;
            }

            if ($qType === 'open' || $q['correct_index'] === null) {
                $hasOpenQuestions = true;
                continue;
            }

            $given = $answers[$q['id']] ?? $answers[(string) $q['id']] ?? null;
            if ($given !== null && (int) $given === (int) $q['correct_index']) {
                $score += $deg;
            }
        }



        // Tasks with open questions remain un-graded (is_graded = 0) and coupons are held (0) until reviewed by teacher.
        // MCQ/TF-only tasks are auto-graded immediately (is_graded = 1) with coupons awarded.
        $isGraded = $hasOpenQuestions ? 0 : 1;
        $coupons = 0;
        $totalDeg = (int) ($task['total_degree'] ?? 0);
        $pct = $totalDeg > 0 ? ($score / $totalDeg * 100) : 0;

        if ($isGraded) {
            $coupons = calculateTaskCoupons($score, $totalDeg, $task['coupon_matrix'] ?? '[]', $task['max_coupons'] ?? 0);
        }

        $conn->begin_transaction();

        // Ensure is_graded and is_deleted columns exist
        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_graded TINYINT(1) NOT NULL DEFAULT 0");
        $conn->query("ALTER TABLE task_submissions ADD COLUMN IF NOT EXISTS is_deleted TINYINT(1) DEFAULT 0");

        // If an old soft-deleted submission exists for this student and task, permanently remove it so the new one takes its place cleanly
        $cleanStmt = $conn->prepare("DELETE FROM task_submissions WHERE task_id=? AND student_id=? AND is_deleted = 1");
        $cleanStmt->bind_param('ii', $taskId, $studentId);
        $cleanStmt->execute();

        // Insert submission
        $ins = $conn->prepare("
            INSERT INTO task_submissions
                (task_id, student_id, church_id, answers, score, coupons_awarded, is_graded, submitted_at, time_taken_sec)
            VALUES (?,?,?,?,?,?,?,NOW(),?)
        ");

        $nullableTime = ($timeTaken !== null) ? (int) $timeTaken : null;
        $ins->bind_param('iiisiiii', $taskId, $studentId, $churchId, $answersJson, $score, $coupons, $isGraded, $nullableTime);
        $ins->execute();
        $submissionId = (int) $conn->insert_id;

        // Award coupons — update task_coupons AND recalculate total coupons
        if ($coupons > 0) {
            $cur = $conn->prepare("SELECT name, coupons, task_coupons, attendance_coupons, commitment_coupons FROM students WHERE id=? LIMIT 1");
            $cur->bind_param('i', $studentId);
            $cur->execute();
            $stu = $cur->get_result()->fetch_assoc();

            $newTask = (int) $stu['task_coupons'] + $coupons;
            $newTotal = $newTask + (int) $stu['attendance_coupons'] + (int) $stu['commitment_coupons'];

            $upd = $conn->prepare("UPDATE students SET task_coupons=?, coupons=? WHERE id=?");
            $upd->bind_param('iii', $newTask, $newTotal, $studentId);
            $upd->execute();

            // Log in coupon_logs
            $log = $conn->prepare("
                INSERT INTO coupon_logs
                    (student_id, uncle_id, old_count, new_count, change_amount, change_type, reason)
                VALUES (?, NULL, ?, ?, ?, 'task', ?)
            ");
            $reason = "تاسك #{$taskId}: {$task['title']}";
            $log->bind_param('iiiis', $studentId, $stu['task_coupons'], $newTask, $coupons, $reason);
            $log->execute();

            // ► AUDIT
            auditCouponChange($studentId, $stu['name'] ?? '', (int) $stu['coupons'], $newTotal, $reason);
        }

        $conn->commit();

        // Push notification to church dashboard — targeted ONLY to uncles of that class
        $stuRow = $conn->query("
            SELECT s.name, s.class_id, s.class, 
                   COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class_name 
            FROM students s 
            LEFT JOIN church_classes cc ON s.class_id = cc.id AND cc.church_id = s.church_id 
            LEFT JOIN classes cl ON s.class_id = cl.id 
            WHERE s.id = $studentId LIMIT 1
        ")->fetch_assoc();
        $stuName = $stuRow['name'] ?? 'طفل';
        $stuClassName = trim((string)($stuRow['class_name'] ?? $stuRow['class'] ?? ''));
        $stuClassId = !empty($stuRow['class_id']) ? (int)$stuRow['class_id'] : (int)($task['class_id'] ?? 0);

        // Resolve task class names if student class name is missing
        $taskResolved = _resolveTaskClassNames($conn, $churchId, $task['class_id'] ?? 0, $task['class_ids'] ?? '', '');
        $classNames = [];
        if (!empty($stuClassName)) {
            $classNames[] = $stuClassName;
        }
        if (!empty($stuRow['class']) && !in_array($stuRow['class'], $classNames)) {
            $classNames[] = $stuRow['class'];
        }
        if (empty($classNames) && !empty($taskResolved['names']) && !in_array('كل الفصول', $taskResolved['names'])) {
            $classNames = $taskResolved['names'];
            $stuClassName = $taskResolved['label'];
        }

        $classSuffix = !empty($stuClassName) ? " — فصل {$stuClassName}" : "";
        $notifBody = $hasOpenQuestions
            ? "{$stuName} سلّم تاسك «{$task['title']}»{$classSuffix} (في انتظار التصحيح)"
            : "{$stuName} سلّم تاسك «{$task['title']}»{$classSuffix} بدرجة {$score} من {$task['total_degree']}";

        pushNotification(
            $conn,
            $churchId,
            'task_submission',
            'تسليم تاسك جديد 📝',
            $notifBody,
            'task',
            $taskId,
            $stuClassId
        );

        $taskUrl = !empty($stuClassName)
            ? '/uncle/dashboard/tasks?class=' . urlencode($stuClassName)
            : '/uncle/dashboard/tasks/';

        _sendWebPushToChurch(
            $conn,
            $churchId,
            'تسليم تاسك جديد 📝',
            $notifBody,
            [
                'notifType' => 'task_submission',
                'url' => $taskUrl,
                'redirect_url' => $taskUrl,
                'className' => $stuClassName,
                'class_name' => $stuClassName,
                'class_names' => $classNames,
                'class_id' => $stuClassId,
                'class_ids' => !empty($task['class_ids']) ? $task['class_ids'] : (string)$stuClassId,
                'task_id' => $taskId,
                'student_id' => $studentId,
                'tag' => 'task_sub_' . $taskId . '_' . $studentId
            ]
        );

        $result = [
            'success' => true,
            'submission_id' => $submissionId,
            'is_graded' => (int) $isGraded,
            'score' => $score,
            'total_degree' => (int) $task['total_degree'],
            'percentage' => round($pct, 1),
            'coupons_awarded' => $coupons,
            'show_result' => (bool) (int) $task['show_result'],
            'show_answers' => (bool) (int) ($task['show_answers'] ?? 0),
            'message' => $isGraded
                ? "أحسنت! درجتك {$score} من {$task['total_degree']} — حصلت على {$coupons} كوبون"
                : "تم تسليم إجاباتك بنجاح! التكليف في انتظار تصحيح ومراجعة الخادم"
        ];



        // Include answers + correct indices so kid can review which were right/wrong

        if (!empty($task['show_answers'])) {

            // Return full questions with correct_index so frontend can highlight

            $qaStmt = $conn->prepare("SELECT id, question_type, question_text, options, correct_index, degree, sort_order FROM task_questions WHERE task_id=? ORDER BY sort_order");

            $qaStmt->bind_param('i', $taskId);

            $qaStmt->execute();

            $result['questions_with_answers'] = $qaStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $result['submitted_answers'] = $answers; // the student's own choices

        }



        if (!$result['show_result']) {

            unset($result['score'], $result['percentage'], $result['coupons_awarded']);

            $result['message'] = 'تم إرسال إجاباتك بنجاح';

        }



        sendJSON($result);

    } catch (Exception $e) {

        if (isset($conn))

            $conn->rollback();

        error_log("submitTaskAnswers error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}





// ─── fetchOgImage — extract og:image or first <img> from any URL ──

function fetchOgImage()

{

    try {

        $url = $_POST['url'] ?? '';

        if (!$url || !filter_var($url, FILTER_VALIDATE_URL)) {

            sendJSON(['success' => false, 'message' => 'رابط غير صالح']);

            return;

        }

        // Fetch the page (timeout 6s, follow redirects)

        $ctx = stream_context_create([

            'http' => [

                'timeout' => 6,

                'follow_location' => 1,

                'max_redirects' => 5,

                'user_agent' => 'Mozilla/5.0 (compatible; SundaySchoolBot/1.0)',

                'ignore_errors' => true,

            ]

        ]);

        $html = @file_get_contents($url, false, $ctx);

        if (!$html) {

            sendJSON(['success' => false, 'message' => 'تعذّر جلب الصفحة']);

            return;

        }



        // 1. Try og:image

        if (

            preg_match('/<meta[^>]+property=["\']og:image["\'][^>]+content=["\']([^"\']+)["\']/i', $html, $m)

            || preg_match('/<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:image["\']/i', $html, $m)

        ) {

            sendJSON(['success' => true, 'image_url' => htmlspecialchars_decode($m[1])]);

            return;

        }

        // 2. Try twitter:image

        if (preg_match('/<meta[^>]+name=["\']twitter:image["\'][^>]+content=["\']([^"\']+)["\']/i', $html, $m)) {

            sendJSON(['success' => true, 'image_url' => htmlspecialchars_decode($m[1])]);

            return;

        }

        // 3. First <img> with src

        if (preg_match('/<img[^>]+src=["\']([^"\']+\.(?:jpg|jpeg|png|gif|webp))["\']/i', $html, $m)) {

            $imgSrc = $m[1];

            if (strpos($imgSrc, 'http') !== 0) {

                $parsed = parse_url($url);

                $imgSrc = $parsed['scheme'] . '://' . $parsed['host'] . $imgSrc;

            }

            sendJSON(['success' => true, 'image_url' => $imgSrc]);

            return;

        }

        sendJSON(['success' => false, 'message' => 'لم يُعثر على صورة في هذا الرابط']);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── getExamStart — READ-ONLY check: has this student already started? ──

// Returns {success:true, started_at:...} if a record exists, or {success:true} with no started_at if not.

// Does NOT create a record — that's startExam's job.

function getExamStart()

{

    try {

        $conn = getDBConnection();

        $studentId = (int) ($_POST['student_id'] ?? 0);

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$studentId || !$taskId) {

            sendJSON(['success' => true]);

            return;

        }



        $tbl = $conn->query("SHOW TABLES LIKE 'exam_starts'")->fetch_assoc();

        if (!$tbl) {

            sendJSON(['success' => true]);

            return;

        }



        $sel = $conn->prepare("SELECT started_at FROM exam_starts WHERE task_id=? AND student_id=? LIMIT 1");

        $sel->bind_param('ii', $taskId, $studentId);

        $sel->execute();

        $row = $sel->get_result()->fetch_assoc();



        if ($row) {

            sendJSON(['success' => true, 'started_at' => $row['started_at']]);

        } else {

            sendJSON(['success' => true]); // no record yet — not started

        }

    } catch (Exception $e) {

        sendJSON(['success' => true]); // non-fatal fallback

    }

}



// ─── startExam — record when a student begins a timed task ────────

// Creates/updates a lightweight record so the timer is server-anchored.

// The JS uses the returned started_at to compute remaining time accurately

// even after closing and reopening the page.

function startExam()

{

    try {

        $conn = getDBConnection();

        $studentId = (int) ($_POST['student_id'] ?? 0);

        $churchId = (int) ($_POST['church_id'] ?? getChurchId());

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$studentId || !$taskId) {

            sendJSON(['success' => false, 'message' => 'بيانات ناقصة']);

            return;

        }



        // Ensure the exam_starts table exists (auto-migrate)

        $conn->query("

            CREATE TABLE IF NOT EXISTS exam_starts (

                id          INT AUTO_INCREMENT PRIMARY KEY,

                task_id     INT NOT NULL,

                student_id  INT NOT NULL,

                church_id   INT NOT NULL,

                started_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

                UNIQUE KEY uniq_exam_start (task_id, student_id)

            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4

        ");



        // Insert only if not already started (preserve original start time)

        $ins = $conn->prepare("

            INSERT IGNORE INTO exam_starts (task_id, student_id, church_id, started_at)

            VALUES (?, ?, ?, NOW())

        ");

        $ins->bind_param('iii', $taskId, $studentId, $churchId);

        $ins->execute();



        // Return the actual start time (original or just-inserted)

        $sel = $conn->prepare("SELECT started_at FROM exam_starts WHERE task_id=? AND student_id=? LIMIT 1");

        $sel->bind_param('ii', $taskId, $studentId);

        $sel->execute();

        $row = $sel->get_result()->fetch_assoc();



        sendJSON(['success' => true, 'started_at' => $row['started_at'] ?? date('Y-m-d H:i:s')]);

    } catch (Exception $e) {

        // Non-fatal — fall back gracefully, client will use local time

        sendJSON(['success' => true, 'started_at' => date('Y-m-d H:i:s'), 'fallback' => true]);

    }

}



// ─── clearExamStart — delete a stale timer record so student can restart ──

function clearExamStart()

{

    try {

        $conn = getDBConnection();

        $studentId = (int) ($_POST['student_id'] ?? 0);

        $taskId = (int) ($_POST['task_id'] ?? 0);



        if (!$studentId || !$taskId) {

            sendJSON(['success' => true]);

            return;

        }



        // Only delete if no active submission exists — never erase a completed exam record
        $chk = $conn->prepare("SELECT id FROM task_submissions WHERE task_id=? AND student_id=? AND (is_deleted IS NULL OR is_deleted = 0) LIMIT 1");

        $chk->bind_param('ii', $taskId, $studentId);

        $chk->execute();

        if ($chk->get_result()->num_rows > 0) {

            // Student already submitted — do NOT clear, they are done

            sendJSON(['success' => false, 'message' => 'submission_exists']);

            return;

        }



        // Safe to delete the stale start record

        $del = $conn->prepare("DELETE FROM exam_starts WHERE task_id=? AND student_id=?");

        $del->bind_param('ii', $taskId, $studentId);

        $del->execute();



        sendJSON(['success' => true]);

    } catch (Exception $e) {

        sendJSON(['success' => true]); // non-fatal

    }

}





function _insertTaskQuestions($conn, $taskId, array $questions)

{

    if (!$questions)

        return;



    // Ensure question_type column exists

    $conn->query("ALTER TABLE task_questions ADD COLUMN IF NOT EXISTS question_type ENUM('mcq','open','tf') NOT NULL DEFAULT 'mcq' AFTER id");

    $conn->query("ALTER TABLE task_questions ADD COLUMN IF NOT EXISTS image_url TEXT DEFAULT NULL");

    // Ensure correct_index is nullable (handles existing NOT NULL columns)

    $conn->query("ALTER TABLE task_questions MODIFY COLUMN correct_index INT DEFAULT NULL");

    $conn->query("ALTER TABLE task_questions ADD COLUMN IF NOT EXISTS degree INT NOT NULL DEFAULT 1 AFTER correct_index");

    $conn->query("ALTER TABLE task_questions ADD COLUMN IF NOT EXISTS sort_order INT NOT NULL DEFAULT 0 AFTER degree");

    $conn->query("ALTER TABLE task_questions ADD COLUMN IF NOT EXISTS image_url TEXT DEFAULT NULL");



    $stmt = $conn->prepare("

        INSERT INTO task_questions

            (task_id, question_type, question_text, options, correct_index, degree, sort_order, image_url)

        VALUES (?,?,?,?,?,?,?,?)

    ");

    foreach ($questions as $i => $q) {

        $type = in_array($q['question_type'] ?? 'mcq', ['mcq', 'open', 'tf']) ? $q['question_type'] : 'mcq';

        $text = $q['question_text'] ?? '';

        $opts = $type === 'open' ? '[]' : (is_array($q['options'])

            ? json_encode($q['options'], JSON_UNESCAPED_UNICODE)

            : ($q['options'] ?? '[]'));

        // open questions have no correct answer — pass NULL as string binding to avoid NOT NULL errors

        $correct = ($type === 'open') ? null : (int) ($q['correct_index'] ?? 0);

        $degree = isset($q['degree']) ? max(0, (int) $q['degree']) : 1;

        $order = (int) ($q['sort_order'] ?? $i);

        $imageUrl = $q['image_url'] ?? '';

        // Use 's' (string) for correct_index so PHP can pass NULL without type mismatch

        $stmt->bind_param('issssiis', $taskId, $type, $text, $opts, $correct, $degree, $order, $imageUrl);

        $stmt->execute();

    }

}



// ─── getStudentTrips (no auth required) ──────────────────────────

// Returns trips for a church with registered kids (photos) + own payment.

function getStudentTrips()

{

    try {

        $conn = getDBConnection();

        $churchId = (int) ($_POST['church_id'] ?? $_GET['church_id'] ?? 0);

        $studentId = (int) ($_POST['student_id'] ?? $_GET['student_id'] ?? 0);

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'church_id مطلوب']);

            return;

        }



        $stmt = $conn->prepare("

            SELECT

                t.id, t.title, t.description, t.type,

                t.start_date, t.end_date, t.status,

                t.price, t.discount, t.discount_type,

                t.max_participants, t.image_url,
                COALESCE(t.show_registered_kids, 1) AS show_registered_kids,
                COALESCE(t.kids_visibility, 'auto_hide') AS kids_visibility

            FROM trips t

            WHERE t.church_id = ?

              AND t.status IN ('planned','active','completed')

            ORDER BY FIELD(t.status,'active','planned','completed'), t.start_date DESC

            LIMIT 20

        ");

        $stmt->bind_param('i', $churchId);

        $stmt->execute();

        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);



        foreach ($rows as &$row) {

            $price = (float) $row['price'];

            $disc = (float) $row['discount'];

            $final = $price;

            if ($disc > 0) {

                $final = $row['discount_type'] === 'percentage'

                    ? $price - ($price * $disc / 100)

                    : max(0, $price - $disc);

            }

            $row['final_price'] = round($final, 2);

            unset($row['price'], $row['discount'], $row['discount_type']);

            $row['start_date_formatted'] = $row['start_date'] ? date('d/m/Y', strtotime($row['start_date'])) : '';

            $row['end_date_formatted'] = $row['end_date'] ? date('d/m/Y', strtotime($row['end_date'])) : '';



            $cStmt = $conn->prepare("SELECT COUNT(*) AS cnt FROM trip_registrations WHERE trip_id = ? AND cancelled = 0");

            $cStmt->bind_param('i', $row['id']);

            $cStmt->execute();

            $row['registered_count'] = (int) ($cStmt->get_result()->fetch_assoc()['cnt'] ?? 0);



            // Registered kids (name + photo only, no payments) can be hidden per trip.

            $row['show_registered_kids'] = (int) ($row['show_registered_kids'] ?? 1);
            $kidsVis = $row['kids_visibility'] ?? 'auto_hide';
            $maxPart = (int) ($row['max_participants'] ?? 0);
            $cnt = $row['registered_count'];

            $shouldShowKids = ($row['show_registered_kids'] === 1);
            if ($kidsVis === 'never') {
                $shouldShowKids = false;
            } elseif ($kidsVis === 'auto_hide') {
                if ($maxPart > 0 && $cnt >= $maxPart) {
                    $shouldShowKids = false;
                }
            }

            $row['registered_kids'] = [];

            if ($shouldShowKids) {

                $rStmt = $conn->prepare("

                    SELECT s.id, s.name, s.image_url,

                           COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class

                    FROM trip_registrations tr

                    JOIN students s ON s.id = tr.student_id

                    LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id

                    LEFT JOIN classes cl ON cl.id = s.class_id

                    WHERE tr.trip_id = ? AND tr.cancelled = 0

                    ORDER BY s.name

                ");

                $rStmt->bind_param('i', $row['id']);

                $rStmt->execute();

                $row['registered_kids'] = $rStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            }



            // Current student's own registration + payment

            $row['my_registration'] = null;

            if ($studentId) {

                $mStmt = $conn->prepare("

                    SELECT tr.id, tr.payment_status, tr.amount_paid,

                           COALESCE((SELECT SUM(amount) FROM trip_payments WHERE registration_id=tr.id AND is_deleted = 0),0) AS total_paid

                    FROM trip_registrations tr

                    WHERE tr.trip_id=? AND tr.student_id=? AND tr.cancelled=0

                    LIMIT 1

                ");

                $mStmt->bind_param('ii', $row['id'], $studentId);

                $mStmt->execute();

                $myReg = $mStmt->get_result()->fetch_assoc();

                if ($myReg) {

                    $myReg['total_paid'] = (float) $myReg['total_paid'];

                    $myReg['remaining'] = max(0, round($row['final_price'] - $myReg['total_paid'], 2));

                    $row['my_registration'] = $myReg;

                }

                // Also attach this student's points for this trip (if stored)

                try {

                    $pStmt = $conn->prepare("SELECT trip_points FROM students WHERE id = ? AND church_id = ? LIMIT 1");

                    $pStmt->bind_param('ii', $studentId, $churchId);

                    $pStmt->execute();

                    $pRes = $pStmt->get_result()->fetch_assoc();

                    $tp = $pRes['trip_points'] ?? '';

                    $pointsMap = json_decode($tp, true);

                    if (!is_array($pointsMap))

                        $pointsMap = [];

                    $row['my_points'] = intval($pointsMap[$row['id']] ?? 0);

                } catch (Exception $e) {

                    $row['my_points'] = 0;

                }

            }

        }

        unset($row);



        sendJSON(['success' => true, 'trips' => $rows]);

    } catch (Exception $e) {

        error_log("getStudentTrips error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// ─── getPublicChurchSettings (no auth required) ───────────────────

// Returns attendance_day and custom_fields for a church by ID.

function getPublicChurchSettings()

{

    try {

        $conn = getDBConnection();

        $churchId = (int) ($_POST['church_id'] ?? $_GET['church_id'] ?? 0);

        if (!$churchId) {

            sendJSON(['success' => false, 'message' => 'church_id مطلوب']);

