// NOTIFICATIONS

// ════════════════════════════════════════════════════════════════



function ensureNotificationsTable($conn)

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        CREATE TABLE IF NOT EXISTS `notifications` (

            `id`          INT AUTO_INCREMENT PRIMARY KEY,

            `church_id`   INT NOT NULL,

            `type`        VARCHAR(50) NOT NULL DEFAULT 'system',

            `title`       VARCHAR(300) NOT NULL,

            `body`        TEXT DEFAULT NULL,

            `entity_type` VARCHAR(50) DEFAULT NULL,

            `entity_id`   INT DEFAULT NULL,

            `is_read`     TINYINT(1) NOT NULL DEFAULT 0,

            `created_at`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

            INDEX idx_church_read (`church_id`, `is_read`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci

    ");

    $res = $conn->query("SHOW COLUMNS FROM `notifications` LIKE 'deleted_by_uncles'");
    if ($res && $res->num_rows === 0) {
        $conn->query("ALTER TABLE `notifications` ADD COLUMN `deleted_by_uncles` TEXT DEFAULT NULL");
    }

}



function getNotifications()
{
    try {
        $conn = getDBConnection();
        $churchId = getChurchId();
        ensureNotificationsTable($conn);

        $uncleId = isset($_SESSION['uncle_id']) ? (int)$_SESSION['uncle_id'] : 0;
        $uncleIdStr = (string)$uncleId;

        $limit = (int) ($_POST['limit'] ?? 50);
        $offset = (int) ($_POST['offset'] ?? 0);
        $isDev = isDeveloperRole();

        if ($isDev) {
            if ($churchId > 0) {
                $stmt = $conn->prepare("
                    SELECT n.id, n.type, n.title, n.body, n.entity_type, n.entity_id, n.is_read, n.created_at, dm.redirect_url
                    FROM notifications n
                    LEFT JOIN developer_messages dm ON n.entity_type = 'developer_message' AND n.entity_id = dm.id
                    WHERE (n.church_id = ? OR n.church_id = 0 OR n.type IN ('whatsapp_otp', 'developer_message'))
                      AND (n.deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, n.deleted_by_uncles) = 0)
                    ORDER BY n.created_at DESC
                    LIMIT ? OFFSET ?
                ");
                $stmt->bind_param('issii', $churchId, $uncleIdStr, $uncleIdStr, $limit, $offset);
                $stmt->execute();
                $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

                $countStmt = $conn->prepare("
                    SELECT COUNT(*) as c 
                    FROM notifications 
                    WHERE (church_id=? OR church_id = 0 OR type IN ('whatsapp_otp', 'developer_message')) 
                      AND is_read=0 
                      AND (deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, deleted_by_uncles) = 0)
                ");
                $countStmt->bind_param('iss', $churchId, $uncleIdStr, $uncleIdStr);
                $countStmt->execute();
                $unread = (int) $countStmt->get_result()->fetch_assoc()['c'];
            } else {
                $stmt = $conn->prepare("
                    SELECT n.id, n.type, n.title, n.body, n.entity_type, n.entity_id, n.is_read, n.created_at, dm.redirect_url
                    FROM notifications n
                    LEFT JOIN developer_messages dm ON n.entity_type = 'developer_message' AND n.entity_id = dm.id
                    WHERE (n.deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, n.deleted_by_uncles) = 0)
                    ORDER BY n.created_at DESC
                    LIMIT ? OFFSET ?
                ");
                $stmt->bind_param('ssii', $uncleIdStr, $uncleIdStr, $limit, $offset);
                $stmt->execute();
                $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

                $countStmt = $conn->prepare("
                    SELECT COUNT(*) as c 
                    FROM notifications 
                    WHERE is_read=0 
                      AND (deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, deleted_by_uncles) = 0)
                ");
                $countStmt->bind_param('ss', $uncleIdStr, $uncleIdStr);
                $countStmt->execute();
                $unread = (int) $countStmt->get_result()->fetch_assoc()['c'];
            }

            foreach ($rows as &$r) {
                if (!empty($r['body'])) {
                    $routeSep = strpos($r['body'], '|||class_id:');
                    if ($routeSep !== false) {
                        $r['body'] = trim(substr($r['body'], 0, $routeSep));
                    }
                }
            }
            unset($r);

            sendJSON(['success' => true, 'notifications' => $rows, 'unread_count' => $unread]);
        } else {
            if (!$churchId && $uncleId) {
                $uChRow = $conn->query("SELECT church_id FROM uncles WHERE id = " . intval($uncleId) . " LIMIT 1")->fetch_assoc();
                if (!empty($uChRow['church_id'])) {
                    $churchId = (int)$uChRow['church_id'];
                }
            }

            $stmt = $conn->prepare("
                SELECT n.id, n.type, n.title, n.body, n.entity_type, n.entity_id, n.is_read, n.created_at, dm.redirect_url
                FROM notifications n
                LEFT JOIN developer_messages dm ON n.entity_type = 'developer_message' AND n.entity_id = dm.id
                WHERE (n.church_id = ? OR n.church_id = 0) 
                  AND n.type != 'whatsapp_otp' 
                  AND (n.deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, n.deleted_by_uncles) = 0)
                ORDER BY n.created_at DESC
                LIMIT ? OFFSET ?
            ");
            $stmt->bind_param('issii', $churchId, $uncleIdStr, $uncleIdStr, $limit, $offset);
            $stmt->execute();
            $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $countStmt = $conn->prepare("SELECT COUNT(*) as c FROM notifications WHERE (church_id=? OR church_id = 0) AND type != 'whatsapp_otp' AND is_read=0 AND (deleted_by_uncles IS NULL OR ? = '0' OR FIND_IN_SET(?, deleted_by_uncles) = 0)");
            $countStmt->bind_param('iss', $churchId, $uncleIdStr, $uncleIdStr);
            $countStmt->execute();
            $unread = (int) $countStmt->get_result()->fetch_assoc()['c'];

            // If uncle is a servant (not admin) with assigned classes, filter task_submission by their classes
            if ($uncleId > 0) {
                $uRoleRow = $conn->query("SELECT role FROM uncles WHERE id = " . intval($uncleId) . " LIMIT 1")->fetch_assoc();
                $uncleRole = strtolower(trim($uRoleRow['role'] ?? ''));
                if (!in_array($uncleRole, ['admin', 'superadmin', 'developer', 'dev'])) {
                    $uClasses = [];
                    $uClsRes = $conn->query("SELECT class_name FROM uncle_class_assignments WHERE uncle_id = " . intval($uncleId));
                    if ($uClsRes) {
                        while ($cr = $uClsRes->fetch_assoc()) {
                            $uClasses[] = trim($cr['class_name']);
                        }
                    }
                    if (!empty($uClasses)) {
                        $uClassIds = [];
                        $escCls = array_map(function($c) use ($conn) { return "'" . $conn->real_escape_string($c) . "'"; }, $uClasses);
                        $cQ = $conn->query("
                            SELECT id FROM church_classes 
                            WHERE church_id = " . intval($churchId) . " AND (arabic_name IN (" . implode(',', $escCls) . ") OR code IN (" . implode(',', $escCls) . ")) 
                            UNION 
                            SELECT id FROM classes 
                            WHERE (arabic_name IN (" . implode(',', $escCls) . ") OR code IN (" . implode(',', $escCls) . "))
                        ");
                        if ($cQ) {
                            while ($cqRow = $cQ->fetch_assoc()) {
                                $uClassIds[] = (int)$cqRow['id'];
                            }
                        }

                        $filteredRows = [];
                        foreach ($rows as $r) {
                            if ($r['type'] === 'task_submission') {
                                $routeSep = strpos($r['body'] ?? '', '|||class_id:');
                                if ($routeSep !== -1 && $routeSep !== false) {
                                    $cId = (int)substr($r['body'], $routeSep + 12);
                                    if ($cId > 0 && !in_array($cId, $uClassIds)) {
                                        if ($r['is_read'] == 0 && $unread > 0) $unread--;
                                        continue;
                                    }
                                }
                            }
                            $filteredRows[] = $r;
                        }
                        $rows = $filteredRows;
                    }
                }
            }

            foreach ($rows as &$r) {
                if (!empty($r['body'])) {
                    $routeSep = strpos($r['body'], '|||class_id:');
                    if ($routeSep !== false) {
                        $r['body'] = trim(substr($r['body'], 0, $routeSep));
                    }
                }
            }
            unset($r);

            sendJSON(['success' => true, 'notifications' => $rows, 'unread_count' => max(0, $unread)]);
        }

    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}



function markNotificationRead()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $id = (int) ($_POST['id'] ?? 0);

        ensureNotificationsTable($conn);

        if (isDeveloperRole()) {
            $stmt = $conn->prepare("UPDATE notifications SET is_read=1 WHERE id=?");
            $stmt->bind_param('i', $id);
        } else {
            $stmt = $conn->prepare("UPDATE notifications SET is_read=1 WHERE id=? AND (church_id=? OR church_id=0)");
            $stmt->bind_param('ii', $id, $churchId);
        }

        $stmt->execute();

        sendJSON(['success' => true]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function deleteNotification()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        $id = (int) ($_POST['id'] ?? 0);

        ensureNotificationsTable($conn);

        $uncleId = isset($_SESSION['uncle_id']) ? (int)$_SESSION['uncle_id'] : 0;
        $uncleIdStr = (string)$uncleId;

        if (isDeveloperRole()) {
            $stmt = $conn->prepare("
                UPDATE notifications 
                SET deleted_by_uncles = CASE 
                    WHEN deleted_by_uncles IS NULL OR deleted_by_uncles = '' THEN ? 
                    WHEN FIND_IN_SET(?, deleted_by_uncles) > 0 THEN deleted_by_uncles
                    ELSE CONCAT(deleted_by_uncles, ',', ?) 
                END
                WHERE id = ?
            ");
            $stmt->bind_param('sssi', $uncleIdStr, $uncleIdStr, $uncleIdStr, $id);
        } else {
            $stmt = $conn->prepare("
                UPDATE notifications 
                SET deleted_by_uncles = CASE 
                    WHEN deleted_by_uncles IS NULL OR deleted_by_uncles = '' THEN ? 
                    WHEN FIND_IN_SET(?, deleted_by_uncles) > 0 THEN deleted_by_uncles
                    ELSE CONCAT(deleted_by_uncles, ',', ?) 
                END
                WHERE id = ? AND (church_id = ? OR church_id = 0)
            ");
            $stmt->bind_param('sssii', $uncleIdStr, $uncleIdStr, $uncleIdStr, $id, $churchId);
        }

        $stmt->execute();

        sendJSON(['success' => true]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function markAllNotificationsRead()

{

    try {

        $conn = getDBConnection();

        $churchId = getChurchId();

        ensureNotificationsTable($conn);

        if (isDeveloperRole()) {
            if ($churchId > 0) {
                $stmt = $conn->prepare("UPDATE notifications SET is_read=1 WHERE (church_id=? OR church_id=0 OR type IN ('whatsapp_otp', 'developer_message')) AND is_read=0");
                $stmt->bind_param('i', $churchId);
            } else {
                $stmt = $conn->prepare("UPDATE notifications SET is_read=1 WHERE is_read=0");
            }
        } else {
            $stmt = $conn->prepare("UPDATE notifications SET is_read=1 WHERE (church_id=? OR church_id=0) AND is_read=0");
            $stmt->bind_param('i', $churchId);
        }

        $stmt->execute();

        sendJSON(['success' => true]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// Helper — create a notification automatically

function pushNotification($conn, $churchId, $type, $title, $body = '', $entityType = null, $entityId = null, $classId = null)

{

    try {

        ensureNotificationsTable($conn);

        // Append routing info to body if classId provided

        $fullBody = $body;

        if ($classId !== null) {

            $fullBody = $body . '|||class_id:' . intval($classId);

        }

        $stmt = $conn->prepare("

            INSERT INTO notifications (church_id, type, title, body, entity_type, entity_id)

            VALUES (?,?,?,?,?,?)

        ");

        $stmt->bind_param('issssi', $churchId, $type, $title, $fullBody, $entityType, $entityId);

        $stmt->execute();

    } catch (Exception $e) {

        error_log("pushNotification error: " . $e->getMessage());

    }

}



// ════════════════════════════════════════════════════════════════

// DEVELOPER MESSAGES

// ════════════════════════════════════════════════════════════════



function ensureDevMessagesTable($conn)

{
    if (defined('SCHEMA_MIGRATED')) { return; }

    $conn->query("

        CREATE TABLE IF NOT EXISTS `developer_messages` (

            `id`             INT AUTO_INCREMENT PRIMARY KEY,

            `to_church_id`   INT NOT NULL DEFAULT 0 COMMENT '0 = broadcast to all churches',

            `subject`        VARCHAR(300) NOT NULL,

            `body`           TEXT NOT NULL,

            `is_read`        TINYINT(1) NOT NULL DEFAULT 0,

            `is_deleted`     TINYINT(1) NOT NULL DEFAULT 0,

            `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

            `redirect_url`   VARCHAR(500) NULL,

            `button_text`    VARCHAR(100) NULL,

            `image_url`      VARCHAR(500) NULL,

            `description`    TEXT NULL,

            `target_type`    VARCHAR(50) DEFAULT 'uncles',

            INDEX idx_target (`to_church_id`, `is_deleted`),

            INDEX idx_read (`is_deleted`, `is_read`)

        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci

    ");

    // Migrate old table if it has wrong columns

    $cols = $conn->query("SHOW COLUMNS FROM developer_messages")->fetch_all(MYSQLI_ASSOC);

    $colNames = array_column($cols, 'Field');

    if (in_array('from_church_id', $colNames) && !in_array('to_church_id', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN to_church_id INT NOT NULL DEFAULT 0 AFTER id");

        $conn->query("ALTER TABLE developer_messages DROP COLUMN from_church_id");

        $conn->query("ALTER TABLE developer_messages DROP COLUMN from_name");

    }

    if (!in_array('redirect_url', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN redirect_url VARCHAR(500) NULL");

    }

    if (!in_array('button_text', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN button_text VARCHAR(100) NULL");

    }

    if (!in_array('image_url', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN image_url VARCHAR(500) NULL");

    }

    if (!in_array('description', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN description TEXT NULL");

    }

    if (!in_array('target_type', $colNames)) {

        $conn->query("ALTER TABLE developer_messages ADD COLUMN target_type VARCHAR(50) DEFAULT 'uncles'");

    }

}



