    }

}



function sendDeveloperMessage()

{

    // Only developers can send messages TO churches

    try {

        $role = strtolower($_SESSION['uncle_role'] ?? '');

        if (!in_array($role, ['developer', 'dev'])) {

            sendJSON(['success' => false, 'message' => 'فقط المطور يمكنه إرسال الرسائل']);

            return;

        }

        $conn = getDBConnection();

        $toChurchId = (int) ($_POST['to_church_id'] ?? 0); // 0 = broadcast to all

        $subject = sanitize($_POST['subject'] ?? '');

        $body = sanitize($_POST['body'] ?? '');

        $redirectUrl = sanitize($_POST['redirect_url'] ?? '');

        $buttonText = sanitize($_POST['button_text'] ?? '');

        $imageUrl = sanitize($_POST['image_url'] ?? '');

        $description = sanitize($_POST['description'] ?? '');

        $targetType = sanitize($_POST['target_type'] ?? 'uncles');



        if (!$subject || !$body) {

            sendJSON(['success' => false, 'message' => 'الموضوع والرسالة مطلوبان']);

            return;

        }



        ensureDevMessagesTable($conn);

        $stmt = $conn->prepare("INSERT INTO developer_messages (to_church_id, subject, body, redirect_url, button_text, image_url, description, target_type) VALUES (?,?,?,?,?,?,?,?)");

        $stmt->bind_param('isssssss', $toChurchId, $subject, $body, $redirectUrl, $buttonText, $imageUrl, $description, $targetType);

        $stmt->execute();

        $msgId = $conn->insert_id;



        // Build notification payload

        $pushPayload = [

            'notifType' => 'developer_message',

            'redirect_url' => $redirectUrl,

            'button_text' => $buttonText,

            'image_url' => $imageUrl,

            'description' => $description,

            'target_type' => $targetType

        ];



        // Send to targeted church(es)

        $targetChurches = [];

        if ($toChurchId > 0) {

            $targetChurches[] = $toChurchId;

        } else {

            $chRows = $conn->query("SELECT id FROM churches WHERE 1 LIMIT 200")->fetch_all(MYSQLI_ASSOC);

            foreach ($chRows as $ch) {

                $targetChurches[] = (int)$ch['id'];

            }

        }



        foreach ($targetChurches as $chId) {

            // Uncles

            if ($targetType === 'uncles' || $targetType === 'both') {

                pushNotification($conn, $chId, 'developer_message', $subject, $body, 'developer_message', $msgId);

                _sendWebPushToChurch($conn, $chId, $subject, $body, $pushPayload);

            }

            // Kids

            if ($targetType === 'kids' || $targetType === 'both') {

                _sendWebPushToKids($conn, $chId, $subject, $body, $pushPayload);

            }

        }



        sendJSON(['success' => true, 'message' => 'تم الإرسال بنجاح']);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function getDeveloperMessages()

{

    try {

        $conn = getDBConnection();

        ensureDevMessagesTable($conn);

        $role = strtolower($_SESSION['uncle_role'] ?? '');

        $isDev = in_array($role, ['developer', 'dev']);



        if ($isDev) {

            // Developer sees ALL messages they sent (outbox)

            $rows = $conn->query("SELECT * FROM developer_messages WHERE is_deleted=0 ORDER BY created_at DESC LIMIT 200")->fetch_all(MYSQLI_ASSOC);

            $unread = 0;

        } else {

            // Church sees messages addressed to them (to_church_id=their id OR broadcast 0)

            $churchId = getChurchId();

            if (!$churchId) {

                sendJSON(['success' => false, 'message' => 'غير مصرح']);

                return;

            }

            $stmt = $conn->prepare("SELECT * FROM developer_messages WHERE is_deleted=0 AND (to_church_id=? OR to_church_id=0) ORDER BY created_at DESC LIMIT 100");

            $stmt->bind_param('i', $churchId);

            $stmt->execute();

            $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $unread = count(array_filter($rows, fn($r) => !$r['is_read']));

        }

        sendJSON(['success' => true, 'messages' => $rows, 'unread_count' => (int) $unread, 'is_developer' => $isDev]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// Helper: send web push to devices subscribed for a church (supports filtering by class or uncle)
function _sendWebPushToChurch($conn, $churchId, $title, $body, $extra = [])
{
    try {
        // Requires push_subscriptions table and VAPID key
        $vapid = defined('VAPID_PRIVATE_KEY') ? VAPID_PRIVATE_KEY : (getenv('VAPID_PRIVATE_KEY') ?: '');
        $vapidPub = defined('VAPID_PUBLIC_KEY') ? VAPID_PUBLIC_KEY : (getenv('VAPID_PUBLIC_KEY') ?: '');
        if (!$vapid || !$vapidPub)
            return;

        $tbl = $conn->query("SHOW TABLES LIKE 'push_subscriptions'")->fetch_assoc();
        if (!$tbl)
            return;

        // Determine if targeting specific uncles or classes
        $targetUncleIds = null;

        // 1. Direct uncle IDs provided
        if (!empty($extra['uncle_ids'])) {
            $rawUncleIds = is_array($extra['uncle_ids']) ? $extra['uncle_ids'] : explode(',', (string)$extra['uncle_ids']);
            $targetUncleIds = array_values(array_unique(array_filter(array_map('intval', $rawUncleIds))));
        }

        // 2. Class targeting provided (class_names, class_name, className, class_id, class_ids)
        $targetClassNames = [];
        if (!empty($extra['class_names']) && is_array($extra['class_names'])) {
            $targetClassNames = array_merge($targetClassNames, $extra['class_names']);
        }
        if (!empty($extra['class_name'])) {
            $targetClassNames[] = $extra['class_name'];
        }
        if (!empty($extra['className'])) {
            $targetClassNames[] = $extra['className'];
        }

        $targetClassIds = [];
        if (!empty($extra['class_id'])) {
            $targetClassIds[] = (int)$extra['class_id'];
        }
        if (!empty($extra['class_ids'])) {
            if (is_array($extra['class_ids'])) {
                $targetClassIds = array_merge($targetClassIds, array_map('intval', $extra['class_ids']));
            } else {
                $targetClassIds = array_merge($targetClassIds, array_map('intval', explode(',', (string)$extra['class_ids'])));
            }
        }

        // If class IDs provided, resolve arabic names and codes from church_classes / classes
        $cleanClassIds = array_values(array_unique(array_filter($targetClassIds, function($id) { return $id > 0; })));
        if (!empty($cleanClassIds)) {
            $idsList = implode(',', $cleanClassIds);
            $cRes = $conn->query("
                SELECT arabic_name, code 
                FROM church_classes 
                WHERE church_id = " . intval($churchId) . " AND id IN ($idsList)
                UNION
                SELECT arabic_name, code 
                FROM classes 
                WHERE id IN ($idsList)
            ");
            if ($cRes) {
                while ($cRow = $cRes->fetch_assoc()) {
                    if (!empty($cRow['arabic_name'])) $targetClassNames[] = $cRow['arabic_name'];
                    if (!empty($cRow['code'])) $targetClassNames[] = $cRow['code'];
                }
            }
        }

        // Filter out 'كل الفصول' and '0' from specific class names
        $specificClassNames = array_values(array_unique(array_filter(array_map('trim', $targetClassNames), function($v) {
            return $v !== '' && $v !== 'كل الفصول' && $v !== '0';
        })));

        // If specific class names exist, find uncles assigned to those classes in this church
        if (!empty($specificClassNames)) {
            // Also fetch any aliases/codes for these names from church_classes / classes
            $escNames = array_map(function($n) use ($conn) { return "'" . $conn->real_escape_string($n) . "'"; }, $specificClassNames);
            $namesIn = implode(',', $escNames);
            $aliasRes = $conn->query("
                SELECT arabic_name, code 
                FROM church_classes 
                WHERE church_id = " . intval($churchId) . " 
                  AND (arabic_name IN ($namesIn) OR code IN ($namesIn))
                UNION
                SELECT arabic_name, code 
                FROM classes 
                WHERE (arabic_name IN ($namesIn) OR code IN ($namesIn))
            ");
            if ($aliasRes) {
                while ($ar = $aliasRes->fetch_assoc()) {
                    if (!empty($ar['arabic_name']) && !in_array($ar['arabic_name'], $specificClassNames)) {
                        $specificClassNames[] = $ar['arabic_name'];
                    }
                    if (!empty($ar['code']) && !in_array($ar['code'], $specificClassNames)) {
                        $specificClassNames[] = $ar['code'];
                    }
                }
            }

            $placeholders = implode(',', array_fill(0, count($specificClassNames), '?'));
            $types = 'i' . str_repeat('s', count($specificClassNames));
            $params = array_merge([$churchId], $specificClassNames);

            $uStmt = $conn->prepare("
                SELECT DISTINCT a.uncle_id 
                FROM uncle_class_assignments a
                JOIN uncles u ON a.uncle_id = u.id
                WHERE a.church_id = ? 
                  AND (u.deleted IS NULL OR u.deleted = 0)
                  AND (a.class_name IN ($placeholders) OR TRIM(a.class_name) IN ($placeholders))
            ");

            $classUncleIds = [];
            if ($uStmt) {
                $uStmt->bind_param($types, ...$params);
                $uStmt->execute();
                $uRes = $uStmt->get_result();
                while ($uRow = $uRes->fetch_assoc()) {
                    $classUncleIds[] = (int)$uRow['uncle_id'];
                }
                $uStmt->close();
            }

            if ($targetUncleIds === null) {
                $targetUncleIds = $classUncleIds;
            } else {
                $targetUncleIds = array_values(array_unique(array_merge($targetUncleIds, $classUncleIds)));
            }
        }

        // Query subscriptions: targeted or all church uncles
        if ($targetUncleIds !== null) {
            if (empty($targetUncleIds)) {
                // Class was specified but no uncles assigned to that class
                error_log("_sendWebPushToChurch: No uncles assigned to targeted class(es) in church $churchId");
                return;
            }
            $cleanUncleIds = implode(',', array_map('intval', $targetUncleIds));
            $stmt = $conn->prepare("SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE (church_id=? OR church_id=0) AND uncle_id IN ($cleanUncleIds) LIMIT 50");
            $stmt->bind_param('i', $churchId);
        } else {
            // General notification to all uncles in the church
            $stmt = $conn->prepare("SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE (church_id=? OR church_id=0) AND uncle_id IS NOT NULL LIMIT 50");
            $stmt->bind_param('i', $churchId);
        }

        $stmt->execute();
        $subs = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        $stmt->close();

        if (!$subs)
            return;

        // Use the same sendPushToSubscription helper if it exists
        if (function_exists('_pushToEndpoint')) {
            $payload = json_encode(array_merge([
                'title' => $title,
                'body' => $body,
                'type' => $extra['notifType'] ?? 'general',
                'notifType' => $extra['notifType'] ?? 'general',
                'className' => $extra['className'] ?? $extra['class_name'] ?? null,
                'icon' => '/logo.png',
                'badge' => '/badge.png'
            ], $extra));

            foreach ($subs as $sub) {
                _pushToEndpoint(
                    $sub['endpoint'],
                    $sub['p256dh'],
                    $sub['auth'],
                    $payload,
                    $vapid,
                    $vapidPub
                );
            }
        }

        // Ensure in-app notification exists so it appears in the notifications modal
        if (function_exists('pushNotification')) {
            $notifType = $extra['notifType'] ?? $extra['type'] ?? 'general';
            $entityType = $extra['entity_type'] ?? null;
            $entityId = isset($extra['entity_id']) ? (int)$extra['entity_id'] : null;
            $classId = isset($extra['class_id']) ? (int)$extra['class_id'] : null;
            $chk = $conn->prepare("SELECT id FROM notifications WHERE church_id = ? AND title = ? AND created_at >= DATE_SUB(NOW(), INTERVAL 60 SECOND) LIMIT 1");
            if ($chk) {
                $chk->bind_param('is', $churchId, $title);
                $chk->execute();
                $exists = $chk->get_result()->fetch_assoc();
                $chk->close();
                if (!$exists) {
                    pushNotification($conn, $churchId, $notifType, $title, $body, $entityType, $entityId, $classId);
                }
            }
        }

    } catch (Exception $e) {
        error_log("_sendWebPushToChurch error: " . $e->getMessage());
    }
}



function savePushSubscription()

{

    try {

        $conn = getDBConnection();

        $endpoint = $_POST['endpoint'] ?? '';

        $p256dh = $_POST['p256dh'] ?? '';

        $auth = $_POST['auth'] ?? '';

        $uncleId = isset($_SESSION['uncle_id']) ? (int) $_SESSION['uncle_id'] : (isset($_POST['uncle_id']) && $_POST['uncle_id'] !== '' ? (int)$_POST['uncle_id'] : null);
        $studentId = isset($_POST['student_id']) && $_POST['student_id'] !== '' ? (int)$_POST['student_id'] : null;

        $churchId = getChurchId();



        if (!$endpoint) {

            sendJSON(['success' => false, 'message' => 'endpoint مطلوب']);

            return;

        }



        $conn->query("

            CREATE TABLE IF NOT EXISTS push_subscriptions (

                id         INT AUTO_INCREMENT PRIMARY KEY,

                church_id  INT NOT NULL DEFAULT 0,

                uncle_id   INT DEFAULT NULL,

                endpoint   TEXT NOT NULL,

                p256dh     TEXT NOT NULL,

                auth       VARCHAR(100) NOT NULL,

                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

                UNIQUE KEY uq_endpoint (endpoint(200))

            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4

        ");


        $colCheck = $conn->query("SHOW COLUMNS FROM push_subscriptions LIKE 'student_id'");
        if ($colCheck && $colCheck->num_rows === 0) {
            $conn->query("ALTER TABLE push_subscriptions ADD COLUMN student_id INT DEFAULT NULL AFTER uncle_id");
        }


        $stmt = $conn->prepare("

            INSERT INTO push_subscriptions (church_id, uncle_id, student_id, endpoint, p256dh, auth)

            VALUES (?,?,?,?,?,?)

            ON DUPLICATE KEY UPDATE church_id=VALUES(church_id), uncle_id=VALUES(uncle_id), student_id=VALUES(student_id), p256dh=VALUES(p256dh), auth=VALUES(auth), updated_at=NOW()

        ");

        $stmt->bind_param('iiisss', $churchId, $uncleId, $studentId, $endpoint, $p256dh, $auth);

        $stmt->execute();

        // Prune old subscriptions for this uncle or student (keep max 3 most recent)
        if ($uncleId) {
            $conn->query("
                DELETE FROM push_subscriptions 
                WHERE uncle_id = $uncleId 
                  AND id NOT IN (
                      SELECT id FROM (
                          SELECT id FROM push_subscriptions 
                          WHERE uncle_id = $uncleId 
                          ORDER BY updated_at DESC, id DESC 
                          LIMIT 3
                      ) as tmp
                  )
            ");
        }
        if ($studentId) {
            $conn->query("
                DELETE FROM push_subscriptions 
                WHERE student_id = $studentId 
                  AND id NOT IN (
                      SELECT id FROM (
                          SELECT id FROM push_subscriptions 
                          WHERE student_id = $studentId 
                          ORDER BY updated_at DESC, id DESC 
                          LIMIT 3
                      ) as tmp
                  )
            ");
        }

        sendJSON(['success' => true]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



function deletePushSubscription()
{
    try {
        $conn = getDBConnection();
        $endpoint = sanitize($_POST['endpoint'] ?? '');
        $studentId = sanitize($_POST['student_id'] ?? '');
        $uncleId = sanitize($_POST['uncle_id'] ?? '');

        if (!$endpoint && !$studentId && !$uncleId) {
            sendJSON(['success' => false, 'message' => 'بيانات الاشتراك مطلوبة']);
            return;
        }

        if ($endpoint) {
            $stmt = $conn->prepare("DELETE FROM push_subscriptions WHERE endpoint = ?");
            $stmt->bind_param('s', $endpoint);
            $stmt->execute();
        }

        if ($studentId) {
            $stmt = $conn->prepare("DELETE FROM push_subscriptions WHERE student_id = ?");
            $stmt->bind_param('s', $studentId);
            $stmt->execute();
        }

        if ($uncleId) {
            $stmt = $conn->prepare("DELETE FROM push_subscriptions WHERE uncle_id = ?");
            $stmt->bind_param('s', $uncleId);
            $stmt->execute();
        }

        sendJSON(['success' => true]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}



function sendPushNotificationAction()

{

    try {

        $conn = getDBConnection();

        $target = $_POST['target'] ?? 'self';   // 'self' | 'church'

        $title = sanitize($_POST['title'] ?? 'إشعار');

        $body = sanitize($_POST['body'] ?? '');

        $url = $_POST['url'] ?? '/';

        $notifType = sanitize($_POST['notifType'] ?? 'system');

        $uncleId = isset($_SESSION['uncle_id']) ? (int) $_SESSION['uncle_id'] : null;

        $churchId = getChurchId();



        $vapidPri = defined('VAPID_PRIVATE_KEY') ? VAPID_PRIVATE_KEY : (getenv('VAPID_PRIVATE_KEY') ?: '');

        $vapidPub = defined('VAPID_PUBLIC_KEY') ? VAPID_PUBLIC_KEY : (getenv('VAPID_PUBLIC_KEY') ?: '');

        if (!$vapidPri || !$vapidPub) {

            sendJSON(['success' => false, 'message' => 'VAPID not configured']);

            return;

        }



        $conn->query("
            CREATE TABLE IF NOT EXISTS push_subscriptions (
                id         INT AUTO_INCREMENT PRIMARY KEY,
                church_id  INT NOT NULL DEFAULT 0,
                uncle_id   INT DEFAULT NULL,
                endpoint   TEXT NOT NULL,
                p256dh     TEXT NOT NULL,
                auth       VARCHAR(100) NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uq_endpoint (endpoint(200))
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
        ");



        if ($target === 'self' && $uncleId) {

            $stmt = $conn->prepare("SELECT endpoint,p256dh,auth FROM push_subscriptions WHERE uncle_id=? LIMIT 10");

            $stmt->bind_param('i', $uncleId);

        } else {

            $stmt = $conn->prepare("SELECT endpoint,p256dh,auth FROM push_subscriptions WHERE church_id=? AND uncle_id IS NOT NULL LIMIT 50");

            $stmt->bind_param('i', $churchId);

        }

        $stmt->execute();

        $subs = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);



        $payload = json_encode([

            'title' => $title,

            'body' => $body,

            'url' => $url,

            'type' => $notifType,

            'notifType' => $notifType,

            'icon' => '/logo.png',

            'badge' => '/badge.png',

        ]);



        $sent = 0;

        foreach ($subs as $sub) {

            if (_pushToEndpoint($sub['endpoint'], $sub['p256dh'], $sub['auth'], $payload, $vapidPri, $vapidPub)) {

                $sent++;

            }

        }

        sendJSON(['success' => true, 'sent' => $sent]);

    } catch (Exception $e) {

        sendJSON(['success' => false, 'message' => $e->getMessage()]);

    }

}



// Helper: send web push notification for WhatsApp OTP specifically to developer account(s) across all churches
function _sendWebPushToDeveloper($conn, $title, $body, $url = '/uncle/dashboard/?open_otp=1', $extra = [])
{
    try {
        $vapid = defined('VAPID_PRIVATE_KEY') ? VAPID_PRIVATE_KEY : (getenv('VAPID_PRIVATE_KEY') ?: '');
        $vapidPub = defined('VAPID_PUBLIC_KEY') ? VAPID_PUBLIC_KEY : (getenv('VAPID_PUBLIC_KEY') ?: '');
        if (!$vapid || !$vapidPub) return;

        $tbl = $conn->query("SHOW TABLES LIKE 'push_subscriptions'")->fetch_assoc();
        if (!$tbl) return;

        // Target active push subscriptions belonging to developer account(s) across all churches
        $sql = "SELECT ps.endpoint, ps.p256dh, ps.auth, ps.uncle_id 
                FROM push_subscriptions ps
                JOIN uncles u ON ps.uncle_id = u.id
                WHERE (LOWER(TRIM(u.role)) IN ('developer', 'dev') 
                   OR LOWER(TRIM(u.username)) = 'peterfayez' 
                   OR LOWER(TRIM(u.email)) = 'peterfayez107@gmail.com'
                   OR u.phone LIKE '%10868837%'
                   OR u.name LIKE '%بيتر فايز%'
                   OR LOWER(TRIM(u.name)) LIKE '%peter fayez%')
                  AND (u.deleted IS NULL OR u.deleted = 0)
                LIMIT 50";
        $stmt = $conn->prepare($sql);
        if (!$stmt) return;
        $stmt->execute();
        $subs = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        $stmt->close();

        if (!$subs) return;

        $payload = json_encode(array_merge([
            'title' => $title,
            'body' => $body,
            'url' => $url,
            'redirect_url' => $url,
            'type' => 'whatsapp_otp',
            'notifType' => 'whatsapp_otp',
            'icon' => '/logo.png',
            'badge' => '/badge.png'
        ], $extra));

        if (function_exists('_pushToEndpoint')) {
            foreach ($subs as $sub) {
                _pushToEndpoint($sub['endpoint'], $sub['p256dh'], $sub['auth'], $payload, $vapid, $vapidPub);
            }
        }

        // Ensure in-app notification exists so it appears in the notifications modal
        if (function_exists('pushNotification')) {
            $notifType = $extra['type'] ?? $extra['notifType'] ?? 'whatsapp_otp';
            $entityType = $extra['entity_type'] ?? 'phone_verification';
            $entityId = isset($extra['otp_code']) ? (int)$extra['otp_code'] : (isset($extra['queue_id']) ? (int)$extra['queue_id'] : null);
            $targetChurchId = !empty($extra['church_id']) ? (int)$extra['church_id'] : 0;
            $chk = $conn->prepare("SELECT id FROM notifications WHERE type = ? AND title = ? AND created_at >= DATE_SUB(NOW(), INTERVAL 60 SECOND) LIMIT 1");
            if ($chk) {
                $chk->bind_param('ss', $notifType, $title);
                $chk->execute();
                $exists = $chk->get_result()->fetch_assoc();
                $chk->close();
                if (!$exists) {
                    pushNotification($conn, $targetChurchId, $notifType, $title, $body, $entityType, $entityId);
                }
            }
        }
    } catch (Exception $e) {
        error_log("_sendWebPushToDeveloper error: " . $e->getMessage());
    }
}

