        if ($isDeveloperRole) {

            $stmt = $conn->prepare("DELETE FROM `rooms_templates` WHERE id = ?");

            $stmt->bind_param("i", $id);

        } else {

            $stmt = $conn->prepare("DELETE FROM `rooms_templates` WHERE id = ? AND church_id = ?");

            $stmt->bind_param("ii", $id, $churchId);

        }



        if ($stmt->execute()) {

            if ($conn->affected_rows > 0) {

