function searchAllStudents()
{
    try {
        checkAuth();

        $query = trim($_POST['query'] ?? $_GET['query'] ?? '');
        $queryAr = trim($_POST['query_ar'] ?? $_GET['query_ar'] ?? '');

        if (mb_strlen($query) < 2 && mb_strlen($queryAr) < 2) {
            sendJSON(['success' => true, 'students' => []]);
            return;
        }

        $conn = getDBConnection();
        $searchTerm = "%" . $query . "%";
        $searchTermAr = !empty($queryAr) ? "%" . $queryAr . "%" : "";

        // Query students across all churches
        $stmt = $conn->prepare("
            SELECT 
                s.id, 
                s.name, 
                s.phone, 
                s.gender, 
                COALESCE(cc.arabic_name, gc.arabic_name, s.class) as class,
                c.id as church_id,
                c.church_name
            FROM students s
            LEFT JOIN church_classes cc ON s.class_id = cc.id AND cc.church_id = s.church_id
            LEFT JOIN classes gc ON s.class_id = gc.id
            LEFT JOIN churches c ON s.church_id = c.id
            WHERE (s.name LIKE ? OR s.phone LIKE ? OR (? != '' AND s.name LIKE ?)) AND COALESCE(s.enrollment_status, 'active') = 'active'
            ORDER BY s.name ASC
            LIMIT 50
        ");
        $stmt->bind_param("ssss", $searchTerm, $searchTerm, $queryAr, $searchTermAr);
        $stmt->execute();
        $result = $stmt->get_result();



        $students = [];

        while ($row = $result->fetch_assoc()) {

            $students[] = $row;

        }



        sendJSON(['success' => true, 'students' => $students, 'data' => $students]);

    } catch (Exception $e) {

        error_log("searchAllStudents error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في البحث: ' . $e->getMessage()]);

    }

}



function getGuests()
{
    try {
        checkAuth();
        $churchId = getChurchId();
        $conn = getDBConnection();

        // Select all guests from students table for this church with their trip registration info
        $stmt = $conn->prepare("
            SELECT 
                s.id as id,
                s.name as name,
                s.phone as phone,
                s.emergency_phone as guardian_name,
                s.class as class,
                s.gender as gender,
                s.medical_notes as notes,
                s.image_url as image_url,
                u.name as created_by_name,
                (SELECT COUNT(*) FROM trip_registrations tr WHERE tr.student_id = s.id AND tr.cancelled = 0) as trip_count,
                (SELECT GROUP_CONCAT(DISTINCT t.title SEPARATOR '، ') FROM trip_registrations tr JOIN trips t ON tr.trip_id = t.id WHERE tr.student_id = s.id AND tr.cancelled = 0) as trip_names
            FROM students s
            LEFT JOIN uncles u ON s.added_by = CAST(u.id AS CHAR)
            WHERE s.church_id = ? AND s.is_guest = 1
            ORDER BY s.created_at DESC
        ");
        $stmt->bind_param("i", $churchId);
        $stmt->execute();
        $result = $stmt->get_result();
        $guests = [];
        while ($row = $result->fetch_assoc()) {
            $guests[] = $row;
        }
        sendJSON(['success' => true, 'data' => $guests]);
    } catch (Exception $e) {
        error_log("getGuests error: " . $e->getMessage());
        sendJSON(['success' => false, 'message' => 'خطأ في جلب الزوار: ' . $e->getMessage()]);
    }
}



function addGuest()
{
    try {
        checkAuth();
        $churchId = getChurchId();
        $uncleId = $_SESSION['uncle_id'] ?? null;
        $conn = getDBConnection();

        $name = sanitize($_POST['name'] ?? '');
        $phone = sanitize($_POST['phone'] ?? '');
        $guardianName = sanitize($_POST['guardian_name'] ?? '');
        $guestClass = sanitize($_POST['class'] ?? '');
        $gender = sanitize($_POST['gender'] ?? '');
        $notes = sanitize($_POST['notes'] ?? '');

        if (empty($name)) {
            sendJSON(['success' => false, 'message' => 'اسم الزائر مطلوب']);
            return;
        }

        if ($gender !== 'male' && $gender !== 'female') {
            $gender = detectGenderFromName($name);
        }
        
        $className = !empty($guestClass) ? $guestClass : 'الزوار';
        $classId = 0;
        
        if (!empty($className)) {
            $classStmt = $conn->prepare("
                SELECT id FROM church_classes 
                WHERE church_id = ? AND arabic_name = ? AND is_active = 1
                UNION
                SELECT id FROM classes 
                WHERE arabic_name = ?
                LIMIT 1
            ");
            $classStmt->bind_param("iss", $churchId, $className, $className);
            $classStmt->execute();
            $classRes = $classStmt->get_result()->fetch_assoc();
            if ($classRes) {
                $classId = intval($classRes['id']);
            }
        }

        // Handle photo upload
        $photoUrl = '';
        if (isset($_FILES['photo']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
            $photoFilename = "profile_" . preg_replace('/[^a-zA-Z0-9]/', '_', $name) . "_" . time() . ".jpg";
            $uploadDir = __DIR__ . '/uploads/students/';
            if (!is_dir($uploadDir)) {
                mkdir($uploadDir, 0755, true);
            }
            $uploadPath = $uploadDir . $photoFilename;
            $allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif'];
            $fileType = mime_content_type($_FILES['photo']['tmp_name']);

            if (in_array($fileType, $allowedTypes)) {
                if (move_uploaded_file($_FILES['photo']['tmp_name'], $uploadPath)) {
                    $photoUrl = "https://" . ($_SERVER['HTTP_HOST'] ?? 'sunday-school.online') . "/uploads/students/" . $photoFilename;
                }
            }
        }

        $stmt = $conn->prepare("
            INSERT INTO students 
            (church_id, name, class_id, class, address, phone, emergency_phone, medical_notes, image_url, gender, added_by, is_guest)
            VALUES (?, ?, ?, ?, '', ?, ?, ?, ?, ?, ?, 1)
        ");
        $addedByStr = $uncleId ? strval($uncleId) : 'church_admin';
        $stmt->bind_param("isissssssss", $churchId, $name, $classId, $className, $phone, $guardianName, $notes, $photoUrl, $gender, $addedByStr);

        if ($stmt->execute()) {
            $guestId = $conn->insert_id;
            sendJSON(['success' => true, 'guest_id' => $guestId, 'message' => 'تم إضافة الزائر بنجاح']);
        } else {
            sendJSON(['success' => false, 'message' => 'فشل في إضافة الزائر: ' . $stmt->error]);
        }
    } catch (Exception $e) {
        error_log("addGuest error: " . $e->getMessage());
        sendJSON(['success' => false, 'message' => 'خطأ في إضافة الزائر: ' . $e->getMessage()]);
    }
}

