function legacy_transferGuestToStudent()

{

    try {

        checkAuth();

        $churchId = getChurchId();

        $conn = getDBConnection();

        ensureGuestsTable($conn);



        $guestId = intval($_POST['guest_id'] ?? 0);

        $classId = intval($_POST['class_id'] ?? 0);

        $customClassName = sanitize($_POST['custom_class_name'] ?? '');



        if ($guestId === 0) {

            sendJSON(['success' => false, 'message' => 'معرف الزائر مطلوب']);

            return;

        }



        // Fetch guest data

        $gstmt = $conn->prepare("SELECT * FROM guests WHERE id = ? AND church_id = ?");

        $gstmt->bind_param("ii", $guestId, $churchId);

        $gstmt->execute();

        $guest = $gstmt->get_result()->fetch_assoc();



        if (!$guest) {

            sendJSON(['success' => false, 'message' => 'الزائر غير موجود']);

            return;

        }



        // Determine the class_id and class name

        $className = '';

        if ($classId > 0) {

            // Check custom church_classes first

            $cs = $conn->prepare("SELECT arabic_name FROM church_classes WHERE id = ? AND church_id = ?");

            $cs->bind_param("ii", $classId, $churchId);

            $cs->execute();

            $cr = $cs->get_result()->fetch_assoc();

            if ($cr) {

                $className = $cr['arabic_name'];

            } else {

                // Try global classes

                $gs = $conn->prepare("SELECT arabic_name FROM classes WHERE id = ?");

                $gs->bind_param("i", $classId);

                $gs->execute();

                $gr = $gs->get_result()->fetch_assoc();

                $className = $gr ? $gr['arabic_name'] : '';

            }

        } elseif (!empty($customClassName)) {

            // "Other" was selected – use custom name, class_id stays 0

            $className = $customClassName;

            $classId = 0;

        } else {

            sendJSON(['success' => false, 'message' => 'يجب اختيار فصل دراسي']);

            return;

        }



        $conn->begin_transaction();



        // Insert into students table
        $name = $guest['name'];
        $gender = $guest['gender'];
        $phone = $guest['phone'];
        $guardianName = $guest['guardian_name'];
        $notes = $guest['notes'];
        $photoUrl = $guest['image_url'] ?? '';

        $addedByType = 'guest_convert';
        $ins = $conn->prepare("
            INSERT INTO students
                (church_id, name, gender, class_id, class, phone, emergency_phone, medical_notes, image_url, enrollment_status, added_by)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?)
        ");
        $ins->bind_param(
            "ississssss",
            $churchId,
            $name,
            $gender,
            $classId,
            $className,
            $phone,
            $guardianName,
            $notes, // Map notes to medical_notes if needed
            $photoUrl,
            $addedByType
        );



        if (!$ins->execute()) {

            $conn->rollback();

            sendJSON(['success' => false, 'message' => 'فشل في إنشاء سجل الطالب: ' . $ins->error]);

            return;

        }



        $newStudentId = $conn->insert_id;



        // Update trip_registrations: link to new student_id and change type

        $upd = $conn->prepare("

            UPDATE trip_registrations

            SET student_id = ?, registration_type = 'student', guest_id = NULL

            WHERE guest_id = ? AND cancelled = 0

        ");

        $upd->bind_param("ii", $newStudentId, $guestId);

        $upd->execute();



        // Delete the guest record (already transferred)

        $del = $conn->prepare("DELETE FROM guests WHERE id = ? AND church_id = ?");

        $del->bind_param("ii", $guestId, $churchId);

        $del->execute();



        $conn->commit();



        sendJSON([

            'success' => true,

            'student_id' => $newStudentId,

            'message' => 'تم تحويل الزائر "' . $name . '" إلى طالب بنجاح'

        ]);

    } catch (Exception $e) {

        if (isset($conn) && $conn->errno) {

            $conn->rollback();

        }

        error_log("transferGuestToStudent error: " . $e->getMessage());

        sendJSON(['success' => false, 'message' => 'خطأ في التحويل: ' . $e->getMessage()]);

    }

}


function getSiblingGroupMembers()
{
    try {
        $studentId = intval($_POST['studentId'] ?? $_GET['studentId'] ?? 0);
        if ($studentId === 0) {
            sendJSON(['success' => false, 'message' => 'معرف الطالب مطلوب']);
            return;
        }
        $conn = getDBConnection();
        // 1. Get the group_id for this student
        $stmt = $conn->prepare("SELECT group_id FROM student_sibling_group_members WHERE student_id = ? LIMIT 1");
        $stmt->bind_param("i", $studentId);
        $stmt->execute();
        $res = $stmt->get_result()->fetch_assoc();
        if (!$res) {
            sendJSON(['success' => true, 'siblings' => [], 'message' => 'لا يوجد مجموعة إخوة']);
            return;
        }
        $groupId = $res['group_id'];

        // 2. Fetch all members of this group
        $stmt2 = $conn->prepare("
            SELECT s.id, s.name, s.image_url, s.coupons,
                   COALESCE(cc.arabic_name, cl.arabic_name, s.class) AS class
            FROM student_sibling_group_members ssgm
            INNER JOIN students s ON s.id = ssgm.student_id
            LEFT JOIN church_classes cc ON cc.id = s.class_id AND cc.church_id = s.church_id
            LEFT JOIN classes cl ON cl.id = s.class_id
            WHERE ssgm.group_id = ?
        ");
        $stmt2->bind_param("s", $groupId);
        $stmt2->execute();
        $siblings = $stmt2->get_result()->fetch_all(MYSQLI_ASSOC);

        sendJSON(['success' => true, 'siblings' => $siblings, 'groupId' => $groupId]);
    } catch (Exception $e) {
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}

function shareCoupons()
{
    try {
        $conn = getDBConnection();
        $senderId = intval($_POST['senderId'] ?? 0);
        $password = $_POST['password'] ?? '';
        $recipientId = intval($_POST['recipientId'] ?? 0);
        $amount = intval($_POST['amount'] ?? 0);
        $category = sanitize($_POST['category'] ?? 'all'); // 'att', 'com', 'task', or 'all'

        if ($senderId <= 0 || $recipientId <= 0 || $amount <= 0 || empty($password)) {
            sendJSON(['success' => false, 'message' => 'بيانات غير صحيحة أو ناقصة']);
            return;
        }

        if ($senderId === $recipientId) {
            sendJSON(['success' => false, 'message' => 'لا يمكنك إرسال كوبونات لنفسك']);
            return;
        }

        // 1. Verify Sender's password
        $stmt = $conn->prepare("SELECT password_hash, name, coupons, attendance_coupons, commitment_coupons, task_coupons FROM students WHERE id = ?");
        $stmt->bind_param("i", $senderId);
        $stmt->execute();
        $sender = $stmt->get_result()->fetch_assoc();
        if (!$sender) {
            sendJSON(['success' => false, 'message' => 'لم يتم العثور على المرسل']);
            return;
        }

        $storedHash = $sender['password_hash'] ?? '';
        $sha256Hash = hash('sha256', $password);
        $matched = false;
        if (!empty($storedHash)) {
            if ($storedHash === $sha256Hash || password_verify($password, $storedHash)) {
                $matched = true;
            }
        }

        if (!$matched) {
            sendJSON(['success' => false, 'message' => 'كلمة المرور غير صحيحة']);
            return;
        }

        // 2. Fetch Recipient details
        $stmtRec = $conn->prepare("SELECT name, coupons, attendance_coupons, commitment_coupons, task_coupons FROM students WHERE id = ?");
        $stmtRec->bind_param("i", $recipientId);
        $stmtRec->execute();
        $recipient = $stmtRec->get_result()->fetch_assoc();
        if (!$recipient) {
            sendJSON(['success' => false, 'message' => 'لم يتم العثور على المتلقي']);
            return;
        }

        $conn->begin_transaction();

        // 3. Subtract from sender
        $sender_total = intval($sender['coupons']);
        $sender_att = intval($sender['attendance_coupons']);
        $sender_com = intval($sender['commitment_coupons']);
        $sender_tsk = intval($sender['task_coupons']);

        if ($category === 'att') {
            if ($sender_att < $amount) {
                throw new Exception('رصيد كوبونات الحضور غير كافٍ');
            }
            $att_sub = $amount;
            $com_sub = 0;
            $tsk_sub = 0;
        } elseif ($category === 'com') {
            if ($sender_com < $amount) {
                throw new Exception('رصيد كوبونات الالتزام غير كافٍ');
            }
            $att_sub = 0;
            $com_sub = $amount;
            $tsk_sub = 0;
        } elseif ($category === 'task') {
            if ($sender_tsk < $amount) {
                throw new Exception('رصيد كوبونات التاسكات غير كافٍ');
            }
            $att_sub = 0;
            $com_sub = 0;
            $tsk_sub = $amount;
        } else {
            // 'all' - Greedy subtraction
            if ($sender_total < $amount) {
                throw new Exception('رصيد الكوبونات الإجمالي غير كافٍ');
            }
            $rem = $amount;
            $att_sub = min($sender_att, $rem);
            $rem -= $att_sub;

            $com_sub = 0;
            if ($rem > 0) {
                $com_sub = min($sender_com, $rem);
                $rem -= $com_sub;
            }

            $tsk_sub = 0;
            if ($rem > 0) {
                $tsk_sub = min($sender_tsk, $rem);
                $rem -= $tsk_sub;
            }
            if ($rem > 0) {
                throw new Exception('رصيد الكوبونات الموزعة غير كافٍ');
            }
        }

        $sender_new_total = $sender_total - $amount;

        $updSender = $conn->prepare("UPDATE students SET coupons = ?, attendance_coupons = attendance_coupons - ?, commitment_coupons = commitment_coupons - ?, task_coupons = task_coupons - ? WHERE id = ?");
        $updSender->bind_param("iiiii", $sender_new_total, $att_sub, $com_sub, $tsk_sub, $senderId);
        if (!$updSender->execute()) {
            throw new Exception('فشل خصم الكوبونات من المرسل');
        }

        // 4. Add to recipient
        $rec_new_total = intval($recipient['coupons']) + $amount;
        $updRec = $conn->prepare("UPDATE students SET coupons = ?, attendance_coupons = attendance_coupons + ?, commitment_coupons = commitment_coupons + ?, task_coupons = task_coupons + ? WHERE id = ?");
        $updRec->bind_param("iiiii", $rec_new_total, $att_sub, $com_sub, $tsk_sub, $recipientId);
        if (!$updRec->execute()) {
            throw new Exception('فشل إضافة الكوبونات للمتلقي');
        }

        // 5. Add Audit Logs
        require_once 'audit.php';
        auditCouponChange($senderId, $sender['name'], $sender_total, $sender_new_total, "إرسال إلى {$recipient['name']} ($category)");
        auditCouponChange($recipientId, $recipient['name'], intval($recipient['coupons']), $rec_new_total, "استلام من {$sender['name']}");

        $conn->commit();
        sendJSON(['success' => true, 'message' => "تم إرسال الكوبونات بنجاح إلى {$recipient['name']}", 'newTotal' => $sender_new_total]);
    } catch (Exception $e) {
        if (isset($conn)) $conn->rollback();
        sendJSON(['success' => false, 'message' => $e->getMessage()]);
    }
}

function _getStudentTripRank($conn, $tripId, $studentId)
{
    $sql = "
        SELECT s.id, SUM(cl.change_amount) as total_points
        FROM coupon_logs cl
        JOIN students s ON cl.student_id = s.id
        WHERE (cl.reason LIKE CONCAT('trip_points_scan:', ?, '%')
           OR cl.reason LIKE CONCAT('trip_points_normal:', ?, '%'))
        GROUP BY s.id
        HAVING total_points > 0
        ORDER BY total_points DESC
    ";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param('ii', $tripId, $tripId);
    $stmt->execute();
    $res = $stmt->get_result();
    
    $rank = 1;
    while ($row = $res->fetch_assoc()) {
        if (intval($row['id']) === $studentId) {
            return $rank;
        }
        $rank++;
    }
    return null;
}

function _checkAndNotifyTripRankUpgrade($conn, $tripId, $studentId, $oldRank, $studentName, $churchId)
{
    $newRank = _getStudentTripRank($conn, $tripId, $studentId);
    if ($newRank !== null && $newRank <= 10) {
        if ($oldRank === null || $newRank < $oldRank) {
            $tripTitle = "الرحلة";
            $leaderboardEnabled = false; // default off
            $tstmt = $conn->prepare("SELECT title, points_config FROM trips WHERE id = ? LIMIT 1");
            $tstmt->bind_param('i', $tripId);
            if ($tstmt->execute()) {
                $tres = $tstmt->get_result()->fetch_assoc();
                if ($tres) {
                    $tripTitle = $tres['title'];
                    $pointsConfig = json_decode($tres['points_config'] ?? '', true);
                    $leaderboardEnabled = isset($pointsConfig['notifications']['leaderboard']) ? (bool)$pointsConfig['notifications']['leaderboard'] : false;
                }
            }
            
            if ($leaderboardEnabled) {
                $title = "🏆 تحديث لوحة الأوائل!";
                $body = "{$studentName} صعد للمركز الـ {$newRank} في لوحة أوائل رحلة {$tripTitle}! 🎉";
                $extra = [
                    'notifType' => 'leaderboard_upgrade',
                    'trip_id' => $tripId,
                    'student_id' => $studentId,
                    'rank' => $newRank
                ];
                
                _sendWebPushToChurch($conn, $churchId, $title, $body, $extra);
                _sendWebPushToKids($conn, $churchId, $title, $body, $extra);
                
                if (function_exists('pushNotification')) {
                    pushNotification($conn, $churchId, 'leaderboard_upgrade', $title, $body, 'leaderboard_upgrade', $tripId);
                }
            }
        }
    }
}

function trackSongDownload() {
    $conn = getDBConnection();
    
    // Ensure table exists
    $conn->query("CREATE TABLE IF NOT EXISTS `song_download_logs` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
        `tracker_uuid` VARCHAR(64) NOT NULL,
        `format` VARCHAR(10) NOT NULL,
        `user_id` INT DEFAULT NULL,
        `user_type` VARCHAR(20) DEFAULT NULL,
        `ip_address` VARCHAR(45) NOT NULL,
        `user_agent` TEXT NOT NULL,
        `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        INDEX idx_song_tracker (`tracker_uuid`),
        INDEX idx_song_format (`format`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");

    $format = sanitize($_POST['format'] ?? '');
    $trackerUuid = sanitize($_POST['tracker_uuid'] ?? '');
    
    if (empty($format) || empty($trackerUuid)) {
        sendJSON(['success' => false, 'message' => 'بيانات ناقصة']);
    }

    // Determine if logged in
    autoRestoreSessionFromRequest();
    $userId = null;
    $userType = null;
    
    if (isset($_SESSION['uncle_id'])) {
        $userId = intval($_SESSION['uncle_id']);
        $userType = 'uncle';
    } elseif (isset($_SESSION['student_id'])) {
        $userId = intval($_SESSION['student_id']);
        $userType = 'student';
    } elseif (isset($_SESSION['church_id'])) {
        $userId = intval($_SESSION['church_id']);
        $userType = 'church';
    }

    if (!$userId && !empty($_POST['uncle_id'])) {
        $userId = intval($_POST['uncle_id']);
        $userType = 'uncle';
    } elseif (!$userId && !empty($_POST['student_id'])) {
        $userId = intval($_POST['student_id']);
        $userType = 'student';
    } elseif (!$userId && !empty($_POST['church_id'])) {
        $userId = intval($_POST['church_id']);
        $userType = 'church';
    } elseif (!$userId && !empty($_POST['user_id']) && !empty($_POST['user_type'])) {
        $userId = intval($_POST['user_id']);
        $userType = sanitize($_POST['user_type']);
    }

    $ipAddress = $_SERVER['REMOTE_ADDR'] ?? '';
    $userAgent = $_SERVER['HTTP_USER_AGENT'] ?? '';

    $stmt = $conn->prepare("INSERT INTO song_download_logs (tracker_uuid, format, user_id, user_type, ip_address, user_agent) VALUES (?, ?, ?, ?, ?, ?)");
    if (!$stmt) {
        sendJSON(['success' => false, 'message' => 'فشل الاستعداد للكتابة']);
    }
    $stmt->bind_param('ssssss', $trackerUuid, $format, $userId, $userType, $ipAddress, $userAgent);
    if ($stmt->execute()) {
        sendJSON(['success' => true]);
    } else {
        sendJSON(['success' => false, 'message' => 'فشل تسجيل التحميل']);
    }
    $stmt->close();
}

function getSongDownloadStats() {
    checkAuth();
    $role = strtolower(trim($_SESSION['uncle_role'] ?? $_SESSION['role'] ?? $_SESSION['user_role'] ?? $_POST['uncle_role'] ?? $_POST['role'] ?? $_GET['uncle_role'] ?? $_GET['role'] ?? ''));
    
    $isDev = in_array($role, ['developer', 'dev']) || !empty($_SESSION['is_developer']);

    if (!$isDev && !empty($_SESSION['uncle_id'])) {
        $connTemp = getDBConnection();
        $stmtTemp = $connTemp->prepare("SELECT role FROM uncles WHERE id = ?");
        if ($stmtTemp) {
            $uId = intval($_SESSION['uncle_id']);
            $stmtTemp->bind_param("i", $uId);
            $stmtTemp->execute();
            $resTemp = $stmtTemp->get_result();
            if ($rowTemp = $resTemp->fetch_assoc()) {
                if (in_array(strtolower(trim($rowTemp['role'] ?? '')), ['developer', 'dev'])) {
                    $isDev = true;
                    $_SESSION['uncle_role'] = $rowTemp['role'];
                }
            }
            $stmtTemp->close();
        }
    }

    if (!$isDev && !empty($_SESSION['church_id'])) {
        $connTemp = getDBConnection();
        $stmtTemp = $connTemp->prepare("SELECT role FROM churches WHERE id = ?");
        if ($stmtTemp) {
            $cId = intval($_SESSION['church_id']);
            $stmtTemp->bind_param("i", $cId);
            $stmtTemp->execute();
            $resTemp = $stmtTemp->get_result();
            if ($rowTemp = $resTemp->fetch_assoc()) {
                if (in_array(strtolower(trim($rowTemp['role'] ?? '')), ['developer', 'dev'])) {
                    $isDev = true;
                    $_SESSION['role'] = $rowTemp['role'];
                }
            }
            $stmtTemp->close();
        }
    }

    if (!$isDev) {
        sendJSON(['success' => false, 'message' => 'غير مصرح - هذه البيانات مخصصة لمطور النظام فقط']);
        return;
    }

    $conn = getDBConnection();

    // Ensure table exists
    $conn->query("CREATE TABLE IF NOT EXISTS `song_download_logs` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
        `tracker_uuid` VARCHAR(64) NOT NULL,
        `format` VARCHAR(10) NOT NULL,
        `user_id` INT DEFAULT NULL,
        `user_type` VARCHAR(20) DEFAULT NULL,
        `ip_address` VARCHAR(45) NOT NULL,
        `user_agent` TEXT NOT NULL,
        `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        INDEX idx_song_tracker (`tracker_uuid`),
        INDEX idx_song_format (`format`)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");

    // Helper function for quick count
    $getVal = function($sql) use ($conn) {
        $res = $conn->query($sql);
        return ($res) ? (int)$res->fetch_assoc()['val'] : 0;
    };

    // Clicks (Downloads)
    $totalClicks = $getVal("SELECT COUNT(*) as val FROM song_download_logs WHERE format IN ('mp3', 'wav')");
    $uniqueUsers = $getVal("SELECT COUNT(DISTINCT tracker_uuid) as val FROM song_download_logs WHERE format IN ('mp3', 'wav')");

    // MP3 Clicks
    $totalMp3 = $getVal("SELECT COUNT(*) as val FROM song_download_logs WHERE format = 'mp3'");
    $uniqueMp3 = $getVal("SELECT COUNT(DISTINCT tracker_uuid) as val FROM song_download_logs WHERE format = 'mp3'");

    // WAV Clicks
    $totalWav = $getVal("SELECT COUNT(*) as val FROM song_download_logs WHERE format = 'wav'");
    $uniqueWav = $getVal("SELECT COUNT(DISTINCT tracker_uuid) as val FROM song_download_logs WHERE format = 'wav'");

    // Plays
    $totalPlays = $getVal("SELECT COUNT(*) as val FROM song_download_logs WHERE format = 'play'");
    $uniquePlays = $getVal("SELECT COUNT(DISTINCT tracker_uuid) as val FROM song_download_logs WHERE format = 'play'");

    // Shares
    $totalShares = $getVal("SELECT COUNT(*) as val FROM song_download_logs WHERE format = 'share'");
    $uniqueShares = $getVal("SELECT COUNT(DISTINCT tracker_uuid) as val FROM song_download_logs WHERE format = 'share'");

    // Format stats breakdown
    $resFormats = $conn->query("SELECT format, COUNT(*) as count FROM song_download_logs GROUP BY format");
    $formatStats = [];
    if ($resFormats) {
        while ($row = $resFormats->fetch_assoc()) {
            $formatStats[$row['format']] = (int)$row['count'];
        }
    }

    // Detailed Log
    $sql = "SELECT l.*, 
                   CASE 
                     WHEN l.user_type = 'uncle' THEN u.name 
                     WHEN l.user_type = 'student' THEN s.name 
                     WHEN l.user_type = 'church' THEN c.church_name
                     ELSE NULL 
                   END as user_display_name,
                   CASE 
                     WHEN l.user_type = 'uncle' THEN u.username 
                     WHEN l.user_type = 'student' THEN s.phone 
                     WHEN l.user_type = 'church' THEN c.church_code
                     ELSE NULL 
                   END as user_username,
                   CASE 
                     WHEN l.user_type = 'uncle' THEN u.image_url 
                     WHEN l.user_type = 'student' THEN s.image_url 
                     WHEN l.user_type = 'church' THEN NULL
                     ELSE NULL 
                   END as user_image_url
            FROM song_download_logs l
            LEFT JOIN uncles u ON l.user_type = 'uncle' AND l.user_id = u.id
            LEFT JOIN students s ON l.user_type = 'student' AND l.user_id = s.id
            LEFT JOIN churches c ON l.user_type = 'church' AND l.user_id = c.id
            ORDER BY l.created_at DESC
            LIMIT 1000";
            
    $resLogs = $conn->query($sql);
    $logs = [];
    if ($resLogs) {
        while ($row = $resLogs->fetch_assoc()) {
            $logs[] = $row;
        }
    }

    sendJSON([
        'success' => true,
        'stats' => [
            'total_clicks' => $totalClicks,
            'unique_users' => $uniqueUsers,
            'total_mp3' => $totalMp3,
            'unique_mp3' => $uniqueMp3,
            'total_wav' => $totalWav,
            'unique_wav' => $uniqueWav,
            'total_plays' => $totalPlays,
            'unique_plays' => $uniquePlays,
            'total_shares' => $totalShares,
            'unique_shares' => $uniqueShares,
            'action_stats' => $formatStats
        ],
        'logs' => $logs
    ]);
}

// ── Export History Backup for Entity Deletion ────────────────
function exportEntityBackup()
{
    checkAuth();
    try {
        $conn = getDBConnection();
        $churchId = getChurchId();

        $type = sanitize($_GET['type'] ?? $_POST['type'] ?? '');
        $id = intval($_GET['id'] ?? $_POST['id'] ?? 0);
        $asDownload = isset($_GET['download']) || isset($_POST['download']) || ($_SERVER['REQUEST_METHOD'] === 'GET');

        if (!$type || !in_array($type, ['trip', 'student', 'uncle', 'church'])) {
            sendJSON(['success' => false, 'message' => 'نوع التصدير غير صالح']);
            return;
        }

        $entityName = '';
        $data = [];

        if ($type === 'trip') {
            if ($id <= 0) { sendJSON(['success' => false, 'message' => 'معرف الرحلة غير صحيح']); return; }

            $stmt = $conn->prepare("SELECT * FROM trips WHERE id = ? AND church_id = ?");
            $stmt->bind_param("ii", $id, $churchId);
            $stmt->execute();
            $trip = $stmt->get_result()->fetch_assoc();
            if (!$trip) { sendJSON(['success' => false, 'message' => 'الرحلة غير موجودة']); return; }
            $entityName = $trip['title'] ?? "Trip_$id";

            $regStmt = $conn->prepare("SELECT * FROM trip_registrations WHERE trip_id = ?");
            $regStmt->bind_param("i", $id);
            $regStmt->execute();
            $registrations = $regStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $wStmt = $conn->prepare("SELECT * FROM trip_waitlist WHERE trip_id = ?");
            $wStmt->bind_param("i", $id);
            $wStmt->execute();
            $waitlist = $wStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $rtStmt = $conn->prepare("SELECT * FROM rooms_templates WHERE trip_id = ?");
            $rtStmt->bind_param("i", $id);
            $rtStmt->execute();
            $rooms = $rtStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $expStmt = $conn->prepare("SELECT * FROM trip_expenses WHERE trip_id = ?");
            $expStmt->bind_param("i", $id);
            $expStmt->execute();
            $expenses = $expStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $auditStmt = $conn->prepare("SELECT * FROM audit_logs WHERE (entity IN ('trip', 'trip_registration') AND (entity_id = ? OR details LIKE ?)) OR notes LIKE ?");
            $likeId = "%" . $id . "%";
            $auditStmt->bind_param("iss", $id, $likeId, $likeId);
            $auditStmt->execute();
            $auditLogs = $auditStmt->get_result()->fetch_all(MYSQLI_ASSOC);

            $data = [
                'trip' => $trip,
