                'waitlist' => $waitlist,
                'rooms_templates' => $rooms,
                'expenses' => $expenses,
                'audit_logs' => $auditLogs
            ];

        } elseif ($type === 'student') {
            if ($id <= 0) { sendJSON(['success' => false, 'message' => 'معرف الطفل غير صحيح']); return; }

            $stmt = $conn->prepare("SELECT * FROM students WHERE id = ? AND church_id = ?");
